    "src/ActivePool.sol": {
      "content": "// SPDX-License-Identifier: BUSL-1.1

pragma solidity 0.8.24;

import "openzeppelin-contracts/contracts/token/ERC20/utils/SafeERC20.sol";
import "openzeppelin-contracts/contracts/utils/math/Math.sol";

import "./Dependencies/Constants.sol";
import "./Interfaces/IActivePool.sol";
import "./Interfaces/IAddressesRegistry.sol";
import "./Interfaces/IJpydfToken.sol";
import "./Interfaces/IInterestRouter.sol";
import "./Interfaces/IDefaultPool.sol";

/*
 * The Active Pool holds the collateral and JPYDF debt (but not JPYDF tokens) for all active troves.
 *
 * When a trove is liquidated, it's Coll and JPYDF debt are transferred from the Active Pool, to either the
 * Stability Pool, the Default Pool, or both, depending on the liquidation conditions.
 *
 */
contract ActivePool is IActivePool {
    using SafeERC20 for IERC20;

    string public constant NAME = "ActivePool";

    IERC20 public immutable collToken;
    address public immutable borrowerOperationsAddress;
    address public immutable troveManagerAddress;
    address public immutable defaultPoolAddress;

    IJpydfToken public immutable jpydfToken;

    IInterestRouter public immutable interestRouter;
    IJpydfRewardsReceiver public immutable stabilityPool;

    uint256 internal collBalance; // deposited coll tracker

    // Aggregate recorded debt tracker. Updated whenever a Trove's debt is touched AND whenever the aggregate pending interest is minted.
    // "D" in the spec.
    uint256 public aggRecordedDebt;

    /* Sum of individual recorded Trove debts weighted by their respective chosen interest rates.
    * Updated at individual Trove operations.
    * "S" in the spec.
    */
    uint256 public aggWeightedDebtSum;

    // Last time at which the aggregate recorded debt and weighted sum were updated
    uint256 public lastAggUpdateTime;

    // Timestamp at which branch was shut down. 0 if not shut down.
    uint256 public shutdownTime;

    // Aggregate batch fees tracker
    uint256 public aggBatchManagementFees;
    /* Sum of individual recorded Trove debts weighted by their respective batch management fees
     * Updated at individual batched Trove operations.
     */
    uint256 public aggWeightedBatchManagementFeeSum;
    // Last time at which the aggregate batch fees and weighted sum were updated
    uint256 public lastAggBatchManagementFeesUpdateTime;

    // --- Events ---

    event CollTokenAddressChanged(address _newCollTokenAddress);
    event BorrowerOperationsAddressChanged(address _newBorrowerOperationsAddress);
    event TroveManagerAddressChanged(address _newTroveManagerAddress);
    event DefaultPoolAddressChanged(address _newDefaultPoolAddress);
    event StabilityPoolAddressChanged(address _newStabilityPoolAddress);
    event ActivePoolCollBalanceUpdated(uint256 _collBalance);
    event ActivePoolAggRecordedDebtUpdated(uint256 _aggRecordedDebt);
    event ActivePoolAggWeightedDebtSumUpdated(uint256 _aggWeightedDebtSum);
    event ActivePoolAggBatchManagementFeesUpdated(uint256 _aggBatchManagementFees);
    event ActivePoolAggWeightedBatchManagementFeeSumUpdated(uint256 _aggWeightedBatchManagementFeeSum);
    event AggregateInterestMinted(
        address indexed _jpydfToken,
        address indexed _stabilityPool,
        address indexed _interestRouter,
        uint256 _pendingAggInterest,
        uint256 _upfrontFee,
        uint256 _mintedAmount,
        uint256 _spYield,
        uint256 _interestRouterYield
    );
    event BatchManagementFeeMinted(
        address indexed _jpydfToken, address indexed _batchManager, uint256 _batchManagementFee
    );

    constructor(IAddressesRegistry _addressesRegistry) {
        collToken = _addressesRegistry.collToken();
        borrowerOperationsAddress = address(_addressesRegistry.borrowerOperations());
        troveManagerAddress = address(_addressesRegistry.troveManager());
        stabilityPool = IJpydfRewardsReceiver(_addressesRegistry.stabilityPool());
        defaultPoolAddress = address(_addressesRegistry.defaultPool());
        interestRouter = _addressesRegistry.interestRouter();
        jpydfToken = _addressesRegistry.jpydfToken();

        emit CollTokenAddressChanged(address(collToken));
        emit BorrowerOperationsAddressChanged(borrowerOperationsAddress);
        emit TroveManagerAddressChanged(troveManagerAddress);
        emit StabilityPoolAddressChanged(address(stabilityPool));
        emit DefaultPoolAddressChanged(defaultPoolAddress);

        // Allow funds movements between Liquity contracts
        collToken.forceApprove(defaultPoolAddress, type(uint256).max);
    }

    // --- Getters for public variables. Required by IPool interface ---

    /*
    * Returns the Coll state variable.
    *
    *Not necessarily equal to the contract's raw Coll balance - ether can be forcibly sent to contracts.
    */
    function getCollBalance() external view override returns (uint256) {
        return collBalance;
    }

    function calcPendingAggInterest() public view returns (uint256) {
        if (shutdownTime != 0) return 0;

        // We use the ceiling of the division here to ensure positive error, while we use regular floor division
        // when calculating the interest accrued by individual Troves.
        // This ensures that `system debt >= sum(trove debt)` always holds, and thus system debt won't turn negative
        // even if all Trove debt is repaid. The difference should be small and it should scale with the number of
        // interest minting events.
        return Math.ceilDiv(aggWeightedDebtSum * (block.timestamp - lastAggUpdateTime), ONE_YEAR * DECIMAL_PRECISION);
    }

    function calcPendingSPYield() external view returns (uint256) {
        return calcPendingAggInterest() * SP_YIELD_SPLIT / DECIMAL_PRECISION;
    }

    function calcPendingAggBatchManagementFee() public view returns (uint256) {
        uint256 periodEnd = shutdownTime != 0 ? shutdownTime : block.timestamp;
        uint256 periodStart = Math.min(lastAggBatchManagementFeesUpdateTime, periodEnd);

        return Math.ceilDiv(aggWeightedBatchManagementFeeSum * (periodEnd - periodStart), ONE_YEAR * DECIMAL_PRECISION);
    }

    function getNewApproxAvgInterestRateFromTroveChange(TroveChange calldata _troveChange)
        external
        view
        returns (uint256)
    {
        // We are ignoring the upfront fee when calculating the approx. avg. interest rate.
        // This is a simple way to resolve the circularity in:
        //   fee depends on avg. interest rate -> avg. interest rate is weighted by debt -> debt includes fee -> ...
        assert(_troveChange.upfrontFee == 0);

        if (shutdownTime != 0) return 0;

        uint256 newAggRecordedDebt = aggRecordedDebt;
        newAggRecordedDebt += calcPendingAggInterest();
        newAggRecordedDebt += _troveChange.appliedRedistJpydfDebtGain;
        newAggRecordedDebt += _troveChange.debtIncrease;
        newAggRecordedDebt += _troveChange.batchAccruedManagementFee;
        newAggRecordedDebt -= _troveChange.debtDecrease;

        uint256 newAggWeightedDebtSum = aggWeightedDebtSum;
        newAggWeightedDebtSum += _troveChange.newWeightedRecordedDebt;
        newAggWeightedDebtSum -= _troveChange.oldWeightedRecordedDebt;

        // Avoid division by 0 if the first ever borrower tries to borrow 0 JPYDF
        // Borrowing 0 JPYDF is not allowed, but our check of debt >= MIN_DEBT happens _after_ calculating the upfront
        // fee, which involves getting the new approx. avg. interest rate
        return newAggRecordedDebt > 0 ? newAggWeightedDebtSum / newAggRecordedDebt : 0;
    }

    // Returns sum of agg.recorded debt plus agg. pending interest. Excludes pending redist. gains.
    function getJpydfDebt() external view returns (uint256) {
        return aggRecordedDebt + calcPendingAggInterest() + aggBatchManagementFees + calcPendingAggBatchManagementFee();
    }

    // --- Pool functionality ---

    function sendColl(address _account, uint256 _amount) external override {
        _requireCallerIsBOorTroveMorSP();

        _accountForSendColl(_amount);

        collToken.safeTransfer(_account, _amount);
    }

    function sendCollToDefaultPool(uint256 _amount) external override {
        _requireCallerIsTroveManager();

        _accountForSendColl(_amount);

        IDefaultPool(defaultPoolAddress).receiveColl(_amount);
    }

    function _accountForSendColl(uint256 _amount) internal {
        uint256 newCollBalance = collBalance - _amount;
        collBalance = newCollBalance;
        emit ActivePoolCollBalanceUpdated(newCollBalance);
    }

    function receiveColl(uint256 _amount) external {
        _requireCallerIsBorrowerOperationsOrDefaultPool();

        _accountForReceivedColl(_amount);

        // Pull Coll tokens from sender
        collToken.safeTransferFrom(msg.sender, address(this), _amount);
    }

    function accountForReceivedColl(uint256 _amount) public {
        _requireCallerIsBorrowerOperationsOrDefaultPool();

        _accountForReceivedColl(_amount);
    }

    function _accountForReceivedColl(uint256 _amount) internal {
        uint256 newCollBalance = collBalance + _amount;
        collBalance = newCollBalance;

        emit ActivePoolCollBalanceUpdated(newCollBalance);
    }

    // --- Aggregate interest operations ---

    // This function is called inside all state-changing user ops: borrower ops, liquidations, redemptions and SP deposits/withdrawals.
    // Some user ops trigger debt changes to Trove(s), in which case _troveDebtChange will be non-zero.
    // The aggregate recorded debt is incremented by the aggregate pending interest, plus the net Trove debt change.
    // The net Trove debt change consists of the sum of a) any debt issued/repaid and b) any redistribution debt gain applied in the encapsulating operation.
    // It does *not* include the Trove's individual accrued interest - this gets accounted for in the aggregate accrued interest.
    // The net Trove debt change could be positive or negative in a repayment (depending on whether its redistribution gain or repayment amount is larger),
    // so this function accepts both the increase and the decrease to avoid using (and converting to/from) signed ints.
    function mintAggInterestAndAccountForTroveChange(TroveChange calldata _troveChange, address _batchAddress)
        external
    {
        _requireCallerIsBOorTroveM();

        // Batch management fees
        if (_batchAddress != address(0)) {
            _mintBatchManagementFeeAndAccountForChange(_troveChange, _batchAddress);
        }

        // Do the arithmetic in 2 steps here to avoid underflow from the decrease
        uint256 newAggRecordedDebt = aggRecordedDebt; // 1 SLOAD
        newAggRecordedDebt += _mintAggInterest(_troveChange.upfrontFee); // adds minted agg. interest + upfront fee
        newAggRecordedDebt += _troveChange.appliedRedistJpydfDebtGain;
        newAggRecordedDebt += _troveChange.debtIncrease;
        newAggRecordedDebt -= _troveChange.debtDecrease;
        aggRecordedDebt = newAggRecordedDebt; // 1 SSTORE
        emit ActivePoolAggRecordedDebtUpdated(newAggRecordedDebt);

        // assert(aggRecordedDebt >= 0) // This should never be negative. If all redistribution gians and all aggregate interest was applied
        // and all Trove debts were repaid, it should become 0.

        // Do the arithmetic in 2 steps here to avoid underflow from the decrease
        uint256 newAggWeightedDebtSum = aggWeightedDebtSum; // 1 SLOAD
        newAggWeightedDebtSum += _troveChange.newWeightedRecordedDebt;
        newAggWeightedDebtSum -= _troveChange.oldWeightedRecordedDebt;
        aggWeightedDebtSum = newAggWeightedDebtSum; // 1 SSTORE
        emit ActivePoolAggWeightedDebtSumUpdated(newAggWeightedDebtSum);
    }

    function mintAggInterest() external override {
        _requireCallerIsBOorSP();
        aggRecordedDebt += _mintAggInterest(0);
        emit ActivePoolAggRecordedDebtUpdated(aggRecordedDebt);
    }

    function _mintAggInterest(uint256 _upfrontFee) internal returns (uint256 mintedAmount) {
        uint256 pendingAggInterest = calcPendingAggInterest();
        mintedAmount = pendingAggInterest + _upfrontFee;

        // Mint part of the JPYDF interest to the SP and part to the router for LPs.
        if (mintedAmount > 0) {
            uint256 spYield = SP_YIELD_SPLIT * mintedAmount / DECIMAL_PRECISION;
            uint256 remainderToLPs = mintedAmount - spYield;

            jpydfToken.mint(address(interestRouter), remainderToLPs);

            if (spYield > 0) {
                jpydfToken.mint(address(stabilityPool), spYield);
                stabilityPool.triggerJpydfRewards(spYield);
            }

            emit AggregateInterestMinted(
                address(jpydfToken),
                address(stabilityPool),
                address(interestRouter),
                pendingAggInterest,
                _upfrontFee,
                mintedAmount,
                spYield,
                remainderToLPs
            );
        }

        lastAggUpdateTime = block.timestamp;
    }

    function mintBatchManagementFeeAndAccountForChange(TroveChange calldata _troveChange, address _batchAddress)
        external
        override
    {
        _requireCallerIsTroveManager();
        _mintBatchManagementFeeAndAccountForChange(_troveChange, _batchAddress);
    }

    function _mintBatchManagementFeeAndAccountForChange(TroveChange memory _troveChange, address _batchAddress)
        internal
    {
        aggRecordedDebt += _troveChange.batchAccruedManagementFee;
        emit ActivePoolAggRecordedDebtUpdated(aggRecordedDebt);

        // Do the arithmetic in 2 steps here to avoid underflow from the decrease
        uint256 newAggBatchManagementFees = aggBatchManagementFees; // 1 SLOAD
        newAggBatchManagementFees += calcPendingAggBatchManagementFee();
        newAggBatchManagementFees -= _troveChange.batchAccruedManagementFee;
        aggBatchManagementFees = newAggBatchManagementFees; // 1 SSTORE
        emit ActivePoolAggBatchManagementFeesUpdated(newAggBatchManagementFees);

        // Do the arithmetic in 2 steps here to avoid underflow from the decrease
        uint256 newAggWeightedBatchManagementFeeSum = aggWeightedBatchManagementFeeSum; // 1 SLOAD
        newAggWeightedBatchManagementFeeSum += _troveChange.newWeightedRecordedBatchManagementFee;
        newAggWeightedBatchManagementFeeSum -= _troveChange.oldWeightedRecordedBatchManagementFee;
        aggWeightedBatchManagementFeeSum = newAggWeightedBatchManagementFeeSum; // 1 SSTORE
        emit ActivePoolAggWeightedBatchManagementFeeSumUpdated(newAggWeightedBatchManagementFeeSum);

        // mint fee to batch address
        if (_troveChange.batchAccruedManagementFee > 0) {
            jpydfToken.mint(_batchAddress, _troveChange.batchAccruedManagementFee);
            emit BatchManagementFeeMinted(
                address(jpydfToken), _batchAddress, _troveChange.batchAccruedManagementFee
            );
        }

        lastAggBatchManagementFeesUpdateTime = block.timestamp;
    }

    // --- Shutdown ---

    function setShutdownFlag() external {
        _requireCallerIsTroveManager();
        shutdownTime = block.timestamp;
    }

    function hasBeenShutDown() external view returns (bool) {
        return shutdownTime != 0;
    }

    // --- 'require' functions ---

    function _requireCallerIsBorrowerOperationsOrDefaultPool() internal view {
        require(
            msg.sender == borrowerOperationsAddress || msg.sender == defaultPoolAddress,
            "ActivePool: Caller is neither BO nor Default Pool"
        );
    }

    function _requireCallerIsBOorTroveMorSP() internal view {
        require(
            msg.sender == borrowerOperationsAddress || msg.sender == troveManagerAddress
                || msg.sender == address(stabilityPool),
            "ActivePool: Caller is neither BorrowerOperations nor TroveManager nor StabilityPool"
        );
    }

    function _requireCallerIsBOorSP() internal view {
        require(
            msg.sender == borrowerOperationsAddress || msg.sender == address(stabilityPool),
            "ActivePool: Caller is not BorrowerOperations nor StabilityPool"
        );
    }

    function _requireCallerIsBOorTroveM() internal view {
        require(
            msg.sender == borrowerOperationsAddress || msg.sender == troveManagerAddress,
            "ActivePool: Caller is neither BorrowerOperations nor TroveManager"
        );
    }

    function _requireCallerIsTroveManager() internal view {
        require(msg.sender == troveManagerAddress, "ActivePool: Caller is not TroveManager");
    }
}
"
    },
    "src/AddressesRegistry.sol": {
      "content": "// SPDX-License-Identifier: BUSL-1.1

pragma solidity 0.8.24;

import "./Dependencies/Ownable.sol";
import {
    MIN_LIQUIDATION_PENALTY_SP,
    COLL_GAS_COMPENSATION_DIVISOR,
    MAX_LIQUIDATION_PENALTY_REDISTRIBUTION,
    URGENT_REDEMPTION_BONUS,
    COLL_GAS_COMPENSATION_CAP
} from "./Dependencies/Constants.sol";
import "./Interfaces/IAddressesRegistry.sol";
import "./Interfaces/IMetadataNFT.sol";
import {IDToken} from "./Interfaces/IDToken.sol";
import {ICollateralVault} from "./Interfaces/ICollateralVault.sol";

contract AddressesRegistry is Ownable, IAddressesRegistry {
    IERC20Metadata public collToken;
    IBorrowerOperations public borrowerOperations;
    ITroveManager public troveManager;
    ITroveNFT public troveNFT;
    IMetadataNFT public metadataNFT;
    IStabilityPool public stabilityPool;
    IPriceFeed public priceFeed;
    IActivePool public activePool;
    IDefaultPool public defaultPool;
    address public gasPoolAddress;
    ICollSurplusPool public collSurplusPool;
    ISortedTroves public sortedTroves;
    IInterestRouter public interestRouter;
    IHintHelpers public hintHelpers;
    IMultiTroveGetter public multiTroveGetter;
    ICollateralRegistry public collateralRegistry;
    IJpydfToken public jpydfToken;
    IWETH public WETH;

    // Critical system collateral ratio. If the system's total collateral ratio (TCR) falls below the CCR, some borrowing operation restrictions are applied
    uint256 public CCR;
    // Shutdown system collateral ratio. If the system's total collateral ratio (TCR) for a given collateral falls below the SCR,
    // the protocol triggers the shutdown of the borrow market and permanently disables all borrowing operations except for closing Troves.
    uint256 public SCR;

    // Minimum collateral ratio for individual troves
    uint256 public MCR;
    // Extra buffer of collateral ratio to join a batch or adjust a trove inside a batch (on top of MCR)
    uint256 public BCR;
    // Liquidation penalty for troves offset to the SP
    uint256 public LIQUIDATION_PENALTY_SP;
    // Liquidation penalty for troves redistributed
    uint256 public LIQUIDATION_PENALTY_REDISTRIBUTION;

    // Zero for branches whose risk parameters are final at deployment. Reserved
    // branches store the only address that may finalize their parameters.
    address public immutable riskParamsFinalizer;
    bool public riskParamsFinalized;

    error InvalidCollGasCompensationCap();
    error InvalidCCR();
    error InvalidMCR();
    error InvalidBCR();
    error InvalidSCR();
    error SPPenaltyTooLow();
    error SPPenaltyGtRedist();
    error RedistPenaltyTooHigh();
    error InvalidCollateralRatioOrder();
    error MCRBelowSPPenalty();
    error MCRBelowRedistributionPenalty();
    error SCRBelowUrgentRedemptionBonus();
    error CallerNotRiskParamsFinalizer();
    error RiskParamsAlreadyFinalized();
    error InvalidExpectedUnderlying();
    error InvalidDToken();
    error InvalidVault();
    error DTokenUnderlyingMismatch(address expected, address actual);
    error VaultUnderlyingMismatch(address expected, address actual);
    error VaultDTokenMismatch(address expected, address actual);
    error DTokenCapNotZero(uint256 cap);
    error DTokenSupplyNotZero(uint256 supply);
    error TrovesExist(uint256 count);
    error BranchDebtNotZero(uint256 debt);
    error BranchCollNotZero(uint256 coll);
    error StabilityPoolNotEmpty(uint256 deposits);
    error OracleFailureShutdownActive();
    error BranchAlreadyShutDown();

    event CollTokenAddressChanged(address _collTokenAddress);
    event BorrowerOperationsAddressChanged(address _borrowerOperationsAddress);
    event TroveManagerAddressChanged(address _troveManagerAddress);
    event TroveNFTAddressChanged(address _troveNFTAddress);
    event MetadataNFTAddressChanged(address _metadataNFTAddress);
    event StabilityPoolAddressChanged(address _stabilityPoolAddress);
    event PriceFeedAddressChanged(address _priceFeedAddress);
    event ActivePoolAddressChanged(address _activePoolAddress);
    event DefaultPoolAddressChanged(address _defaultPoolAddress);
    event GasPoolAddressChanged(address _gasPoolAddress);
    event CollSurplusPoolAddressChanged(address _collSurplusPoolAddress);
    event SortedTrovesAddressChanged(address _sortedTrovesAddress);
    event InterestRouterAddressChanged(address _interestRouterAddress);
    event HintHelpersAddressChanged(address _hintHelpersAddress);
    event MultiTroveGetterAddressChanged(address _multiTroveGetterAddress);
    event CollateralRegistryAddressChanged(address _collateralRegistryAddress);
    event JpydfTokenAddressChanged(address _jpydfTokenAddress);
    event WETHAddressChanged(address _wethAddress);
    event RiskParamsFinalized(
        address indexed underlying,
        uint256 CCR,
        uint256 MCR,
        uint256 BCR,
        uint256 SCR,
        uint256 liquidationPenaltySP,
        uint256 liquidationPenaltyRedistribution,
        uint256 collGasCompensationCap
    );

    constructor(
        address _initialOwner,
        uint256 _ccr,
        uint256 _mcr,
        uint256 _bcr,
        uint256 _scr,
        uint256 _liquidationPenaltySP,
        uint256 _liquidationPenaltyRedistribution,
        address _riskParamsFinalizer
    ) Ownable(_initialOwner) {
        _requireValidRiskParams(_ccr, _mcr, _bcr, _scr, _liquidationPenaltySP, _liquidationPenaltyRedistribution);

        CCR = _ccr;
        SCR = _scr;
        MCR = _mcr;
        BCR = _bcr;
        LIQUIDATION_PENALTY_SP = _liquidationPenaltySP;
        LIQUIDATION_PENALTY_REDISTRIBUTION = _liquidationPenaltyRedistribution;
        riskParamsFinalizer = _riskParamsFinalizer;
        riskParamsFinalized = _riskParamsFinalizer == address(0);
    }

    function setAddresses(AddressVars memory _vars) external onlyOwner {
        collToken = _vars.collToken;
        borrowerOperations = _vars.borrowerOperations;
        troveManager = _vars.troveManager;
        troveNFT = _vars.troveNFT;
        metadataNFT = _vars.metadataNFT;
        stabilityPool = _vars.stabilityPool;
        priceFeed = _vars.priceFeed;
        activePool = _vars.activePool;
        defaultPool = _vars.defaultPool;
        gasPoolAddress = _vars.gasPoolAddress;
        collSurplusPool = _vars.collSurplusPool;
        sortedTroves = _vars.sortedTroves;
        interestRouter = _vars.interestRouter;
        hintHelpers = _vars.hintHelpers;
        multiTroveGetter = _vars.multiTroveGetter;
        collateralRegistry = _vars.collateralRegistry;
        jpydfToken = _vars.jpydfToken;
        WETH = _vars.WETH;

        emit CollTokenAddressChanged(address(_vars.collToken));
        emit BorrowerOperationsAddressChanged(address(_vars.borrowerOperations));
        emit TroveManagerAddressChanged(address(_vars.troveManager));
        emit TroveNFTAddressChanged(address(_vars.troveNFT));
        emit MetadataNFTAddressChanged(address(_vars.metadataNFT));
        emit StabilityPoolAddressChanged(address(_vars.stabilityPool));
        emit PriceFeedAddressChanged(address(_vars.priceFeed));
        emit ActivePoolAddressChanged(address(_vars.activePool));
        emit DefaultPoolAddressChanged(address(_vars.defaultPool));
        emit GasPoolAddressChanged(_vars.gasPoolAddress);
        emit CollSurplusPoolAddressChanged(address(_vars.collSurplusPool));
        emit SortedTrovesAddressChanged(address(_vars.sortedTroves));
        emit InterestRouterAddressChanged(address(_vars.interestRouter));
        emit HintHelpersAddressChanged(address(_vars.hintHelpers));
        emit MultiTroveGetterAddressChanged(address(_vars.multiTroveGetter));
        emit CollateralRegistryAddressChanged(address(_vars.collateralRegistry));
        emit JpydfTokenAddressChanged(address(_vars.jpydfToken));
        emit WETHAddressChanged(address(_vars.WETH));

        _renounceOwnership();
    }

    function finalizeRiskParams(address _expectedUnderlying, RiskParams calldata _riskParams) external {
        if (riskParamsFinalized) revert RiskParamsAlreadyFinalized();
        if (msg.sender != riskParamsFinalizer) revert CallerNotRiskParamsFinalizer();

        _requireFinalizedRiskParams(
            _riskParams.CCR,
            _riskParams.MCR,
            _riskParams.BCR,
            _riskParams.SCR,
            _riskParams.LIQUIDATION_PENALTY_SP,
            _riskParams.LIQUIDATION_PENALTY_REDISTRIBUTION
        );
        if (
            _riskParams.COLL_GAS_COMPENSATION_CAP == 0
                || _riskParams.COLL_GAS_COMPENSATION_CAP > COLL_GAS_COMPENSATION_CAP
        ) {
            revert InvalidCollGasCompensationCap();
        }
        _requireBranchReadyForFinalization(_expectedUnderlying);

        CCR = _riskParams.CCR;
        MCR = _riskParams.MCR;
        BCR = _riskParams.BCR;
        SCR = _riskParams.SCR;
        LIQUIDATION_PENALTY_SP = _riskParams.LIQUIDATION_PENALTY_SP;
        LIQUIDATION_PENALTY_REDISTRIBUTION = _riskParams.LIQUIDATION_PENALTY_REDISTRIBUTION;
        riskParamsFinalized = true;

        borrowerOperations.syncRiskParams(_riskParams.CCR, _riskParams.MCR, _riskParams.BCR, _riskParams.SCR);
        troveManager.syncRiskParams(_riskParams);

        emit RiskParamsFinalized(
            _expectedUnderlying,
            _riskParams.CCR,
            _riskParams.MCR,
            _riskParams.BCR,
            _riskParams.SCR,
            _riskParams.LIQUIDATION_PENALTY_SP,
            _riskParams.LIQUIDATION_PENALTY_REDISTRIBUTION,
            _riskParams.COLL_GAS_COMPENSATION_CAP
        );
    }

    function _requireValidRiskParams(
        uint256 _ccr,
        uint256 _mcr,
        uint256 _bcr,
        uint256 _scr,
        uint256 _liquidationPenaltySP,
        uint256 _liquidationPenaltyRedistribution
    ) internal pure {
        if (_ccr <= 1e18 || _ccr >= 2e18) revert InvalidCCR();
        if (_mcr <= 1e18 || _mcr >= 2e18) revert InvalidMCR();
        if (_bcr < 5e16 || _bcr >= 50e16) revert InvalidBCR();
        if (_scr <= 1e18 || _scr >= 2e18) revert InvalidSCR();
        if (_liquidationPenaltySP < MIN_LIQUIDATION_PENALTY_SP) revert SPPenaltyTooLow();
        if (_liquidationPenaltySP > _liquidationPenaltyRedistribution) revert SPPenaltyGtRedist();
        if (_liquidationPenaltyRedistribution > MAX_LIQUIDATION_PENALTY_REDISTRIBUTION) revert RedistPenaltyTooHigh();
    }

    function _requireFinalizedRiskParams(
        uint256 _ccr,
        uint256 _mcr,
        uint256 _bcr,
        uint256 _scr,
        uint256 _liquidationPenaltySP,
        uint256 _liquidationPenaltyRedistribution
    ) internal pure {
        _requireValidRiskParams(_ccr, _mcr, _bcr, _scr, _liquidationPenaltySP, _liquidationPenaltyRedistribution);
        if (_scr >= _mcr || _mcr >= _ccr) revert InvalidCollateralRatioOrder();
        if (
            _mcr * (COLL_GAS_COMPENSATION_DIVISOR - 1)
                < (1e18 + _liquidationPenaltySP) * COLL_GAS_COMPENSATION_DIVISOR
        ) revert MCRBelowSPPenalty();
        if (1e18 + _liquidationPenaltyRedistribution > _mcr) revert MCRBelowRedistributionPenalty();
        if (1e18 + URGENT_REDEMPTION_BONUS > _scr) revert SCRBelowUrgentRedemptionBonus();
    }

    function _requireBranchReadyForFinalization(address _expectedUnderlying) internal view {
        if (_expectedUnderlying.code.length == 0) revert InvalidExpectedUnderlying();
        if (address(collToken).code.length == 0) revert InvalidDToken();

        IDToken dToken = IDToken(address(collToken));
        address dTokenUnderlying = address(dToken.underlying());
        if (dTokenUnderlying != _expectedUnderlying) {
            revert DTokenUnderlyingMismatch(_expectedUnderlying, dTokenUnderlying);
        }

        address vaultAddress = dToken.vault();
        if (vaultAddress.code.length == 0) revert InvalidVault();
        ICollateralVault vault = ICollateralVault(vaultAddress);
        address vaultDToken = address(vault.dToken());
        if (vaultDToken != address(dToken)) revert VaultDTokenMismatch(address(dToken), vaultDToken);
        address vaultUnderlying = address(vault.underlying());
        if (vaultUnderlying != _expectedUnderlying) {
            revert VaultUnderlyingMismatch(_expectedUnderlying, vaultUnderlying);
        }

        uint256 dTokenCap = dToken.cap();
        if (dTokenCap != 0) revert DTokenCapNotZero(dTokenCap);
        uint256 dTokenSupply = dToken.totalSupply();
        if (dTokenSupply != 0) revert DTokenSupplyNotZero(dTokenSupply);

        uint256 troveCount = troveManager.getTroveIdsCount();
        if (troveCount != 0) revert TrovesExist(troveCount);
        uint256 branchDebt = borrowerOperations.getEntireBranchDebt();
        if (branchDebt != 0) revert BranchDebtNotZero(branchDebt);
        uint256 branchColl = borrowerOperations.getEntireBranchColl();
        if (branchColl != 0) revert BranchCollNotZero(branchColl);
        uint256 stabilityPoolDeposits = stabilityPool.getTotalJpydfDeposits();
        if (stabilityPoolDeposits != 0) revert StabilityPoolNotEmpty(stabilityPoolDeposits);

        if (borrowerOperations.isOracleFailureShutdown()) revert OracleFailureShutdownActive();
        if (borrowerOperations.hasBeenShutDown() || troveManager.shutdownTime() != 0 || activePool.hasBeenShutDown()) {
            revert BranchAlreadyShutDown();
        }
    }
}
"
