    "src/BorrowerOperations.sol": {
      "content": "// SPDX-License-Identifier: BUSL-1.1

pragma solidity 0.8.24;

import "openzeppelin-contracts/contracts/token/ERC20/utils/SafeERC20.sol";

import "./Interfaces/IBorrowerOperations.sol";
import "./Interfaces/IAddressesRegistry.sol";
import "./Interfaces/ITroveManager.sol";
import "./Interfaces/IJpydfToken.sol";
import "./Interfaces/ICollSurplusPool.sol";
import "./Interfaces/ISortedTroves.sol";
import "./Dependencies/LiquityBase.sol";
import "./Dependencies/AddRemoveManagers.sol";
import "./Types/LatestTroveData.sol";
import "./Types/LatestBatchData.sol";

contract BorrowerOperations is LiquityBase, AddRemoveManagers, IBorrowerOperations {
    using SafeERC20 for IERC20;

    // --- Connected contract declarations ---

    IAddressesRegistry internal immutable addressesRegistry;
    IERC20 internal immutable collToken;
    ITroveManager internal troveManager;
    address internal gasPoolAddress;
    ICollSurplusPool internal collSurplusPool;
    IJpydfToken internal jpydfToken;
    // A doubly linked list of Troves, sorted by their collateral ratios
    ISortedTroves internal sortedTroves;
    // Wrapped ETH for liquidation reserve (gas compensation)
    IWETH internal immutable WETH;

    // Critical system collateral ratio. If the system's total collateral ratio (TCR) falls below the CCR, some borrowing operation restrictions are applied
    uint256 public CCR;

    // Shutdown system collateral ratio. If the system's total collateral ratio (TCR) for a given collateral falls below the SCR,
    // the protocol triggers the shutdown of the borrow market and permanently disables all borrowing operations except for closing Troves.
    uint256 public SCR;
    bool public hasBeenShutDown;
    bool public isOracleFailureShutdown;

    // Minimum collateral ratio for individual troves
    uint256 public MCR;

    // Extra buffer of collateral ratio to join a batch or adjust a trove inside a batch (on top of MCR)
    uint256 public BCR;

    /*
    * Mapping from TroveId to individual delegate for interest rate setting.
    *
    * This address then has the ability to update the borrower’s interest rate, but not change its debt or collateral.
    * Useful for instance for cold/hot wallet setups.
    */
    mapping(uint256 => InterestIndividualDelegate) private interestIndividualDelegateOf;

    /*
     * Mapping from TroveId to granted address for interest rate setting (batch manager).
     *
     * Batch managers set the interest rate for every Trove in the batch. The interest rate is the same for all Troves in the batch.
     */
    mapping(uint256 => address) public interestBatchManagerOf;

    // List of registered Interest Batch Managers
    mapping(address => InterestBatchManager) private interestBatchManagers;

    /* --- Variable container structs  ---

    Used to hold, return and assign variables inside a function, in order to avoid the error:
    "CompilerError: Stack too deep". */

    struct OpenTroveVars {
        ITroveManager troveManager;
        uint256 troveId;
        TroveChange change;
        LatestBatchData batch;
    }

    struct LocalVariables_openTrove {
        ITroveManager troveManager;
        IActivePool activePool;
        IJpydfToken jpydfToken;
        uint256 troveId;
        uint256 price;
        uint256 avgInterestRate;
        uint256 entireDebt;
        uint256 ICR;
        uint256 newTCR;
        bool newOracleFailureDetected;
    }

    struct LocalVariables_adjustTrove {
        IActivePool activePool;
        IJpydfToken jpydfToken;
        LatestTroveData trove;
        uint256 price;
        uint256 newDebt;
        uint256 newColl;
    }

    struct LocalVariables_setInterestBatchManager {
        ITroveManager troveManager;
        IActivePool activePool;
        ISortedTroves sortedTroves;
        address oldBatchManager;
        LatestTroveData trove;
        LatestBatchData oldBatch;
        LatestBatchData newBatch;
    }

    struct LocalVariables_removeFromBatch {
        ITroveManager troveManager;
        ISortedTroves sortedTroves;
        address batchManager;
        LatestTroveData trove;
        LatestBatchData batch;
        uint256 batchFutureDebt;
        TroveChange batchChange;
    }

    error IsShutDown();
    error TCRNotBelowSCR();
    error ZeroAdjustment();
    error NotOwnerNorInterestManager();
    error TroveInBatch();
    error TroveNotInBatch();
    error InterestNotInRange();
    error BatchInterestRateChangePeriodNotPassed();
    error DelegateInterestRateChangePeriodNotPassed();
    error TroveExists();
    error TroveNotOpen();
    error TroveNotActive();
    error TroveNotZombie();
    error TroveWithZeroDebt();
    error UpfrontFeeTooHigh();
    error ICRBelowMCR();
    error ICRBelowMCRPlusBCR();
    error RepaymentNotMatchingCollWithdrawal();
    error TCRBelowCCR();
    error DebtBelowMin();
    error CollWithdrawalTooHigh();
    error NotEnoughJpydfBalance();
    error InterestRateTooLow();
    error InterestRateTooHigh();
    error InterestRateNotNew();
    error InvalidInterestBatchManager();
    error BatchManagerExists();
    error BatchManagerNotNew();
    error NewFeeNotLower();
    error CallerNotTroveManager();
    error CallerNotPriceFeed();
    error MinGeMax();
    error AnnualManagementFeeTooHigh();
    error MinInterestRateChangePeriodTooLow();
    error NewOracleFailureDetected();
    error BatchSharesRatioTooLow();
    error CallerNotAddressesRegistry();
    error RiskParamsNotFinalized();

    event TroveManagerAddressChanged(address _newTroveManagerAddress);
    event GasPoolAddressChanged(address _gasPoolAddress);
    event CollSurplusPoolAddressChanged(address _collSurplusPoolAddress);
    event SortedTrovesAddressChanged(address _sortedTrovesAddress);
    event JpydfTokenAddressChanged(address _jpydfTokenAddress);

    event ShutDown(uint256 _tcr);

    constructor(IAddressesRegistry _addressesRegistry)
        AddRemoveManagers(_addressesRegistry)
        LiquityBase(_addressesRegistry)
    {
        // This makes impossible to open a trove with zero withdrawn JPYDF
        assert(MIN_DEBT > 0);

        addressesRegistry = _addressesRegistry;
        collToken = _addressesRegistry.collToken();

        WETH = _addressesRegistry.WETH();

        CCR = _addressesRegistry.CCR();
        SCR = _addressesRegistry.SCR();
        MCR = _addressesRegistry.MCR();
        BCR = _addressesRegistry.BCR();

        troveManager = _addressesRegistry.troveManager();
        gasPoolAddress = _addressesRegistry.gasPoolAddress();
        collSurplusPool = _addressesRegistry.collSurplusPool();
        sortedTroves = _addressesRegistry.sortedTroves();
        jpydfToken = _addressesRegistry.jpydfToken();

        emit TroveManagerAddressChanged(address(troveManager));
        emit GasPoolAddressChanged(gasPoolAddress);
        emit CollSurplusPoolAddressChanged(address(collSurplusPool));
        emit SortedTrovesAddressChanged(address(sortedTroves));
        emit JpydfTokenAddressChanged(address(jpydfToken));

        // Allow funds movements between Liquity contracts
        collToken.forceApprove(address(activePool), type(uint256).max);
    }

    function syncRiskParams(uint256 _ccr, uint256 _mcr, uint256 _bcr, uint256 _scr) external override {
        if (msg.sender != address(addressesRegistry)) revert CallerNotAddressesRegistry();

        CCR = _ccr;
        MCR = _mcr;
        BCR = _bcr;
        SCR = _scr;
    }

    // --- Borrower Trove Operations ---

    function openTrove(
        address _owner,
        uint256 _ownerIndex,
        uint256 _collAmount,
        uint256 _jpydfAmount,
        uint256 _upperHint,
        uint256 _lowerHint,
        uint256 _annualInterestRate,
        uint256 _maxUpfrontFee,
        address _addManager,
        address _removeManager,
        address _receiver
    ) external override returns (uint256) {
        _requireValidAnnualInterestRate(_annualInterestRate);

        OpenTroveVars memory vars;

        vars.troveId = _openTrove(
            _owner,
            _ownerIndex,
            _collAmount,
            _jpydfAmount,
            _annualInterestRate,
            address(0),
            0,
            0,
            _maxUpfrontFee,
            _addManager,
            _removeManager,
            _receiver,
            vars.change
        );

        // Set the stored Trove properties and mint the NFT
        troveManager.onOpenTrove(_owner, vars.troveId, vars.change, _annualInterestRate);

        sortedTroves.insert(vars.troveId, _annualInterestRate, _upperHint, _lowerHint);

        return vars.troveId;
    }

    function openTroveAndJoinInterestBatchManager(OpenTroveAndJoinInterestBatchManagerParams calldata _params)
        external
        override
        returns (uint256)
    {
        _requireValidInterestBatchManager(_params.interestBatchManager);

        OpenTroveVars memory vars;
        vars.troveManager = troveManager;

        vars.batch = vars.troveManager.getLatestBatchData(_params.interestBatchManager);

        // We set old weighted values here, as it’s only necessary for batches, so we don’t need to pass them to _openTrove func
        vars.change.batchAccruedManagementFee = vars.batch.accruedManagementFee;
        vars.change.oldWeightedRecordedDebt = vars.batch.weightedRecordedDebt;
        vars.change.oldWeightedRecordedBatchManagementFee = vars.batch.weightedRecordedBatchManagementFee;
        vars.troveId = _openTrove(
            _params.owner,
            _params.ownerIndex,
            _params.collAmount,
            _params.jpydfAmount,
            vars.batch.annualInterestRate,
            _params.interestBatchManager,
            vars.batch.entireDebtWithoutRedistribution,
            vars.batch.annualManagementFee,
            _params.maxUpfrontFee,
            _params.addManager,
            _params.removeManager,
            _params.receiver,
            vars.change
        );

        interestBatchManagerOf[vars.troveId] = _params.interestBatchManager;

        // Set the stored Trove properties and mint the NFT
        vars.troveManager.onOpenTroveAndJoinBatch(
            _params.owner,
            vars.troveId,
            vars.change,
            _params.interestBatchManager,
            vars.batch.entireCollWithoutRedistribution,
            vars.batch.entireDebtWithoutRedistribution
        );

        sortedTroves.insertIntoBatch(
            vars.troveId,
            BatchId.wrap(_params.interestBatchManager),
            vars.batch.annualInterestRate,
            _params.upperHint,
            _params.lowerHint
        );

        return vars.troveId;
    }

    function _openTrove(
        address _owner,
        uint256 _ownerIndex,
        uint256 _collAmount,
        uint256 _jpydfAmount,
        uint256 _annualInterestRate,
        address _interestBatchManager,
        uint256 _batchEntireDebt,
        uint256 _batchManagementAnnualFee,
        uint256 _maxUpfrontFee,
        address _addManager,
        address _removeManager,
        address _receiver,
        TroveChange memory _change
    ) internal returns (uint256) {
        if (!addressesRegistry.riskParamsFinalized()) revert RiskParamsNotFinalized();
        _requireIsNotShutDown();

        LocalVariables_openTrove memory vars;

        // stack too deep not allowing to reuse troveManager from outer functions
        vars.troveManager = troveManager;
        vars.activePool = activePool;
        vars.jpydfToken = jpydfToken;

        vars.price = _requireOraclesLive();

        // --- Checks ---

        vars.troveId = uint256(keccak256(abi.encode(msg.sender, _owner, _ownerIndex)));
        _requireTroveDoesNotExist(vars.troveManager, vars.troveId);

        _change.collIncrease = _collAmount;
        _change.debtIncrease = _jpydfAmount;

        // For simplicity, we ignore the fee when calculating the approx. interest rate
        _change.newWeightedRecordedDebt = (_batchEntireDebt + _change.debtIncrease) * _annualInterestRate;

        vars.avgInterestRate = vars.activePool.getNewApproxAvgInterestRateFromTroveChange(_change);
        _change.upfrontFee = _calcUpfrontFee(_change.debtIncrease, vars.avgInterestRate);
        _requireUserAcceptsUpfrontFee(_change.upfrontFee, _maxUpfrontFee);

        vars.entireDebt = _change.debtIncrease + _change.upfrontFee;
        _requireAtLeastMinDebt(vars.entireDebt);

        vars.ICR = LiquityMath._computeCR(_collAmount, vars.entireDebt, vars.price);

        // Recalculate newWeightedRecordedDebt, now taking into account the upfront fee, and the batch fee if needed
        if (_interestBatchManager == address(0)) {
            _change.newWeightedRecordedDebt = vars.entireDebt * _annualInterestRate;

            // ICR is based on the requested JPYDF amount + upfront fee.
            _requireICRisAboveMCR(vars.ICR);
        } else {
            // old values have been set outside, before calling this function
            _change.newWeightedRecordedDebt = (_batchEntireDebt + vars.entireDebt) * _annualInterestRate;
            _change.newWeightedRecordedBatchManagementFee =
                (_batchEntireDebt + vars.entireDebt) * _batchManagementAnnualFee;

            // ICR is based on the requested JPYDF amount + upfront fee.
            // Troves in a batch have a stronger requirement (MCR+BCR)
            _requireICRisAboveMCRPlusBCR(vars.ICR);
        }

        vars.newTCR = _getNewTCRFromTroveChange(_change, vars.price);
        _requireNewTCRisAboveCCR(vars.newTCR);

        // --- Effects & interactions ---

        // Set add/remove managers
        _setAddManager(vars.troveId, _addManager);
        _setRemoveManagerAndReceiver(vars.troveId, _removeManager, _receiver);

        vars.activePool.mintAggInterestAndAccountForTroveChange(_change, _interestBatchManager);

        // Pull coll tokens from sender and move them to the Active Pool
        _pullCollAndSendToActivePool(vars.activePool, _collAmount);

        // Mint the requested _jpydfAmount to the borrower and mint the gas comp to the GasPool
        vars.jpydfToken.mint(msg.sender, _jpydfAmount);
        IERC20(address(WETH)).safeTransferFrom(msg.sender, gasPoolAddress, ETH_GAS_COMPENSATION);

        return vars.troveId;
    }

    // Send collateral to a trove
    function addColl(uint256 _troveId, uint256 _collAmount) external override {
        ITroveManager troveManagerCached = troveManager;
        _requireTroveIsActive(troveManagerCached, _troveId);

        TroveChange memory troveChange;
        troveChange.collIncrease = _collAmount;

        _adjustTrove(
            troveManagerCached,
            _troveId,
            troveChange,
            0 // _maxUpfrontFee
        );
    }

    // Withdraw collateral from a trove
    function withdrawColl(uint256 _troveId, uint256 _collWithdrawal) external override {
        ITroveManager troveManagerCached = troveManager;
        _requireTroveIsActive(troveManagerCached, _troveId);

        TroveChange memory troveChange;
        troveChange.collDecrease = _collWithdrawal;

        _adjustTrove(
            troveManagerCached,
            _troveId,
            troveChange,
            0 // _maxUpfrontFee
        );
    }

    // Withdraw JPYDF tokens from a trove: mint new JPYDF tokens to the owner, and increase the trove's debt accordingly
    function withdrawJpydf(uint256 _troveId, uint256 _jpydfAmount, uint256 _maxUpfrontFee) external override {
        ITroveManager troveManagerCached = troveManager;
        _requireTroveIsActive(troveManagerCached, _troveId);

        TroveChange memory troveChange;
        troveChange.debtIncrease = _jpydfAmount;
        _adjustTrove(troveManagerCached, _troveId, troveChange, _maxUpfrontFee);
    }

    // Repay JPYDF tokens to a Trove: Burn the repaid JPYDF tokens, and reduce the trove's debt accordingly
    function repayJpydf(uint256 _troveId, uint256 _jpydfAmount) external override {
        ITroveManager troveManagerCached = troveManager;
        _requireTroveIsActive(troveManagerCached, _troveId);

        TroveChange memory troveChange;
        troveChange.debtDecrease = _jpydfAmount;

        _adjustTrove(
            troveManagerCached,
            _troveId,
            troveChange,
            0 // _maxUpfrontFee
        );
    }

    function _initTroveChange(
        TroveChange memory _troveChange,
        uint256 _collChange,
        bool _isCollIncrease,
        uint256 _jpydfChange,
        bool _isDebtIncrease
    ) internal pure {
        if (_isCollIncrease) {
            _troveChange.collIncrease = _collChange;
        } else {
            _troveChange.collDecrease = _collChange;
        }

        if (_isDebtIncrease) {
            _troveChange.debtIncrease = _jpydfChange;
        } else {
            _troveChange.debtDecrease = _jpydfChange;
        }
    }

    function adjustTrove(
        uint256 _troveId,
        uint256 _collChange,
        bool _isCollIncrease,
        uint256 _jpydfChange,
        bool _isDebtIncrease,
        uint256 _maxUpfrontFee
    ) external override {
        ITroveManager troveManagerCached = troveManager;
        _requireTroveIsActive(troveManagerCached, _troveId);

        TroveChange memory troveChange;
        _initTroveChange(troveChange, _collChange, _isCollIncrease, _jpydfChange, _isDebtIncrease);
        _adjustTrove(troveManagerCached, _troveId, troveChange, _maxUpfrontFee);
    }

    function adjustZombieTrove(
        uint256 _troveId,
        uint256 _collChange,
        bool _isCollIncrease,
        uint256 _jpydfChange,
        bool _isDebtIncrease,
        uint256 _upperHint,
        uint256 _lowerHint,
        uint256 _maxUpfrontFee
    ) external override {
        ITroveManager troveManagerCached = troveManager;
        _requireTroveIsZombie(troveManagerCached, _troveId);

        TroveChange memory troveChange;
        _initTroveChange(troveChange, _collChange, _isCollIncrease, _jpydfChange, _isDebtIncrease);
        _adjustTrove(troveManagerCached, _troveId, troveChange, _maxUpfrontFee);

        troveManagerCached.setTroveStatusToActive(_troveId);

        address batchManager = interestBatchManagerOf[_troveId];
        uint256 batchAnnualInterestRate;
        if (batchManager != address(0)) {
            LatestBatchData memory batch = troveManagerCached.getLatestBatchData(batchManager);
            batchAnnualInterestRate = batch.annualInterestRate;
        }
        _reInsertIntoSortedTroves(
            _troveId,
            troveManagerCached.getTroveAnnualInterestRate(_troveId),
            _upperHint,
            _lowerHint,
            batchManager,
            batchAnnualInterestRate
        );
    }

    function adjustTroveInterestRate(
        uint256 _troveId,
        uint256 _newAnnualInterestRate,
        uint256 _upperHint,
        uint256 _lowerHint,
        uint256 _maxUpfrontFee
    ) external {
        _requireIsNotShutDown();

        ITroveManager troveManagerCached = troveManager;

        _requireValidAnnualInterestRate(_newAnnualInterestRate);
        _requireIsNotInBatch(_troveId);
        _requireSenderIsOwnerOrInterestManager(_troveId);
        _requireTroveIsActive(troveManagerCached, _troveId);

        LatestTroveData memory trove = troveManagerCached.getLatestTroveData(_troveId);
        _requireValidDelegateAdjustment(_troveId, trove.lastInterestRateAdjTime, _newAnnualInterestRate);
        _requireAnnualInterestRateIsNew(trove.annualInterestRate, _newAnnualInterestRate);

        uint256 newDebt = trove.entireDebt;

        TroveChange memory troveChange;
        troveChange.appliedRedistJpydfDebtGain = trove.redistJpydfDebtGain;
        troveChange.appliedRedistCollGain = trove.redistCollGain;
        troveChange.newWeightedRecordedDebt = newDebt * _newAnnualInterestRate;
        troveChange.oldWeightedRecordedDebt = trove.weightedRecordedDebt;

        // Apply upfront fee on premature adjustments. It checks the resulting ICR
        if (block.timestamp < trove.lastInterestRateAdjTime + INTEREST_RATE_ADJ_COOLDOWN) {
            newDebt = _applyUpfrontFee(trove.entireColl, newDebt, troveChange, _maxUpfrontFee, false);
        }

        // Recalculate newWeightedRecordedDebt, now taking into account the upfront fee
        troveChange.newWeightedRecordedDebt = newDebt * _newAnnualInterestRate;

        activePool.mintAggInterestAndAccountForTroveChange(troveChange, address(0));

        sortedTroves.reInsert(_troveId, _newAnnualInterestRate, _upperHint, _lowerHint);
        troveManagerCached.onAdjustTroveInterestRate(
            _troveId, trove.entireColl, newDebt, _newAnnualInterestRate, troveChange
        );
    }

    /*
    * _adjustTrove(): Alongside a debt change, this function can perform either a collateral top-up or a collateral withdrawal.
    */
    function _adjustTrove(
        ITroveManager _troveManager,
        uint256 _troveId,
        TroveChange memory _troveChange,
        uint256 _maxUpfrontFee
    ) internal {
        LocalVariables_adjustTrove memory vars;
        bool riskIncreasing = (_troveChange.collDecrease | _troveChange.debtIncrease) != 0;
        // Pure collateral additions and repayments remain available during an oracle pause.
        if (riskIncreasing || hasBeenShutDown) {
            _requireIsNotShutDown();
            vars.price = _requireOraclesLive();
        }

        vars.activePool = activePool;
        vars.jpydfToken = jpydfToken;

        // --- Checks ---

        _requireTroveIsOpen(_troveManager, _troveId);

        address owner = troveNFT.ownerOf(_troveId);
        address receiver = owner; // If it’s a withdrawal, and remove manager privilege is set, a different receiver can be defined

        if (riskIncreasing) {
            receiver = _requireSenderIsOwnerOrRemoveManagerAndGetReceiver(_troveId, owner);
        } else {
            // RemoveManager assumes AddManager, so if the former is set, there's no need to check the latter
            _requireSenderIsOwnerOrAddManager(_troveId, owner);
            // No need to check the type of trove change for two reasons:
            // - If the check above fails, it means sender is not owner, nor AddManager, nor RemoveManager.
            //   An independent 3rd party should not be allowed here.
            // - If it's not collIncrease or debtDecrease, _requireNonZeroAdjustment would revert
        }

        vars.trove = _troveManager.getLatestTroveData(_troveId);

        // When the adjustment is a debt repayment, check it's a valid amount and that the caller has enough JPYDF
        if (_troveChange.debtDecrease > 0) {
            uint256 maxRepayment = vars.trove.entireDebt > MIN_DEBT ? vars.trove.entireDebt - MIN_DEBT : 0;
            if (_troveChange.debtDecrease > maxRepayment) {
                _troveChange.debtDecrease = maxRepayment;
            }
            _requireSufficientJpydfBalance(vars.jpydfToken, msg.sender, _troveChange.debtDecrease);
        }

        _requireNonZeroAdjustment(_troveChange);

        // When the adjustment is a collateral withdrawal, check that it's no more than the Trove's entire collateral
        if (_troveChange.collDecrease > 0) {
            _requireValidCollWithdrawal(vars.trove.entireColl, _troveChange.collDecrease);
        }

        vars.newColl = vars.trove.entireColl + _troveChange.collIncrease - _troveChange.collDecrease;
        vars.newDebt = vars.trove.entireDebt + _troveChange.debtIncrease - _troveChange.debtDecrease;

        address batchManager = interestBatchManagerOf[_troveId];
        bool isTroveInBatch = batchManager != address(0);
        LatestBatchData memory batch;
        uint256 batchFutureDebt;
        if (isTroveInBatch) {
            batch = _troveManager.getLatestBatchData(batchManager);

            batchFutureDebt = batch.entireDebtWithoutRedistribution + vars.trove.redistJpydfDebtGain
                + _troveChange.debtIncrease - _troveChange.debtDecrease;

            _troveChange.appliedRedistJpydfDebtGain = vars.trove.redistJpydfDebtGain;
            _troveChange.appliedRedistCollGain = vars.trove.redistCollGain;
            _troveChange.batchAccruedManagementFee = batch.accruedManagementFee;
            _troveChange.oldWeightedRecordedDebt = batch.weightedRecordedDebt;
            _troveChange.newWeightedRecordedDebt = batchFutureDebt * batch.annualInterestRate;
            _troveChange.oldWeightedRecordedBatchManagementFee = batch.weightedRecordedBatchManagementFee;
            _troveChange.newWeightedRecordedBatchManagementFee = batchFutureDebt * batch.annualManagementFee;
        } else {
            _troveChange.appliedRedistJpydfDebtGain = vars.trove.redistJpydfDebtGain;
            _troveChange.appliedRedistCollGain = vars.trove.redistCollGain;
            _troveChange.oldWeightedRecordedDebt = vars.trove.weightedRecordedDebt;
            _troveChange.newWeightedRecordedDebt = vars.newDebt * vars.trove.annualInterestRate;
        }

        // Pay an upfront fee on debt increases
        if (_troveChange.debtIncrease > 0) {
            uint256 avgInterestRate = vars.activePool.getNewApproxAvgInterestRateFromTroveChange(_troveChange);
            _troveChange.upfrontFee = _calcUpfrontFee(_troveChange.debtIncrease, avgInterestRate);
            _requireUserAcceptsUpfrontFee(_troveChange.upfrontFee, _maxUpfrontFee);

            vars.newDebt += _troveChange.upfrontFee;
            if (isTroveInBatch) {
                batchFutureDebt += _troveChange.upfrontFee;
                // Recalculate newWeightedRecordedDebt, now taking into account the upfront fee
                _troveChange.newWeightedRecordedDebt = batchFutureDebt * batch.annualInterestRate;
                _troveChange.newWeightedRecordedBatchManagementFee = batchFutureDebt * batch.annualManagementFee;
            } else {
                // Recalculate newWeightedRecordedDebt, now taking into account the upfront fee
                _troveChange.newWeightedRecordedDebt = vars.newDebt * vars.trove.annualInterestRate;
            }
        }

        // Make sure the Trove doesn't end up zombie
        // Now the max repayment is capped to stay above MIN_DEBT, so this only applies to adjustZombieTrove
        _requireAtLeastMinDebt(vars.newDebt);

        // Pure repayment/addition improves backing even below MCR/CCR.
        if (riskIncreasing) _requireValidAdjustmentInCurrentMode(_troveChange, vars, isTroveInBatch);

        // --- Effects and interactions ---

        if (isTroveInBatch) {
            _troveManager.onAdjustTroveInsideBatch(
                _troveId,
                vars.newColl,
                vars.newDebt,
                _troveChange,
                batchManager,
                batch.entireCollWithoutRedistribution,
                batch.entireDebtWithoutRedistribution
            );
        } else {
            _troveManager.onAdjustTrove(_troveId, vars.newColl, vars.newDebt, _troveChange);
        }

        vars.activePool.mintAggInterestAndAccountForTroveChange(_troveChange, batchManager);
        _moveTokensFromAdjustment(receiver, _troveChange, vars.jpydfToken, vars.activePool);
    }

    function closeTrove(uint256 _troveId) external override {
        ITroveManager troveManagerCached = troveManager;
        IActivePool activePoolCached = activePool;
        IJpydfToken jpydfTokenCached = jpydfToken;

        // --- Checks ---

        address owner = troveNFT.ownerOf(_troveId);
        address receiver = _requireSenderIsOwnerOrRemoveManagerAndGetReceiver(_troveId, owner);
        _requireTroveIsOpen(troveManagerCached, _troveId);

        LatestTroveData memory trove = troveManagerCached.getLatestTroveData(_troveId);

        // The borrower must repay their entire debt including accrued interest, batch fee and redist. gains
        _requireSufficientJpydfBalance(jpydfTokenCached, msg.sender, trove.entireDebt);

        TroveChange memory troveChange;
        troveChange.appliedRedistJpydfDebtGain = trove.redistJpydfDebtGain;
        troveChange.appliedRedistCollGain = trove.redistCollGain;
        troveChange.collDecrease = trove.entireColl;
        troveChange.debtDecrease = trove.entireDebt;

        address batchManager = interestBatchManagerOf[_troveId];
        LatestBatchData memory batch;
        if (batchManager != address(0)) {
            batch = troveManagerCached.getLatestBatchData(batchManager);
            uint256 batchFutureDebt =
                batch.entireDebtWithoutRedistribution - (trove.entireDebt - trove.redistJpydfDebtGain);
            troveChange.batchAccruedManagementFee = batch.accruedManagementFee;
            troveChange.oldWeightedRecordedDebt = batch.weightedRecordedDebt;
            troveChange.newWeightedRecordedDebt = batchFutureDebt * batch.annualInterestRate;
            troveChange.oldWeightedRecordedBatchManagementFee = batch.weightedRecordedBatchManagementFee;
            troveChange.newWeightedRecordedBatchManagementFee = batchFutureDebt * batch.annualManagementFee;
        } else {
            troveChange.oldWeightedRecordedDebt = trove.weightedRecordedDebt;
            // troveChange.newWeightedRecordedDebt = 0;
        }

        if (!hasBeenShutDown) {
            (uint256 price, bool oracleFailure) = priceFeed.fetchPrice();
            if (oracleFailure) revert NewOracleFailureDetected();
            _requireNewTCRisAboveCCR(_getNewTCRFromTroveChange(troveChange, price));
        }

        troveManagerCached.onCloseTrove(
            _troveId,
            troveChange,
            batchManager,
            batch.entireCollWithoutRedistribution,
            batch.entireDebtWithoutRedistribution
        );

        // If trove is in batch
        if (batchManager != address(0)) {
            // Unlink here in BorrowerOperations
            interestBatchManagerOf[_troveId] = address(0);
        }

        activePoolCached.mintAggInterestAndAccountForTroveChange(troveChange, batchManager);

        // Return ETH gas compensation
        IERC20(address(WETH)).safeTransferFrom(gasPoolAddress, receiver, ETH_GAS_COMPENSATION);
        // Burn the remainder of the Trove's entire debt from the user
        jpydfTokenCached.burn(msg.sender, trove.entireDebt);

        // Send the collateral back to the user
        activePoolCached.sendColl(receiver, trove.entireColl);

        _wipeTroveMappings(_troveId);
    }

    function applyPendingDebt(uint256 _troveId, uint256 _lowerHint, uint256 _upperHint) public {
        _requireIsNotShutDown();

        ITroveManager troveManagerCached = troveManager;

        _requireTroveIsOpen(troveManagerCached, _troveId);

        LatestTroveData memory trove = troveManagerCached.getLatestTroveData(_troveId);
        _requireNonZeroDebt(trove.entireDebt);

        TroveChange memory change;
        change.appliedRedistJpydfDebtGain = trove.redistJpydfDebtGain;
        change.appliedRedistCollGain = trove.redistCollGain;

        address batchManager = interestBatchManagerOf[_troveId];
        LatestBatchData memory batch;

        if (batchManager == address(0)) {
            change.oldWeightedRecordedDebt = trove.weightedRecordedDebt;
            change.newWeightedRecordedDebt = trove.entireDebt * trove.annualInterestRate;
        } else {
            batch = troveManagerCached.getLatestBatchData(batchManager);
            change.batchAccruedManagementFee = batch.accruedManagementFee;
            change.oldWeightedRecordedDebt = batch.weightedRecordedDebt;
            change.newWeightedRecordedDebt =
                (batch.entireDebtWithoutRedistribution + trove.redistJpydfDebtGain) * batch.annualInterestRate;
            change.oldWeightedRecordedBatchManagementFee = batch.weightedRecordedBatchManagementFee;
            change.newWeightedRecordedBatchManagementFee =
                (batch.entireDebtWithoutRedistribution + trove.redistJpydfDebtGain) * batch.annualManagementFee;
        }

        troveManagerCached.onApplyTroveInterest(
            _troveId,
            trove.entireColl,
            trove.entireDebt,
            batchManager,
            batch.entireCollWithoutRedistribution,
            batch.entireDebtWithoutRedistribution,
            change
        );
        activePool.mintAggInterestAndAccountForTroveChange(change, batchManager);

        // If the trove was zombie, and now it’s not anymore, put it back in the list
        if (_checkTroveIsZombie(troveManagerCached, _troveId) && trove.entireDebt >= MIN_DEBT) {
            troveManagerCached.setTroveStatusToActive(_troveId);
            _reInsertIntoSortedTroves(
                _troveId, trove.annualInterestRate, _upperHint, _lowerHint, batchManager, batch.annualInterestRate
            );
        }
    }

    function getInterestIndividualDelegateOf(uint256 _troveId)
        external
        view
        returns (InterestIndividualDelegate memory)
    {
        return interestIndividualDelegateOf[_troveId];
    }

    function setInterestIndividualDelegate(
        uint256 _troveId,
        address _delegate,
        uint128 _minInterestRate,
        uint128 _maxInterestRate,
        // only needed if trove was previously in a batch:
        uint256 _newAnnualInterestRate,
        uint256 _upperHint,
        uint256 _lowerHint,
        uint256 _maxUpfrontFee,
        uint256 _minInterestRateChangePeriod
    ) external {
        _requireIsNotShutDown();
        _requireTroveIsActive(troveManager, _troveId);
        _requireCallerIsBorrower(_troveId);
        _requireValidAnnualInterestRate(_minInterestRate);
        _requireValidAnnualInterestRate(_maxInterestRate);
        // With the check below, it could only be ==
        _requireOrderedRange(_minInterestRate, _maxInterestRate);

        interestIndividualDelegateOf[_troveId] =
            InterestIndividualDelegate(_delegate, _minInterestRate, _maxInterestRate, _minInterestRateChangePeriod);
        // Can’t have both individual delegation and batch manager
        if (interestBatchManagerOf[_troveId] != address(0)) {
            // Not needed, implicitly checked in removeFromBatch
            //_requireValidAnnualInterestRate(_newAnnualInterestRate);
            removeFromBatch(_troveId, _newAnnualInterestRate, _upperHint, _lowerHint, _maxUpfrontFee);
        }
    }

    function removeInterestIndividualDelegate(uint256 _troveId) external {
        _requireCallerIsBorrower(_troveId);
        delete interestIndividualDelegateOf[_troveId];
    }

    function getInterestBatchManager(address _account) external view returns (InterestBatchManager memory) {
        return interestBatchManagers[_account];
    }

    function registerBatchManager(
        uint128 _minInterestRate,
        uint128 _maxInterestRate,
        uint128 _currentInterestRate,
        uint128 _annualManagementFee,
        uint128 _minInterestRateChangePeriod
    ) external {
        _requireIsNotShutDown();
        _requireNonExistentInterestBatchManager(msg.sender);
        _requireValidAnnualInterestRate(_minInterestRate);
        _requireValidAnnualInterestRate(_maxInterestRate);
        // With the check below, it could only be ==
        _requireOrderedRange(_minInterestRate, _maxInterestRate);
        _requireInterestRateInRange(_currentInterestRate, _minInterestRate, _maxInterestRate);
        // Not needed, implicitly checked in the condition above:
        //_requireValidAnnualInterestRate(_currentInterestRate);
        if (_annualManagementFee > MAX_ANNUAL_BATCH_MANAGEMENT_FEE) revert AnnualManagementFeeTooHigh();
        if (_minInterestRateChangePeriod < MIN_INTEREST_RATE_CHANGE_PERIOD) revert MinInterestRateChangePeriodTooLow();

        interestBatchManagers[msg.sender] =
            InterestBatchManager(_minInterestRate, _maxInterestRate, _minInterestRateChangePeriod);

        troveManager.onRegisterBatchManager(msg.sender, _currentInterestRate, _annualManagementFee);
    }

    function lowerBatchManagementFee(uint256 _newAnnualManagementFee) external {
        if (hasBeenShutDown) revert IsShutDown();
        _requireValidInterestBatchManager(msg.sender);

        ITroveManager troveManagerCached = troveManager;

        LatestBatchData memory batch = troveManagerCached.getLatestBatchData(msg.sender);
        if (_newAnnualManagementFee >= batch.annualManagementFee) {
            revert NewFeeNotLower();
        }

        // Lower batch fee on TM
        troveManagerCached.onLowerBatchManagerAnnualFee(
            msg.sender,
            batch.entireCollWithoutRedistribution,
            batch.entireDebtWithoutRedistribution,
            _newAnnualManagementFee
        );

        // active pool mint
        TroveChange memory batchChange;
        batchChange.batchAccruedManagementFee = batch.accruedManagementFee;
        batchChange.oldWeightedRecordedDebt = batch.weightedRecordedDebt;
        batchChange.newWeightedRecordedDebt = batch.entireDebtWithoutRedistribution * batch.annualInterestRate;
        batchChange.oldWeightedRecordedBatchManagementFee = batch.weightedRecordedBatchManagementFee;
        batchChange.newWeightedRecordedBatchManagementFee =
            batch.entireDebtWithoutRedistribution * _newAnnualManagementFee;

        activePool.mintAggInterestAndAccountForTroveChange(batchChange, msg.sender);
    }

    function setBatchManagerAnnualInterestRate(
        uint128 _newAnnualInterestRate,
        uint256 _upperHint,
        uint256 _lowerHint,
        uint256 _maxUpfrontFee
    ) external {
        _requireIsNotShutDown();
        _requireValidInterestBatchManager(msg.sender);
        _requireInterestRateInBatchManagerRange(msg.sender, _newAnnualInterestRate);
        // Not needed, implicitly checked in the condition above:
        //_requireValidAnnualInterestRate(_newAnnualInterestRate);

        ITroveManager troveManagerCached = troveManager;
        IActivePool activePoolCached = activePool;

        LatestBatchData memory batch = troveManagerCached.getLatestBatchData(msg.sender);
        _requireBatchInterestRateChangePeriodPassed(msg.sender, uint256(batch.lastInterestRateAdjTime));

        uint256 newDebt = batch.entireDebtWithoutRedistribution;

        TroveChange memory batchChange;
        batchChange.batchAccruedManagementFee = batch.accruedManagementFee;
        batchChange.oldWeightedRecordedDebt = batch.weightedRecordedDebt;
        batchChange.newWeightedRecordedDebt = newDebt * _newAnnualInterestRate;
        batchChange.oldWeightedRecordedBatchManagementFee = batch.weightedRecordedBatchManagementFee;
        batchChange.newWeightedRecordedBatchManagementFee = newDebt * batch.annualManagementFee;

        // Apply upfront fee on premature adjustments
        if (
            batch.annualInterestRate != _newAnnualInterestRate
                && block.timestamp < batch.lastInterestRateAdjTime + INTEREST_RATE_ADJ_COOLDOWN
        ) {
            uint256 price = _requireOraclesLive();

            uint256 avgInterestRate = activePoolCached.getNewApproxAvgInterestRateFromTroveChange(batchChange);
            batchChange.upfrontFee = _calcUpfrontFee(newDebt, avgInterestRate);
            _requireUserAcceptsUpfrontFee(batchChange.upfrontFee, _maxUpfrontFee);

            newDebt += batchChange.upfrontFee;

            // Recalculate the batch's weighted terms, now taking into account the upfront fee
            batchChange.newWeightedRecordedDebt = newDebt * _newAnnualInterestRate;
            batchChange.newWeightedRecordedBatchManagementFee = newDebt * batch.annualManagementFee;

            // Disallow a premature adjustment if it would result in TCR < CCR
            // (which includes the case when TCR is already below CCR before the adjustment).
            uint256 newTCR = _getNewTCRFromTroveChange(batchChange, price);
            _requireNewTCRisAboveCCR(newTCR);
        }

        activePoolCached.mintAggInterestAndAccountForTroveChange(batchChange, msg.sender);

        // Check batch is not empty, and then reinsert in sorted list
        if (!sortedTroves.isEmptyBatch(BatchId.wrap(msg.sender))) {
            sortedTroves.reInsertBatch(BatchId.wrap(msg.sender), _newAnnualInterestRate, _upperHint, _lowerHint);
        }

        troveManagerCached.onSetBatchManagerAnnualInterestRate(
            msg.sender, batch.entireCollWithoutRedistribution, newDebt, _newAnnualInterestRate, batchChange.upfrontFee
        );
    }

    function setInterestBatchManager(
        uint256 _troveId,
        address _newBatchManager,
        uint256 _upperHint,
        uint256 _lowerHint,
        uint256 _maxUpfrontFee
    ) public override {
        _requireIsNotShutDown();
        LocalVariables_setInterestBatchManager memory vars;
        vars.troveManager = troveManager;
        vars.activePool = activePool;
        vars.sortedTroves = sortedTroves;

        _requireTroveIsActive(vars.troveManager, _troveId);
        _requireCallerIsBorrower(_troveId);
        _requireValidInterestBatchManager(_newBatchManager);
        _requireIsNotInBatch(_troveId);

        interestBatchManagerOf[_troveId] = _newBatchManager;
        // Can’t have both individual delegation and batch manager
        if (interestIndividualDelegateOf[_troveId].account != address(0)) delete interestIndividualDelegateOf[_troveId];

        vars.trove = vars.troveManager.getLatestTroveData(_troveId);
        vars.newBatch = vars.troveManager.getLatestBatchData(_newBatchManager);

        TroveChange memory newBatchTroveChange;
        newBatchTroveChange.appliedRedistJpydfDebtGain = vars.trove.redistJpydfDebtGain;
        newBatchTroveChange.appliedRedistCollGain = vars.trove.redistCollGain;
        newBatchTroveChange.batchAccruedManagementFee = vars.newBatch.accruedManagementFee;
        newBatchTroveChange.oldWeightedRecordedDebt =
            vars.newBatch.weightedRecordedDebt + vars.trove.weightedRecordedDebt;
        newBatchTroveChange.newWeightedRecordedDebt =
            (vars.newBatch.entireDebtWithoutRedistribution + vars.trove.entireDebt) * vars.newBatch.annualInterestRate;

        // An upfront fee is always charged upon joining a batch to ensure that borrowers can not game the fee logic
        // and gain free interest rate updates (e.g. if they also manage the batch they joined)
        // It checks the resulting ICR
        vars.trove.entireDebt =
            _applyUpfrontFee(vars.trove.entireColl, vars.trove.entireDebt, newBatchTroveChange, _maxUpfrontFee, true);

        // Recalculate newWeightedRecordedDebt, now taking into account the upfront fee
        newBatchTroveChange.newWeightedRecordedDebt =
            (vars.newBatch.entireDebtWithoutRedistribution + vars.trove.entireDebt) * vars.newBatch.annualInterestRate;

        // Add batch fees
        newBatchTroveChange.oldWeightedRecordedBatchManagementFee = vars.newBatch.weightedRecordedBatchManagementFee;
        newBatchTroveChange.newWeightedRecordedBatchManagementFee =
            (vars.newBatch.entireDebtWithoutRedistribution + vars.trove.entireDebt) * vars.newBatch.annualManagementFee;
        vars.activePool.mintAggInterestAndAccountForTroveChange(newBatchTroveChange, _newBatchManager);

        vars.troveManager.onSetInterestBatchManager(
            ITroveManager.OnSetInterestBatchManagerParams({
                troveId: _troveId,
                troveColl: vars.trove.entireColl,
                troveDebt: vars.trove.entireDebt,
                troveChange: newBatchTroveChange,
                newBatchAddress: _newBatchManager,
                newBatchColl: vars.newBatch.entireCollWithoutRedistribution,
                newBatchDebt: vars.newBatch.entireDebtWithoutRedistribution
            })
        );

        vars.sortedTroves.remove(_troveId);
        vars.sortedTroves.insertIntoBatch(
            _troveId, BatchId.wrap(_newBatchManager), vars.newBatch.annualInterestRate, _upperHint, _lowerHint
        );
    }

    function kickFromBatch(uint256 _troveId, uint256 _upperHint, uint256 _lowerHint) external override {
        _removeFromBatch({
            _troveId: _troveId,
            _newAnnualInterestRate: 0, // ignored when kicking
            _upperHint: _upperHint,
            _lowerHint: _lowerHint,
            _maxUpfrontFee: 0, // will use the batch's existing interest rate, so no fee
            _kick: true
        });
    }

    function removeFromBatch(
        uint256 _troveId,
        uint256 _newAnnualInterestRate,
        uint256 _upperHint,
        uint256 _lowerHint,
        uint256 _maxUpfrontFee
    ) public override {
        _removeFromBatch({
            _troveId: _troveId,
            _newAnnualInterestRate: _newAnnualInterestRate,
            _upperHint: _upperHint,
            _lowerHint: _lowerHint,
            _maxUpfrontFee: _maxUpfrontFee,
            _kick: false
        });
    }

    function _removeFromBatch(
        uint256 _troveId,
        uint256 _newAnnualInterestRate,
        uint256 _upperHint,
        uint256 _lowerHint,
        uint256 _maxUpfrontFee,
        bool _kick
    ) internal {
        _requireIsNotShutDown();

        LocalVariables_removeFromBatch memory vars;
        vars.troveManager = troveManager;
        vars.sortedTroves = sortedTroves;

        if (_kick) {
            _requireTroveIsOpen(vars.troveManager, _troveId);
        } else {
            _requireTroveIsActive(vars.troveManager, _troveId);
            _requireCallerIsBorrower(_troveId);
            _requireValidAnnualInterestRate(_newAnnualInterestRate);
        }

        vars.batchManager = _requireIsInBatch(_troveId);
        vars.trove = vars.troveManager.getLatestTroveData(_troveId);
        vars.batch = vars.troveManager.getLatestBatchData(vars.batchManager);

        if (_kick) {
            if (vars.batch.totalDebtShares * MAX_BATCH_SHARES_RATIO >= vars.batch.entireDebtWithoutRedistribution) {
                revert BatchSharesRatioTooLow();
            }
            _newAnnualInterestRate = vars.batch.annualInterestRate;
        }

        delete interestBatchManagerOf[_troveId];

        if (!_checkTroveIsZombie(vars.troveManager, _troveId)) {
            // Remove trove from Batch in SortedTroves
            vars.sortedTroves.removeFromBatch(_troveId);
            // Reinsert as single trove
            vars.sortedTroves.insert(_troveId, _newAnnualInterestRate, _upperHint, _lowerHint);
        }

        vars.batchFutureDebt =
            vars.batch.entireDebtWithoutRedistribution - (vars.trove.entireDebt - vars.trove.redistJpydfDebtGain);

        vars.batchChange.appliedRedistJpydfDebtGain = vars.trove.redistJpydfDebtGain;
        vars.batchChange.appliedRedistCollGain = vars.trove.redistCollGain;
        vars.batchChange.batchAccruedManagementFee = vars.batch.accruedManagementFee;
        vars.batchChange.oldWeightedRecordedDebt = vars.batch.weightedRecordedDebt;
        vars.batchChange.newWeightedRecordedDebt =
            vars.batchFutureDebt * vars.batch.annualInterestRate + vars.trove.entireDebt * _newAnnualInterestRate;

        // Apply upfront fee on premature adjustments. It checks the resulting ICR
        if (
            vars.batch.annualInterestRate != _newAnnualInterestRate
                && block.timestamp < vars.trove.lastInterestRateAdjTime + INTEREST_RATE_ADJ_COOLDOWN
        ) {
            vars.trove.entireDebt =
                _applyUpfrontFee(vars.trove.entireColl, vars.trove.entireDebt, vars.batchChange, _maxUpfrontFee, false);
        }

        // Recalculate newWeightedRecordedDebt, now taking into account the upfront fee
        vars.batchChange.newWeightedRecordedDebt =
            vars.batchFutureDebt * vars.batch.annualInterestRate + vars.trove.entireDebt * _newAnnualInterestRate;
        // Add batch fees
        vars.batchChange.oldWeightedRecordedBatchManagementFee = vars.batch.weightedRecordedBatchManagementFee;
        vars.batchChange.newWeightedRecordedBatchManagementFee = vars.batchFutureDebt * vars.batch.annualManagementFee;

        activePool.mintAggInterestAndAccountForTroveChange(vars.batchChange, vars.batchManager);

        vars.troveManager.onRemoveFromBatch(
            _troveId,
            vars.trove.entireColl,
            vars.trove.entireDebt,
            vars.batchChange,
            vars.batchManager,
            vars.batch.entireCollWithoutRedistribution,
            vars.batch.entireDebtWithoutRedistribution,
            _newAnnualInterestRate
        );
    }

    function switchBatchManager(
        uint256 _troveId,
        uint256 _removeUpperHint,
        uint256 _removeLowerHint,
        address _newBatchManager,
        uint256 _addUpperHint,
        uint256 _addLowerHint,
        uint256 _maxUpfrontFee
    ) external override {
        address oldBatchManager = _requireIsInBatch(_troveId);
        _requireNewInterestBatchManager(oldBatchManager, _newBatchManager);

        LatestBatchData memory oldBatch = troveManager.getLatestBatchData(oldBatchManager);

        removeFromBatch(_troveId, oldBatch.annualInterestRate, _removeUpperHint, _removeLowerHint, 0);
        setInterestBatchManager(_troveId, _newBatchManager, _addUpperHint, _addLowerHint, _maxUpfrontFee);
    }

    function _applyUpfrontFee(
        uint256 _troveEntireColl,
        uint256 _troveEntireDebt,
        TroveChange memory _troveChange,
        uint256 _maxUpfrontFee,
        bool _isTroveInBatch
    ) internal returns (uint256) {
        uint256 price = _requireOraclesLive();

        uint256 avgInterestRate = activePool.getNewApproxAvgInterestRateFromTroveChange(_troveChange);
        _troveChange.upfrontFee = _calcUpfrontFee(_troveEntireDebt, avgInterestRate);
        _requireUserAcceptsUpfrontFee(_troveChange.upfrontFee, _maxUpfrontFee);

        _troveEntireDebt += _troveChange.upfrontFee;

        // ICR is based on the requested JPYDF amount + upfront fee.
        uint256 newICR = LiquityMath._computeCR(_troveEntireColl, _troveEntireDebt, price);
        if (_isTroveInBatch) {
            _requireICRisAboveMCRPlusBCR(newICR);
        } else {
            _requireICRisAboveMCR(newICR);
        }

        // Disallow a premature adjustment if it would result in TCR < CCR
        // (which includes the case when TCR is already below CCR before the adjustment).
        uint256 newTCR = _getNewTCRFromTroveChange(_troveChange, price);
        _requireNewTCRisAboveCCR(newTCR);

        return _troveEntireDebt;
    }

    function _calcUpfrontFee(uint256 _debt, uint256 _avgInterestRate) internal pure returns (uint256) {
        return _calcInterest(_debt * _avgInterestRate, UPFRONT_INTEREST_PERIOD);
    }

    // Call from TM to clean state here
    function onLiquidateTrove(uint256 _troveId) external {
        _requireCallerIsTroveManager();

        _wipeTroveMappings(_troveId);
    }

    function _wipeTroveMappings(uint256 _troveId) internal {
        delete interestIndividualDelegateOf[_troveId];
        delete interestBatchManagerOf[_troveId];
        _wipeAddRemoveManagers(_troveId);
    }

    /**
     * Claim remaining collateral from a liquidation with ICR exceeding the liquidation penalty
     */
    function claimCollateral() external override {
        // send coll from CollSurplus Pool to owner
        collSurplusPool.claimColl(msg.sender);
    }

    function shutdown() external {
        if (hasBeenShutDown) revert IsShutDown();

        uint256 totalColl = getEntireBranchColl();
        uint256 totalDebt = getEntireBranchDebt();
        (uint256 price, bool newOracleFailureDetected) = priceFeed.fetchPrice();
        // Reject failed quotes, including aged JPY provenance, without permanent shutdown.
        if (newOracleFailureDetected) return;

        // Otherwise, proceed with the TCR check:
        uint256 TCR = LiquityMath._computeCR(totalColl, totalDebt, price);
        if (TCR >= SCR) revert TCRNotBelowSCR();

        _applyShutdown();

        emit ShutDown(TCR);
    }

    // Not technically a "Borrower op", but seems best placed here given current shutdown logic.
    function shutdownFromOracleFailure() external {
        _requireCallerIsPriceFeed();

        // No-op rather than revert here, so that the outer function call which fetches the price does not revert
        // if the system is already in temporary or permanent shutdown.
        if (hasBeenShutDown || isOracleFailureShutdown) return;

        isOracleFailureShutdown = true;
    }

    function resumeFromOracleFailure() external {
        _requireCallerIsPriceFeed();
        isOracleFailureShutdown = false;
    }

    function _applyShutdown() internal {
        activePool.mintAggInterest();
        isOracleFailureShutdown = false;
        hasBeenShutDown = true;
        troveManager.shutdown();
    }

    // --- Helper functions ---

    function _reInsertIntoSortedTroves(
        uint256 _troveId,
        uint256 _troveAnnualInterestRate,
        uint256 _upperHint,
        uint256 _lowerHint,
        address _batchManager,
        uint256 _batchAnnualInterestRate
    ) internal {
        // If it was in a batch, we need to put it back, otherwise we insert it normally
        if (_batchManager == address(0)) {
            sortedTroves.insert(_troveId, _troveAnnualInterestRate, _upperHint, _lowerHint);
        } else {
            sortedTroves.insertIntoBatch(
                _troveId, BatchId.wrap(_batchManager), _batchAnnualInterestRate, _upperHint, _lowerHint
            );
        }
    }

    // This function mints the JPYDF corresponding to the borrower's chosen debt increase
    // (it does not mint the accrued interest).
    function _moveTokensFromAdjustment(
        address withdrawalReceiver,
        TroveChange memory _troveChange,
        IJpydfToken _jpydfToken,
        IActivePool _activePool
    ) internal {
        if (_troveChange.debtIncrease > 0) {
            _jpydfToken.mint(withdrawalReceiver, _troveChange.debtIncrease);
        } else if (_troveChange.debtDecrease > 0) {
            _jpydfToken.burn(msg.sender, _troveChange.debtDecrease);
        }

        if (_troveChange.collIncrease > 0) {
            // Pull coll tokens from sender and move them to the Active Pool
            _pullCollAndSendToActivePool(_activePool, _troveChange.collIncrease);
        } else if (_troveChange.collDecrease > 0) {
            // Pull Coll from Active Pool and decrease its recorded Coll balance
            _activePool.sendColl(withdrawalReceiver, _troveChange.collDecrease);
        }
    }

    function _pullCollAndSendToActivePool(IActivePool _activePool, uint256 _amount) internal {
        // Send Coll tokens from sender to active pool
        collToken.safeTransferFrom(msg.sender, address(_activePool), _amount);
        // Make sure Active Pool accountancy is right
        _activePool.accountForReceivedColl(_amount);
    }

    function checkBatchManagerExists(address _batchManager) external view returns (bool) {
        return interestBatchManagers[_batchManager].maxInterestRate > 0;
    }

    // --- 'Require' wrapper functions ---

    function _requireIsNotShutDown() internal view {
        if (hasBeenShutDown || isOracleFailureShutdown) {
            revert IsShutDown();
        }
    }

    function _requireNonZeroAdjustment(TroveChange memory _troveChange) internal pure {
        if (
            (_troveChange.collIncrease | _troveChange.collDecrease | _troveChange.debtIncrease | _troveChange.debtDecrease)
                == 0
        ) {
            revert ZeroAdjustment();
        }
    }

    function _requireSenderIsOwnerOrInterestManager(uint256 _troveId) internal view {
        address owner = troveNFT.ownerOf(_troveId);
        if (msg.sender != owner && msg.sender != interestIndividualDelegateOf[_troveId].account) {
            revert NotOwnerNorInterestManager();
        }
    }

    function _requireValidDelegateAdjustment(
        uint256 _troveId,
        uint256 _lastInterestRateAdjTime,
        uint256 _annualInterestRate
    ) internal view {
        InterestIndividualDelegate memory individualDelegate = interestIndividualDelegateOf[_troveId];
        // We have previously checked that sender is either owner or delegate
        // If it’s owner, this restriction doesn’t apply
        if (individualDelegate.account == msg.sender) {
            _requireInterestRateInRange(
                _annualInterestRate, individualDelegate.minInterestRate, individualDelegate.maxInterestRate
            );
            _requireDelegateInterestRateChangePeriodPassed(
                _lastInterestRateAdjTime, individualDelegate.minInterestRateChangePeriod
            );
        }
    }

    function _requireIsNotInBatch(uint256 _troveId) internal view {
        if (interestBatchManagerOf[_troveId] != address(0)) {
            revert TroveInBatch();
        }
    }

    function _requireIsInBatch(uint256 _troveId) internal view returns (address) {
        address batchManager = interestBatchManagerOf[_troveId];
        if (batchManager == address(0)) {
            revert TroveNotInBatch();
        }

        return batchManager;
    }

    function _requireTroveDoesNotExist(ITroveManager _troveManager, uint256 _troveId) internal view {
        ITroveManager.Status status = _troveManager.getTroveStatus(_troveId);
        if (status != ITroveManager.Status.nonExistent) {
            revert TroveExists();
        }
    }

    function _requireTroveIsOpen(ITroveManager _troveManager, uint256 _troveId) internal view {
        ITroveManager.Status status = _troveManager.getTroveStatus(_troveId);
        if (status != ITroveManager.Status.active && status != ITroveManager.Status.zombie) {
            revert TroveNotOpen();
        }
    }

    function _requireTroveIsActive(ITroveManager _troveManager, uint256 _troveId) internal view {
        ITroveManager.Status status = _troveManager.getTroveStatus(_troveId);
        if (status != ITroveManager.Status.active) {
            revert TroveNotActive();
        }
    }

    function _requireTroveIsZombie(ITroveManager _troveManager, uint256 _troveId) internal view {
        if (!_checkTroveIsZombie(_troveManager, _troveId)) {
            revert TroveNotZombie();
        }
    }

    function _checkTroveIsZombie(ITroveManager _troveManager, uint256 _troveId) internal view returns (bool) {
        ITroveManager.Status status = _troveManager.getTroveStatus(_troveId);
        return status == ITroveManager.Status.zombie;
    }

    function _requireNonZeroDebt(uint256 _troveDebt) internal pure {
        if (_troveDebt == 0) {
            revert TroveWithZeroDebt();
        }
    }

    function _requireUserAcceptsUpfrontFee(uint256 _fee, uint256 _maxFee) internal pure {
        if (_fee > _maxFee) {
            revert UpfrontFeeTooHigh();
        }
    }

    function _requireValidAdjustmentInCurrentMode(
        TroveChange memory _troveChange,
        LocalVariables_adjustTrove memory _vars,
        bool _isTroveInBatch
    ) internal view {
        uint256 price = _vars.price;
        uint256 newICR = LiquityMath._computeCR(_vars.newColl, _vars.newDebt, price);
        /*
        * Below Critical Threshold, it is not permitted:
        *
        * - Borrowing, unless it brings TCR up to CCR again
        * - Collateral withdrawal except accompanied by a debt repayment of at least the same value
        *
        * In Normal Mode, ensure:
        *
        * - The adjustment won't pull the TCR below CCR
        *
        * In Both cases:
        * - The new ICR is above MCR, or MCR+BCR if a batched trove
        */

        if (_isTroveInBatch) {
            _requireICRisAboveMCRPlusBCR(newICR);
        } else {
            _requireICRisAboveMCR(newICR);
        }

        uint256 newTCR = _getNewTCRFromTroveChange(_troveChange, price);
        if (_checkBelowCriticalThreshold(price, CCR)) {
            _requireNoBorrowingUnlessNewTCRisAboveCCR(_troveChange.debtIncrease, newTCR);
            _requireDebtRepaymentGeCollWithdrawal(_troveChange, price);
        } else {
            // if Normal Mode
            _requireNewTCRisAboveCCR(newTCR);
        }
    }

    function _requireICRisAboveMCR(uint256 _newICR) internal view {
        if (_newICR < MCR) {
            revert ICRBelowMCR();
        }
    }

    function _requireICRisAboveMCRPlusBCR(uint256 _newICR) internal view {
        if (_newICR < MCR + BCR) {
            revert ICRBelowMCRPlusBCR();
        }
    }

    function _requireNoBorrowingUnlessNewTCRisAboveCCR(uint256 _debtIncrease, uint256 _newTCR) internal view {
        if (_debtIncrease > 0 && _newTCR < CCR) {
            revert TCRBelowCCR();
        }
    }

    function _requireDebtRepaymentGeCollWithdrawal(TroveChange memory _troveChange, uint256 _price) internal pure {
        if ((_troveChange.debtDecrease * DECIMAL_PRECISION < _troveChange.collDecrease * _price)) {
            revert RepaymentNotMatchingCollWithdrawal();
        }
    }

    function _requireNewTCRisAboveCCR(uint256 _newTCR) internal view {
        if (_newTCR < CCR) {
            revert TCRBelowCCR();
        }
    }

    function _requireAtLeastMinDebt(uint256 _debt) internal pure {
        if (_debt < MIN_DEBT) {
            revert DebtBelowMin();
        }
    }

    function _requireValidCollWithdrawal(uint256 _currentColl, uint256 _collWithdrawal) internal pure {
        if (_collWithdrawal > _currentColl) {
            revert CollWithdrawalTooHigh();
        }
    }

    function _requireSufficientJpydfBalance(IJpydfToken _jpydfToken, address _borrower, uint256 _debtRepayment)
        internal
        view
    {
        if (_jpydfToken.balanceOf(_borrower) < _debtRepayment) {
            revert NotEnoughJpydfBalance();
        }
    }

    function _requireValidAnnualInterestRate(uint256 _annualInterestRate) internal pure {
        if (_annualInterestRate < MIN_ANNUAL_INTEREST_RATE) {
            revert InterestRateTooLow();
        }
        if (_annualInterestRate > MAX_ANNUAL_INTEREST_RATE) {
            revert InterestRateTooHigh();
        }
    }

    function _requireAnnualInterestRateIsNew(uint256 _oldAnnualInterestRate, uint256 _newAnnualInterestRate)
        internal
        pure
    {
        if (_oldAnnualInterestRate == _newAnnualInterestRate) {
            revert InterestRateNotNew();
        }
    }

    function _requireOrderedRange(uint256 _minInterestRate, uint256 _maxInterestRate) internal pure {
        if (_minInterestRate >= _maxInterestRate) revert MinGeMax();
    }

    function _requireInterestRateInBatchManagerRange(address _interestBatchManagerAddress, uint256 _annualInterestRate)
        internal
        view
    {
        InterestBatchManager memory interestBatchManager = interestBatchManagers[_interestBatchManagerAddress];
        _requireInterestRateInRange(
            _annualInterestRate, interestBatchManager.minInterestRate, interestBatchManager.maxInterestRate
        );
    }

    function _requireInterestRateInRange(
        uint256 _annualInterestRate,
        uint256 _minInterestRate,
        uint256 _maxInterestRate
    ) internal pure {
        if (_minInterestRate > _annualInterestRate || _annualInterestRate > _maxInterestRate) {
            revert InterestNotInRange();
        }
    }

    function _requireBatchInterestRateChangePeriodPassed(
        address _interestBatchManagerAddress,
        uint256 _lastInterestRateAdjTime
    ) internal view {
        InterestBatchManager memory interestBatchManager = interestBatchManagers[_interestBatchManagerAddress];
        if (block.timestamp < _lastInterestRateAdjTime + uint256(interestBatchManager.minInterestRateChangePeriod)) {
            revert BatchInterestRateChangePeriodNotPassed();
        }
    }

    function _requireDelegateInterestRateChangePeriodPassed(
        uint256 _lastInterestRateAdjTime,
        uint256 _minInterestRateChangePeriod
    ) internal view {
        if (block.timestamp < _lastInterestRateAdjTime + _minInterestRateChangePeriod) {
            revert DelegateInterestRateChangePeriodNotPassed();
        }
    }

    function _requireValidInterestBatchManager(address _interestBatchManagerAddress) internal view {
        if (interestBatchManagers[_interestBatchManagerAddress].maxInterestRate == 0) {
            revert InvalidInterestBatchManager();
        }
    }

    function _requireNonExistentInterestBatchManager(address _interestBatchManagerAddress) internal view {
        if (interestBatchManagers[_interestBatchManagerAddress].maxInterestRate > 0) {
            revert BatchManagerExists();
        }
    }

    function _requireNewInterestBatchManager(address _oldBatchManagerAddress, address _newBatchManagerAddress)
        internal
        pure
    {
        if (_oldBatchManagerAddress == _newBatchManagerAddress) {
            revert BatchManagerNotNew();
        }
    }

    function _requireCallerIsTroveManager() internal view {
        if (msg.sender != address(troveManager)) {
            revert CallerNotTroveManager();
        }
    }

    function _requireCallerIsPriceFeed() internal view {
        if (msg.sender != address(priceFeed)) {
            revert CallerNotPriceFeed();
        }
    }

    function _requireOraclesLive() internal returns (uint256) {
        (uint256 price, bool newOracleFailureDetected) = priceFeed.fetchPrice();
        if (newOracleFailureDetected) {
            revert NewOracleFailureDetected();
        }

        return price;
    }

    // --- ICR and TCR getters ---

    function _getNewTCRFromTroveChange(TroveChange memory _troveChange, uint256 _price)
        internal
        view
        returns (uint256 newTCR)
    {
        uint256 totalColl = getEntireBranchColl();
        totalColl += _troveChange.collIncrease;
        totalColl -= _troveChange.collDecrease;

        uint256 totalDebt = getEntireBranchDebt();
        totalDebt += _troveChange.debtIncrease;
        totalDebt += _troveChange.upfrontFee;
        totalDebt -= _troveChange.debtDecrease;

        newTCR = LiquityMath._computeCR(totalColl, totalDebt, _price);
    }
}
"
    },
    "src/CollSurplusPool.sol": {
      "content": "// SPDX-License-Identifier: BUSL-1.1

pragma solidity 0.8.24;

import "openzeppelin-contracts/contracts/token/ERC20/utils/SafeERC20.sol";

import "./Interfaces/ICollSurplusPool.sol";
import "./Interfaces/IAddressesRegistry.sol";

contract CollSurplusPool is ICollSurplusPool {
    using SafeERC20 for IERC20;

    string public constant NAME = "CollSurplusPool";

    IERC20 public immutable collToken;
    address public immutable borrowerOperationsAddress;
    address public immutable troveManagerAddress;

    // deposited ether tracker
    uint256 internal collBalance;
    // Collateral surplus claimable by trove owners
    mapping(address => uint256) internal balances;

    // --- Events ---

    event BorrowerOperationsAddressChanged(address _newBorrowerOperationsAddress);
    event TroveManagerAddressChanged(address _newTroveManagerAddress);

    event CollBalanceUpdated(address indexed _account, uint256 _newBalance);
    event CollSent(address indexed _to, uint256 _amount);

    constructor(IAddressesRegistry _addressesRegistry) {
        collToken = _addressesRegistry.collToken();
        borrowerOperationsAddress = address(_addressesRegistry.borrowerOperations());
        troveManagerAddress = address(_addressesRegistry.troveManager());

        emit BorrowerOperationsAddressChanged(borrowerOperationsAddress);
        emit TroveManagerAddressChanged(troveManagerAddress);
    }

    /* Returns the collBalance state variable
       Not necessarily equal to the raw coll balance - coll can be forcibly sent to contracts. */
    function getCollBalance() external view override returns (uint256) {
        return collBalance;
    }

    function getCollateral(address _account) external view override returns (uint256) {
        return balances[_account];
    }

    // --- Pool functionality ---

    function accountSurplus(address _account, uint256 _amount) external override {
        _requireCallerIsTroveManager();

        uint256 newAmount = balances[_account] + _amount;
        balances[_account] = newAmount;
        collBalance = collBalance + _amount;

        emit CollBalanceUpdated(_account, newAmount);
    }

    function claimColl(address _account) external override {
        _requireCallerIsBorrowerOperations();
        uint256 claimableColl = balances[_account];
        require(claimableColl > 0, "CollSurplusPool: No collateral available to claim");

        balances[_account] = 0;
        emit CollBalanceUpdated(_account, 0);

        collBalance = collBalance - claimableColl;
        emit CollSent(_account, claimableColl);

        collToken.safeTransfer(_account, claimableColl);
    }

    // --- 'require' functions ---

    function _requireCallerIsBorrowerOperations() internal view {
        require(msg.sender == borrowerOperationsAddress, "CollSurplusPool: Caller is not Borrower Operations");
    }

    function _requireCallerIsTroveManager() internal view {
        require(msg.sender == troveManagerAddress, "CollSurplusPool: Caller is not TroveManager");
    }
}
"
    },
    "src/CollateralRegistry.sol": {
      "content": "// SPDX-License-Identifier: BUSL-1.1

pragma solidity 0.8.24;

import "openzeppelin-contracts/contracts/token/ERC20/extensions/IERC20Metadata.sol";

import "./Interfaces/ITroveManager.sol";
import "./Interfaces/IJpydfToken.sol";
import "./Dependencies/Constants.sol";
import "./Dependencies/LiquityMath.sol";

import "./Interfaces/ICollateralRegistry.sol";

contract CollateralRegistry is ICollateralRegistry {
    // See: https://github.com/ethereum/solidity/issues/12587
    uint256 public immutable totalCollaterals;

    IERC20Metadata internal immutable token0;
    IERC20Metadata internal immutable token1;
    IERC20Metadata internal immutable token2;
    IERC20Metadata internal immutable token3;
    IERC20Metadata internal immutable token4;
    IERC20Metadata internal immutable token5;
    IERC20Metadata internal immutable token6;
    IERC20Metadata internal immutable token7;
    IERC20Metadata internal immutable token8;
    IERC20Metadata internal immutable token9;

    ITroveManager internal immutable troveManager0;
    ITroveManager internal immutable troveManager1;
    ITroveManager internal immutable troveManager2;
    ITroveManager internal immutable troveManager3;
    ITroveManager internal immutable troveManager4;
    ITroveManager internal immutable troveManager5;
    ITroveManager internal immutable troveManager6;
    ITroveManager internal immutable troveManager7;
    ITroveManager internal immutable troveManager8;
    ITroveManager internal immutable troveManager9;

    IJpydfToken public immutable jpydfToken;

    uint256 public baseRate;

    // The timestamp of the latest fee operation (redemption or new JPYDF issuance)
    uint256 public lastFeeOperationTime = block.timestamp;

    event BaseRateUpdated(uint256 _baseRate);
    event LastFeeOpTimeUpdated(uint256 _lastFeeOpTime);

    constructor(IJpydfToken _jpydfToken, IERC20Metadata[] memory _tokens, ITroveManager[] memory _troveManagers) {
        uint256 numTokens = _tokens.length;
        require(numTokens > 0, "Collateral list cannot be empty");
        require(numTokens <= 10, "Collateral list too long");
        totalCollaterals = numTokens;

        jpydfToken = _jpydfToken;

        token0 = _tokens[0];
        token1 = numTokens > 1 ? _tokens[1] : IERC20Metadata(address(0));
        token2 = numTokens > 2 ? _tokens[2] : IERC20Metadata(address(0));
        token3 = numTokens > 3 ? _tokens[3] : IERC20Metadata(address(0));
        token4 = numTokens > 4 ? _tokens[4] : IERC20Metadata(address(0));
        token5 = numTokens > 5 ? _tokens[5] : IERC20Metadata(address(0));
        token6 = numTokens > 6 ? _tokens[6] : IERC20Metadata(address(0));
        token7 = numTokens > 7 ? _tokens[7] : IERC20Metadata(address(0));
        token8 = numTokens > 8 ? _tokens[8] : IERC20Metadata(address(0));
        token9 = numTokens > 9 ? _tokens[9] : IERC20Metadata(address(0));

        troveManager0 = _troveManagers[0];
        troveManager1 = numTokens > 1 ? _troveManagers[1] : ITroveManager(address(0));
        troveManager2 = numTokens > 2 ? _troveManagers[2] : ITroveManager(address(0));
        troveManager3 = numTokens > 3 ? _troveManagers[3] : ITroveManager(address(0));
        troveManager4 = numTokens > 4 ? _troveManagers[4] : ITroveManager(address(0));
        troveManager5 = numTokens > 5 ? _troveManagers[5] : ITroveManager(address(0));
        troveManager6 = numTokens > 6 ? _troveManagers[6] : ITroveManager(address(0));
        troveManager7 = numTokens > 7 ? _troveManagers[7] : ITroveManager(address(0));
        troveManager8 = numTokens > 8 ? _troveManagers[8] : ITroveManager(address(0));
        troveManager9 = numTokens > 9 ? _troveManagers[9] : ITroveManager(address(0));

        // Initialize the baseRate state variable
        baseRate = INITIAL_BASE_RATE;
        emit BaseRateUpdated(INITIAL_BASE_RATE);
    }

    struct RedemptionTotals {
        uint256 numCollaterals;
        uint256 jpydfSupplyAtStart;
        uint256 unbacked;
        uint256 redeemedAmount;
    }

    function redeemCollateral(uint256 _jpydfAmount, uint256 _maxIterationsPerCollateral, uint256 _maxFeePercentage)
        external
    {
        _requireValidMaxFeePercentage(_maxFeePercentage);
        _requireAmountGreaterThanZero(_jpydfAmount);

        RedemptionTotals memory totals;

        totals.numCollaterals = totalCollaterals;
        uint256[] memory unbackedPortions = new uint256[](totals.numCollaterals);
        uint256[] memory prices = new uint256[](totals.numCollaterals);

        // Gather and accumulate unbacked portions
        for (uint256 index = 0; index < totals.numCollaterals; index++) {
            ITroveManager troveManager = getTroveManager(index);
            (uint256 unbackedPortion, uint256 price, bool redeemable) =
                troveManager.getUnbackedPortionPriceAndRedeemability();
            prices[index] = price;
            if (redeemable) {
                totals.unbacked += unbackedPortion;
                unbackedPortions[index] = unbackedPortion;
            }
        }

        // There’s an unlikely scenario where all the normally redeemable branches (i.e. having TCR > SCR) have 0 unbacked
        // In that case, we redeem proportionally to branch size
        if (totals.unbacked == 0) {
            unbackedPortions = new uint256[](totals.numCollaterals);
            for (uint256 index = 0; index < totals.numCollaterals; index++) {
                ITroveManager troveManager = getTroveManager(index);
                (,, bool redeemable) = troveManager.getUnbackedPortionPriceAndRedeemability();
                if (redeemable) {
                    uint256 unbackedPortion = troveManager.getEntireBranchDebt();
                    totals.unbacked += unbackedPortion;
                    unbackedPortions[index] = unbackedPortion;
                }
            }
        } else {
            // Don't allow redeeming more than the total unbacked in one go, as that would result in a disproportionate
            // redemption (see CS-JPYDF-013). Instead, truncate the redemption to total unbacked. If this happens, the
            // redeemer can call `redeemCollateral()` a second time to redeem the remainder of their JPYDF.
            if (_jpydfAmount > totals.unbacked) {
                _jpydfAmount = totals.unbacked;
            }
        }

        totals.jpydfSupplyAtStart = jpydfToken.totalSupply();
        // Decay the baseRate due to time passed, and then increase it according to the size of this redemption.
        // Use the saved total JPYDF supply value, from before it was reduced by the redemption.
        // We only compute it here, and update it at the end,
        // because the final redeemed amount may be less than the requested amount
        // Redeemers should take this into account in order to request the optimal amount to not overpay
        uint256 redemptionRate =
            _calcRedemptionRate(_getUpdatedBaseRateFromRedemption(_jpydfAmount, totals.jpydfSupplyAtStart));
        require(redemptionRate <= _maxFeePercentage, "CR: Fee exceeded provided maximum");
        // Implicit by the above and the _requireValidMaxFeePercentage checks
        //require(newBaseRate < DECIMAL_PRECISION, "CR: Fee would eat up all collateral");

        // Compute redemption amount for each collateral and redeem against the corresponding TroveManager
        for (uint256 index = 0; index < totals.numCollaterals; index++) {
            //uint256 unbackedPortion = unbackedPortions[index];
            if (unbackedPortions[index] > 0) {
                uint256 redeemAmount = _jpydfAmount * unbackedPortions[index] / totals.unbacked;
                if (redeemAmount > 0) {
                    ITroveManager troveManager = getTroveManager(index);
                    uint256 redeemedAmount = troveManager.redeemCollateral(
                        msg.sender, redeemAmount, prices[index], redemptionRate, _maxIterationsPerCollateral
                    );
                    totals.redeemedAmount += redeemedAmount;
                }

                // Ensure that per-branch redeems add up to `_jpydfAmount` exactly
                _jpydfAmount -= redeemAmount;
                totals.unbacked -= unbackedPortions[index];
            }
        }

        _updateBaseRateAndGetRedemptionRate(totals.redeemedAmount, totals.jpydfSupplyAtStart);

        // Burn the total JPYDF that is cancelled with debt
        if (totals.redeemedAmount > 0) {
            jpydfToken.burn(msg.sender, totals.redeemedAmount);
        }
    }

    // --- Internal fee functions ---

    // Update the last fee operation time only if time passed >= decay interval. This prevents base rate griefing.
    function _updateLastFeeOpTime() internal {
        uint256 minutesPassed = _minutesPassedSinceLastFeeOp();

        if (minutesPassed > 0) {
            lastFeeOperationTime += ONE_MINUTE * minutesPassed;
            emit LastFeeOpTimeUpdated(lastFeeOperationTime);
        }
    }

    function _minutesPassedSinceLastFeeOp() internal view returns (uint256) {
        return (block.timestamp - lastFeeOperationTime) / ONE_MINUTE;
    }

    // Updates the `baseRate` state with math from `_getUpdatedBaseRateFromRedemption`
    function _updateBaseRateAndGetRedemptionRate(uint256 _jpydfAmount, uint256 _totalJpydfSupplyAtStart) internal {
        uint256 newBaseRate = _getUpdatedBaseRateFromRedemption(_jpydfAmount, _totalJpydfSupplyAtStart);

        //assert(newBaseRate <= DECIMAL_PRECISION); // This is already enforced in `_getUpdatedBaseRateFromRedemption`

        // Update the baseRate state variable
        baseRate = newBaseRate;
        emit BaseRateUpdated(newBaseRate);

        _updateLastFeeOpTime();
    }

    /*
     * This function calculates the new baseRate in the following way:
     * 1) decays the baseRate based on time passed since last redemption or JPYDF borrowing operation.
     * then,
     * 2) increases the baseRate based on the amount redeemed, as a proportion of total supply
     */
    function _getUpdatedBaseRateFromRedemption(uint256 _redeemAmount, uint256 _totalJpydfSupply)
        internal
        view
        returns (uint256)
    {
        // decay the base rate
        uint256 decayedBaseRate = _calcDecayedBaseRate();

        // get the fraction of total supply that was redeemed
        uint256 redeemedJpydfFraction = _redeemAmount * DECIMAL_PRECISION / _totalJpydfSupply;

        uint256 newBaseRate = decayedBaseRate + redeemedJpydfFraction / REDEMPTION_BETA;
        newBaseRate = LiquityMath._min(newBaseRate, DECIMAL_PRECISION); // cap baseRate at a maximum of 100%

        return newBaseRate;
    }

    function _calcDecayedBaseRate() internal view returns (uint256) {
        uint256 minutesPassed = _minutesPassedSinceLastFeeOp();
        uint256 decayFactor = LiquityMath._decPow(REDEMPTION_MINUTE_DECAY_FACTOR, minutesPassed);

        return baseRate * decayFactor / DECIMAL_PRECISION;
    }

    function _calcRedemptionRate(uint256 _baseRate) internal pure returns (uint256) {
        return LiquityMath._min(
            REDEMPTION_FEE_FLOOR + _baseRate,
            DECIMAL_PRECISION // cap at a maximum of 100%
        );
    }

    function _calcRedemptionFee(uint256 _redemptionRate, uint256 _amount) internal pure returns (uint256) {
        uint256 redemptionFee = _redemptionRate * _amount / DECIMAL_PRECISION;
        return redemptionFee;
    }

    // external redemption rate/fee getters

    function getRedemptionRate() external view override returns (uint256) {
        return _calcRedemptionRate(baseRate);
    }

    function getRedemptionRateWithDecay() public view override returns (uint256) {
        return _calcRedemptionRate(_calcDecayedBaseRate());
    }

    function getRedemptionRateForRedeemedAmount(uint256 _redeemAmount) external view returns (uint256) {
        uint256 totalJpydfSupply = jpydfToken.totalSupply();
        uint256 newBaseRate = _getUpdatedBaseRateFromRedemption(_redeemAmount, totalJpydfSupply);
        return _calcRedemptionRate(newBaseRate);
    }

    function getRedemptionFeeWithDecay(uint256 _ETHDrawn) external view override returns (uint256) {
        return _calcRedemptionFee(getRedemptionRateWithDecay(), _ETHDrawn);
    }

    function getEffectiveRedemptionFeeInJpydf(uint256 _redeemAmount) external view override returns (uint256) {
        uint256 totalJpydfSupply = jpydfToken.totalSupply();
        uint256 newBaseRate = _getUpdatedBaseRateFromRedemption(_redeemAmount, totalJpydfSupply);
        return _calcRedemptionFee(_calcRedemptionRate(newBaseRate), _redeemAmount);
    }

    // getters

    function getToken(uint256 _index) external view returns (IERC20Metadata) {
        if (_index == 0) return token0;
        else if (_index == 1) return token1;
        else if (_index == 2) return token2;
        else if (_index == 3) return token3;
        else if (_index == 4) return token4;
        else if (_index == 5) return token5;
        else if (_index == 6) return token6;
        else if (_index == 7) return token7;
        else if (_index == 8) return token8;
        else if (_index == 9) return token9;
        else revert("Invalid index");
    }

    function getTroveManager(uint256 _index) public view returns (ITroveManager) {
        if (_index == 0) return troveManager0;
        else if (_index == 1) return troveManager1;
        else if (_index == 2) return troveManager2;
        else if (_index == 3) return troveManager3;
        else if (_index == 4) return troveManager4;
        else if (_index == 5) return troveManager5;
        else if (_index == 6) return troveManager6;
        else if (_index == 7) return troveManager7;
        else if (_index == 8) return troveManager8;
        else if (_index == 9) return troveManager9;
        else revert("Invalid index");
    }

    // require functions

    function _requireValidMaxFeePercentage(uint256 _maxFeePercentage) internal pure {
        require(
            _maxFeePercentage >= REDEMPTION_FEE_FLOOR && _maxFeePercentage <= DECIMAL_PRECISION,
            "Max fee percentage must be between 0.5% and 100%"
        );
    }

    function _requireAmountGreaterThanZero(uint256 _amount) internal pure {
        require(_amount > 0, "CollateralRegistry: Amount must be greater than zero");
    }
}
"
    },
    "src/CollateralVault.sol": {
      "content": "// SPDX-License-Identifier: BUSL-1.1

pragma solidity 0.8.24;

import "openzeppelin-contracts/contracts/token/ERC20/utils/SafeERC20.sol";
import "openzeppelin-contracts/contracts/token/ERC20/IERC20.sol";
import "openzeppelin-contracts/contracts/utils/math/Math.sol";
import "openzeppelin-contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";
import "openzeppelin-contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "openzeppelin-contracts-upgradeable/proxy/utils/Initializable.sol";
import "openzeppelin-contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";

import "./Interfaces/IDToken.sol";
import "./Interfaces/IStrategy.sol";
import "./Interfaces/ICollateralVault.sol";

/// @dev Morpho V2 incident surface called only through this Vault. Keeping the
///      concrete interface local avoids widening the common `IStrategy` ABI.
interface IMorphoV2IncidentStrategy {
    function forceDeallocate(address _adapter, bytes calldata _data, uint256 _assets)
        external
        returns (uint256 penaltyShares, uint256 penaltyAssets, uint256 valuationLossAssets, uint256 withdrawnAssets);
}

/**
 * @title CollateralVault - Push-model collateral custody and yield Vault (Upgradeable)
 * @notice One Vault per collateral asset. Custodies the Underlying, mints/burns
 *         the corresponding dToken 1:1 (decimals-adjusted), serves redemptions
 *         from a liquid buffer with a delayed-claim fallback, allocates buffer
 *         excess to whitelisted Strategies, receives principal-return push-back
 *         through `receiveFromStrategy`, and lets Strategies push yield directly
 *         into the buffer without reducing principal valuation caches.
 *         Backstop repair funds are tracked as a separate reserve and are not
 *         spendable by redeem / claim until GOV releases them to the buffer.
 *         Accumulated yield is moved to the treasury address via
 *         `transferYieldToTreasury`.
 *
 * @dev    Built in two layers over one reserved storage layout:
 *           - dToken portion (Phase 3a): deposit / redeem / redeemWithPermit /
 *             claim, buffer accounting, pause, config setters, and the
 *             deferred-underlying binding (`setUnderlying` + `_requireUnderlyingReady`).
 *             With no Strategy registered (`strategies[]` empty) the Vault holds
 *             100% of the Underlying in its buffer and these still work alone.
 *           - Strategy / yield layer (Phase 3b): allocate /
 *             receiveFromStrategy / direct yield pushes /
 *             transferYieldToTreasury / strategy whitelist + CRUD / writeoff /
 *             allocation pause / strategy views. The push-model storage layout
 *             was reserved in full from Phase 3a (see STATE), so this layer was
 *             added without shifting any storage slot.
 *
 *         Deferred-underlying interplay: because the push model reverses the
 *         approve direction (a Strategy approves the Vault in its initializer,
 *         §2.2.5), `addStrategy` no longer touches `underlying.safeApprove`. The
 *         activation-order guard that previously fell out of that approve is
 *         restored explicitly in `addStrategy` (underlying must be set and must
 *         match the Strategy's), so a placeholder / mismatched-asset Strategy can
 *         never be registered (dToken.md §2.2.10 / §2.2.11).
 */
contract CollateralVault is
    Initializable,
    ICollateralVault,
    ReentrancyGuardUpgradeable,
    AccessControlUpgradeable,
    UUPSUpgradeable
{
    using SafeERC20 for IERC20;

    // =============================================================
    //                          CONSTANTS
    // =============================================================

    bytes32 internal constant GOV_ROLE = keccak256("GOV_ROLE");
    // ALLOCATOR is deliberately restricted to allocate; no legacy umbrella role.
    bytes32 internal constant ALLOCATOR_ROLE = keccak256("ALLOCATOR_ROLE");
    bytes32 internal constant WITHDRAWER_ROLE = keccak256("WITHDRAWER_ROLE");
    bytes32 internal constant HARVESTER_ROLE = keccak256("HARVESTER_ROLE");
    bytes32 internal constant TREASURY_TRANSFER_ROLE = keccak256("TREASURY_TRANSFER_ROLE");
    bytes32 internal constant GUARDIAN_ROLE = keccak256("GUARDIAN_ROLE");
    bytes32 internal constant WRITEOFF_ROLE = keccak256("WRITEOFF_ROLE");

    uint256 internal constant BPS_DENOMINATOR = 10000;
    uint256 internal constant DEFAULT_STRATEGY_VALUATION_MAX_AGE = 1 days;
    /// @dev Default gas budget handed to each Strategy valuation probe. A registered Strategy must
    ///      value itself within the active budget; a probe that exceeds it is a genuine valuation
    ///      failure. GOV can retune the budget within the bounds below.
    uint256 internal constant DEFAULT_STRATEGY_VALUATION_GAS = 500_000;
    uint256 internal constant MIN_STRATEGY_VALUATION_GAS = 100_000;
    uint256 internal constant MAX_STRATEGY_VALUATION_GAS = 2_000_000;
    /// @dev Headroom the Vault keeps for the probe call frames and the catch paths.
    uint256 internal constant STRATEGY_VALUATION_GAS_MARGIN = 20_000;
    uint256 public constant MAX_STRATEGIES = 32;

    // =============================================================
    //                         STATE
    // =============================================================
    // NOTE: full push-model layout was reserved from Phase 3a so that the
    //       Phase 3b Strategy upgrade was purely additive. Fields marked
    //       "[3b]" belong to the Strategy / yield layer.

    IERC20 public override underlying;
    IDToken public override dToken;
    address public override treasury;

    uint256 public override bufferTargetBps;
    uint256 public override bufferFloor;

    uint256 public allocateMaxMove; // [3b]
    uint256 public allocatorCooldown; // [3b]
    uint256 public lastAllocatorTime; // [3b]

    bool public override pausedDeposit;
    bool public override pausedRedeem;
    bool public override pausedClaim;
    bool public pausedAllocation; // [3b]

    IStrategy[] public strategies; // [3b]
    mapping(IStrategy => StrategyConfig) public strategyConfigs; // [3b]
    uint256 public totalWeightBps; // [3b]
    mapping(address => bool) public whitelistedStrategies; // [3b]

    mapping(uint256 => WithdrawRequest) public withdrawRequests;
    uint256 public nextRequestId;
    uint256 public withdrawDelay;
    uint256 public override pendingWithdrawals;
    uint256 private _backstopReserve;
    mapping(IStrategy => StrategyValuationCache) public override strategyValuationCaches; // [3b]
    uint256 public override strategyValuationMaxAge; // [3b]
    /// @dev Zero means DEFAULT_STRATEGY_VALUATION_GAS, so an upgraded proxy whose slot is still
    ///      unset keeps the default budget instead of probing with no gas.
    uint256 private _strategyValuationGasBudget; // [3b]

    /// @dev Storage gap for future upgrades. See OpenZeppelin's storage gap guidance.
    uint256[46] private __gap;

    // =============================================================
    //                          ERRORS
    // =============================================================

    error Paused();
    error ZeroAddress();
    error ZeroAmount();
    /// @dev Caller cannot fund the fixed Strategy valuation probe budget. Same signature as the
    ///      price-feed gas guard so JpyFreezeLib and PriceFeedProxy bubble it instead of shutting down.
    error InsufficientGasForExternalCall();
    error InvalidStrategyValuationGasBudget(uint256 budget);
    error InvalidBufferConfig();
    error RequestNotReady();
    error RequestNotFound();
    error InsufficientBuffer();
    error InvalidDTokenAmount();
    error PermitFailed();

    // Strategy / yield layer (push model) errors
    error StrategyAlreadyExists();
    error StrategyNotFound();
    error StrategyHasPrincipal();
    error StrategyHasAssets();
    error InvalidWeight();
    error CooldownNotMet();
    error NotWhitelisted();
    error NotContract();
    error WeightExceedsBps();
    error AlreadyWhitelisted();
    error NotRegisteredStrategy();
    error TooManyStrategies();

    // Deferred-underlying (placeholder branch) errors
    error UnderlyingNotSet();
    error UnderlyingMismatch();
    error UnderlyingAlreadySet();
    error UnderlyingNotAllowed();
    error InvalidBackingTarget();
    error InsufficientBackstop();
    error StrategyWriteoffNotReady();
    error InvalidBackingRatioGuard();
    error BackingRatioBelowMinimum(uint256 actual, uint256 minimum);
    error RecoveryBelowMinimum(uint256 actual, uint256 minimum);

    // =============================================================
    //                        CONSTRUCTOR
    // =============================================================

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    // =============================================================
    //                        INITIALIZER
    // =============================================================

    /// @notice Initialize the Vault.
    /// @dev `_underlying == address(0)` is **allowed**: the Vault deploys as a
    ///      placeholder and is bound later via `setUnderlying` (deferred-binding
    ///      for placeholder branches). `_dToken` / `_treasury` / `_admin` must be
    ///      non-zero. While `underlying == address(0)`, the `_requireUnderlyingReady`
    ///      guard makes deposit/redeem/redeemWithPermit/backstopDeposit revert
    ///      (the Vault is inert).
    function initialize(IERC20 _underlying, IDToken _dToken, address _treasury, address _admin) external initializer {
        if (address(_dToken) == address(0)) revert ZeroAddress();
        if (_treasury == address(0)) revert ZeroAddress();
        if (_admin == address(0)) revert ZeroAddress();
        if (address(_dToken).code.length == 0) revert NotContract();
        if (_dToken.vault() != address(this)) revert UnderlyingMismatch();
        if (address(_underlying) != address(0) && !_dToken.allowedUnderlying(address(_underlying))) {
            revert UnderlyingNotAllowed();
        }

        __ReentrancyGuard_init();
        __AccessControl_init();
        __UUPSUpgradeable_init();

        underlying = _underlying; // may be address(0) for a placeholder branch
        dToken = _dToken;
        treasury = _treasury;

        bufferTargetBps = 2000; // 20%
        allocateMaxMove = type(uint256).max;
        strategyValuationMaxAge = DEFAULT_STRATEGY_VALUATION_MAX_AGE;
        _strategyValuationGasBudget = DEFAULT_STRATEGY_VALUATION_GAS;
        withdrawDelay = 1 days;
        nextRequestId = 1;

        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _grantRole(GOV_ROLE, _admin);
        _grantRole(ALLOCATOR_ROLE, _admin);
        _grantRole(WITHDRAWER_ROLE, _admin);
        _grantRole(HARVESTER_ROLE, _admin);
        _grantRole(TREASURY_TRANSFER_ROLE, _admin);
        _grantRole(GUARDIAN_ROLE, _admin);
        _grantRole(WRITEOFF_ROLE, _admin);
    }

    // =============================================================
    //                    UUPS UPGRADE
    // =============================================================

    function _authorizeUpgrade(address) internal override onlyRole(GOV_ROLE) {}

    function _checkRole(bytes32 role, address account) internal view override {
        if (!hasRole(role, account)) revert();
    }

    // =============================================================
    //                      MODIFIERS
    // =============================================================

    modifier whenNotPausedDeposit() {
        if (pausedDeposit) revert Paused();
        _;
    }

    modifier whenNotPausedRedeem() {
        if (pausedRedeem) revert Paused();
        _;
    }

    modifier whenNotPausedClaim() {
        if (pausedClaim) revert Paused();
        _;
    }

    /// @notice Gate Vault-managed outbound operations.
    /// @dev Strategy→buffer recovery (`Strategy.sendToVault`) and yield-only
    ///      pushes (`Strategy.sendProfitToVault`) stay available while allocation
    ///      is paused because they move funds to the Vault. Outflows from the
    ///      Vault (`allocate` and `transferYieldToTreasury`) are stopped.
    modifier whenNotPausedAllocation() {
        if (pausedAllocation) revert Paused();
        _;
    }

    // =============================================================
    //                     USER FUNCTIONS
    // =============================================================

    /// @inheritdoc ICollateralVault
    function deposit(uint256 _underlyingAmount)
        external
        override
        nonReentrant
        whenNotPausedDeposit
        returns (uint256 dTokenAmount)
    {
        IERC20 u = _requireUnderlyingReady();
        if (_underlyingAmount == 0) revert ZeroAmount();
        _requireConfirmedFullyBacked();
        uint256 vaultUnderlyingBeforeDeposit = u.balanceOf(address(this));
        u.safeTransferFrom(msg.sender, address(this), _underlyingAmount);
        uint256 received = u.balanceOf(address(this)) - vaultUnderlyingBeforeDeposit;
        if (received == 0) revert ZeroAmount();
        dTokenAmount = dToken.convertToDToken(received);
        dToken.mint(msg.sender, dTokenAmount);
        emit Deposited(msg.sender, received, dTokenAmount);
    }

    /// @inheritdoc ICollateralVault
    function redeem(uint256 _dTokenAmount, address _receiver)
        external
        override
        nonReentrant
        whenNotPausedRedeem
        returns (uint256 underlyingReceived, uint256 requestId)
    {
        uint256 underlyingNeeded = _requireValidRedemption(_dTokenAmount, _receiver);
        uint256 bufferBal = bufferBalance();

        dToken.burn(msg.sender, _dTokenAmount);

        return _completeRedemption(_receiver, _dTokenAmount, underlyingNeeded, bufferBal);
    }

    /// @inheritdoc ICollateralVault
    /// @dev Identical to `redeem` except dToken is pulled in via EIP-2612 permit
    ///      and burned from the Vault. The permit signature is verified against
    ///      the dToken's EIP-712 domain, which tracks its live `name()`.
    function redeemWithPermit(
        uint256 _dTokenAmount,
        uint256 _deadline,
        uint8 _v,
        bytes32 _r,
        bytes32 _s,
        address _receiver
    ) external override nonReentrant whenNotPausedRedeem returns (uint256 underlyingReceived, uint256 requestId) {
        uint256 underlyingNeeded = _requireValidRedemption(_dTokenAmount, _receiver);

        _permitOrRequireAllowance(_dTokenAmount, _deadline, _v, _r, _s);
        IERC20(address(dToken)).safeTransferFrom(msg.sender, address(this), _dTokenAmount);

        uint256 bufferBal = bufferBalance();

        dToken.burn(address(this), _dTokenAmount);

        return _completeRedemption(_receiver, _dTokenAmount, underlyingNeeded, bufferBal);
    }

    /// @inheritdoc ICollateralVault
    function claim(uint256 _requestId)
        external
        override
        nonReentrant
        whenNotPausedClaim
        returns (uint256 underlyingClaimed)
    {
        WithdrawRequest storage req = withdrawRequests[_requestId];
        address requestOwner = req.owner;

        // Checks
        if (requestOwner == address(0)) revert RequestNotFound();
        if (req.claimed) return 0;
        if (block.timestamp < req.claimableAt) revert RequestNotReady();

        _requireConfirmedFullyBacked();
        underlyingClaimed = req.underlyingAmount;
        if (bufferBalance() < underlyingClaimed) revert InsufficientBuffer();

        // Effects
        req.claimed = true;
        pendingWithdrawals -= underlyingClaimed;

        // Interaction
        underlying.safeTransfer(requestOwner, underlyingClaimed);
        emit WithdrawClaimed(requestOwner, _requestId, underlyingClaimed);
    }

    // =============================================================
    //                  DEFERRED-BINDING ACTIVATION
    // =============================================================

    /// @inheritdoc ICollateralVault
    /// @dev One-shot. Enforces dToken-first ordering by requiring the dToken to
    ///      already be bound to the same underlying (`dToken.underlying()`), so
    ///      the custody asset and the 1:1/decimals valuation can never diverge.
    function setUnderlying(IERC20 _underlying) external override onlyRole(GOV_ROLE) {
        if (address(_underlying) == address(0)) revert ZeroAddress();
        if (address(underlying) != address(0)) revert UnderlyingAlreadySet();
        if (address(dToken.underlying()) != address(_underlying)) revert UnderlyingMismatch();
        if (!dToken.allowedUnderlying(address(_underlying))) revert UnderlyingNotAllowed();

        underlying = _underlying;
        emit UnderlyingSet(address(_underlying));
    }

    // =============================================================
    //                   ALLOCATOR FUNCTIONS
    // =============================================================

    /// @inheritdoc ICollateralVault
    /// @dev Buffer excess is split across Strategies by `weightBps` (used only
    ///      for allocation, never for harvest in the push model). Placeholder-safe:
    ///      a not-yet-bound Vault has `_managedUnderlying() == 0` (empty
    ///      `strategies[]` and a zero `bufferBalance()`), so this early-returns
    ///      before touching `underlying`. `addStrategy`'s underlying guard further
    ///      guarantees an unbound Vault has no Strategy to allocate to.
    function allocate() external override onlyRole(ALLOCATOR_ROLE) whenNotPausedAllocation nonReentrant {
        if (block.timestamp < lastAllocatorTime + allocatorCooldown) revert CooldownNotMet();

        uint256 managedAssets = _managedUnderlying();
        if (managedAssets == 0) return;

        uint256 targetBuffer = _requiredBuffer(managedAssets);

        uint256 bufferBefore = bufferBalance();

        if (bufferBefore > targetBuffer) {
            uint256 excess = bufferBefore - targetBuffer;
            if (excess > allocateMaxMove) excess = allocateMaxMove;
            _allocateToStrategies(excess);
            if (excess != 0) _requireConfirmedFullyBacked();
        }

        lastAllocatorTime = block.timestamp;
        emit Allocated(bufferBefore, targetBuffer, bufferBalance());
    }

    // =============================================================
    //                STRATEGY → VAULT PUSH ENTRY POINT
    // =============================================================

    /// @inheritdoc ICollateralVault
    /// @dev Principal/cache-reducing push-back entry point. The amount credited
    ///      is measured by the Vault's own balance diff, so fee-on-transfer /
    ///      rebasing underlyings are accounted by what actually arrived (the
    ///      caller Strategy decrements its `principal` by this returned
    ///      `received` when returning principal). A declared/received mismatch
    ///      invalidates the fallback valuation cache: the Vault cannot infer
    ///      how much upstream position value moved from the receipt alone.
    function receiveFromStrategy(uint256 _declaredAmount) external override nonReentrant returns (uint256 received) {
        IStrategy strategy = IStrategy(msg.sender);
        if (!_isRegisteredStrategy(strategy)) revert NotRegisteredStrategy();

        if (_declaredAmount == 0) {
            emit ReceivedFromStrategy(msg.sender, 0, 0);
            return 0;
        }

        uint256 vaultUnderlyingBeforeReceive = underlying.balanceOf(address(this));
        underlying.safeTransferFrom(msg.sender, address(this), _declaredAmount);
        received = underlying.balanceOf(address(this)) - vaultUnderlyingBeforeReceive;
        if (received == _declaredAmount) {
            _reduceStrategyValuationCache(strategy, received);
        } else {
            _invalidateStrategyValuationCache(strategy);
        }

        emit ReceivedFromStrategy(msg.sender, _declaredAmount, received);
    }

    // =============================================================
    //                  BACKSTOP / REPAIR ENTRY POINT
    // =============================================================

    /// @inheritdoc ICollateralVault
    /// @dev Unlike `deposit`, this does not mint dToken. It increases the
    ///      protected backstop reserve and `totalUnderlying()` without increasing
    ///      `bufferBalance()`. The reserve only becomes redeem / claim liquidity
    ///      after GOV explicitly releases it.
    function backstopDeposit(uint256 _underlyingAmount) external override nonReentrant returns (uint256 received) {
        IERC20 u = _requireUnderlyingReady();
        if (_underlyingAmount == 0) revert ZeroAmount();

        uint256 vaultUnderlyingBeforeBackstop = u.balanceOf(address(this));
        u.safeTransferFrom(msg.sender, address(this), _underlyingAmount);
        received = u.balanceOf(address(this)) - vaultUnderlyingBeforeBackstop;
        if (received == 0) revert ZeroAmount();
        _backstopReserve += received;

        emit BackstopDeposited(msg.sender, _underlyingAmount, received);
    }

    /// @inheritdoc ICollateralVault
    function releaseBackstopToBuffer(uint256 _amount) external override onlyRole(GOV_ROLE) returns (uint256 released) {
        _requireUnderlyingReady();
        if (_amount == 0) revert ZeroAmount();
        if (backstopBalance() < _amount) revert InsufficientBackstop();

        _backstopReserve -= _amount;
        released = _amount;
        emit BackstopReleased(msg.sender, released);
    }

    // =============================================================
    //                YIELD / TREASURY FUNCTIONS
    // =============================================================

    /// @inheritdoc ICollateralVault
    /// @dev Sends only managed-asset surplus over liabilities, and keeps the same
    ///      liquid buffer that `allocate` reserves (buffer target + every queued
    ///      withdrawal, see `_requiredBuffer`) on hand. It therefore never dips
    ///      into underlying that is inside a Strategy or protected as backstop
    ///      reserve, and never sweeps liquidity a pending `claim` depends on.
    ///      Strategy value uses `min(estimatedTotalUnderlying, principal)`, so
    ///      unrealized yield is not pre-counted. Unlike backing views, this path
    ///      does not spend against cached or partial Strategy valuation: one
    ///      unavailable registered Strategy makes the entire transfer zero.
    function transferYieldToTreasury()
        external
        override
        onlyRole(TREASURY_TRANSFER_ROLE)
        whenNotPausedAllocation
        nonReentrant
        returns (uint256 transferred)
    {
        uint256 managedAssets = _managedUnderlying();
        uint256 currentLiabilities = _actualLiabilities();
        if (managedAssets <= currentLiabilities) {
            emit YieldTransferredToTreasury(0, treasury);
            return 0;
        }

        uint256 managedSurplus = managedAssets - currentLiabilities;

        // Reserve the same liquid buffer that `allocate` keeps on hand (buffer
        // target + every queued withdrawal). Only buffer above that reserve is
        // sweepable, so yield extraction can never starve a pending `claim` of
        // liquidity; the genuine surplus remains the upper bound either way.
        uint256 requiredBuffer = _requiredBuffer(managedAssets);
        uint256 liquidBufferBalance = bufferBalance();
        uint256 freeBuffer = liquidBufferBalance > requiredBuffer ? liquidBufferBalance - requiredBuffer : 0;
        transferred = managedSurplus < freeBuffer ? managedSurplus : freeBuffer;

        if (transferred > 0) {
            underlying.safeTransfer(treasury, transferred);
        }
        emit YieldTransferredToTreasury(transferred, treasury);
    }

    // =============================================================
    //                  GOVERNANCE FUNCTIONS (dToken portion)
    // =============================================================

    function setBufferConfig(uint256 _targetBps, uint256 _floor) external override onlyRole(GOV_ROLE) {
        if (_targetBps > BPS_DENOMINATOR) revert InvalidBufferConfig();
        uint256 oldTargetBps = bufferTargetBps;
        uint256 oldFloor = bufferFloor;
        bufferTargetBps = _targetBps;
        bufferFloor = _floor;
        emit BufferConfigUpdated(oldTargetBps, _targetBps, oldFloor, _floor);
    }

    function setWithdrawDelay(uint256 _delay) external override onlyRole(GOV_ROLE) {
        if (_delay > 30 days) revert InvalidBufferConfig();
        uint256 oldDelay = withdrawDelay;
        withdrawDelay = _delay;
        emit WithdrawDelayUpdated(oldDelay, _delay);
    }

    function setTreasury(address _treasury) external override onlyRole(GOV_ROLE) {
        if (_treasury == address(0)) revert ZeroAddress();
        address oldTreasury = treasury;
        treasury = _treasury;
        emit TreasuryUpdated(oldTreasury, _treasury);
    }

    function pauseDeposit() external override onlyRole(GUARDIAN_ROLE) {
        pausedDeposit = true;
        emit DepositPaused();
    }

    function unpauseDeposit() external override onlyRole(GOV_ROLE) {
        pausedDeposit = false;
        emit DepositUnpaused();
    }

    function pauseRedeem() external override onlyRole(GUARDIAN_ROLE) {
        pausedRedeem = true;
        emit RedeemPaused();
    }

    function unpauseRedeem() external override onlyRole(GOV_ROLE) {
        pausedRedeem = false;
        emit RedeemUnpaused();
    }

    function pauseClaim() external override onlyRole(GUARDIAN_ROLE) {
        pausedClaim = true;
        emit ClaimPaused();
    }

    function unpauseClaim() external override onlyRole(GOV_ROLE) {
        pausedClaim = false;
        emit ClaimUnpaused();
    }

    // =============================================================
    //               GOVERNANCE FUNCTIONS (Strategy layer)
    // =============================================================

    // --- Whitelist Management ---

    function addToWhitelist(address _strategy) external override onlyRole(GOV_ROLE) {
        if (_strategy == address(0)) revert ZeroAddress();
        if (_strategy.code.length == 0) revert NotContract();
        if (whitelistedStrategies[_strategy]) revert AlreadyWhitelisted();
        whitelistedStrategies[_strategy] = true;
        emit StrategyWhitelisted(_strategy);
    }

    function removeFromWhitelist(address _strategy) external override onlyRole(GUARDIAN_ROLE) {
        if (!whitelistedStrategies[_strategy]) revert StrategyNotFound();
        whitelistedStrategies[_strategy] = false;
        emit StrategyRemovedFromWhitelist(_strategy);

        StrategyConfig storage config = strategyConfigs[IStrategy(_strategy)];
        if (config.enabled || config.weightBps != 0) {
            _disableStrategy(IStrategy(_strategy), config);
            _pauseUserFlows();
            _pauseAllocationIfNeeded();
        }
    }

    // --- Strategy CRUD ---

    /// @inheritdoc ICollateralVault
    /// @dev Restores the deferred-underlying activation-order guard that the push
    ///      model would otherwise drop. In the pull model `addStrategy` called
    ///      `underlying.safeApprove(strategy, ...)`, which reverted on a
    ///      placeholder Vault (`underlying == address(0)`). The push model
    ///      reverses the approve direction (the Strategy approves the Vault in its
    ///      initializer, §2.2.5), so that implicit guard is gone. We restore it
    ///      explicitly — and additionally pin `strategy.underlying()` to the
    ///      Vault's underlying — so a placeholder or mismatched-asset Strategy can
    ///      never be registered (which would make `allocate` ship the wrong token
    ///      and `receiveFromStrategy` pull a different one). dToken.md §2.2.10 / §2.2.11.
    function addStrategy(IStrategy _strategy, uint256 _weightBps, uint256 _cap) external override onlyRole(GOV_ROLE) {
        if (address(_strategy) == address(0)) revert ZeroAddress();
        if (address(_strategy).code.length == 0) revert NotContract();
        if (_isRegisteredStrategy(_strategy)) revert StrategyAlreadyExists();
        if (!whitelistedStrategies[address(_strategy)]) revert NotWhitelisted();

        IERC20 u = underlying;
        if (address(u) == address(0)) revert UnderlyingNotSet();
        if (_strategy.underlying() != address(u)) revert UnderlyingMismatch();

        if (strategies.length >= MAX_STRATEGIES) revert TooManyStrategies();
        if (totalWeightBps + _weightBps > BPS_DENOMINATOR) revert WeightExceedsBps();

        strategies.push(_strategy);
        strategyConfigs[_strategy] = StrategyConfig({enabled: true, weightBps: _weightBps, cap: _cap});
        totalWeightBps += _weightBps;
        _refreshStrategyValuation(_strategy);

        emit StrategyAdded(address(_strategy), _weightBps, _cap);
    }

    function updateStrategy(IStrategy _strategy, uint256 _weightBps, uint256 _cap, bool _enabled)
        external
        override
        onlyRole(GOV_ROLE)
    {
        if (!_isRegisteredStrategy(_strategy)) revert StrategyNotFound();

        StrategyConfig storage config = strategyConfigs[_strategy];
        if (!_enabled && _weightBps > 0) revert InvalidWeight();

        uint256 newTotal = totalWeightBps - config.weightBps + _weightBps;
        if (newTotal > BPS_DENOMINATOR) revert WeightExceedsBps();

        totalWeightBps = newTotal;
        config.weightBps = _weightBps;
        config.cap = _cap;
        config.enabled = _enabled;

        emit StrategyUpdated(address(_strategy), _weightBps, _cap, _enabled);
    }

    /// @inheritdoc ICollateralVault
    /// @dev Outstanding principal and assets do not prevent emergency disabling.
    function emergencyDisableStrategy(IStrategy _strategy) external override onlyRole(GUARDIAN_ROLE) {
        if (!_isRegisteredStrategy(_strategy)) revert StrategyNotFound();

        _disableStrategy(_strategy, strategyConfigs[_strategy]);
        _pauseUserFlows();
        _pauseAllocationIfNeeded();
    }

    /// @inheritdoc ICollateralVault
    /// @dev Both principal and live estimated assets must be readable and zero.
    ///      Recover assets first; a principal writeoff alone does not prove that
    ///      the Strategy has no residual assets. Enabled or disabled Strategies
    ///      may be removed once both conditions hold.
    function removeStrategy(IStrategy _strategy) external override onlyRole(GUARDIAN_ROLE) nonReentrant {
        (uint256 strategyIndex, bool registered) = _strategyIndex(_strategy);
        if (!registered) revert StrategyNotFound();
        (uint256 principal_, bool principalAvailable) = _tryPrincipal(_strategy);
        if (!principalAvailable || principal_ != 0) revert StrategyHasPrincipal();
        (uint256 estimated, bool estimateAvailable) = _tryEstimatedTotalUnderlying(_strategy);
        if (!estimateAvailable || estimated != 0) revert StrategyHasAssets();

        StrategyConfig storage config = strategyConfigs[_strategy];
        totalWeightBps -= config.weightBps;
        delete strategyConfigs[_strategy];

        uint256 length = strategies.length;
        strategies[strategyIndex] = strategies[length - 1];
        strategies.pop();

        _invalidateStrategyValuationCache(_strategy);
        emit StrategyRemoved(address(_strategy));
    }

    /// @inheritdoc ICollateralVault
    /// @dev Works on enabled and disabled-but-still-registered Strategies alike
    ///      (membership in `strategies[]` is the authoritative "registered"
    ///      status, matching `receiveFromStrategy` / `_isRegisteredStrategy`).
    ///      Book-only: no asset moves. Recover what is recoverable first
    ///      (`sendToVault` / emergency), then write off only the residual loss.
    ///      The emitted amount is the Strategy-reported actual writeoff, so
    ///      over-large requests report the clamped amount.
    ///      Live Strategies must first be disabled or allocation-paused, preventing
    ///      a standalone writeoff key from reducing backing while allocation is
    ///      still operating normally.
    function writeoffStrategyPrincipal(IStrategy _strategy, uint256 _amount, uint256 _minBackingRatioAfter)
        external
        override
        onlyRole(WRITEOFF_ROLE)
        nonReentrant
    {
        if (_minBackingRatioAfter > 1e18) revert InvalidBackingRatioGuard();
        if (!_isRegisteredStrategy(_strategy)) revert StrategyNotFound();
        _requireStrategyIncidentReady(_strategy);
        _pauseUserFlows();
        uint256 writtenOff = _strategy.writeoffPrincipal(_amount);
        if (!_refreshStrategyValuation(_strategy)) {
            _reduceStrategyValuationCache(_strategy, writtenOff);
        }
        uint256 backingAfter = _backingRatio();
        if (backingAfter < _minBackingRatioAfter) revert BackingRatioBelowMinimum(backingAfter, _minBackingRatioAfter);
        emit StrategyPrincipalWrittenOff(address(_strategy), writtenOff);
    }

    /// @inheritdoc ICollateralVault
    function forceDeallocateMorphoV2(
        IStrategy _strategy,
        address _adapter,
        bytes calldata _data,
        uint256 _assets,
        uint256 _minReceived,
        uint256 _minBackingRatioAfter
    )
        external
        override
        onlyRole(WRITEOFF_ROLE)
        nonReentrant
        returns (uint256 penaltyShares, uint256 penaltyAssets, uint256 valuationLossAssets)
    {
        if (_assets == 0 || _minReceived == 0) revert ZeroAmount();
        if (_minBackingRatioAfter > 1e18) revert InvalidBackingRatioGuard();
        if (!_isRegisteredStrategy(_strategy)) revert StrategyNotFound();

        // Any penalty attributed to tracked shares is an immediate confirmed
        // loss. Stop every outbound and user Vault flow in this same transaction
        // before realizing it.
        _pauseAllocationIfNeeded();
        _pauseUserFlows();

        uint256 balanceBefore = underlying.balanceOf(address(this));
        uint256 withdrawnAssets;
        (penaltyShares, penaltyAssets, valuationLossAssets, withdrawnAssets) =
            IMorphoV2IncidentStrategy(address(_strategy)).forceDeallocate(_adapter, _data, _assets);
        uint256 received = underlying.balanceOf(address(this)) - balanceBefore;
        if (received < _minReceived) revert RecoveryBelowMinimum(received, _minReceived);
        if (!_refreshStrategyValuation(_strategy)) {
            if (received == withdrawnAssets) {
                _reduceStrategyValuationCache(_strategy, valuationLossAssets + withdrawnAssets);
            } else {
                _invalidateStrategyValuationCache(_strategy);
            }
        }
        emit ReceivedFromStrategy(address(_strategy), withdrawnAssets, received);

        uint256 backingAfter = _backingRatio();
        if (backingAfter < _minBackingRatioAfter) {
            revert BackingRatioBelowMinimum(backingAfter, _minBackingRatioAfter);
        }

        emit MorphoV2ForceDeallocated(
            address(_strategy), _adapter, _assets, penaltyShares, penaltyAssets, valuationLossAssets, backingAfter
        );
    }

    // --- Config / Pause (Strategy layer) ---

    function setAllocatorConfig(uint256 _maxMove, uint256 _cooldown) external override onlyRole(GOV_ROLE) {
        uint256 oldMaxMove = allocateMaxMove;
        uint256 oldCooldown = allocatorCooldown;
        allocateMaxMove = _maxMove;
        allocatorCooldown = _cooldown;
        emit AllocatorConfigUpdated(oldMaxMove, _maxMove, oldCooldown, _cooldown);
    }

    function setStrategyValuationMaxAge(uint256 _maxAge) external override onlyRole(GOV_ROLE) {
        uint256 oldMaxAge = strategyValuationMaxAge;
        strategyValuationMaxAge = _maxAge;
        emit StrategyValuationMaxAgeUpdated(oldMaxAge, _maxAge);
    }

    /// @inheritdoc ICollateralVault
    function setStrategyValuationGasBudget(uint256 _budget) external override onlyRole(GOV_ROLE) {
        if (_budget < MIN_STRATEGY_VALUATION_GAS || _budget > MAX_STRATEGY_VALUATION_GAS) {
            revert InvalidStrategyValuationGasBudget(_budget);
        }
        uint256 oldBudget = strategyValuationGasBudget();
        _strategyValuationGasBudget = _budget;
        emit StrategyValuationGasBudgetUpdated(oldBudget, _budget);
    }

    /// @inheritdoc ICollateralVault
    function strategyValuationGasBudget() public view override returns (uint256 budget) {
        budget = _strategyValuationGasBudget;
        if (budget == 0) budget = DEFAULT_STRATEGY_VALUATION_GAS;
    }

    function refreshStrategyValuation(IStrategy _strategy) external override returns (bool refreshed) {
        if (!_isRegisteredStrategy(_strategy)) revert StrategyNotFound();
        refreshed = _refreshStrategyValuation(_strategy);
    }

    /// @inheritdoc ICollateralVault
    /// @dev Allows WRITEOFF_ROLE as well as GOV_ROLE because invalidating a
    ///      fallback valuation cache can only remove stale backing from solvency
    ///      views. This gives the high-threshold incident role a same-block
    ///      response when a Strategy's live valuation is unavailable, without
    ///      giving low-threshold guardians the power to reprice collateral.
    ///      The WRITEOFF_ROLE path uses the same incident-ready guard as
    ///      `writeoffStrategyPrincipal`: allocation must be paused or the
    ///      Strategy must already be disabled.
    function invalidateStrategyValuationCache(IStrategy _strategy) external override {
        bool isGov = hasRole(GOV_ROLE, msg.sender);
        if (!isGov) _checkRole(WRITEOFF_ROLE, msg.sender);
        if (!_isRegisteredStrategy(_strategy)) revert StrategyNotFound();
        if (!isGov) _requireStrategyIncidentReady(_strategy);
        _invalidateStrategyValuationCache(_strategy);
    }

    function pauseAllocation() external override onlyRole(GUARDIAN_ROLE) {
        pausedAllocation = true;
        emit AllocationPaused();
    }

    function unpauseAllocation() external override onlyRole(GOV_ROLE) {
        pausedAllocation = false;
        emit AllocationUnpaused();
    }

    // =============================================================
    //                      VIEW FUNCTIONS
    // =============================================================

    /// @notice Underlying currently held in the Vault liquid buffer.
    /// @dev Placeholder-safe: returns 0 while `underlying == address(0)` so that
    ///      monitoring/subgraph reads of an inert placeholder branch do not revert
    ///      on `address(0).balanceOf(...)`. Excludes the protected backstop
    ///      reserve, so redeem / claim / allocate / treasury cannot consume
    ///      backstop funds unless GOV first releases them.
    function bufferBalance() public view override returns (uint256) {
        uint256 rawBalance = _rawUnderlyingBalance();
        uint256 reserve = _backstopReserve;
        return rawBalance > reserve ? rawBalance - reserve : 0;
    }

    /// @notice Underlying held as protected backstop reserve, capped by live balance.
    function backstopBalance() public view override returns (uint256) {
        uint256 rawBalance = _rawUnderlyingBalance();
        uint256 reserve = _backstopReserve;
        return reserve < rawBalance ? reserve : rawBalance;
    }

    /// @notice Total underlying the Vault can account for (buffer + conservative
    ///         Strategy valuation + protected backstop reserve). With no Strategy
    ///         registered this equals the Vault's raw underlying balance.
    /// @dev Uses `min(estimatedTotalUnderlying, principal)` per Strategy to stay
    ///      conservative against unrealized yield. If a Strategy valuation view
    ///      reverts, a fresh bounded last-good conservative cache is used; stale
    ///      or missing caches fall back to zero.
    ///      Placeholder-safe via `_rawUnderlyingBalance()` (returns 0 while unbound;
    ///      `strategies[]` is empty until Phase 3b activation, which itself
    ///      requires a bound underlying).
    function totalUnderlying() public view override returns (uint256 total) {
        (total,) = _totalUnderlyingWithAvailability();
    }

    /// @dev Same conservative sum as `totalUnderlying`, plus whether every
    ///      registered Strategy was valued live or from a fresh cache.
    function _totalUnderlyingWithAvailability() internal view returns (uint256 total, bool available) {
        total = _rawUnderlyingBalance();
        available = true;
        uint256 strategyCount = strategies.length;
        for (uint256 strategyIndex; strategyIndex < strategyCount; strategyIndex++) {
            (uint256 value, bool valued) = _strategyConservativeValueWithAvailability(strategies[strategyIndex]);
            total += value;
            if (!valued) available = false;
        }
    }

    /// @inheritdoc ICollateralVault
    function backingRatio() external view override returns (uint256) {
        return _backingRatio();
    }

    /// @inheritdoc ICollateralVault
    function backingRatioForPricing() external view override returns (uint256 ratio, bool available) {
        uint256 liabilities = _actualLiabilities();
        if (liabilities == 0) return (1e18, true);

        uint256 totalAssets;
        (totalAssets, available) = _totalUnderlyingWithAvailability();
        // Unknown Strategy assets are unnecessary when the known lower bound
        // already covers every dToken and queued-claim liability.
        if (totalAssets >= liabilities) return (1e18, true);
        if (!available) return (0, false);

        ratio = Math.mulDiv(totalAssets, 1e18, liabilities);
    }

    function _backingRatio() internal view returns (uint256) {
        uint256 liabilities = _actualLiabilities();
        if (liabilities == 0) return 1e18;

        uint256 totalAssets = totalUnderlying();
        if (totalAssets >= liabilities) return 1e18;

        return Math.mulDiv(totalAssets, 1e18, liabilities);
    }

    /// @inheritdoc ICollateralVault
    function actualLiabilities() public view override returns (uint256) {
        return _actualLiabilities();
    }

    function getStrategiesCount() external view override returns (uint256) {
        return strategies.length;
    }

    // =============================================================
    //                   INTERNAL FUNCTIONS
    // =============================================================

    /// @dev User liabilities in underlying terms: dToken backing + queued claims.
    function _actualLiabilities() internal view returns (uint256) {
        uint256 supply = dToken.totalSupply();
        uint256 userLiabilities = supply == 0 ? 0 : _dTokenToUnderlyingRoundingUp(supply);
        return userLiabilities + pendingWithdrawals;
    }

    /// @dev User balance-sheet mutations require strict pre-state solvency.
    ///      Unlike pricing views, this gate never accepts cached Strategy values;
    ///      unavailable live values conservatively contribute zero.
    function _requireConfirmedFullyBacked() internal view {
        uint256 liabilities = _actualLiabilities();
        if (liabilities == 0) return;

        uint256 totalAssets = _rawUnderlyingBalance();
        if (totalAssets >= liabilities) return;

        uint256 strategyCount = strategies.length;
        for (uint256 strategyIndex; strategyIndex < strategyCount; strategyIndex++) {
            (,,,, uint256 conservativeValue, bool liveAvailable) = _liveStrategyValuation(strategies[strategyIndex]);
            if (liveAvailable) {
                if (conservativeValue >= liabilities - totalAssets) return;
                totalAssets += conservativeValue;
            }
        }

        revert BackingRatioBelowMinimum(Math.mulDiv(totalAssets, 1e18, liabilities), 1e18);
    }

    /// @dev Shared pre-state validation for both redemption entry points. Keeps
    ///      the solvency check before permit, burn, queue mutation, and transfer.
    ///      Also rejects dToken dust that cannot map to an underlying base unit.
    function _requireValidRedemption(uint256 _dTokenAmount, address _receiver)
        internal
        view
        returns (uint256 underlyingAmount)
    {
        _requireUnderlyingReady();
        if (_dTokenAmount == 0) revert ZeroAmount();
        if (_receiver == address(0)) revert ZeroAddress();
        underlyingAmount = dToken.convertToUnderlying(_dTokenAmount);
        if (underlyingAmount == 0) revert InvalidDTokenAmount();
        if (dToken.convertToDToken(underlyingAmount) != _dTokenAmount) revert InvalidDTokenAmount();
        _requireConfirmedFullyBacked();
    }

    /// @dev Liability views round up so any unexpected or force-created dToken dust
    ///      is treated as one full underlying base unit rather than understated.
    function _dTokenToUnderlyingRoundingUp(uint256 _dTokenAmount) internal view returns (uint256 underlyingAmount) {
        underlyingAmount = dToken.convertToUnderlying(_dTokenAmount);
        if (dToken.convertToDToken(underlyingAmount) < _dTokenAmount) {
            underlyingAmount += 1;
        }
    }

    function _requireUnderlyingReady() internal view returns (IERC20 u) {
        u = underlying;
        if (address(u) == address(0)) revert UnderlyingNotSet();
        if (address(dToken.underlying()) != address(u)) revert UnderlyingMismatch();
    }

    function _queueWithdrawRequest(address _receiver, uint256 _remaining) private returns (uint256 requestId) {
        requestId = nextRequestId++;
        uint256 claimableAt = block.timestamp + withdrawDelay;
        withdrawRequests[requestId] =
            WithdrawRequest({owner: _receiver, underlyingAmount: _remaining, claimableAt: claimableAt, claimed: false});
        pendingWithdrawals += _remaining;
        emit WithdrawRequested(msg.sender, _receiver, requestId, _remaining, claimableAt);
    }

    function _completeRedemption(
        address _receiver,
        uint256 _dTokenAmount,
        uint256 _underlyingNeeded,
        uint256 _bufferBal
    ) private returns (uint256 underlyingReceived, uint256 requestId) {
        uint256 underlyingSent = _bufferBal < _underlyingNeeded ? _bufferBal : _underlyingNeeded;
        uint256 remaining = _underlyingNeeded - underlyingSent;

        // Preserve CEI for the delayed branch: record the fixed claim before
        // the token interaction. A later transfer failure rolls the request
        // and burn back with the rest of the transaction.
        if (remaining != 0) {
            requestId = _queueWithdrawRequest(_receiver, remaining);
        }

        if (underlyingSent != 0) {
            uint256 receiverBalanceBefore = underlying.balanceOf(_receiver);
            underlying.safeTransfer(_receiver, underlyingSent);
            underlyingReceived = underlying.balanceOf(_receiver) - receiverBalanceBefore;
        }

        emit Redeemed(msg.sender, _receiver, _dTokenAmount, underlyingReceived, requestId);
    }

    function _permitOrRequireAllowance(uint256 _dTokenAmount, uint256 _deadline, uint8 _v, bytes32 _r, bytes32 _s)
        private
    {
        try dToken.permit(msg.sender, address(this), _dTokenAmount, _deadline, _v, _r, _s) {}
        catch {
            if (IERC20(address(dToken)).allowance(msg.sender, address(this)) < _dTokenAmount) revert PermitFailed();
        }
    }

    function _rawUnderlyingBalance() internal view returns (uint256) {
        if (address(underlying) == address(0)) return 0;
        return underlying.balanceOf(address(this));
    }

    /// @dev Assets managed for liquidity/yield operations. Excludes protected
    ///      backstop reserve so repair funds cannot create allocatable or
    ///      treasury-sweepable surplus until GOV explicitly releases them.
    ///      Returns zero unless every registered Strategy has a live valuation,
    ///      preventing outbound transfers based on a partial system view.
    function _managedUnderlying() internal view returns (uint256 total) {
        total = bufferBalance();
        uint256 strategyCount = strategies.length;
        for (uint256 strategyIndex; strategyIndex < strategyCount; strategyIndex++) {
            (,,,, uint256 conservativeValue, bool liveAvailable) = _liveStrategyValuation(strategies[strategyIndex]);
            if (!liveAvailable) return 0;
            total += conservativeValue;
        }
    }

    /// @dev Liquid buffer that must stay on hand for redemption / claim
    ///      liquidity: the configured buffer target (`bufferTargetBps` of managed
    ///      assets, floored at `bufferFloor`) plus every queued withdrawal.
    ///      Shared by `allocate` (keeps this before pushing excess to Strategies)
    ///      and `transferYieldToTreasury` (keeps this before sweeping yield), so
    ///      the two Vault outflows reserve liquidity identically and neither can
    ///      strand a pending `claim`.
    function _requiredBuffer(uint256 _managedAssets) internal view returns (uint256 requiredBuffer) {
        requiredBuffer = Math.mulDiv(_managedAssets, bufferTargetBps, BPS_DENOMINATOR);
        if (requiredBuffer < bufferFloor) requiredBuffer = bufferFloor;
        requiredBuffer += pendingWithdrawals;
    }

    /// @dev Conservative Strategy value for solvency views. Live reads always
    ///      win; the bounded cache is used only for transient valuation
    ///      unavailability so one external view failure does not reprice every
    ///      Trove to zero in the same block.
    function _strategyConservativeValue(IStrategy _strategy) internal view returns (uint256) {
        (uint256 value,) = _strategyConservativeValueWithAvailability(_strategy);
        return value;
    }

    /// @dev Distinguishes a measured zero from a value that could not be read.
    function _strategyConservativeValueWithAvailability(IStrategy _strategy)
        internal
        view
        returns (uint256 value, bool available)
    {
        (,,,, uint256 conservativeValue, bool liveAvailable) = _liveStrategyValuation(_strategy);
        if (liveAvailable) return (conservativeValue, true);

        (uint256 cachedValue, bool cacheAvailable,) = _cachedStrategyConservativeValue(_strategy);
        return cacheAvailable ? (cachedValue, true) : (0, false);
    }

    function _liveStrategyValuation(IStrategy _strategy)
        internal
        view
        returns (
            uint256 estimated,
            bool estimateAvailable,
            uint256 principal_,
            bool principalAvailable,
            uint256 conservativeValue,
            bool liveAvailable
        )
    {
        (estimated, estimateAvailable) = _tryEstimatedTotalUnderlying(_strategy);
        (principal_, principalAvailable) = _tryPrincipal(_strategy);
        if (estimateAvailable && principalAvailable) {
            conservativeValue = estimated < principal_ ? estimated : principal_;
            liveAvailable = true;
        }
    }

    function _cachedStrategyConservativeValue(IStrategy _strategy)
        internal
        view
        returns (uint256 cachedValue, bool available, bool stale)
    {
        StrategyValuationCache memory cache = strategyValuationCaches[_strategy];
        if (!cache.initialized) return (0, false, false);

        uint256 maxAge = strategyValuationMaxAge;
        if (maxAge == 0 || block.timestamp - cache.updatedAt > maxAge) {
            return (0, false, true);
        }

        return (cache.conservativeValue, true, false);
    }

    function _refreshStrategyValuation(IStrategy _strategy) internal returns (bool refreshed) {
        (
            uint256 estimated,
            bool estimateAvailable,
            uint256 principal_,
            bool principalAvailable,
            uint256 conservativeValue,
            bool liveAvailable
        ) = _liveStrategyValuation(_strategy);

        if (!liveAvailable) {
            emit StrategyValuationRefreshFailed(address(_strategy), estimateAvailable, principalAvailable);
            return false;
        }

        strategyValuationCaches[_strategy] = StrategyValuationCache({
            conservativeValue: conservativeValue, updatedAt: block.timestamp, initialized: true
        });
        emit StrategyValuationRefreshed(address(_strategy), estimated, principal_, conservativeValue);
        return true;
    }

    function _reduceStrategyValuationCache(IStrategy _strategy, uint256 _amount) internal {
        if (_amount == 0) return;

        StrategyValuationCache storage cache = strategyValuationCaches[_strategy];
        uint256 oldValue = cache.conservativeValue;
        if (!cache.initialized) return;
        // Exhausting a historical estimate does not prove the residual position
        // is worth zero. Only a live valuation may establish an available zero.
        if (_amount >= oldValue) {
            _invalidateStrategyValuationCache(_strategy);
            return;
        }

        uint256 newValue = oldValue - _amount;
        cache.conservativeValue = newValue;
        emit StrategyValuationCacheReduced(address(_strategy), oldValue, newValue, _amount);
    }

    function _setStrategyValuationCache(IStrategy _strategy, uint256 _conservativeValue) internal {
        StrategyValuationCache storage cache = strategyValuationCaches[_strategy];
        cache.conservativeValue = _conservativeValue;
        cache.updatedAt = block.timestamp;
        cache.initialized = true;
    }

    function _invalidateStrategyValuationCache(IStrategy _strategy) internal {
        StrategyValuationCache storage cache = strategyValuationCaches[_strategy];
        emit StrategyValuationCacheInvalidated(address(_strategy), cache.conservativeValue, cache.updatedAt);
        delete strategyValuationCaches[_strategy];
    }

    function _requireStrategyIncidentReady(IStrategy _strategy) internal view {
        if (strategyConfigs[_strategy].enabled && !pausedAllocation) revert StrategyWriteoffNotReady();
    }

    function _pauseUserFlows() internal {
        if (!pausedDeposit) {
            pausedDeposit = true;
            emit DepositPaused();
        }
        if (!pausedRedeem) {
            pausedRedeem = true;
            emit RedeemPaused();
        }
        if (!pausedClaim) {
            pausedClaim = true;
            emit ClaimPaused();
        }
    }

    function _pauseAllocationIfNeeded() internal {
        if (!pausedAllocation) {
            // Strategy incidents should not allow fresh outbound allocation while loss recovery or writeoff is assessed.
            pausedAllocation = true;
            emit AllocationPaused();
        }
    }

    function _disableStrategy(IStrategy _strategy, StrategyConfig storage _config) internal {
        uint256 oldWeight = _config.weightBps;
        if (oldWeight != 0) {
            totalWeightBps -= oldWeight;
        }
        _config.weightBps = 0;
        _config.enabled = false;

        emit StrategyUpdated(address(_strategy), 0, _config.cap, false);
        emit StrategyEmergencyDisabled(address(_strategy), oldWeight);
    }

    function _tryEstimatedTotalUnderlying(IStrategy _strategy)
        internal
        view
        returns (uint256 estimated, bool available)
    {
        // Check each probe at its call boundary: the previous probe may have spent its budget.
        // Bubble caller underfunding instead of treating a clipped stipend as valuation failure.
        uint256 budget = strategyValuationGasBudget();
        if (gasleft() < budget * 64 / 63 + STRATEGY_VALUATION_GAS_MARGIN) {
            revert InsufficientGasForExternalCall();
        }
        try _strategy.estimatedTotalUnderlying{gas: budget}() returns (uint256 value) {
            return (value, true);
        } catch {
            return (0, false);
        }
    }

    function _tryPrincipal(IStrategy _strategy) internal view returns (uint256 principal_, bool available) {
        uint256 budget = strategyValuationGasBudget();
        if (gasleft() < budget * 64 / 63 + STRATEGY_VALUATION_GAS_MARGIN) {
            revert InsufficientGasForExternalCall();
        }
        try _strategy.principal{gas: budget}() returns (uint256 value) {
            return (value, true);
        } catch {
            return (0, false);
        }
    }

    /// @dev A Strategy is "registered" while it sits in `strategies[]` — enabled,
    ///      or merely disabled-but-not-yet-removed (so it can still push back its
    ///      remaining principal via `receiveFromStrategy`). Bounded by
    ///      MAX_STRATEGIES.
    function _isRegisteredStrategy(IStrategy _strategy) internal view returns (bool) {
        (, bool found) = _strategyIndex(_strategy);
        return found;
    }

    function _strategyIndex(IStrategy _strategy) internal view returns (uint256 index, bool found) {
        uint256 strategyCount = strategies.length;
        for (uint256 strategyIndex; strategyIndex < strategyCount; strategyIndex++) {
            if (strategies[strategyIndex] == _strategy) return (strategyIndex, true);
        }
        return (0, false);
    }

    /// @dev Split `_amount` across enabled Strategies by `weightBps`, respecting
    ///      each Strategy's cap. Cap-trimmed remainder stays in the buffer (it is
    ///      NOT re-spread to other Strategies). Push deposit: transfer underlying
    ///      to the Strategy first, then call `deposit` with the Strategy's net
    ///      receipt so principal cannot be inflated by transfer fees. A rejected
    ///      deposit is skipped only after the Strategy returns the funds and the
    ///      Vault's exact pre-transfer balance is restored.
    function _allocateToStrategies(uint256 _amount) internal {
        if (totalWeightBps == 0) return;
        for (uint256 strategyIndex; strategyIndex < strategies.length; strategyIndex++) {
            IStrategy strategy = strategies[strategyIndex];
            StrategyConfig storage strategyConfig = strategyConfigs[strategy];
            if (!strategyConfig.enabled) continue;

            uint256 targetAllocation = Math.mulDiv(_amount, strategyConfig.weightBps, totalWeightBps);
            if (targetAllocation == 0) continue;

            // Cap check (per-Strategy upper bound). Allocation requires a full
            // live valuation because fallback cache is based on min(est, principal).
            (uint256 currentEstimatedUnderlying,,,, uint256 currentConservativeValue, bool liveAvailable) =
                _liveStrategyValuation(strategy);
            if (!liveAvailable) {
                emit StrategyAllocationSkipped(address(strategy));
                continue;
            }
            if (currentEstimatedUnderlying >= strategyConfig.cap) {
                emit StrategyAllocationSkipped(address(strategy));
                continue;
            }
            uint256 remainingStrategyCap = strategyConfig.cap - currentEstimatedUnderlying;
            if (targetAllocation > remainingStrategyCap) targetAllocation = remainingStrategyCap;

            uint256 strategyUnderlyingBeforeTransfer = underlying.balanceOf(address(strategy));
            underlying.safeTransfer(address(strategy), targetAllocation);
            uint256 strategyUnderlyingReceived =
                underlying.balanceOf(address(strategy)) - strategyUnderlyingBeforeTransfer;
            if (strategy.deposit(targetAllocation, strategyUnderlyingReceived) == 0) {
                emit StrategyAllocationSkipped(address(strategy));
                continue;
            }
            if (!_refreshStrategyValuation(strategy)) {
                _setStrategyValuationCache(strategy, currentConservativeValue + strategyUnderlyingReceived);
            }
            emit StrategyAllocated(address(strategy), strategyUnderlyingReceived);
        }
    }
}
"
    },
    "src/CollateralVaultLens.sol": {
      "content": "// SPDX-License-Identifier: BUSL-1.1

pragma solidity 0.8.24;

import "openzeppelin-contracts/contracts/utils/math/Math.sol";

import "./Interfaces/ICollateralVault.sol";
import "./Interfaces/IStrategy.sol";

/**
 * @title CollateralVaultLens - read-only reporting surface for CollateralVault
 * @notice Ops and monitoring views, moved out of the Vault so they do not consume its
 *         EIP-170 budget. Fully stateless: no funds, no roles, no storage at all. The Vault
 *         is a parameter, so one deployment serves every branch, and each answer is
 *         reconstructed from that Vault's public getters plus direct calls to its Strategies.
 *
 * @dev    Why this exists: `CollateralVault` was within ~50 bytes of the 24,576-byte
 *         runtime limit, which blocked correctness fixes. These views are the largest
 *         removable surface and none of them is on a user or governance path — the Vault
 *         itself never calls them.
 *
 *         The reconstruction is exact rather than approximate. `_liveValuation` and
 *         `_cachedValuation` mirror the Vault's internal helpers, and every input they
 *         need (`strategies`, `strategyConfigs`, `strategyValuationCaches`,
 *         `strategyValuationMaxAge`, `totalUnderlying`, `actualLiabilities`) is already
 *         public. A Strategy view that reverts is caught here exactly as the Vault
 *         catches it, so an unreadable Strategy reports as unavailable rather than
 *         reverting the whole report.
 */
contract CollateralVaultLens {
    error InvalidBackingTarget();
    error StrategyNotFound();

    // =============================================================
    //                        SOLVENCY VIEWS
    // =============================================================

    /// @notice Underlying the Vault is short of its liabilities, or 0 when fully backed.
    function backingShortfall(ICollateralVault vault) external view returns (uint256) {
        uint256 totalAssets = vault.totalUnderlying();
        uint256 liabilities = vault.actualLiabilities();
        return liabilities > totalAssets ? liabilities - totalAssets : 0;
    }

    /// @notice Underlying that must be added to reach `_targetRatio` backing.
    function backstopRequiredForRatio(ICollateralVault vault, uint256 _targetRatio)
        external
        view
        returns (uint256)
    {
        if (_targetRatio > 1e18) revert InvalidBackingTarget();
        if (_targetRatio == 0) return 0;

        uint256 liabilities = vault.actualLiabilities();
        if (liabilities == 0) return 0;

        uint256 requiredAssets = Math.mulDiv(liabilities, _targetRatio, 1e18, Math.Rounding.Up);
        uint256 totalAssets = vault.totalUnderlying();
        return requiredAssets > totalAssets ? requiredAssets - totalAssets : 0;
    }

    // =============================================================
    //                       STRATEGY VIEWS
    // =============================================================

    function getStrategiesCount(ICollateralVault vault) external view returns (uint256) {
        return vault.getStrategiesCount();
    }

    /// @dev Reverts `StrategyNotFound` out of bounds, matching what the Vault did. Reading
    ///      `strategies(index)` through the public getter would panic on the array access
    ///      instead, which is a different error for the same condition.
    function getStrategyAt(ICollateralVault vault, uint256 _index)
        external
        view
        returns (IStrategy strategy, ICollateralVault.StrategyConfig memory config)
    {
        if (_index >= vault.getStrategiesCount()) revert StrategyNotFound();
        strategy = vault.strategies(_index);
        config = _configOf(vault, strategy);
    }

    function getAllStrategies(ICollateralVault vault)
        external
        view
        returns (
            IStrategy[] memory strategies_,
            ICollateralVault.StrategyConfig[] memory configs,
            uint256[] memory balances
        )
    {
        uint256 count = vault.getStrategiesCount();
        strategies_ = new IStrategy[](count);
        configs = new ICollateralVault.StrategyConfig[](count);
        balances = new uint256[](count);

        for (uint256 i; i < count; i++) {
            IStrategy strategy = vault.strategies(i);
            strategies_[i] = strategy;
            configs[i] = _configOf(vault, strategy);
            (uint256 estimated, bool available) = _tryEstimated(strategy);
            balances[i] = available ? estimated : 0;
        }
    }

    /// @notice Per-Strategy monitoring snapshot, identical in shape and content to what the
    ///         Vault used to return.
    function getStrategyStatuses(ICollateralVault vault)
        external
        view
        returns (ICollateralVault.StrategyStatus[] memory statuses)
    {
        uint256 count = vault.getStrategiesCount();
        statuses = new ICollateralVault.StrategyStatus[](count);
        for (uint256 i; i < count; i++) {
            IStrategy strategy = vault.strategies(i);
            statuses[i] = _buildStatus(vault, strategy, _configOf(vault, strategy));
        }
    }

    // =============================================================
    //                          INTERNAL
    // =============================================================

    function _configOf(ICollateralVault vault, IStrategy _strategy) internal view returns (ICollateralVault.StrategyConfig memory config) {
        (bool enabled, uint256 weightBps, uint256 cap) = vault.strategyConfigs(_strategy);
        config = ICollateralVault.StrategyConfig({enabled: enabled, weightBps: weightBps, cap: cap});
    }

    function _tryEstimated(IStrategy _strategy) internal view returns (uint256 estimated, bool available) {
        try _strategy.estimatedTotalUnderlying() returns (uint256 value) {
            return (value, true);
        } catch {
            return (0, false);
        }
    }

    function _tryPrincipal(IStrategy _strategy) internal view returns (uint256 principal_, bool available) {
        try _strategy.principal() returns (uint256 value) {
            return (value, true);
        } catch {
            return (0, false);
        }
    }

    /// @dev Mirrors `CollateralVault._liveStrategyValuation`.
    function _liveValuation(IStrategy _strategy)
        internal
        view
        returns (
            uint256 estimated,
            bool estimateAvailable,
            uint256 principal_,
            bool principalAvailable,
            uint256 conservativeValue,
            bool liveAvailable
        )
    {
        (estimated, estimateAvailable) = _tryEstimated(_strategy);
        (principal_, principalAvailable) = _tryPrincipal(_strategy);
        if (estimateAvailable && principalAvailable) {
            conservativeValue = estimated < principal_ ? estimated : principal_;
            liveAvailable = true;
        }
    }

    /// @dev Mirrors `CollateralVault._cachedStrategyConservativeValue`.
    function _cachedValuation(ICollateralVault vault, IStrategy _strategy)
        internal
        view
        returns (uint256 cachedValue, bool available, bool stale)
    {
        (uint256 conservativeValue, uint256 updatedAt, bool initialized) = vault.strategyValuationCaches(_strategy);
        if (!initialized) return (0, false, false);

        uint256 maxAge = vault.strategyValuationMaxAge();
        if (maxAge == 0 || block.timestamp - updatedAt > maxAge) return (0, false, true);

        return (conservativeValue, true, false);
    }

    /// @dev Mirrors `CollateralVault._buildStrategyStatus`.
    function _buildStatus(ICollateralVault vault, IStrategy _strategy, ICollateralVault.StrategyConfig memory _config)
        internal
        view
        returns (ICollateralVault.StrategyStatus memory status)
    {
        status.strategy = _strategy;
        status.config = _config;

        (
            uint256 estimated,
            bool estimateAvailable,
            uint256 principal_,
            bool principalAvailable,
            uint256 conservativeValue,
            bool liveAvailable
        ) = _liveValuation(_strategy);
        (uint256 cachedValue, bool cacheAvailable, bool cacheStale) = _cachedValuation(vault, _strategy);
        (uint256 rawCachedValue, uint256 cacheUpdatedAt,) = vault.strategyValuationCaches(_strategy);

        status.estimatedUnderlying = estimated;
        status.principal = principal_;
        status.estimateAvailable = estimateAvailable;
        status.principalAvailable = principalAvailable;
        status.cachedConservativeValue = rawCachedValue;
        status.cacheUpdatedAt = cacheUpdatedAt;
        status.cacheAvailable = cacheAvailable;
        status.cacheStale = cacheStale;

        if (estimateAvailable) {
            status.capRemaining = _config.cap > estimated ? _config.cap - estimated : 0;
        }

        if (liveAvailable) {
            status.conservativeValue = conservativeValue;
            if (estimated > principal_) {
                status.estimatedGain = estimated - principal_;
            } else {
                status.estimatedLoss = principal_ - estimated;
            }
        } else if (cacheAvailable) {
            status.conservativeValue = cachedValue;
            status.usingCachedConservativeValue = true;
        }
    }
}
"
    },
    "src/DFStabilityPool.sol": {
      "content": "// SPDX-License-Identifier: BUSL-1.1

pragma solidity 0.8.24;

import "openzeppelin-contracts/contracts/token/ERC20/utils/SafeERC20.sol";

import "./Interfaces/IStabilityPool.sol";
import "./Interfaces/IAddressesRegistry.sol";
import "./Interfaces/IStabilityPoolEvents.sol";
import "./Interfaces/ITroveManager.sol";
import "./Interfaces/IJpydfToken.sol";
import "./Dependencies/LiquityBase.sol";

/*
 * The Stability Pool holds JPYDF tokens deposited by Stability Pool depositors.
 *
 * When a trove is liquidated, then depending on system conditions, some of its JPYDF debt gets offset with
 * JPYDF in the Stability Pool:  that is, the offset debt evaporates, and an equal amount of JPYDF tokens in the Stability Pool is burned.
 *
 * Thus, a liquidation causes each depositor to receive a JPYDF loss, in proportion to their deposit as a share of total deposits.
 * They also receive an Coll gain, as the collateral of the liquidated trove is distributed among Stability depositors,
 * in the same proportion.
 *
 * When a liquidation occurs, it depletes every deposit by the same fraction: for example, a liquidation that depletes 40%
 * of the total JPYDF in the Stability Pool, depletes 40% of each deposit.
 *
 * A deposit that has experienced a series of liquidations is termed a "compounded deposit": each liquidation depletes the deposit,
 * multiplying it by some factor in range ]0,1[
 *
 *
 * --- IMPLEMENTATION ---
 *
 * We use a highly scalable method of tracking deposits and Coll gains that has O(1) complexity.
 *
 * When a liquidation occurs, rather than updating each depositor's deposit and Coll gain, we simply update two state variables:
 * a product P, and a sum S.
 *
 * A mathematical manipulation allows us to factor out the initial deposit, and accurately track all depositors' compounded deposits
 * and accumulated Coll gains over time, as liquidations occur, using just these two variables P and S. When depositors join the
 * Stability Pool, they get a snapshot of the latest P and S: P_t and S_t, respectively.
 *
 * The formula for a depositor's accumulated Coll gain is derived here:
 * https://github.com/liquity/dev/blob/main/papers/Scalable_Reward_Distribution_with_Compounding_Stakes.pdf
 *
 * For a given deposit d_t, the ratio P/P_t tells us the factor by which a deposit has decreased since it joined the Stability Pool,
 * and the term d_t * (S - S_t)/P_t gives us the deposit's total accumulated Coll gain.
 *
 * Each liquidation updates the product P and sum S. After a series of liquidations, a compounded deposit and corresponding Coll gain
 * can be calculated using the initial deposit, the depositor’s snapshots of P and S, and the latest values of P and S.
 *
 * Any time a depositor updates their deposit (withdrawal, top-up) their accumulated Coll gain is paid out, their new deposit is recorded
 * (based on their latest compounded deposit and modified by the withdrawal/top-up), and they receive new snapshots of the latest P and S.
 * Essentially, they make a fresh deposit that overwrites the old one.
 *
 *
 * --- SCALE FACTOR ---
 *
 * Since P is a running product in range ]0,1] that is always-decreasing, it should never reach 0 when multiplied by a number in range ]0,1[.
 * Unfortunately, Solidity floor division always reaches 0, sooner or later.
 *
 * A series of liquidations that nearly empty the Pool (and thus each multiply P by a very small number in range ]0,1[ ) may push P
 * to its 36 digit decimal limit, and round it to 0, when in fact the Pool hasn't been emptied: this would break deposit tracking.
 * 
 * P is stored at 36-digit precision as a uint. That is, a value of "1" is represented by a value of 1e36 in the code.
 *
 * So, to track P accurately, we use a scale factor: if a liquidation would cause P to decrease below 1e27,
 * we first multiply P by 1e9, and increment a currentScale factor by 1.
 *
 * The added benefit of using 1e9 for the scale factor that it ensures negligible precision loss close to the
 * scale boundary: when P is at its minimum value of 1e27, the relative precision loss in P due to floor division is only on the
 * order of 1e-27.
 *
 * --- MIN JPYDF IN SP ---
 *
 * Once totalJpydfDeposits has become >= MIN_JPYDF_IN_SP, a liquidation may never fully empty the Pool - a minimum of 1 JPYDF remains in the SP at all times thereafter.
 * This is enforced for liquidations in TroveManager.batchLiquidateTroves, and for withdrawals in StabilityPool.withdrawFromSP.
 * As such, it is impossible to empty the Stability Pool via liquidations, and P can never become 0.
 *
 * --- TRACKING DEPOSIT OVER SCALE CHANGES ---
 *
 * When a deposit is made, it gets a snapshot of the currentScale.
 *
 * When calculating a compounded deposit, we compare the current scale to the deposit's scale snapshot. If they're equal, the compounded deposit is given by d_t * P/P_t.
 * If it spans one scale change, it is given by d_t * P/(P_t * 1e9).
 *
 *  --- TRACKING DEPOSITOR'S COLL GAIN OVER SCALE CHANGES  ---
 *
 * We calculate the depositor's accumulated Coll gain for the scale at which they made the deposit, using the Coll gain formula:
 * e_1 = d_t * (S - S_t) / P_t
 *
 * and also for the scale after, taking care to divide the latter by a factor of 1e9:
 * e_2 = d_t * S / (P_t * 1e9)
 *
 * The gain in the second scale will be full, as the starting point was in the previous scale, thus no need to subtract anything.
 * The deposit therefore was present for reward events from the beginning of that second scale.
 *
 *        S_i-S_t + S_{i+1}
 *      .<--------.------------>
 *      .         .
 *      . S_i     .   S_{i+1}
 *   <--.-------->.<----------->
 *   S_t.         .
 *   <->.         .
 *      t         .
 *  |---+---------|-------------|-----...
 *         i            i+1
 *
 * The sum of (e_1 + e_2) captures the depositor's total accumulated Coll gain, handling the case where their
 * deposit spanned one scale change.
 *
 * --- UPDATING P WHEN A LIQUIDATION OCCURS ---
 *
 * Please see the implementation spec in the proof document, which closely follows on from the compounded deposit / Coll gain derivations:
 * https://github.com/liquity/liquity/blob/master/papers/Scalable_Reward_Distribution_with_Compounding_Stakes.pdf
 *
 *
 */
contract DFStabilityPool is LiquityBase, IStabilityPool, IStabilityPoolEvents {
    using SafeERC20 for IERC20;

    string public constant NAME = "StabilityPool";

    IAddressesRegistry internal immutable addressesRegistry;
    IERC20 public immutable collToken;
    ITroveManager public immutable troveManager;
    IJpydfToken public immutable jpydfToken;

    uint256 internal collBalance; // deposited coll tracker

    // Tracker for JPYDF held in the pool. Changes when users deposit/withdraw, and when Trove debt is offset.
    uint256 internal totalJpydfDeposits;

    // Total remaining JPYDF yield gains (from Trove interest mints) held by SP, and not yet paid out to depositors
    // From the contract's perspective, this is a write-only variable.
    uint256 internal yieldGainsOwed;
    // Total remaining JPYDF yield gains (from Trove interest mints) held by SP, not yet paid out to depositors,
    // and not accounted for because they were received when the total deposits were too small
    uint256 internal yieldGainsPending;

    // --- Data structures ---

    struct Deposit {
        uint256 initialValue;
    }

    struct Snapshots {
        uint256 S; // Coll reward sum liqs
        uint256 P;
        uint256 B; // JPYDF reward sum from minted interest
        uint256 scale;
    }

    mapping(address => Deposit) public deposits; // depositor address -> Deposit struct
    mapping(address => Snapshots) public depositSnapshots; // depositor address -> snapshots struct
    mapping(address => uint256) public stashedColl;

    /*  Product 'P': Running product by which to multiply an initial deposit, in order to find the current compounded deposit,
    * after a series of liquidations have occurred, each of which cancel some JPYDF debt with the deposit.
    *
    * During its lifetime, a deposit's value evolves from d_t to d_t * P / P_t , where P_t
    * is the snapshot of P taken at the instant the deposit was made. 18-digit decimal.
    */
    uint256 public P = P_PRECISION;

    uint256 public constant P_PRECISION = 1e36;

    // A scale change will happen if P decreases by a factor of at least this much
    uint256 public constant SCALE_FACTOR = 1e9;

    // Highest power `SCALE_FACTOR` can be raised to without overflow
    uint256 public constant MAX_SCALE_FACTOR_EXPONENT = 8;

    // The number of scale changes after which an untouched deposit stops receiving yield / coll gains
    uint256 public constant SCALE_SPAN = 2;

    // Each time the scale of P shifts by SCALE_FACTOR, the scale is incremented by 1
    uint256 public currentScale;

    /* Coll Gain sum 'S': During its lifetime, each deposit d_t earns an Coll gain of ( d_t * [S - S_t] )/P_t, where S_t
    * is the depositor's snapshot of S taken at the time t when the deposit was made.
    *
    * The 'S' sums are stored in a mapping (scale => sum).
    * - The mapping records the sum S at different scales.
    */
    mapping(uint256 => uint256) public scaleToS;
    mapping(uint256 => uint256) public scaleToB;

    // Prevent same-block flash deposits from capturing liquidation gains and
    // immediately withdrawing in the same atomic bundle. The guard requires
    // persistence across a block boundary; it does not guarantee an intervening
    // offset or a full block of liquidation exposure.
    mapping(address => uint256) public lastDepositBlock;

    // --- Events ---

    event TroveManagerAddressChanged(address _newTroveManagerAddress);
    event JpydfTokenAddressChanged(address _newJpydfTokenAddress);

    constructor(IAddressesRegistry _addressesRegistry) LiquityBase(_addressesRegistry) {
        addressesRegistry = _addressesRegistry;
        collToken = _addressesRegistry.collToken();
        troveManager = _addressesRegistry.troveManager();
        jpydfToken = _addressesRegistry.jpydfToken();

        emit TroveManagerAddressChanged(address(troveManager));
        emit JpydfTokenAddressChanged(address(jpydfToken));
    }

    // --- Getters for public variables. Required by IPool interface ---

    function getCollBalance() external view override returns (uint256) {
        return collBalance;
    }

    function getTotalJpydfDeposits() external view override returns (uint256) {
        return totalJpydfDeposits;
    }

    function getYieldGainsOwed() external view override returns (uint256) {
        return yieldGainsOwed;
    }

    function getYieldGainsPending() external view override returns (uint256) {
        return yieldGainsPending;
    }

    // --- External Depositor Functions ---

    /*  provideToSP():
    * - Calculates depositor's Coll gain
    * - Calculates the compounded deposit
    * - Increases deposit, and takes new snapshots of accumulators P and S
    * - Sends depositor's accumulated Coll gains to depositor
    */
    function provideToSP(uint256 _topUp, bool _doClaim) external override {
        if (!addressesRegistry.riskParamsFinalized()) revert RiskParamsNotFinalized();
        _requireNonZeroAmount(_topUp);

        activePool.mintAggInterest();

        uint256 initialDeposit = deposits[msg.sender].initialValue;

        uint256 currentCollGain = getDepositorCollGain(msg.sender);
        if (_doClaim && initialDeposit > 0 && (currentCollGain > 0 || stashedColl[msg.sender] > 0)) {
            _requireCollGainClaimAfterDeposit();
        }
        uint256 currentYieldGain = getDepositorYieldGain(msg.sender);
        uint256 compoundedJpydfDeposit = getCompoundedJpydfDeposit(msg.sender);
        (uint256 keptYieldGain, uint256 yieldGainToSend) = _getYieldToKeepOrSend(currentYieldGain, _doClaim);
        uint256 newDeposit = compoundedJpydfDeposit + _topUp + keptYieldGain;
        (uint256 newStashedColl, uint256 collToSend) =
            _getNewStashedCollAndCollToSend(msg.sender, currentCollGain, _doClaim);

        emit DepositOperation(
            msg.sender,
            Operation.provideToSP,
            initialDeposit - compoundedJpydfDeposit,
            int256(_topUp),
            currentYieldGain,
            yieldGainToSend,
            currentCollGain,
            collToSend
        );

        lastDepositBlock[msg.sender] = block.number;
        _updateDepositAndSnapshots(msg.sender, newDeposit, newStashedColl);
        jpydfToken.sendToPool(msg.sender, address(this), _topUp);
        _updateTotalJpydfDeposits(_topUp + keptYieldGain, 0);
        _decreaseYieldGainsOwed(currentYieldGain);
        _sendJpydfToDepositor(msg.sender, yieldGainToSend);
        _sendCollGainToDepositor(collToSend);

        // If there were pending yields and with the new deposit we are reaching the threshold, let’s move the yield to owed
        _updateYieldRewardsSum(0);
    }

    function _getYieldToKeepOrSend(uint256 _currentYieldGain, bool _doClaim) internal pure returns (uint256, uint256) {
        uint256 yieldToKeep;
        uint256 yieldToSend;

        if (_doClaim) {
            yieldToKeep = 0;
            yieldToSend = _currentYieldGain;
        } else {
            yieldToKeep = _currentYieldGain;
            yieldToSend = 0;
        }

        return (yieldToKeep, yieldToSend);
    }

    /*  withdrawFromSP():
    * - Calculates depositor's Coll gain
    * - Calculates the compounded deposit
    * - Sends the requested JPYDF withdrawal to depositor
    * - (If _amount > userDeposit, the user withdraws all of their compounded deposit)
    * - Decreases deposit by withdrawn amount and takes new snapshots of accumulators P and S
    */
    function withdrawFromSP(uint256 _amount, bool _doClaim) external override {
        uint256 initialDeposit = deposits[msg.sender].initialValue;
        _requireUserHasDeposit(initialDeposit);
        _requireWithdrawalAfterDeposit();

        activePool.mintAggInterest();

        uint256 currentCollGain = getDepositorCollGain(msg.sender);
        uint256 currentYieldGain = getDepositorYieldGain(msg.sender);
        uint256 compoundedJpydfDeposit = getCompoundedJpydfDeposit(msg.sender);
        uint256 jpydfToWithdraw = LiquityMath._min(_amount, compoundedJpydfDeposit);
        (uint256 keptYieldGain, uint256 yieldGainToSend) = _getYieldToKeepOrSend(currentYieldGain, _doClaim);
        uint256 newDeposit = compoundedJpydfDeposit - jpydfToWithdraw + keptYieldGain;
        (uint256 newStashedColl, uint256 collToSend) =
            _getNewStashedCollAndCollToSend(msg.sender, currentCollGain, _doClaim);

        emit DepositOperation(
            msg.sender,
            Operation.withdrawFromSP,
            initialDeposit - compoundedJpydfDeposit,
            -int256(jpydfToWithdraw),
            currentYieldGain,
            yieldGainToSend,
            currentCollGain,
            collToSend
        );

        _updateDepositAndSnapshots(msg.sender, newDeposit, newStashedColl);
        _decreaseYieldGainsOwed(currentYieldGain);
        uint256 newTotalJpydfDeposits = _updateTotalJpydfDeposits(keptYieldGain, jpydfToWithdraw);
        _sendJpydfToDepositor(msg.sender, jpydfToWithdraw + yieldGainToSend);
        _sendCollGainToDepositor(collToSend);

        require(newTotalJpydfDeposits >= MIN_JPYDF_IN_SP, "Withdrawal must leave totalJpydfDeposits >= MIN_JPYDF_IN_SP");
    }

    function _getNewStashedCollAndCollToSend(address _depositor, uint256 _currentCollGain, bool _doClaim)
        internal
        view
        returns (uint256 newStashedColl, uint256 collToSend)
    {
        if (_doClaim) {
            newStashedColl = 0;
            collToSend = stashedColl[_depositor] + _currentCollGain;
        } else {
            newStashedColl = stashedColl[_depositor] + _currentCollGain;
            collToSend = 0;
        }
    }

    // This function is only needed in the case a user has no deposit but still has remaining stashed Coll gains.
    function claimAllCollGains() external {
        _requireUserHasNoDeposit(msg.sender);

        activePool.mintAggInterest();

        uint256 collToSend = stashedColl[msg.sender];
        _requireNonZeroAmount(collToSend);
        stashedColl[msg.sender] = 0;

        emit DepositOperation(msg.sender, Operation.claimAllCollGains, 0, 0, 0, 0, 0, collToSend);
        emit DepositUpdated(msg.sender, 0, 0, 0, 0, 0, 0);

        _sendCollGainToDepositor(collToSend);
    }

    // --- JPYDF reward functions ---

    function triggerJpydfRewards(uint256 _jpydfYield) external {
        _requireCallerIsActivePool();
        _updateYieldRewardsSum(_jpydfYield);
    }

    function _updateYieldRewardsSum(uint256 _newYield) internal {
        uint256 accumulatedYieldGains = yieldGainsPending + _newYield;
        if (accumulatedYieldGains == 0) return;

        // When total deposits is very small, B is not updated. In this case, the JPYDF issued is held
        // until the total deposits reach 1 JPYDF (remains in the balance of the SP).
        if (totalJpydfDeposits < MIN_JPYDF_IN_SP) {
            yieldGainsPending = accumulatedYieldGains;
            return;
        }

        yieldGainsOwed += accumulatedYieldGains;
        yieldGainsPending = 0;

        scaleToB[currentScale] += P * accumulatedYieldGains / totalJpydfDeposits;
        emit B_Updated(scaleToB[currentScale], currentScale);
    }

    // --- Liquidation functions ---

    /*
    * Cancels out the specified debt against the JPYDF contained in the Stability Pool (as far as possible)
    * and transfers the Trove's Coll collateral from ActivePool to StabilityPool.
    * Only called by liquidation functions in the TroveManager.
    */
    function offset(uint256 _debtToOffset, uint256 _collToAdd) external override {
        _requireCallerIsTroveManager();

        scaleToS[currentScale] += P * _collToAdd / totalJpydfDeposits;
        emit S_Updated(scaleToS[currentScale], currentScale);

        uint256 numerator = P * (totalJpydfDeposits - _debtToOffset);
        uint256 newP = numerator / totalJpydfDeposits;

        // For `P` to turn zero, `totalJpydfDeposits` has to be greater than `P * (totalJpydfDeposits - _debtToOffset)`.
        // - As the offset must leave at least 1 JPYDF in the SP (MIN_JPYDF_IN_SP),
        //   the minimum value of `totalJpydfDeposits - _debtToOffset` is `1e18`
        // - It can be shown that `P` is always in range [1e27, 1e36].
        // Thus, to turn `P` zero, `totalJpydfDeposits` has to be greater than `1e27 * 1e18`,
        // and the offset has to be (near) maximal.
        // In other words, there needs to be octillions of JPYDF in the SP, which is unlikely to happen in practice.
        require(newP > 0, "P must never decrease to 0");

        // Overflow analysis of scaling up P:
        // We know that the resulting P is <= 1e36, and it's the result of dividing numerator by totalJpydfDeposits.
        // Thus, numerator <= 1e36 * totalJpydfDeposits, so unless totalJpydfDeposits is septillions of JPYDF, it won’t overflow.
        // That holds on every iteration as an upper bound. We multiply numerator by SCALE_FACTOR,
        // but numerator is by definition smaller than 1e36 * totalJpydfDeposits / SCALE_FACTOR.
        while (newP < P_PRECISION / SCALE_FACTOR) {
            numerator *= SCALE_FACTOR;
            newP = numerator / totalJpydfDeposits;
            currentScale += 1;
            emit ScaleUpdated(currentScale);
        }

        emit P_Updated(newP);
        P = newP;

        _moveOffsetCollAndDebt(_collToAdd, _debtToOffset);
    }

    function _moveOffsetCollAndDebt(uint256 _collToAdd, uint256 _debtToOffset) internal {
        // Cancel the liquidated JPYDF debt with the JPYDF in the stability pool
        _updateTotalJpydfDeposits(0, _debtToOffset);

        // Burn the debt that was successfully offset
        jpydfToken.burn(address(this), _debtToOffset);

        // Update internal Coll balance tracker
        uint256 newCollBalance = collBalance + _collToAdd;
        collBalance = newCollBalance;

        // Pull Coll from Active Pool
        activePool.sendColl(address(this), _collToAdd);

        emit StabilityPoolCollBalanceUpdated(newCollBalance);
    }

    function _updateTotalJpydfDeposits(uint256 _depositIncrease, uint256 _depositDecrease) internal returns (uint256) {
        if (_depositIncrease == 0 && _depositDecrease == 0) return totalJpydfDeposits;
        uint256 newTotalJpydfDeposits = totalJpydfDeposits + _depositIncrease - _depositDecrease;
        totalJpydfDeposits = newTotalJpydfDeposits;

        emit StabilityPoolJpydfBalanceUpdated(newTotalJpydfDeposits);
        return newTotalJpydfDeposits;
    }

    function _decreaseYieldGainsOwed(uint256 _amount) internal {
        if (_amount == 0) return;
        uint256 newYieldGainsOwed = yieldGainsOwed - _amount;
        yieldGainsOwed = newYieldGainsOwed;
    }

    // --- Reward calculator functions for depositor ---

    function getDepositorCollGain(address _depositor) public view override returns (uint256) {
        uint256 initialDeposit = deposits[_depositor].initialValue;
        if (initialDeposit == 0) return 0;

        Snapshots storage snapshots = depositSnapshots[_depositor];

        // Coll gains from the same scale in which the deposit was made need no scaling
        uint256 normalizedGains = scaleToS[snapshots.scale] - snapshots.S;

        // Scale down further coll gains by a power of `SCALE_FACTOR` depending on how many scale changes they span
        for (uint256 i = 1; i <= SCALE_SPAN; ++i) {
            normalizedGains += scaleToS[snapshots.scale + i] / SCALE_FACTOR ** i;
        }

        return LiquityMath._min(initialDeposit * normalizedGains / snapshots.P, collBalance);
    }

    function getDepositorYieldGain(address _depositor) public view override returns (uint256) {
        uint256 initialDeposit = deposits[_depositor].initialValue;
        if (initialDeposit == 0) return 0;

        Snapshots storage snapshots = depositSnapshots[_depositor];

        // Yield gains from the same scale in which the deposit was made need no scaling
        uint256 normalizedGains = scaleToB[snapshots.scale] - snapshots.B;

        // Scale down further yield gains by a power of `SCALE_FACTOR` depending on how many scale changes they span
        for (uint256 i = 1; i <= SCALE_SPAN; ++i) {
            normalizedGains += scaleToB[snapshots.scale + i] / SCALE_FACTOR ** i;
        }

        return LiquityMath._min(initialDeposit * normalizedGains / snapshots.P, yieldGainsOwed);
    }

    function getDepositorYieldGainWithPending(address _depositor) external view override returns (uint256) {
        if (totalJpydfDeposits < MIN_JPYDF_IN_SP) return 0;

        uint256 initialDeposit = deposits[_depositor].initialValue;
        if (initialDeposit == 0) return 0;

        Snapshots storage snapshots = depositSnapshots[_depositor];
        uint256 newYieldGainsOwed = yieldGainsOwed;

        // Yield gains from the same scale in which the deposit was made need no scaling
        uint256 normalizedGains = scaleToB[snapshots.scale] - snapshots.B;

        // Scale down further yield gains by a power of `SCALE_FACTOR` depending on how many scale changes they span
        for (uint256 i = 1; i <= SCALE_SPAN; ++i) {
            normalizedGains += scaleToB[snapshots.scale + i] / SCALE_FACTOR ** i;
        }

        // Pending gains
        uint256 pendingSPYield = activePool.calcPendingSPYield();
        newYieldGainsOwed += pendingSPYield;

        if (currentScale <= snapshots.scale + SCALE_SPAN) {
            normalizedGains +=
                P * pendingSPYield / totalJpydfDeposits / SCALE_FACTOR ** (currentScale - snapshots.scale);
        }

        return LiquityMath._min(initialDeposit * normalizedGains / snapshots.P, newYieldGainsOwed);
    }

    // --- Compounded deposit ---

    function getCompoundedJpydfDeposit(address _depositor) public view override returns (uint256 compoundedDeposit) {
        uint256 initialDeposit = deposits[_depositor].initialValue;
        if (initialDeposit == 0) return 0;

        Snapshots storage snapshots = depositSnapshots[_depositor];

        uint256 scaleDiff = currentScale - snapshots.scale;

        // Compute the compounded deposit. If one or more scale changes in `P` were made during the deposit's lifetime,
        // account for them.
        // If more than `MAX_SCALE_FACTOR_EXPONENT` scale changes were made, then the divisor is greater than 2^256 so
        // any deposit amount would be rounded down to zero.
        if (scaleDiff <= MAX_SCALE_FACTOR_EXPONENT) {
            compoundedDeposit = initialDeposit * P / snapshots.P / SCALE_FACTOR ** scaleDiff;
        } else {
            compoundedDeposit = 0;
        }
    }

    // --- Sender functions for JPYDF deposit and Coll gains ---

    function _sendCollGainToDepositor(uint256 _collAmount) internal {
        if (_collAmount == 0) return;

        uint256 newCollBalance = collBalance - _collAmount;
        collBalance = newCollBalance;
        emit StabilityPoolCollBalanceUpdated(newCollBalance);
        collToken.safeTransfer(msg.sender, _collAmount);
    }

    // Send JPYDF to user and decrease JPYDF in Pool
    function _sendJpydfToDepositor(address _depositor, uint256 _jpydfToSend) internal {
        if (_jpydfToSend == 0) return;
        jpydfToken.returnFromPool(address(this), _depositor, _jpydfToSend);
    }

    // --- Stability Pool Deposit Functionality ---

    function _updateDepositAndSnapshots(address _depositor, uint256 _newDeposit, uint256 _newStashedColl) internal {
        deposits[_depositor].initialValue = _newDeposit;
        stashedColl[_depositor] = _newStashedColl;

        if (_newDeposit == 0) {
            delete depositSnapshots[_depositor];
            emit DepositUpdated(_depositor, 0, _newStashedColl, 0, 0, 0, 0);
            return;
        }

        uint256 currentScaleCached = currentScale;
        uint256 currentP = P;

        // Get S for the current scale
        uint256 currentS = scaleToS[currentScaleCached];
        uint256 currentB = scaleToB[currentScaleCached];

        // Record new snapshots of the latest running product P and sum S for the depositor
        depositSnapshots[_depositor].P = currentP;
        depositSnapshots[_depositor].S = currentS;
        depositSnapshots[_depositor].B = currentB;
        depositSnapshots[_depositor].scale = currentScaleCached;

        emit DepositUpdated(_depositor, _newDeposit, _newStashedColl, currentP, currentS, currentB, currentScaleCached);
    }

    // --- 'require' functions ---

    function _requireCallerIsActivePool() internal view {
        require(msg.sender == address(activePool), "StabilityPool: Caller is not ActivePool");
    }

    function _requireCallerIsTroveManager() internal view {
        require(msg.sender == address(troveManager), "StabilityPool: Caller is not TroveManager");
    }

    function _requireUserHasDeposit(uint256 _initialDeposit) internal pure {
        require(_initialDeposit > 0, "StabilityPool: User must have a non-zero deposit");
    }

    function _requireUserHasNoDeposit(address _address) internal view {
        uint256 initialDeposit = deposits[_address].initialValue;
        require(initialDeposit == 0, "StabilityPool: User must have no deposit");
    }

    function _requireNonZeroAmount(uint256 _amount) internal pure {
        require(_amount > 0, "StabilityPool: Amount must be non-zero");
    }

    function _requireWithdrawalAfterDeposit() internal view {
        require(lastDepositBlock[msg.sender] < block.number, "StabilityPool: Withdrawal must wait after deposit");
    }

    function _requireCollGainClaimAfterDeposit() internal view {
        require(lastDepositBlock[msg.sender] < block.number, "StabilityPool: Coll gain claim must wait after deposit");
    }
}
"
    },
    "src/DToken.sol": {
      "content": "// SPDX-License-Identifier: BUSL-1.1

pragma solidity 0.8.24;

import "openzeppelin-contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol";
import "openzeppelin-contracts-upgradeable/token/ERC20/extensions/ERC20PermitUpgradeable.sol";
import "openzeppelin-contracts-upgradeable/token/ERC20/extensions/IERC20MetadataUpgradeable.sol";
import "openzeppelin-contracts-upgradeable/proxy/utils/Initializable.sol";
import "openzeppelin-contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "openzeppelin-contracts-upgradeable/access/OwnableUpgradeable.sol";

import "./Interfaces/IDToken.sol";
import {IAddressesRegistry} from "src/Interfaces/IAddressesRegistry.sol";

/**
 * @title DToken - Collateral Benefit Token (Upgradeable)
 * @notice ERC-20 token representing a 1:1 principal claim on Underlying
 * @dev - decimals fixed at 18 (per Liquity v2 requirements)
 *      - mint/burn permissions restricted to CollateralVault only
 *      - EIP-2612 permit support (enables redeem without prior approve)
 *      - No yield accrual (principal claim only)
 *      - Upgradeable via UUPS pattern
 */
contract DToken is
    Initializable,
    ERC20Upgradeable,
    ERC20PermitUpgradeable,
    OwnableUpgradeable,
    UUPSUpgradeable,
    IDToken
{
    /// @notice Corresponding Underlying token
    IERC20MetadataUpgradeable public override underlying;

    /// @notice Vault address that issues this dToken
    address public override vault;

    /// @notice Fixed decimals for dToken
    uint8 public constant DTOKEN_DECIMALS = 18;

    /// @notice Underlying token decimals
    uint8 public override underlyingDecimals;

    /// @notice Custom name for dToken, set after initialization
    string private _customName;

    /// @notice Custom symbol for dToken, set after initialization
    string private _customSymbol;

    /// @notice Multiplier for decimals conversion (10^(18 - underlyingDecimals))
    uint256 private _decimalMultiplier;

    /// @notice Maximum supply cap for dToken
    /// @dev 18 decimals. Starts closed until the branch's risk parameters are final.
    uint256 public override cap;

    /// @notice Pending owner for two-step ownership transfer
    address private _pendingOwner;

    /// @notice Underlying tokens allowed for this dToken binding.
    mapping(address => bool) public override allowedUnderlying;

    /// @notice One-shot binding to the Core branch that controls mint readiness.
    address public override riskParamsRegistry;

    /// @dev Storage gap for future upgrades. See OpenZeppelin's storage gap guidance:
    /// https://docs.openzeppelin.com/upgrades-plugins/writing-upgradeable#storage-gaps
    /// Always append new storage variables above this gap and shrink the gap
    /// instead of inserting variables between existing storage slots.
    uint256[47] private __gap;

    // --- Errors ---

    /// @notice Address cannot be zero
    error ZeroAddress();

    /// @notice Mint/burn called from non-Vault address
    error OnlyVault();

    /// @notice Underlying decimals exceeds 18
    error InvalidUnderlyingDecimals();

    /// @notice Address must be a deployed contract
    error NotContract();

    /// @notice Underlying token has not been allowlisted
    error UnderlyingNotAllowed();

    /// @notice Total supply after mint exceeds cap
    error CapExceeded(uint256 totalSupplyAfterMint, uint256 cap);

    /// @notice Token info already set
    error TokenInfoAlreadySet();

    /// @notice Token name cannot be empty
    error EmptyTokenName();

    /// @notice Token symbol cannot be empty
    error EmptyTokenSymbol();

    /// @notice Token info cannot be changed after supply exists
    error SupplyAlreadyExists();

    /// @notice Token info has not been configured yet
    error TokenInfoNotSet();

    /// @notice Ownership renounce is disabled to preserve governance controls
    error RenounceOwnershipDisabled();

    error DToken__RiskParamsNotFinalized();
    error DToken__RiskParamsRegistryAlreadySet();
    error DToken__RegistryCollateralMismatch();
    error DToken__CapMustBeZero();

    // --- Events ---

    /// @notice Emitted when cap is updated
    event CapUpdated(uint256 oldCap, uint256 newCap);

    event RiskParamsRegistryBound(address indexed registry);

    /// @notice Emitted when token metadata and underlying asset are configured
    event TokenInfoSet(string name, string symbol, address indexed underlying, uint8 underlyingDecimals);

    /// @notice Emitted when an underlying token allowlist entry is updated
    event AllowedUnderlyingUpdated(address indexed underlying, bool allowed);

    /// @notice Emitted when an ownership transfer is started
    event OwnershipTransferStarted(address indexed previousOwner, address indexed newOwner);

    // --- Modifiers ---

    modifier onlyVault() {
        if (msg.sender != vault) revert OnlyVault();
        _;
    }

    // --- Constructor (for implementation) ---

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    // --- Initializer ---

    /**
     * @notice dToken initialization function
     * @param _vault Vault address that issues this dToken
     * @param _owner Owner with upgrade permissions
     */
    function initialize(address _vault, address _owner) external initializer {
        if (_vault == address(0)) revert ZeroAddress();
        if (_owner == address(0)) revert ZeroAddress();

        // Initialize with placeholders. Values will be set later via setTokenInfo.
        __ERC20_init("DToken Placeholder", "dTOKEN");
        __ERC20Permit_init("DToken Placeholder");
        __Ownable_init();
        __UUPSUpgradeable_init();

        _transferOwnership(_owner);

        vault = _vault;
    }

    /**
     * @notice Set token name, symbol, and underlying asset
     * @dev Can only be called once by the owner.
     * @param _newName Token name (e.g., "dWBTC")
     * @param _newSymbol Token symbol (e.g., "dWBTC")
     * @param _underlying Corresponding Underlying token
     */
    function setTokenInfo(string memory _newName, string memory _newSymbol, IERC20MetadataUpgradeable _underlying)
        external
        onlyOwner
    {
        if (address(underlying) != address(0)) revert TokenInfoAlreadySet();
        if (address(_underlying) == address(0)) revert ZeroAddress();
        if (bytes(_newName).length == 0) revert EmptyTokenName();
        if (bytes(_newSymbol).length == 0) revert EmptyTokenSymbol();
        if (totalSupply() != 0) revert SupplyAlreadyExists();

        address underlyingAddress = address(_underlying);
        if (underlyingAddress.code.length == 0) revert NotContract();
        if (!allowedUnderlying[underlyingAddress]) revert UnderlyingNotAllowed();

        // Bind `underlying` before the external decimals() call below so a reentrant
        // setTokenInfo() is rejected by the TokenInfoAlreadySet check above (one-shot
        // guard). The remaining state is written only after decimals validation passes.
        underlying = _underlying;

        uint8 _underlyingDecimals = _underlying.decimals();
        if (_underlyingDecimals > DTOKEN_DECIMALS) revert InvalidUnderlyingDecimals();

        _customName = _newName;
        _customSymbol = _newSymbol;
        underlyingDecimals = _underlyingDecimals;
        _decimalMultiplier = 10 ** (DTOKEN_DECIMALS - _underlyingDecimals);

        emit TokenInfoSet(_newName, _newSymbol, address(_underlying), _underlyingDecimals);
    }

    // --- UUPS Upgrade Authorization ---

    function _authorizeUpgrade(address) internal override onlyOwner {}

    // --- Ownership Overrides ---

    /**
     * @notice Pending owner for two-step ownership transfer.
     */
    function pendingOwner() public view returns (address) {
        return _pendingOwner;
    }

    /**
     * @notice Start a two-step ownership transfer.
     * @dev Passing address(0) cancels an existing pending transfer, matching
     *      OpenZeppelin Ownable2Step behavior.
     */
    function transferOwnership(address newOwner) public override onlyOwner {
        _pendingOwner = newOwner;
        emit OwnershipTransferStarted(owner(), newOwner);
    }

    /**
     * @notice Accept a pending ownership transfer.
     */
    function acceptOwnership() public {
        require(_pendingOwner == _msgSender(), "Ownable2Step: caller is not the new owner");
        _transferOwnership(_msgSender());
    }

    /**
     * @notice Disable ownership renounce to avoid permanently bricking cap,
     *         token-info, and upgrade governance.
     */
    function renounceOwnership() public view override onlyOwner {
        revert RenounceOwnershipDisabled();
    }

    function _transferOwnership(address newOwner) internal override {
        delete _pendingOwner;
        super._transferOwnership(newOwner);
    }

    // --- ERC20 Overrides ---

    /**
     * @notice Returns the name of the token.
     */
    function name() public view override(ERC20Upgradeable, IERC20MetadataUpgradeable) returns (string memory) {
        return bytes(_customName).length > 0 ? _customName : super.name();
    }

    /**
     * @notice Returns the symbol of the token.
     */
    function symbol() public view override(ERC20Upgradeable, IERC20MetadataUpgradeable) returns (string memory) {
        return bytes(_customSymbol).length > 0 ? _customSymbol : super.symbol();
    }

    /**
     * @notice dToken decimals is always 18
     * @dev Liquity v2 assumes collateral tokens have 18 decimals
     */
    function decimals() public pure override(ERC20Upgradeable, IERC20MetadataUpgradeable) returns (uint8) {
        return DTOKEN_DECIMALS;
    }

    /**
     * @notice EIP-712 domain name for permit signatures.
     * @dev Binds the EIP-712 DOMAIN_SEPARATOR to the live token name() (set via setTokenInfo)
     *      instead of the constructor-time placeholder. Standard wallets/frontends build the
     *      permit domain from `name()`, so without this the on-chain separator (placeholder)
     *      and the off-chain signature (real name) would diverge and permit() would revert.
     *
     *      Safe on OpenZeppelin Contracts (upgradeable) v4.9: EIP712Upgradeable does NOT cache
     *      the domain separator for proxies — `_domainSeparatorV4()` rebuilds it from
     *      `_EIP712NameHash()` = keccak256(_EIP712Name()) on every call — so overriding
     *      `_EIP712Name()` here propagates to both DOMAIN_SEPARATOR() and eip712Domain()
     *      with no extra storage, gap change, or re-initialization. setTokenInfo() is one-shot
     *      and gated on totalSupply()==0, so the name is final before any holder can sign a permit.
     */
    function _EIP712Name() internal view virtual override returns (string memory) {
        return name();
    }

    // --- Vault-Only Functions ---

    /**
     * @notice Mint dToken
     * @dev Callable by Vault only. Reverts if cap is exceeded
     * @param _to Recipient address
     * @param _amount Mint amount (18 decimals)
     */
    function mint(address _to, uint256 _amount) external override onlyVault {
        // Underlying must be bound (via setTokenInfo) before any mint. Otherwise a
        // mint while unbound would push totalSupply() > 0 and permanently brick
        // setTokenInfo() (SupplyAlreadyExists), stranding the dToken at placeholder
        // metadata with reverting conversions. Enforces "no mint before bind" on-chain.
        if (address(underlying) == address(0)) revert TokenInfoNotSet();
        _requireRiskParamsFinalized();
        uint256 newTotalSupply = totalSupply() + _amount;
        if (newTotalSupply > cap) {
            revert CapExceeded(newTotalSupply, cap);
        }
        _mint(_to, _amount);
    }

    /**
     * @notice Burn dToken
     * @dev Callable by Vault only
     * @param _from Address to burn from
     * @param _amount Burn amount (18 decimals)
     */
    function burn(address _from, uint256 _amount) external override onlyVault {
        _burn(_from, _amount);
    }

    // --- Conversion Functions ---

    /**
     * @notice Convert UnderlyingAmount to dTokenAmount
     * @dev Converts Underlying decimals to 18 decimals
     * @param _underlyingAmount Amount in Underlying (underlyingDecimals)
     * @return dTokenAmount amount (18 decimals)
     */
    function convertToDToken(uint256 _underlyingAmount) external view override returns (uint256) {
        if (_decimalMultiplier == 0) revert TokenInfoNotSet();
        return _underlyingAmount * _decimalMultiplier;
    }

    /**
     * @notice Convert dTokenAmount to UnderlyingAmount
     * @dev Converts 18 decimals to Underlying decimals
     * @param _dTokenAmount dToken amount (18 decimals)
     * @return underlyingAmount amount (underlyingDecimals)
     */
    function convertToUnderlying(uint256 _dTokenAmount) external view override returns (uint256) {
        if (_decimalMultiplier == 0) revert TokenInfoNotSet();
        return _dTokenAmount / _decimalMultiplier;
    }

    // --- View Functions ---

    /**
     * @notice Override of nonces function
     */
    function nonces(address owner)
        public
        view
        override(ERC20PermitUpgradeable, IERC20PermitUpgradeable)
        returns (uint256)
    {
        return super.nonces(owner);
    }

    // --- Admin Functions ---

    /**
     * @notice Set the maximum supply cap for dToken
     * @dev Callable by Owner only (admin privilege)
     * @param _newCap New cap value (18 decimals)
     */
    function setCap(uint256 _newCap) external override onlyOwner {
        if (_newCap != 0) _requireRiskParamsFinalized();
        uint256 oldCap = cap;
        cap = _newCap;
        emit CapUpdated(oldCap, _newCap);
    }

    /// @inheritdoc IDToken
    function setRiskParamsRegistry(address _registry) external override onlyOwner {
        if (riskParamsRegistry != address(0)) revert DToken__RiskParamsRegistryAlreadySet();
        if (_registry.code.length == 0) revert NotContract();
        if (cap != 0) revert DToken__CapMustBeZero();
        if (totalSupply() != 0) revert SupplyAlreadyExists();
        if (address(IAddressesRegistry(_registry).collToken()) != address(this)) {
            revert DToken__RegistryCollateralMismatch();
        }
        riskParamsRegistry = _registry;
        emit RiskParamsRegistryBound(_registry);
    }

    function _requireRiskParamsFinalized() internal view {
        address registry = riskParamsRegistry;
        if (registry == address(0) || !IAddressesRegistry(registry).riskParamsFinalized()) {
            revert DToken__RiskParamsNotFinalized();
        }
    }

    /**
     * @notice Allow or disallow an underlying asset before `setTokenInfo`.
     * @dev Mainnet deployments should allowlist exactly the intended token
     *      contract for this dToken (for example the canonical USDC address)
     *      before binding metadata. EOA / predeploy addresses are rejected.
     */
    function setAllowedUnderlying(address _underlying, bool _allowed) external override onlyOwner {
        if (_underlying == address(0)) revert ZeroAddress();
        if (address(underlying) != address(0)) revert TokenInfoAlreadySet();
        if (_underlying.code.length == 0) revert NotContract();

        allowedUnderlying[_underlying] = _allowed;
        emit AllowedUnderlyingUpdated(_underlying, _allowed);
    }
}
"
    },
    "src/DebtInFrontHelper.sol": {
      "content": "// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.24;

import {SignedMath} from "openzeppelin/contracts/utils/math/SignedMath.sol";
import {ICollateralRegistry} from "./Interfaces/ICollateralRegistry.sol";
import {IDebtInFrontHelper} from "./Interfaces/IDebtInFrontHelper.sol";
import {IHintHelpers} from "./Interfaces/IHintHelpers.sol";
import {ISortedTroves} from "./Interfaces/ISortedTroves.sol";
import {ITroveManager} from "./Interfaces/ITroveManager.sol";
import {LatestTroveData} from "./Types/LatestTroveData.sol";

/*
 * Helper contract used by the frontend to calculate debt-in-front precisely.
 * Not part of the core Liquity system.
 */
contract DebtInFrontHelper is IDebtInFrontHelper {
    ICollateralRegistry public immutable collateralRegistry;
    IHintHelpers public immutable hintHelpers;

    constructor(ICollateralRegistry _collateralRegistry, IHintHelpers _hintHelpers) {
        collateralRegistry = _collateralRegistry;
        hintHelpers = _hintHelpers;
    }

    function _findHint(
        ITroveManager _troveManager,
        uint256 _collIndex,
        uint256 _interestRateLo,
        uint256 _hintId,
        uint256 _numTrials,
        uint256 _randomSeed
    ) internal view returns (uint256 hintId) {
        uint256 diff = _hintId != 0
            ? SignedMath.abs(int256(_troveManager.getTroveAnnualInterestRate(_hintId)) - int256(_interestRateLo))
            : type(uint256).max;

        (uint256 newHintId, uint256 newDiff,) =
            hintHelpers.getApproxHint(_collIndex, _interestRateLo, _numTrials, _randomSeed);

        return newDiff < diff ? newHintId : _hintId;
    }

    function _getDebtBetween(
        uint256 _collIndex,
        uint256 _interestRateLo, // inclusive
        uint256 _interestRateHi, // exclusive
        uint256 _excludedTroveId,
        bool _stopAfterExludedTrove,
        uint256 _hintId,
        uint256 _numTrials
    ) internal view returns (uint256 debt, uint256 blockTimestamp) {
        ITroveManager troveManager = collateralRegistry.getTroveManager(_collIndex);
        require(address(troveManager) != address(0), "Invalid collateral index");

        ISortedTroves sortedTroves = troveManager.sortedTroves();
        assert(address(sortedTroves) != address(0));

        if (_numTrials > 0) {
            uint256 randomSeed = uint256(
                keccak256(
                    abi.encode(
                        block.timestamp,
                        _collIndex,
                        _interestRateLo,
                        _interestRateHi,
                        _excludedTroveId,
                        _hintId,
                        _numTrials
                    )
                )
            );

            _hintId = _findHint(troveManager, _collIndex, _interestRateLo, _hintId, _numTrials, randomSeed);
        }

        (uint256 currId,) = sortedTroves.findInsertPosition(_interestRateLo, _hintId, _hintId);

        while (currId != 0) {
            LatestTroveData memory trove = troveManager.getLatestTroveData(currId);
            if (trove.annualInterestRate >= _interestRateHi) break;

            if (currId == _excludedTroveId) {
                if (_stopAfterExludedTrove) break;
            } else {
                debt += trove.entireDebt;
            }

            currId = sortedTroves.getPrev(currId);
        }

        blockTimestamp = block.timestamp;
    }

    function getDebtBetweenInterestRates(
        uint256 _collIndex,
        uint256 _interestRateLo, // inclusive
        uint256 _interestRateHi, // exclusive
        uint256 _excludedTroveId,
        uint256 _hintId,
        uint256 _numTrials
    ) external view returns (uint256 debt, uint256 blockTimestamp) {
        return
            _getDebtBetween(_collIndex, _interestRateLo, _interestRateHi, _excludedTroveId, false, _hintId, _numTrials);
    }

    function getDebtBetweenInterestRateAndTrove(
        uint256 _collIndex,
        uint256 _interestRateLo, // inclusive
        uint256 _interestRateHi, // exclusive
        uint256 _troveIdToStopAt, // excluded
        uint256 _hintId,
        uint256 _numTrials
    ) external view returns (uint256 debt, uint256 blockTimestamp) {
        return
            _getDebtBetween(_collIndex, _interestRateLo, _interestRateHi, _troveIdToStopAt, true, _hintId, _numTrials);
    }
}
"
    },
    "src/DefaultPool.sol": {
      "content": "// SPDX-License-Identifier: BUSL-1.1

pragma solidity 0.8.24;

import "openzeppelin-contracts/contracts/token/ERC20/utils/SafeERC20.sol";

import "./Interfaces/IDefaultPool.sol";
import "./Interfaces/IAddressesRegistry.sol";
import "./Interfaces/IActivePool.sol";

/*
 * The Default Pool holds the Coll and JPYDF debt (but not JPYDF tokens) from liquidations that have been redistributed
 * to active troves but not yet "applied", i.e. not yet recorded on a recipient active trove's struct.
 *
 * When a trove makes an operation that applies its pending Coll and JPYDF debt, its pending Coll and JPYDF debt is moved
 * from the Default Pool to the Active Pool.
 */
contract DefaultPool is IDefaultPool {
    using SafeERC20 for IERC20;

    string public constant NAME = "DefaultPool";

    IERC20 public immutable collToken;
    address public immutable troveManagerAddress;
    address public immutable activePoolAddress;
    uint256 internal collBalance; // deposited Coll tracker
    uint256 internal JpydfDebt; // debt

    event CollTokenAddressChanged(address _newCollTokenAddress);
    event ActivePoolAddressChanged(address _newActivePoolAddress);
    event TroveManagerAddressChanged(address _newTroveManagerAddress);
    event DefaultPoolJpydfDebtUpdated(uint256 _jpydfDebt);
    event DefaultPoolCollBalanceUpdated(uint256 _collBalance);

    constructor(IAddressesRegistry _addressesRegistry) {
        collToken = _addressesRegistry.collToken();
        troveManagerAddress = address(_addressesRegistry.troveManager());
        activePoolAddress = address(_addressesRegistry.activePool());

        emit CollTokenAddressChanged(address(collToken));
        emit TroveManagerAddressChanged(troveManagerAddress);
        emit ActivePoolAddressChanged(activePoolAddress);

        // Allow funds movements between Liquity contracts
        collToken.forceApprove(activePoolAddress, type(uint256).max);
    }

    // --- Getters for public variables. Required by IPool interface ---

    /*
    * Returns the collBalance state variable.
    *
    * Not necessarily equal to the contract's raw Coll balance - ether can be forcibly sent to contracts.
    */
    function getCollBalance() external view override returns (uint256) {
        return collBalance;
    }

    function getJpydfDebt() external view override returns (uint256) {
        return JpydfDebt;
    }

    // --- Pool functionality ---

    function sendCollToActivePool(uint256 _amount) external override {
        _requireCallerIsTroveManager();
        uint256 newCollBalance = collBalance - _amount;
        collBalance = newCollBalance;
        emit DefaultPoolCollBalanceUpdated(newCollBalance);

        // Send Coll to Active Pool and increase its recorded Coll balance
        IActivePool(activePoolAddress).receiveColl(_amount);
    }

    function receiveColl(uint256 _amount) external {
        _requireCallerIsActivePool();

        uint256 newCollBalance = collBalance + _amount;
        collBalance = newCollBalance;

        // Pull Coll tokens from ActivePool
        collToken.safeTransferFrom(msg.sender, address(this), _amount);

        emit DefaultPoolCollBalanceUpdated(newCollBalance);
    }

    function increaseJpydfDebt(uint256 _amount) external override {
        _requireCallerIsTroveManager();
        JpydfDebt = JpydfDebt + _amount;
        emit DefaultPoolJpydfDebtUpdated(JpydfDebt);
    }

    function decreaseJpydfDebt(uint256 _amount) external override {
        _requireCallerIsTroveManager();
        JpydfDebt = JpydfDebt - _amount;
        emit DefaultPoolJpydfDebtUpdated(JpydfDebt);
    }

    // --- 'require' functions ---

    function _requireCallerIsActivePool() internal view {
        require(msg.sender == activePoolAddress, "DefaultPool: Caller is not the ActivePool");
    }

    function _requireCallerIsTroveManager() internal view {
        require(msg.sender == troveManagerAddress, "DefaultPool: Caller is not the TroveManager");
    }
}
"
    },
    "src/Dependencies/AddRemoveManagers.sol": {
      "content": "// SPDX-License-Identifier: BUSL-1.1

pragma solidity 0.8.24;

import "../Interfaces/IAddRemoveManagers.sol";
import "../Interfaces/IAddressesRegistry.sol";
import "../Interfaces/ITroveNFT.sol";

contract AddRemoveManagers is IAddRemoveManagers {
    ITroveNFT internal immutable troveNFT;

    struct RemoveManagerReceiver {
        address manager;
        address receiver;
    }

    /*
     * Mapping from TroveId to granted address for operations that "give" money to the trove (add collateral, pay debt).
     * Useful for instance for cold/hot wallet setups.
     * If its value is zero address, any address is allowed to do those operations on behalf of trove owner.
     * Otherwise, only the address in this mapping (and the trove owner) will be allowed.
     * To restrict this permission to no one, trove owner should be set in this mapping.
     */
    mapping(uint256 => address) public addManagerOf;

    /*
     * Mapping from TroveId to granted addresses for operations that "withdraw" money from the trove (withdraw collateral, borrow),
     * and for each of those addresses another address for the receiver of those withdrawn funds.
     * Useful for instance for cold/hot wallet setups or for automations.
     * Only the address in this mapping, if any, and the trove owner, will be allowed.
     * Therefore, by default this permission is restricted to no one.
     * If the receiver is zero, the owner is assumed as the receiver.
     * RemoveManager also assumes AddManager permission
     */
    mapping(uint256 => RemoveManagerReceiver) public removeManagerReceiverOf;

    error EmptyManager();
    error NotBorrower();
    error NotOwnerNorAddManager();
    error NotOwnerNorRemoveManager();

    event TroveNFTAddressChanged(address _newTroveNFTAddress);
    event AddManagerUpdated(uint256 indexed _troveId, address _newAddManager);
    event RemoveManagerAndReceiverUpdated(uint256 indexed _troveId, address _newRemoveManager, address _newReceiver);

    constructor(IAddressesRegistry _addressesRegistry) {
        troveNFT = _addressesRegistry.troveNFT();
        emit TroveNFTAddressChanged(address(troveNFT));
    }

    function setAddManager(uint256 _troveId, address _manager) external {
        _requireCallerIsBorrower(_troveId);
        _setAddManager(_troveId, _manager);
    }

    function _setAddManager(uint256 _troveId, address _manager) internal {
        addManagerOf[_troveId] = _manager;
        emit AddManagerUpdated(_troveId, _manager);
    }

    function setRemoveManager(uint256 _troveId, address _manager) external {
        setRemoveManagerWithReceiver(_troveId, _manager, troveNFT.ownerOf(_troveId));
    }

    function setRemoveManagerWithReceiver(uint256 _troveId, address _manager, address _receiver) public {
        _requireCallerIsBorrower(_troveId);
        _setRemoveManagerAndReceiver(_troveId, _manager, _receiver);
    }

    function _setRemoveManagerAndReceiver(uint256 _troveId, address _manager, address _receiver) internal {
        _requireNonZeroManagerUnlessWiping(_manager, _receiver);
        removeManagerReceiverOf[_troveId].manager = _manager;
        removeManagerReceiverOf[_troveId].receiver = _receiver;
        emit RemoveManagerAndReceiverUpdated(_troveId, _manager, _receiver);
    }

    function _wipeAddRemoveManagers(uint256 _troveId) internal {
        delete addManagerOf[_troveId];
        delete removeManagerReceiverOf[_troveId];
        emit AddManagerUpdated(_troveId, address(0));
        emit RemoveManagerAndReceiverUpdated(_troveId, address(0), address(0));
    }

    function _requireNonZeroManagerUnlessWiping(address _manager, address _receiver) internal pure {
        if (_manager == address(0) && _receiver != address(0)) {
            revert EmptyManager();
        }
    }

    function _requireCallerIsBorrower(uint256 _troveId) internal view {
        if (msg.sender != troveNFT.ownerOf(_troveId)) {
            revert NotBorrower();
        }
    }

    function _requireSenderIsOwnerOrAddManager(uint256 _troveId, address _owner) internal view {
        address addManager = addManagerOf[_troveId];
        if (msg.sender != _owner && addManager != address(0) && msg.sender != addManager) {
            // RemoveManager assumes AddManager permission too
            address removeManager = removeManagerReceiverOf[_troveId].manager;
            if (msg.sender != removeManager) {
                revert NotOwnerNorAddManager();
            }
        }
    }

    function _requireSenderIsOwnerOrRemoveManagerAndGetReceiver(uint256 _troveId, address _owner)
        internal
        view
        returns (address)
    {
        address manager = removeManagerReceiverOf[_troveId].manager;
        address receiver = removeManagerReceiverOf[_troveId].receiver;
        if (msg.sender != _owner && msg.sender != manager) {
            revert NotOwnerNorRemoveManager();
        }
        if (receiver == address(0) || msg.sender != manager) {
            return _owner;
        }
        return receiver;
    }
}
"
    },
