    "src/Interfaces/IPriceFeedProxy.sol": {
      "content": "// SPDX-License-Identifier: MIT

pragma solidity ^0.8.0;

import "./IPriceFeed.sol";
import "./IBorrowerOperations.sol";

/**
 * @title IPriceFeedProxy
 * @notice Interface for a swappable-source price feed: a fixed reference address whose
 *         underlying price source is switchable behind a 12h timelock. This is NOT a
 *         UUPS / delegatecall / storage proxy and is not upgradeable in the storage sense.
 *         Extends IPriceFeed (original Liquity interface) with proxy-specific functions.
 * @dev Ownership (2-step) is provided by inheriting OpenZeppelin Ownable2Step in the
 *      implementation. Its functions (owner, pendingOwner, transferOwnership,
 *      acceptOwnership, renounceOwnership) and events (OwnershipTransferred,
 *      OwnershipTransferStarted) appear on the ABI via inheritance. The
 *      implementation disables renounceOwnership to preserve the source-swap
 *      recovery path.
 */
interface IPriceFeedProxy is IPriceFeed {
    // --- Events ---
    event SourceUpdated(address indexed oldSource, address indexed newSource);
    /// @dev oldPrice is live when oldSourceHealthy is true, otherwise cached.
    ///      oldRedemptionPrice is cached if the old source is unhealthy OR its JPY
    ///      provenance is invalid or at least 30 hours old, even when oldSourceHealthy
    ///      is true. The flag describes source fetches, not redemption-cache provenance.
    ///      priceGuardBypassed is true only for an explicit confirmSourceEmergency call.
    event SourceSwitchValidated(
        address indexed oldSource,
        address indexed newSource,
        bool oldSourceHealthy,
        bool priceGuardBypassed,
        uint256 oldPrice,
        uint256 newPrice,
        uint256 oldRedemptionPrice,
        uint256 newRedemptionPrice
    );
    event SourceProposed(address indexed proposedSource, uint256 executableAt);
    event SourceProposalCancelled(address indexed cancelledSource);
    /// @notice Emitted when the proxy's own fail-safe activates: the source reverted, or
    ///         returned an invalid (0/max) or failure-flagged price, so the proxy triggered
    ///         temporary oracle-failure shutdown and served a fallback price. Lets monitors
    ///         detect proxy-level oracle-failure handling, not just BorrowerOperations' event.
    event SourceFailureHandled(address indexed source);

    /// @notice Emitted when borrowerOperations.shutdownFromOracleFailure() reverted inside the
    ///         proxy's fail-safe path. That call reverts only on caller-mismatch (this proxy is
    ///         not the branch's registered priceFeed -- a deploy miswire), since it is a no-op
    ///         when already in temporary or permanent shutdown. The proxy intentionally does NOT
    ///         propagate the revert
    ///         (that would let one branch DoS the system-wide redemption loop); it serves
    ///         lastGoodPrice and raises this alarm so monitoring can detect a miswired branch.
    event ShutdownCallReverted(address indexed borrowerOperations, address indexed source);
    event OracleFailureShutdownResumed(
        address indexed source, uint256 validatedPrice, uint256 validatedRedemptionPrice
    );

    // --- Errors ---
    error InvalidSource();
    error SameSource();
    error InvalidAddress();
    error NoProposalPending();
    error TimelockNotElapsed();
    error SourcePriceDeviationTooLarge(uint256 oldPrice, uint256 newPrice, uint256 maxDeviationBps);
    error ZeroOwnerAddress();
    error RenounceOwnershipDisabled();
    error OracleFailureShutdownNotActive();
    error SourceNotHealthy();
    error UrgentRedemptionPriceUnavailable(address source);

    // --- Views ---
    function source() external view returns (address);
    function proposedSource() external view returns (address);
    function sourceProposedAt() external view returns (uint256);
    function TIMELOCK_DELAY() external view returns (uint256);
    function MAX_SOURCE_SWITCH_DEVIATION_BPS() external view returns (uint256);
    function borrowerOperations() external view returns (IBorrowerOperations);

    // --- Timelocked source switching ---
    function proposeSource(address _newSource) external;
    function confirmSource() external;
    function confirmSourceEmergency() external;
    function cancelSourceProposal() external;
    function resumeFromOracleFailure() external;
}
"
    },
    "src/Interfaces/IRedemptionHelper.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

interface IRedemptionHelper {
    struct SimulationContext {
        address troveManager;
        address sortedTroves;
        bool redeemable;
        uint256 price;
        uint256 proportion;
        uint256 attemptedJpydf;
        uint256 redeemedJpydf;
        uint256 iterations;
    }

    struct Redeemed {
        uint256 jpydf;
        uint256 coll;
    }

    function simulateRedemption(uint256 _jpydf, uint256 _maxIterationsPerCollateral)
        external
        returns (SimulationContext[] memory branch, uint256 totalProportions);

    // Find the request amount associated with the proportional quote within the
    // iteration limit. This is not a full-fill guarantee: unavailable branches
    // retain their allocation weights, so part of truncatedJpydf may remain unspent.
    // Sum redeemed[i].jpydf for the expected fill. This helps avoid overpaying fees.
    //
    // Also returns the expected fee that will be paid (as a percentage), and the
    // expected collateral amounts that will be paid out in exchange for the
    // redeemed JPYDF. The latter may be used to calculate the _minCollRedeemed
    // parameter passed to redeemCollateral().
    function truncateRedemption(uint256 _jpydf, uint256 _maxIterationsPerCollateral)
        external
        returns (uint256 truncatedJpydf, uint256 feePct, Redeemed[] memory redeemed);

    // Wrapper around CollateralRegistry's redeemCollateral() that adds slippage
    // protection in the form of a minimum acceptable collateral amounts parameter.
    function redeemCollateral(
        uint256 _jpydf,
        uint256 _maxIterationsPerCollateral,
        uint256 _maxFeePct,
        uint256[] memory _minCollRedeemed
    ) external;
}
"
    },
