    "src/JPYdfTroveNFT.sol": {
      "content": "// SPDX-License-Identifier: BUSL-1.1

pragma solidity 0.8.24;

import {ERC721} from "openzeppelin-contracts/contracts/token/ERC721/ERC721.sol";
import {IERC20Metadata} from "openzeppelin-contracts/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import {IERC721Metadata} from "openzeppelin-contracts/contracts/token/ERC721/extensions/IERC721Metadata.sol";

import {IAddressesRegistry} from "src/Interfaces/IAddressesRegistry.sol";
import {IMetadataNFT} from "src/Interfaces/IMetadataNFT.sol";
import {IJpydfToken} from "src/Interfaces/IJpydfToken.sol";
import {ITroveNFT} from "src/Interfaces/ITroveNFT.sol";
import {ITroveManager} from "src/Interfaces/ITroveManager.sol";
import {LatestTroveData} from "src/Types/LatestTroveData.sol";

contract JPYdfTroveNFT is ERC721, ITroveNFT {
    error JPYdfTroveNFT__CallerIsNotTroveManager();

    ITroveManager public immutable troveManager;
    IERC20Metadata internal immutable collToken;
    IJpydfToken internal immutable jpydfToken;

    IMetadataNFT public immutable metadataNFT;

    constructor(IAddressesRegistry _addressesRegistry)
        ERC721(
            string.concat("JPYdf - ", _addressesRegistry.collToken().name()),
            string.concat("JPYdf_", _addressesRegistry.collToken().symbol())
        )
    {
        troveManager = _addressesRegistry.troveManager();
        collToken = _addressesRegistry.collToken();
        metadataNFT = _addressesRegistry.metadataNFT();
        jpydfToken = _addressesRegistry.jpydfToken();
    }

    function tokenURI(uint256 _tokenId) public view override(ERC721, IERC721Metadata) returns (string memory) {
        LatestTroveData memory latestTroveData = troveManager.getLatestTroveData(_tokenId);

        IMetadataNFT.TroveData memory troveData = IMetadataNFT.TroveData({
            _tokenId: _tokenId,
            _owner: ownerOf(_tokenId),
            _collToken: address(collToken),
            _jpydfToken: address(jpydfToken),
            _collAmount: latestTroveData.entireColl,
            _debtAmount: latestTroveData.entireDebt,
            _interestRate: latestTroveData.annualInterestRate,
            _status: troveManager.getTroveStatus(_tokenId)
        });

        return metadataNFT.uri(troveData);
    }

    function mint(address _owner, uint256 _troveId) external override {
        _requireCallerIsTroveManager();
        _mint(_owner, _troveId);
    }

    function burn(uint256 _troveId) external override {
        _requireCallerIsTroveManager();
        _burn(_troveId);
    }

    function _requireCallerIsTroveManager() internal view {
        if (msg.sender != address(troveManager)) revert JPYdfTroveNFT__CallerIsNotTroveManager();
    }
}
"
    },
    "src/JpydfToken.sol": {
      "content": "// SPDX-License-Identifier: BUSL-1.1

pragma solidity 0.8.24;

import "openzeppelin-contracts/contracts/token/ERC20/extensions/ERC20Permit.sol";
import "./Dependencies/Ownable.sol";
import "./Interfaces/IJpydfToken.sol";

/*
 * --- Functionality added specific to the JpydfToken ---
 *
 * 1) Transfer protection: blacklist of addresses that are invalid recipients (i.e. core Liquity contracts) in external
 * transfer() and transferFrom() calls. The purpose is to protect users from losing tokens by mistakenly sending JPYDF directly to a Liquity
 * core contract, when they should rather call the right function.
 *
 * 2) sendToPool() and returnFromPool(): functions callable only Liquity core contracts, which move JPYDF tokens between Liquity <-> user.
 *
 * 3) Dormant bridge readiness: bridge-specific mint/burn entrypoints gated by an independent bridgeAdmin and
 * bridge minter registry. The existing core mint()/burn() paths remain unchanged.
 */

contract JpydfToken is Ownable, IJpydfToken, ERC20Permit {
    string internal constant _NAME = "JPYdf Stablecoin";
    string internal constant _SYMBOL = "JPYdf";
    uint256 public constant BRIDGE_MINTER_TIMELOCK = 48 hours;

    // --- Addresses ---

    address public collateralRegistryAddress;
    mapping(address => bool) troveManagerAddresses;
    mapping(address => bool) stabilityPoolAddresses;
    mapping(address => bool) borrowerOperationsAddresses;
    mapping(address => bool) activePoolAddresses;

    address public override bridgeAdmin;
    address public override pendingBridgeAdmin;
    address public override proposedBridgeMinter;
    uint256 public override bridgeMinterProposedAt;
    uint256 public override bridgeMinterCount;
    mapping(address => bool) public bridgeMinterAddresses;

    // --- Events ---
    event CollateralRegistryAddressChanged(address _newCollateralRegistryAddress);
    event TroveManagerAddressAdded(address _newTroveManagerAddress);
    event StabilityPoolAddressAdded(address _newStabilityPoolAddress);
    event BorrowerOperationsAddressAdded(address _newBorrowerOperationsAddress);
    event ActivePoolAddressAdded(address _newActivePoolAddress);

    constructor(address _initialOwner, address _bridgeAdmin, bool _testOnly)
        Ownable(_initialOwner)
        ERC20(_testOnly ? "testJPYdf Stablecoin" : _NAME, _testOnly ? "testJPYdf" : _SYMBOL)
        ERC20Permit(_testOnly ? "testJPYdf Stablecoin" : _NAME)
    {
        if (_initialOwner == address(0)) revert JpydfToken__ZeroOwner();
        if (_bridgeAdmin == address(0)) revert JpydfToken__ZeroBridgeAdmin();
        if (_bridgeAdmin == _initialOwner) revert JpydfToken__BridgeAdminCannotBeOwner();
        _requireBridgeAdminContract(_bridgeAdmin);

        bridgeAdmin = _bridgeAdmin;
        emit BridgeAdminTransferred(address(0), _bridgeAdmin);
    }

    modifier onlyBridgeAdmin() {
        _requireCallerIsBridgeAdmin();
        _;
    }

    function setBranchAddresses(
        address _troveManagerAddress,
        address _stabilityPoolAddress,
        address _borrowerOperationsAddress,
        address _activePoolAddress
    ) external override onlyOwner {
        _requireCoreContract(_troveManagerAddress);
        _requireCoreContract(_stabilityPoolAddress);
        _requireCoreContract(_borrowerOperationsAddress);
        _requireCoreContract(_activePoolAddress);

        troveManagerAddresses[_troveManagerAddress] = true;
        emit TroveManagerAddressAdded(_troveManagerAddress);

        stabilityPoolAddresses[_stabilityPoolAddress] = true;
        emit StabilityPoolAddressAdded(_stabilityPoolAddress);

        borrowerOperationsAddresses[_borrowerOperationsAddress] = true;
        emit BorrowerOperationsAddressAdded(_borrowerOperationsAddress);

        activePoolAddresses[_activePoolAddress] = true;
        emit ActivePoolAddressAdded(_activePoolAddress);
    }

    function setCollateralRegistry(address _collateralRegistryAddress) external override onlyOwner {
        _requireCoreContract(_collateralRegistryAddress);

        collateralRegistryAddress = _collateralRegistryAddress;
        emit CollateralRegistryAddressChanged(_collateralRegistryAddress);

        _renounceOwnership();
    }

    // --- Bridge readiness ---

    function proposeBridgeMinter(address _bridgeMinter) external override onlyBridgeAdmin {
        if (_bridgeMinter == address(0)) revert JpydfToken__ZeroBridgeMinter();
        if (_bridgeMinter == address(this)) revert JpydfToken__BridgeMinterCannotBeToken();
        if (_bridgeMinter == bridgeAdmin || _bridgeMinter == pendingBridgeAdmin) {
            revert JpydfToken__BridgeMinterCannotBeAdmin();
        }
        if (bridgeMinterAddresses[_bridgeMinter]) revert JpydfToken__BridgeMinterAlreadySet();
        if (proposedBridgeMinter != address(0)) revert JpydfToken__BridgeMinterAlreadyProposed();
        _requireBridgeMinterContract(_bridgeMinter);

        proposedBridgeMinter = _bridgeMinter;
        bridgeMinterProposedAt = block.timestamp;

        emit BridgeMinterProposed(_bridgeMinter, block.timestamp, block.timestamp + BRIDGE_MINTER_TIMELOCK);
    }

    function confirmBridgeMinter() external override onlyBridgeAdmin {
        address bridgeMinter = proposedBridgeMinter;
        if (bridgeMinter == address(0)) revert JpydfToken__NoBridgeMinterProposed();
        if (bridgeMinter == bridgeAdmin || bridgeMinter == pendingBridgeAdmin) {
            revert JpydfToken__BridgeMinterCannotBeAdmin();
        }
        _requireBridgeMinterContract(bridgeMinter);
        if (block.timestamp < bridgeMinterProposedAt + BRIDGE_MINTER_TIMELOCK) {
            revert JpydfToken__BridgeMinterTimelockNotElapsed();
        }

        bridgeMinterAddresses[bridgeMinter] = true;
        bridgeMinterCount++;
        delete proposedBridgeMinter;
        delete bridgeMinterProposedAt;

        emit BridgeMinterConfirmed(bridgeMinter);
    }

    function cancelBridgeMinterProposal() external override onlyBridgeAdmin {
        address bridgeMinter = proposedBridgeMinter;
        if (bridgeMinter == address(0)) revert JpydfToken__NoBridgeMinterProposed();

        delete proposedBridgeMinter;
        delete bridgeMinterProposedAt;

        emit BridgeMinterProposalCancelled(bridgeMinter);
    }

    function removeBridgeMinter(address _bridgeMinter) external override onlyBridgeAdmin {
        if (!bridgeMinterAddresses[_bridgeMinter]) revert JpydfToken__NotBridgeMinter();

        bridgeMinterAddresses[_bridgeMinter] = false;
        bridgeMinterCount--;

        emit BridgeMinterRemoved(_bridgeMinter);
    }

    function transferBridgeAdmin(address _newBridgeAdmin) external override onlyBridgeAdmin {
        if (_newBridgeAdmin == address(0)) revert JpydfToken__ZeroBridgeAdmin();
        if (_newBridgeAdmin == address(this)) revert JpydfToken__BridgeAdminCannotBeToken();
        if (_newBridgeAdmin == owner()) revert JpydfToken__BridgeAdminCannotBeOwner();
        if (bridgeMinterAddresses[_newBridgeAdmin] || _newBridgeAdmin == proposedBridgeMinter) {
            revert JpydfToken__BridgeAdminCannotBeMinter();
        }
        _requireBridgeAdminContract(_newBridgeAdmin);

        pendingBridgeAdmin = _newBridgeAdmin;

        emit BridgeAdminTransferStarted(bridgeAdmin, _newBridgeAdmin);
    }

    function acceptBridgeAdmin() external override {
        if (msg.sender != pendingBridgeAdmin) revert JpydfToken__CallerIsNotPendingBridgeAdmin();
        if (bridgeMinterAddresses[msg.sender] || msg.sender == proposedBridgeMinter) {
            revert JpydfToken__BridgeAdminCannotBeMinter();
        }
        _requireBridgeAdminContract(msg.sender);

        address previousBridgeAdmin = bridgeAdmin;
        bridgeAdmin = msg.sender;
        delete pendingBridgeAdmin;

        emit BridgeAdminTransferred(previousBridgeAdmin, msg.sender);
    }

    function renounceBridgeAdmin() external override onlyBridgeAdmin {
        if (bridgeMinterCount != 0) revert JpydfToken__BridgeMintersStillSet();
        if (proposedBridgeMinter != address(0)) revert JpydfToken__CannotRenounceWithPendingBridgeMinter();

        address previousBridgeAdmin = bridgeAdmin;
        delete bridgeAdmin;
        delete pendingBridgeAdmin;

        emit BridgeAdminTransferred(previousBridgeAdmin, address(0));
    }

    function isBridgeMinter(address _account) external view override returns (bool) {
        return bridgeMinterAddresses[_account];
    }

    // --- Functions for intra-Liquity calls ---

    function mint(address _account, uint256 _amount) external override {
        _requireCallerIsBOorAP();
        _mint(_account, _amount);
    }

    function burn(address _account, uint256 _amount) external override {
        _requireCallerIsCRorBOorTMorSP();
        _burn(_account, _amount);
    }

    function bridgeMint(address _account, uint256 _amount) external override {
        _requireCallerIsBridgeMinter();
        _requireValidRecipient(_account);
        _mint(_account, _amount);
        emit BridgeMint(msg.sender, _account, _amount);
    }

    function bridgeBurn(uint256 _amount) external override {
        _requireCallerIsBridgeMinter();
        _burn(msg.sender, _amount);
        emit BridgeBurn(msg.sender, _amount);
    }

    function isValidRecipient(address _recipient) external view override returns (bool) {
        return _isValidRecipient(_recipient);
    }

    function requireValidRecipient(address _recipient) external view override {
        _requireValidRecipient(_recipient);
    }

    function sendToPool(address _sender, address _poolAddress, uint256 _amount) external override {
        _requireCallerIsStabilityPool();
        _transfer(_sender, _poolAddress, _amount);
    }

    function returnFromPool(address _poolAddress, address _receiver, uint256 _amount) external override {
        _requireCallerIsStabilityPool();
        _transfer(_poolAddress, _receiver, _amount);
    }

    // --- External functions ---

    function transfer(address recipient, uint256 amount) public override(ERC20, IERC20) returns (bool) {
        _requireValidRecipient(recipient);
        return super.transfer(recipient, amount);
    }

    function transferFrom(address sender, address recipient, uint256 amount)
        public
        override(ERC20, IERC20)
        returns (bool)
    {
        _requireValidRecipient(recipient);
        return super.transferFrom(sender, recipient, amount);
    }

    // --- 'require' functions ---

    function _requireValidRecipient(address _recipient) internal view {
        if (!_isValidRecipient(_recipient)) revert JpydfToken__CannotTransferToProtocolContract();
    }

    function _isValidRecipient(address _recipient) internal view returns (bool) {
        return _recipient != address(0) && _recipient != address(this) && _recipient != collateralRegistryAddress
            && !troveManagerAddresses[_recipient] && !stabilityPoolAddresses[_recipient]
            && !borrowerOperationsAddresses[_recipient] && !activePoolAddresses[_recipient];
    }

    function _requireCallerIsBOorAP() internal view {
        if (!(borrowerOperationsAddresses[msg.sender] || activePoolAddresses[msg.sender])) {
            revert JpydfToken__CallerIsNotBorrowerOperationsOrActivePool();
        }
    }

    function _requireCallerIsCRorBOorTMorSP() internal view {
        if (
            msg.sender != collateralRegistryAddress && !borrowerOperationsAddresses[msg.sender]
                && !troveManagerAddresses[msg.sender] && !stabilityPoolAddresses[msg.sender]
        ) revert JpydfToken__CallerIsNotCoreBurner();
    }

    function _requireCallerIsStabilityPool() internal view {
        if (!stabilityPoolAddresses[msg.sender]) revert JpydfToken__CallerIsNotStabilityPool();
    }

    function _requireCallerIsBridgeAdmin() internal view {
        if (msg.sender != bridgeAdmin) revert JpydfToken__CallerIsNotBridgeAdmin();
    }

    function _requireCallerIsBridgeMinter() internal view {
        if (!bridgeMinterAddresses[msg.sender]) revert JpydfToken__CallerIsNotBridgeMinter();
    }

    function _requireCoreContract(address _account) internal view {
        if (_account == address(0)) revert JpydfToken__ZeroCoreAddress();
        if (_account.code.length == 0) revert JpydfToken__CoreAddressMustBeContract();
    }

    function _requireBridgeAdminContract(address _account) internal view {
        if (_account.code.length == 0) revert JpydfToken__BridgeAdminMustBeContract();
    }

    function _requireBridgeMinterContract(address _account) internal view {
        if (_account.code.length == 0) revert JpydfToken__BridgeMinterMustBeContract();
    }
}
"
    },
    "src/LiquidationCandidateGetter.sol": {
      "content": "// SPDX-License-Identifier: BUSL-1.1

pragma solidity 0.8.24;

import "./Interfaces/ICollateralRegistry.sol";
import "./Interfaces/ILiquidationCandidateGetter.sol";
import "./Interfaces/ISortedTroves.sol";
import "./Interfaces/ITroveManager.sol";
import "./Types/LatestTroveData.sol";

/**
 * @title LiquidationCandidateGetter
 * @notice Read-only helper for liquidation bots and monitoring.
 * @dev This contract deliberately stays outside the core Liquity state machine:
 *      it only walks branch-local `SortedTroves`, recomputes ICR using the
 *      caller-supplied protocol price/MCR, and returns enough debt/collateral
 *      data for off-chain batching. Zombie Troves are not in `SortedTroves`, so
 *      callers that need full coverage must use the `WithLastZombie` path.
 */
contract LiquidationCandidateGetter is ILiquidationCandidateGetter {
    ICollateralRegistry public immutable collateralRegistry;

    constructor(ICollateralRegistry _collateralRegistry) {
        if (address(_collateralRegistry) == address(0)) revert LiquidationCandidateGetter__InvalidCollateralRegistry();
        collateralRegistry = _collateralRegistry;
    }

    function getLiquidationCandidates(
        uint256 _collIndex,
        uint256 _startId,
        uint256 _maxIterations,
        uint256 _price,
        uint256 _mcr
    ) external view returns (LiquidationCandidate[] memory candidates, uint256 currId) {
        (candidates, currId,) = _getLiquidationCandidates(_collIndex, _startId, _maxIterations, _price, _mcr, false);
    }

    function getLiquidationCandidatesWithLastZombie(
        uint256 _collIndex,
        uint256 _startId,
        uint256 _maxIterations,
        uint256 _price,
        uint256 _mcr,
        bool _includeLastZombie
    ) external view returns (LiquidationCandidate[] memory candidates, uint256 currId, bool includedLastZombie) {
        return _getLiquidationCandidates(_collIndex, _startId, _maxIterations, _price, _mcr, _includeLastZombie);
    }

    function getLastZombieLiquidationCandidate(uint256 _collIndex, uint256 _price, uint256 _mcr)
        external
        view
        returns (bool found, LiquidationCandidate memory candidate)
    {
        return _getLastZombieLiquidationCandidate(_requireTroveManager(_collIndex), _price, _mcr);
    }

    function _getLiquidationCandidates(
        uint256 _collIndex,
        uint256 _startId,
        uint256 _maxIterations,
        uint256 _price,
        uint256 _mcr,
        bool _includeLastZombie
    ) internal view returns (LiquidationCandidate[] memory candidates, uint256 currId, bool includedLastZombie) {
        ITroveManager troveManager = _requireTroveManager(_collIndex);

        ISortedTroves sortedTroves = troveManager.sortedTroves();
        assert(address(sortedTroves) != address(0));

        LiquidationCandidate[] memory candidateBuffer =
            new LiquidationCandidate[](_maxIterations + (_includeLastZombie ? 1 : 0));
        // `currId` is returned as a cursor for the next scan. The current Trove
        // is advanced before any expensive reads so off-chain callers can safely
        // resume even when a candidate is skipped after rechecking ICR.
        currId = _startId == 0 ? sortedTroves.getFirst() : _startId;
        uint256 candidateCount;

        for (uint256 scannedCount; scannedCount < _maxIterations && currId != 0; ++scannedCount) {
            uint256 troveId = currId;
            currId = sortedTroves.getNext(troveId);

            uint256 icr = troveManager.getCurrentICR(troveId, _price);
            if (icr >= _mcr) continue;

            LatestTroveData memory trove = troveManager.getLatestTroveData(troveId);
            candidateBuffer[candidateCount++] = LiquidationCandidate({
                id: troveId,
                ICR: icr,
                entireDebt: trove.entireDebt,
                entireColl: trove.entireColl
            });
        }

        if (_includeLastZombie) {
            // Redemptions can leave one zombie outside `SortedTroves`. Append it
            // explicitly so keepers do not miss a liquidatable zombie when a
            // branch is otherwise idle.
            LiquidationCandidate memory lastZombie;
            (includedLastZombie, lastZombie) = _getLastZombieLiquidationCandidate(troveManager, _price, _mcr);
            if (includedLastZombie) {
                candidateBuffer[candidateCount++] = lastZombie;
            }
        }

        candidates = new LiquidationCandidate[](candidateCount);
        for (uint256 candidateIndex; candidateIndex < candidateCount; ++candidateIndex) {
            candidates[candidateIndex] = candidateBuffer[candidateIndex];
        }
    }

    function _getLastZombieLiquidationCandidate(ITroveManager _troveManager, uint256 _price, uint256 _mcr)
        internal
        view
        returns (bool found, LiquidationCandidate memory candidate)
    {
        uint256 troveId = _troveManager.lastZombieTroveId();
        if (troveId == 0) return (false, candidate);
        if (_troveManager.getTroveStatus(troveId) != ITroveManager.Status.zombie) return (false, candidate);

        uint256 icr = _troveManager.getCurrentICR(troveId, _price);
        if (icr >= _mcr) return (false, candidate);

        LatestTroveData memory trove = _troveManager.getLatestTroveData(troveId);
        return (
            true,
            LiquidationCandidate({id: troveId, ICR: icr, entireDebt: trove.entireDebt, entireColl: trove.entireColl})
        );
    }

    function _requireTroveManager(uint256 _collIndex) internal view returns (ITroveManager troveManager) {
        troveManager = collateralRegistry.getTroveManager(_collIndex);
        if (address(troveManager) == address(0)) revert LiquidationCandidateGetter__InvalidCollateralIndex();
    }
}
"
    },
    "src/MultiTroveGetter.sol": {
      "content": "// SPDX-License-Identifier: BUSL-1.1

pragma solidity 0.8.24;

import "./Interfaces/ICollateralRegistry.sol";
import "./Interfaces/IMultiTroveGetter.sol";
import "./Types/BatchId.sol";

/*  Helper contract for grabbing Trove data for the front end. Not part of the core Liquity system. */
contract MultiTroveGetter is IMultiTroveGetter {
    ICollateralRegistry public immutable collateralRegistry;

    constructor(ICollateralRegistry _collateralRegistry) {
        collateralRegistry = _collateralRegistry;
    }

    function getMultipleSortedTroves(uint256 _collIndex, int256 _startIdx, uint256 _count)
        external
        view
        returns (CombinedTroveData[] memory _troves)
    {
        ITroveManager troveManager = collateralRegistry.getTroveManager(_collIndex);
        require(address(troveManager) != address(0), "Invalid collateral index");

        ISortedTroves sortedTroves = troveManager.sortedTroves();
        assert(address(sortedTroves) != address(0));

        uint256 startIdx;
        bool descend;

        if (_startIdx >= 0) {
            startIdx = uint256(_startIdx);
            descend = true;
        } else {
            startIdx = uint256(-(_startIdx + 1));
            descend = false;
        }

        uint256 sortedTrovesSize = sortedTroves.getSize();

        if (startIdx >= sortedTrovesSize) {
            _troves = new CombinedTroveData[](0);
        } else {
            uint256 maxCount = sortedTrovesSize - startIdx;

            if (_count > maxCount) {
                _count = maxCount;
            }

            if (descend) {
                _troves = _getMultipleSortedTrovesFromHead(troveManager, sortedTroves, startIdx, _count);
            } else {
                _troves = _getMultipleSortedTrovesFromTail(troveManager, sortedTroves, startIdx, _count);
            }
        }
    }

    function _getOneTrove(ITroveManager _troveManager, uint256 _id, CombinedTroveData memory _out) internal view {
        _out.id = _id;

        LatestTroveData memory troveData = _troveManager.getLatestTroveData(_id);
        _out.entireDebt = troveData.entireDebt;
        _out.entireColl = troveData.entireColl;
        _out.redistJpydfDebtGain = troveData.redistJpydfDebtGain;
        _out.redistCollGain = troveData.redistCollGain;
        _out.accruedInterest = troveData.accruedInterest;
        _out.recordedDebt = troveData.recordedDebt;
        _out.annualInterestRate = troveData.annualInterestRate;
        _out.accruedBatchManagementFee = troveData.accruedBatchManagementFee;
        _out.lastInterestRateAdjTime = troveData.lastInterestRateAdjTime;

        (
            , // debt
            , // coll
            _out.stake,
            , // status
            , // arrayIndex
            _out.lastDebtUpdateTime,
            , // lastInterestRateAdjTime
            , // annualInterestRate
            _out.interestBatchManager,
            _out.batchDebtShares
        ) = _troveManager.Troves(_id);

        (_out.snapshotETH, _out.snapshotJpydfDebt) = _troveManager.rewardSnapshots(_id);
    }

    function _getMultipleSortedTrovesFromHead(
        ITroveManager _troveManager,
        ISortedTroves _sortedTroves,
        uint256 _startIdx,
        uint256 _count
    ) internal view returns (CombinedTroveData[] memory _troves) {
        uint256 currentTroveId = _sortedTroves.getFirst();

        for (uint256 idx = 0; idx < _startIdx; ++idx) {
            currentTroveId = _sortedTroves.getNext(currentTroveId);
        }

        _troves = new CombinedTroveData[](_count);

        for (uint256 idx = 0; idx < _count; ++idx) {
            _getOneTrove(_troveManager, currentTroveId, _troves[idx]);
            currentTroveId = _sortedTroves.getNext(currentTroveId);
        }
    }

    function _getMultipleSortedTrovesFromTail(
        ITroveManager _troveManager,
        ISortedTroves _sortedTroves,
        uint256 _startIdx,
        uint256 _count
    ) internal view returns (CombinedTroveData[] memory _troves) {
        uint256 currentTroveId = _sortedTroves.getLast();

        for (uint256 idx = 0; idx < _startIdx; ++idx) {
            currentTroveId = _sortedTroves.getPrev(currentTroveId);
        }

        _troves = new CombinedTroveData[](_count);

        for (uint256 idx = 0; idx < _count; ++idx) {
            _getOneTrove(_troveManager, currentTroveId, _troves[idx]);
            currentTroveId = _sortedTroves.getPrev(currentTroveId);
        }
    }

    function getDebtPerInterestRateAscending(uint256 _collIndex, uint256 _startId, uint256 _maxIterations)
        external
        view
        returns (DebtPerInterestRate[] memory data, uint256 currId)
    {
        ITroveManager troveManager = collateralRegistry.getTroveManager(_collIndex);
        require(address(troveManager) != address(0), "Invalid collateral index");

        ISortedTroves sortedTroves = troveManager.sortedTroves();
        assert(address(sortedTroves) != address(0));

        data = new DebtPerInterestRate[](_maxIterations);
        currId = _startId == 0 ? sortedTroves.getLast() : _startId;

        for (uint256 i = 0; i < _maxIterations; ++i) {
            if (currId == 0) break;

            (, uint256 prevId, BatchId interestBatchManager,) = sortedTroves.nodes(currId);
            LatestTroveData memory trove = troveManager.getLatestTroveData(currId);
            data[i].interestBatchManager = BatchId.unwrap(interestBatchManager);
            data[i].interestRate = trove.annualInterestRate;
            data[i].debt = trove.entireDebt;

            currId = prevId;
        }
    }
}
"
    },
    "src/NFTMetadata/JPYdfMetadataNFT.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {IERC20Metadata} from "openzeppelin-contracts/contracts/token/ERC20/extensions/IERC20Metadata.sol";

import {IMetadataNFT} from "src/Interfaces/IMetadataNFT.sol";
import {ITroveManager} from "src/Interfaces/ITroveManager.sol";
import {FixedAssetReader} from "src/NFTMetadata/utils/FixedAssets.sol";
import {JPYdfBaseSVG} from "src/NFTMetadata/utils/JPYdfBaseSVG.sol";
import {json} from "src/NFTMetadata/utils/JSON.sol";
import {svg} from "src/NFTMetadata/utils/SVG.sol";
import {LibString} from "src/NFTMetadata/utils/Utils.sol";
import {bauhaus} from "src/NFTMetadata/utils/bauhaus.sol";

contract JPYdfMetadataNFT is IMetadataNFT {
    FixedAssetReader public immutable assetReader;

    constructor(FixedAssetReader _assetReader) {
        assetReader = _assetReader;
    }

    function uri(TroveData memory _troveData) public view returns (string memory) {
        string memory attr = attributes(_troveData);
        return json.formattedMetadata(
            string.concat("JPYdf - ", IERC20Metadata(_troveData._collToken).name()),
            string.concat(
                "JPYdf is a collateralized debt protocol. Users can lock up ",
                IERC20Metadata(_troveData._collToken).symbol(),
                " to mint JPYdf. The individual collateralized debt positions are called Troves and are represented as NFTs."
            ),
            renderSVGImage(_troveData),
            attr
        );
    }

    function renderSVGImage(TroveData memory _troveData) internal view returns (string memory) {
        return svg._svg(
            JPYdfBaseSVG._svgProps(),
            string.concat(
                JPYdfBaseSVG._baseElements(assetReader),
                bauhaus._bauhaus(IERC20Metadata(_troveData._collToken).symbol(), _troveData._tokenId),
                dynamicTextComponents(_troveData)
            )
        );
    }

    function attributes(TroveData memory _troveData) public pure returns (string memory) {
        return string.concat(
            '[{"trait_type": "Collateral Token", "value": "',
            LibString.toHexString(_troveData._collToken),
            '"}, {"trait_type": "Collateral Amount", "value": "',
            LibString.toString(_troveData._collAmount),
            '"}, {"trait_type": "Debt Token", "value": "',
            LibString.toHexString(_troveData._jpydfToken),
            '"}, {"trait_type": "Debt Amount", "value": "',
            LibString.toString(_troveData._debtAmount),
            '"}, {"trait_type": "Interest Rate", "value": "',
            LibString.toString(_troveData._interestRate),
            '"}, {"trait_type": "Status", "value": "',
            _status2Str(_troveData._status),
            '"} ]'
        );
    }

    function dynamicTextComponents(TroveData memory _troveData) public view returns (string memory) {
        string memory id = LibString.toHexString(_troveData._tokenId);
        id = string.concat(LibString.slice(id, 0, 6), "...", LibString.slice(id, 38, 42));

        return string.concat(
            JPYdfBaseSVG._formattedIdEl(id),
            JPYdfBaseSVG._formattedAddressEl(_troveData._owner),
            JPYdfBaseSVG._collLogo(IERC20Metadata(_troveData._collToken).symbol(), assetReader),
            JPYdfBaseSVG._statusEl(_status2Str(_troveData._status)),
            JPYdfBaseSVG._dynamicTextEls(_troveData._debtAmount, _troveData._collAmount, _troveData._interestRate)
        );
    }

    function _status2Str(ITroveManager.Status status) internal pure returns (string memory) {
        if (status == ITroveManager.Status.active) return "Active";
        if (status == ITroveManager.Status.closedByOwner) return "Closed";
        if (status == ITroveManager.Status.closedByLiquidation) return "Liquidated";
        if (status == ITroveManager.Status.zombie) return "Below Min Debt";
        return "";
    }
}
"
    },
    "src/NFTMetadata/utils/FixedAssets.sol": {
      "content": "//SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import "Solady/utils/SSTORE2.sol";

contract FixedAssetReader {
    struct Asset {
        uint128 start;
        uint128 end;
    }

    address public immutable pointer;

    mapping(bytes4 => Asset) public assets;

    function readAsset(bytes4 _sig) public view returns (string memory) {
        return string(SSTORE2.read(pointer, uint256(assets[_sig].start), uint256(assets[_sig].end)));
    }

    constructor(address _pointer, bytes4[] memory _sigs, Asset[] memory _assets) {
        require(_pointer != address(0), "FixedAssetReader: Invalid pointer");
        pointer = _pointer;
        require(_sigs.length == _assets.length, "FixedAssetReader: Invalid input");
        for (uint256 i = 0; i < _sigs.length; i++) {
            assets[_sigs[i]] = _assets[i];
        }
    }
}
"
    },
    "src/NFTMetadata/utils/JPYdfBaseSVG.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {FixedAssetReader} from "src/NFTMetadata/utils/FixedAssets.sol";
import {svg} from "src/NFTMetadata/utils/SVG.sol";
