    "src/PriceFeeds/DFWstETHPriceFeed.sol": {
      "content": "// SPDX-License-Identifier: MIT

pragma solidity 0.8.24;

import "openzeppelin-contracts/contracts/utils/math/Math.sol";

import "../Interfaces/IJpyUsdRateProvider.sol";
import "./CompositePriceFeed.sol";
import "./JpyFreezeLib.sol";

// Minimal wstETH view used as the rate provider. stEthPerToken() returns the
// stETH amount (18-dec) backing 1 wstETH -- the canonical rate.
interface IWstETHRate {
    function stEthPerToken() external view returns (uint256);
    function decimals() external view returns (uint8);
}

/**
 * @title DFWstETHPriceFeed
 * @notice Composite-rate JPY price feed for wstETH (wrapped staked ETH) collateral.
 * @dev Inherits the pruned `CompositePriceFeed` canonical-rate base (the same base
 *      as the composite-feed family) and computes:
 *          wstETH/USD = (stETH/USD, Chainlink) × (stETH per wstETH, canonical rate)
 *          wstETH/JPY = wstETH/USD / (JPY/USD)
 *          dToken/JPY = wstETH/JPY × min(1, Vault backing)
 *      The canonical rate is read from the wstETH token itself
 *      (stEthPerToken()), not Chainlink — so it has no staleness. A canonical-rate
 *      read failure (revert or zero) at fetch time is treated as an oracle failure,
 *      the same policy as sUSDS's convertToAssets failure. Because the math treats
 *      the rate as an 18-decimal value, deployment rejects a rate provider unless
 *      the wstETH token reports 18 decimals and a nonzero rate.
 *
 *      The JPY rate and freeze state come from the same shared provider as every
 *      standard DF feed. This avoids branch-local rate and timer divergence. The
 *      JPY-conversion / freeze / backing logic is the shared `JpyFreezeLib`; only
 *      its state lives here, because this feed inherits CompositePriceFeed rather
 *      than DFPriceFeedBase.
 *      `CompositePriceFeed` is intentionally limited to the primary ->
 *      lastGoodPrice path; the unused upstream LST ETHUSDxCanonical fallback was
 *      removed with the upstream WSTETH/RETH feeds. The `MainnetPriceFeedBase`
 *      diff is limited to Chainlink response-validation hardening, and the extra
 *      JPY/backing logic lives only in DF files.
 *
 *      Redemptions additionally derive a market-sensitive stETH/USD reference as
 *      ETH/USD x stETH/ETH, then use max(direct stETH/USD, derived stETH/USD).
 *      This closes the direct-feed update lag without pricing a genuine stETH depeg
 *      at par with ETH. Normal redemption fails closed if either reference feed is
 *      unavailable. Urgent redemption after irreversible shutdown also fails closed:
 *      wind-down never settles against a direct-only or cached quote.
 *
 *      Mainnet: stETH/USD `0xCfE54B5cD566aB89272946F602D76Ea879CAb4a8`,
 *      wstETH (rate provider) `0x7f39C581F595B53c5cb19bD0b3f8dA6c935E2Ca0`.
 */
contract DFWstETHPriceFeed is CompositePriceFeed {
    using JpyFreezeLib for JpyFreezeLib.JpyConversionState;

    error InvalidCollateralVault();
    error InvalidInitialPrice();
    error InvalidRateProvider();
    error InvalidRateProviderDecimals();
    error InvalidRateProviderRate();
    error InvalidJpyUsdRateProvider();

    event RedemptionReferenceUnavailable(address indexed oracle, uint256 stEthUsdPrice);
    event UrgentRedemptionReferenceUnavailable(address indexed oracle, uint256 stEthUsdPrice);

    enum PriceUse {
        Normal,
        Redemption,
        UrgentRedemption
    }

    IJpyUsdRateProvider public immutable jpyUsdRateProvider;

    Oracle public redemptionEthUsdOracle;
    Oracle public redemptionStEthEthOracle;

    address public immutable collateralVault;
    // Backing-ratio state operated on by JpyFreezeLib (see its field docs).
    JpyFreezeLib.JpyConversionState internal jpyConversionState;

    constructor(
        address _stEthUsdOracleAddress,
        address _redemptionEthUsdOracleAddress,
        address _redemptionStEthEthOracleAddress,
        address _wstEthAddress,
        uint256 _stEthUsdStalenessThreshold,
        uint256 _redemptionEthUsdStalenessThreshold,
        uint256 _redemptionStEthEthStalenessThreshold,
        address _jpyUsdRateProviderAddress,
        address _collateralVaultAddress,
        address _borrowerOperationsAddress
    )
        CompositePriceFeed(
            _stEthUsdOracleAddress, _wstEthAddress, _stEthUsdStalenessThreshold, _borrowerOperationsAddress
        )
    {
        redemptionEthUsdOracle.aggregator = AggregatorV3Interface(_redemptionEthUsdOracleAddress);
        redemptionEthUsdOracle.stalenessThreshold = _redemptionEthUsdStalenessThreshold;
        redemptionEthUsdOracle.decimals = redemptionEthUsdOracle.aggregator.decimals();
        assert(redemptionEthUsdOracle.decimals == 8);

        redemptionStEthEthOracle.aggregator = AggregatorV3Interface(_redemptionStEthEthOracleAddress);
        redemptionStEthEthOracle.stalenessThreshold = _redemptionStEthEthStalenessThreshold;
        redemptionStEthEthOracle.decimals = redemptionStEthEthOracle.aggregator.decimals();
        assert(redemptionStEthEthOracle.decimals == 18);

        _validateRateProvider(_wstEthAddress);

        if (_collateralVaultAddress.code.length == 0) revert InvalidCollateralVault();
        collateralVault = _collateralVaultAddress;
        jpyConversionState.initialize();

        if (_jpyUsdRateProviderAddress.code.length == 0) revert InvalidJpyUsdRateProvider();
        jpyUsdRateProvider = IJpyUsdRateProvider(_jpyUsdRateProviderAddress);

        // Fetch an initial price and confirm the oracle setup is live at deploy time.
        _fetchPricePrimary(false);
        if (priceSource != PriceSource.primary || lastGoodPrice == 0) revert InvalidInitialPrice();

        (, bool redemptionEthUsdOracleDown) = _getOracleAnswer(redemptionEthUsdOracle);
        if (redemptionEthUsdOracleDown) revert InvalidInitialPrice();
        (, bool redemptionStEthEthOracleDown) = _getOracleAnswer(redemptionStEthEthOracle);
        if (redemptionStEthEthOracleDown) revert InvalidInitialPrice();
    }

    function _validateRateProvider(address _wstEthAddress) private view {
        if (_wstEthAddress.code.length == 0) revert InvalidRateProvider();
        if (IWstETHRate(_wstEthAddress).decimals() != 18) revert InvalidRateProviderDecimals();
        if (IWstETHRate(_wstEthAddress).stEthPerToken() == 0) revert InvalidRateProviderRate();
    }

    /**
     * @dev Primary path. `ethUsdOracle` is the upstream slot reused as stETH/USD.
     *      Normal pricing uses stETH/USD. Redemption uses the higher of direct
     *      stETH/USD and ETH/USD x stETH/ETH. An unavailable reference
     *      fails the redemption quote closed so the normal stETH/USD quote can never
     *      silently reopen the oracle-lag arbitrage.
     */
    function _fetchPricePrimary(bool _isRedemption) internal override returns (uint256, bool) {
        return _fetchPricePrimaryFor(_isRedemption ? PriceUse.Redemption : PriceUse.Normal);
    }

    function fetchUrgentRedemptionPrice() public override returns (uint256, bool) {
        if (priceSource == PriceSource.primary) return _fetchPricePrimaryFor(PriceUse.UrgentRedemption);

        assert(priceSource == PriceSource.lastGoodPrice);
        return (lastGoodPrice, true);
    }

    function _fetchPricePrimaryFor(PriceUse _priceUse) internal returns (uint256, bool) {
        assert(priceSource == PriceSource.primary);

        // stETH/USD (18-dec normalized).
        (uint256 stEthUsdPrice, bool stEthUsdOracleDown) = _getOracleAnswer(ethUsdOracle);
        if (stEthUsdOracleDown) {
            return (_shutDownAndReturnLastGoodPrice(address(ethUsdOracle.aggregator)), true);
        }

        // stETH per wstETH (canonical rate, 18-dec).
        (uint256 stEthPerWstEth, bool rateIsDown) = _getCanonicalRate();
        if (rateIsDown) {
            return (_shutDownAndReturnLastGoodPrice(rateProviderAddress), true);
        }

        uint256 usdPrice = stEthUsdPrice;
        if (_priceUse != PriceUse.Normal) {
            (uint256 redemptionReference, bool referenceDown, address failedOracle) = _getRedemptionReference();
            if (referenceDown && _priceUse == PriceUse.Redemption) {
                emit RedemptionReferenceUnavailable(failedOracle, stEthUsdPrice);
                // The production caller is PriceFeedProxy, so a direct source -> BO pause call
                // fails BO's caller check. Absorb that expected topology mismatch so this
                // dedicated alert survives and return failure=true for the registered Proxy to
                // latch the pause. A directly registered test/source still signals BO here.
                try borrowerOperations.shutdownFromOracleFailure() {} catch {}
                return (lastGoodPrice, true);
            } else if (referenceDown) {
                emit UrgentRedemptionReferenceUnavailable(failedOracle, stEthUsdPrice);
                return (lastGoodPrice, true);
            } else if (redemptionReference > usdPrice) {
                usdPrice = redemptionReference;
            }
        }

        // wstETH/USD = selected USD price × (stETH per wstETH); both 18-dec.
        uint256 wstEthUsdPrice = Math.mulDiv(usdPrice, stEthPerWstEth, 1e18);

        // SHARED JPY/USD leg: a JPY-leg failure must not synchronously stop every branch.
        // Substitute the last good JPY rate and keep operating; the stETH/USD
        // and canonical legs above are still live, so the price tracks them and only the
        // (low-vol) FX leg is frozen. Auto-resumes when JPY/USD is fresh again; a prolonged
        // freeze escalates to recoverable oracle shutdown so the feed never serves arbitrarily
        // stale FX (ORCL-SEC-005).
        (uint256 wstEthJpyPrice, bool jpyFreezeExpired) =
            JpyFreezeLib.convertUsdPriceToJpyWithFreeze(jpyUsdRateProvider, wstEthUsdPrice);
        if (jpyFreezeExpired) {
            return (_shutDownFromSharedJpyFailure(), true);
        }

        (uint256 dTokenJpyPrice, bool backingUnavailable) =
            jpyConversionState.applyBackingRatio(collateralVault, wstEthJpyPrice);
        if (backingUnavailable) {
            return (_shutDownAndReturnLastGoodPrice(collateralVault), true);
        }

        // `lastGoodPrice` belongs to the normal borrow/liquidation path. The
        // enclosing PriceFeedProxy maintains a distinct redemption cache, so a
        // borrower-protective redemption quote must never contaminate this source
        // cache and later overvalue collateral during a normal-source failure.
        if (_priceUse == PriceUse.Normal) lastGoodPrice = dTokenJpyPrice;
        return (dTokenJpyPrice, false);
    }

    function _getRedemptionReference() internal view returns (uint256, bool, address) {
        (uint256 ethUsdPrice, bool ethUsdOracleDown) = _getOracleAnswer(redemptionEthUsdOracle);
        if (ethUsdOracleDown) return (0, true, address(redemptionEthUsdOracle.aggregator));

        (uint256 stEthEthPrice, bool stEthEthOracleDown) = _getOracleAnswer(redemptionStEthEthOracle);
        if (stEthEthOracleDown) return (0, true, address(redemptionStEthEthOracle.aggregator));

        return (Math.mulDiv(ethUsdPrice, stEthEthPrice, 1e18), false, address(0));
    }

    /**
     * @dev Canonical rate = stETH per wstETH via the wstETH token contract.
     *      Mirrors the upstream canonical-rate gas-griefing guard: on OOG, revert
     *      `InsufficientGasForExternalCall` instead of triggering a false shutdown.
     */
    function _getCanonicalRate() internal view override returns (uint256, bool) {
        uint256 gasBefore = gasleft();

        try IWstETHRate(rateProviderAddress).stEthPerToken() returns (uint256 stEthPerWstEth) {
            if (stEthPerWstEth == 0) return (0, true);
            return (stEthPerWstEth, false);
        } catch {
            if (gasleft() <= gasBefore / 64) revert InsufficientGasForExternalCall();
            return (0, true);
        }
    }

    /// @dev Last valid backing ratio (see JpyFreezeLib.JpyConversionState.lastGoodBacking).
    function lastGoodBacking() public view returns (uint256) {
        return jpyConversionState.lastGoodBacking;
    }

    /// @dev Shared-JPY-failure shutdown; see `JpyFreezeLib.shutDownFromSharedJpyFailure`.
    function _shutDownFromSharedJpyFailure() internal returns (uint256) {
        JpyFreezeLib.shutDownFromSharedJpyFailure(borrowerOperations, jpyUsdRateProvider);
        return lastGoodPrice;
    }
}
"
    },
    "src/PriceFeeds/JpyFreezeLib.sol": {
      "content": "// SPDX-License-Identifier: MIT

pragma solidity 0.8.24;

import "openzeppelin-contracts/contracts/utils/math/Math.sol";

import "../Interfaces/IBorrowerOperations.sol";
import "../Interfaces/IJpyUsdRateProvider.sol";

// CollateralVault view used by every DF feed to read the dToken backing ratio.
interface IBackingRatioSource {
    function backingRatioForPricing() external view returns (uint256 ratio, bool available);
}

/**
 * @title JpyFreezeLib
 * @notice Shared DF layer applied by every JPY-denominated feed after its USD price
 *         is acquired: USD→JPY conversion through the shared soft-freeze provider
 *         (ORCL-SEC-005), the shared-JPY-failure shutdown signalling, and the Vault
 *         backing-ratio adjustment (dToken/JPY = Coll/JPY × min(1, backing)).
 * @dev Internal library: all functions are inlined into the calling feed, so events
 *      are emitted by (and storage belongs to) the feed itself. The error and event
 *      declared here intentionally reuse the exact signatures of
 *      `MainnetPriceFeedBase.InsufficientGasForExternalCall` /
 *      `MainnetPriceFeedBase.ShutDownFromOracleFailure`, so selectors and topics are
 *      indistinguishable from the pre-library feeds.
 *
 *      The shared `JpyUsdRateProvider` remains a separate contract: it owns the
 *      last-good JPY rate, report provenance, freeze timer, recovery, and bounded
 *      expiry, so every branch receives the same rate and expiry decision. This
 *      library only holds the per-feed backing-ratio state and the per-feed glue.
 */
library JpyFreezeLib {
    struct JpyConversionState {
        // Last valid backing ratio, 1e18-scaled and in (0, 1e18]. Kept for monitoring
        // and last-good-price reconstruction only; a live Vault read failure is treated
        // as an oracle failure rather than silently reusing this value.
        uint256 lastGoodBacking;
    }

    // Same signature (selector) as MainnetPriceFeedBase.InsufficientGasForExternalCall.
    error InsufficientGasForExternalCall();

    // Same signature (topic0) as MainnetPriceFeedBase.ShutDownFromOracleFailure.
    event ShutDownFromOracleFailure(address _failedOracleAddr);

    function initialize(JpyConversionState storage self) internal {
        self.lastGoodBacking = 1e18;
    }

    /**
     * @dev USD (18-dec) → JPY (18-dec) using the JPY/USD oracle (USD per JPY), with a
     *      soft-freeze fallback for the shared JPY leg (ORCL-SEC-005). Both operands
     *      are 18-dec normalized (raw 8-dec × 1e10), so the conversion is a single
     *      full-precision multiplication/division:
     *          collJpy = mulDiv(collUsd, 1e18, jpyUsdRate)
     *      Example: ETH=$3,000, JPY/USD=0.006667 →
     *          3000e18 * 1e18 / 6.667e15 ≈ 450,000e18 (= ¥450,000).
     *
     *      The provider owns the last-good rate, report provenance, freeze timer, and
     *      per-outage expiry. Every branch therefore receives the same rate and expiry
     *      decision while that outage remains unhealthy.
     *
     *      Note: the provider preserves the gas-griefing guard. An out-of-gas Chainlink
     *      read reverts with `InsufficientGasForExternalCall` rather than being silently
     *      treated as a freeze.
     */
    function convertUsdPriceToJpyWithFreeze(IJpyUsdRateProvider _jpyUsdRateProvider, uint256 _usdPrice)
        internal
        returns (uint256, bool)
    {
        (uint256 jpyUsdRate, bool jpyFreezeExpired) = _jpyUsdRateProvider.fetchJpyUsdRate();
        if (jpyFreezeExpired) return (0, true);
        return (Math.mulDiv(_usdPrice, 1e18, jpyUsdRate), false);
    }

    /// @dev The provider latches shared expiry for the current unhealthy episode before this
    ///      call. Catch a source-level
    ///      BorrowerOperations authorization failure so the enclosing PriceFeedProxy call
    ///      does not roll that provider mutation back. The source returns failure=true and stays
    ///      on its primary path so recovery remains observable; the registered proxy performs
    ///      temporary shutdown and later validates the recovered source before resuming.
    function shutDownFromSharedJpyFailure(
        IBorrowerOperations _borrowerOperations,
        IJpyUsdRateProvider _jpyUsdRateProvider
    ) internal returns (bool signalledDirectly) {
        try _borrowerOperations.shutdownFromOracleFailure() {
            signalledDirectly = true;
        } catch {}
        emit ShutDownFromOracleFailure(address(_jpyUsdRateProvider));
    }

    /**
     * @dev Apply the Vault's dToken backing ratio. A normal read failure returns
     *      `backingUnavailable=true` so the caller can enter the standard oracle
     *      shutdown path. Gas-starved calls re-revert with the upstream gas guard
     *      selector so PriceFeedProxy will not misclassify them as oracle failures.
     *      The ratio is lower-bounded to 1 wei when a live Vault returns a measured zero,
     *      because upstream price feed consumers use zero as an invalid-price sentinel. A
     *      complete backing loss is therefore represented as a near-zero price instead of a
     *      stale fail-safe fallback.
     *
     *      The pricing-specific Vault view distinguishes a measured zero from
     *      valuation unavailability. Only the measured zero reaches the 1-wei
     *      floor; unavailability takes the standard oracle-failure path.
     */
    function applyBackingRatio(JpyConversionState storage self, address _collateralVault, uint256 _jpyPrice)
        internal
        returns (uint256, bool)
    {
        uint256 gasBefore = gasleft();

        try IBackingRatioSource(_collateralVault).backingRatioForPricing() returns (
            uint256 liveBacking, bool backingAvailable
        ) {
            if (!backingAvailable) return (0, true);

            if (liveBacking > 1e18) {
                liveBacking = 1e18;
            } else if (liveBacking == 0) {
                // Unchanged: a fully-measured zero still becomes a near-zero price rather than
                // a shutdown, per the original design note above. That is a separate policy
                // question from this fix -- serving collateral at 1e-18 of its value makes the
                // whole book liquidatable, but shutting down instead would quote lastGoodPrice
                // over collateral that is genuinely gone. Only the *unavailable* case is
                // changed here, because that one is not a measurement at all.
                liveBacking = 1;
            }

            self.lastGoodBacking = liveBacking;
            return (Math.mulDiv(_jpyPrice, liveBacking, 1e18), false);
        } catch (bytes memory err) {
            // The Vault reverts with the same gas-guard error when the caller cannot fund the
            // fixed Strategy probe budget (Guardian Remediation L-01). Bubble it unchanged so a
            // gas-starved call is never classified as an oracle failure.
            if (err.length == 4 && bytes4(err) == InsufficientGasForExternalCall.selector) {
                revert InsufficientGasForExternalCall();
            }
            if (gasleft() <= gasBefore / 64) revert InsufficientGasForExternalCall();
            return (0, true);
        }
    }
}
"
    },
    "src/PriceFeeds/JpyUsdRateProvider.sol": {
      "content": "// SPDX-License-Identifier: MIT

pragma solidity 0.8.24;

import "../Dependencies/AggregatorV3Interface.sol";
import "../Interfaces/IJpyUsdRateProvider.sol";

/**
 * @title JpyUsdRateProvider
 * @notice Single source of JPY/USD rate and soft-freeze state for every collateral branch.
 * @dev A shared contract is required because inherited state remains local to each deployed
 *      price feed. Healthy Chainlink responses refresh one shared cache. Invalid, stale, or
 *      reverting responses reuse that cache for at most MAX_JPY_FREEZE_DURATION. Expiration
 *      remains latched while the oracle is unhealthy, but a later fresh response starts a new
 *      healthy episode. Branches that already observed expiry remain in the reversible Core
 *      oracle pause until their registered PriceFeed explicitly resumes them.
 */
contract JpyUsdRateProvider is IJpyUsdRateProvider {
    error InsufficientGasForExternalCall();
    error InvalidOracle();
    error InvalidStalenessThreshold();
    error InvalidInitialOracleResponse();
    error UnexpectedOracleDecimals();

    uint256 public constant MAX_JPY_FREEZE_DURATION = 24 hours;

    AggregatorV3Interface public immutable jpyUsdOracle;
    uint256 public immutable stalenessThreshold;
    uint8 public immutable oracleDecimals;

    uint256 public lastGoodJpyRate;
    uint256 public override lastGoodJpyUpdatedAt;
    uint256 public jpyFrozenSince;
    bool public jpyFreezeExpired;

    event JpyRateFrozen(uint256 timestamp, uint256 frozenRate);
    event JpyRateUnfrozen(uint256 timestamp, uint256 liveRate);
    event JpyFreezeExpired(uint256 timestamp, uint256 frozenRate);

    struct ChainlinkResponse {
        uint80 roundId;
        uint80 answeredInRound;
        int256 answer;
        uint256 updatedAt;
        bool success;
    }

    constructor(address _jpyUsdOracleAddress, uint256 _stalenessThreshold) {
        if (_jpyUsdOracleAddress.code.length == 0) revert InvalidOracle();
        if (_stalenessThreshold == 0) revert InvalidStalenessThreshold();

        jpyUsdOracle = AggregatorV3Interface(_jpyUsdOracleAddress);
        stalenessThreshold = _stalenessThreshold;
        oracleDecimals = jpyUsdOracle.decimals();
        if (oracleDecimals != 8) revert UnexpectedOracleDecimals();

        ChainlinkResponse memory response = _getCurrentChainlinkResponse();
        if (!_isFresh(response)) revert InvalidInitialOracleResponse();

        lastGoodJpyRate = _scaleTo18Decimals(response.answer);
        lastGoodJpyUpdatedAt = response.updatedAt;
    }

    function fetchJpyUsdRate() external returns (uint256 rate, bool freezeExpired) {
        ChainlinkResponse memory response = _getCurrentChainlinkResponse();
        if (_isFresh(response)) {
            rate = _scaleTo18Decimals(response.answer);
            lastGoodJpyRate = rate;
            lastGoodJpyUpdatedAt = response.updatedAt;
            jpyFreezeExpired = false;

            if (jpyFrozenSince != 0) {
                jpyFrozenSince = 0;
                emit JpyRateUnfrozen(block.timestamp, rate);
            }
            return (rate, false);
        }

        // Terminal for the current outage, not for the provider's lifetime. Keep returning the
        // expired signal while the oracle is unhealthy, but leave the fresh-read path above
        // reachable so a later valid round can begin a new episode.
        if (jpyFreezeExpired) return (lastGoodJpyRate, true);

        // The response is not fresh, but it may still be decodable and NEWER than what we
        // cached. `lastGoodJpyUpdatedAt` only advances on a fresh read, and nothing polls this
        // contract, so after a quiet period the cache can lag the newest published round by an
        // unbounded amount. Serving that older rate is strictly worse, and the freeze onset
        // below is derived from the same timestamp, so the lag also shortens the grace window.
        // Adopt the newer round here: same validity checks as `_isFresh` minus the staleness
        // clause, which is the one condition we already know fails.
        if (
            response.success && response.roundId != 0 && response.answeredInRound >= response.roundId
                && response.updatedAt != 0 && response.updatedAt <= block.timestamp && response.answer > 0
                && response.updatedAt > lastGoodJpyUpdatedAt
        ) {
            lastGoodJpyRate = _scaleTo18Decimals(response.answer);
            lastGoodJpyUpdatedAt = response.updatedAt;
            // A newer valid round marks a new data episode even if no caller observed it while
            // fresh. Re-anchor the stale episode below instead of inheriting the old timer. An
            // already-expired episode returned above and still requires an observed fresh
            // response to clear its latch.
            jpyFrozenSince = 0;
        }

        rate = lastGoodJpyRate;
        if (jpyFrozenSince == 0) {
            uint256 freezeStartedAt = block.timestamp;
            if (block.timestamp - lastGoodJpyUpdatedAt >= stalenessThreshold) {
                freezeStartedAt = lastGoodJpyUpdatedAt + stalenessThreshold;
            }
            jpyFrozenSince = freezeStartedAt;
            emit JpyRateFrozen(freezeStartedAt, rate);
        }

        if (block.timestamp - jpyFrozenSince >= MAX_JPY_FREEZE_DURATION) {
            jpyFreezeExpired = true;
            emit JpyFreezeExpired(block.timestamp, rate);
            return (rate, true);
        }

        return (rate, false);
    }

    function _getCurrentChainlinkResponse() internal view returns (ChainlinkResponse memory response) {
        uint256 gasBefore = gasleft();

        // Both fresh and stale-but-new adoption require `response.success`, so invalidate the
        // response here before either path can scale or cache a differently-scaled answer.
        try jpyUsdOracle.decimals() returns (uint8 liveDecimals) {
            if (liveDecimals != oracleDecimals) return response;
        } catch {
            if (gasleft() <= gasBefore / 64) revert InsufficientGasForExternalCall();
            return response;
        }

        gasBefore = gasleft();

        try jpyUsdOracle.latestRoundData() returns (
            uint80 roundId, int256 answer, uint256, /* startedAt */ uint256 updatedAt, uint80 answeredInRound
        ) {
            response.roundId = roundId;
            response.answeredInRound = answeredInRound;
            response.answer = answer;
            response.updatedAt = updatedAt;
            response.success = true;
            return response;
        } catch {
            if (gasleft() <= gasBefore / 64) revert InsufficientGasForExternalCall();
            return response;
        }
    }

    function _isFresh(ChainlinkResponse memory _response) internal view returns (bool) {
        return _response.success && _response.roundId != 0 && _response.answeredInRound >= _response.roundId
            && _response.updatedAt != 0 && _response.updatedAt <= block.timestamp
            && block.timestamp - _response.updatedAt < stalenessThreshold && _response.answer > 0;
    }

    function _scaleTo18Decimals(int256 _answer) internal pure returns (uint256) {
        return uint256(_answer) * 1e10;
    }
}
"
    },
    "src/PriceFeeds/MainnetPriceFeedBase.sol": {
      "content": "// SPDX-License-Identifier: MIT

pragma solidity 0.8.24;

import "../Dependencies/AggregatorV3Interface.sol";
import "../Interfaces/IMainnetPriceFeed.sol";
import "../Interfaces/IBorrowerOperations.sol";

abstract contract MainnetPriceFeedBase is IMainnetPriceFeed {
    // Determines where the PriceFeed sources data from. Possible states:
    // - primary: Uses the primary price calculation, which depends on the specific feed
    // - ETHUSDxCanonical: Uses Chainlink's ETH-USD multiplied by the LST' canonical rate
    // - lastGoodPrice: the last good price recorded by this PriceFeed.
    PriceSource public priceSource;

    // Last good price tracker for the derived USD price
    uint256 public lastGoodPrice;

    struct Oracle {
        AggregatorV3Interface aggregator;
        uint256 stalenessThreshold;
        uint8 decimals;
    }

    struct ChainlinkResponse {
        uint80 roundId;
        uint80 answeredInRound;
        int256 answer;
        uint256 timestamp;
        bool success;
    }

    error InsufficientGasForExternalCall();

    event ShutDownFromOracleFailure(address _failedOracleAddr);

    Oracle public ethUsdOracle;

    IBorrowerOperations borrowerOperations;

    constructor(address _ethUsdOracleAddress, uint256 _ethUsdStalenessThreshold, address _borrowOperationsAddress) {
        // Store ETH-USD oracle
        ethUsdOracle.aggregator = AggregatorV3Interface(_ethUsdOracleAddress);
        ethUsdOracle.stalenessThreshold = _ethUsdStalenessThreshold;
        ethUsdOracle.decimals = ethUsdOracle.aggregator.decimals();

        borrowerOperations = IBorrowerOperations(_borrowOperationsAddress);

        assert(ethUsdOracle.decimals == 8);
    }

    function _getOracleAnswer(Oracle memory _oracle) internal view returns (uint256, bool) {
        (uint256 scaledPrice, bool oracleIsDown,) = _getOracleAnswerWithTimestamp(_oracle);
        return (scaledPrice, oracleIsDown);
    }

    /// @dev Returns the response timestamp alongside the normal oracle result. Callers that
    ///      cache a healthy answer can retain the matching timestamp as its provenance.
    function _getOracleAnswerWithTimestamp(Oracle memory _oracle)
        internal
        view
        returns (uint256 scaledPrice, bool oracleIsDown, uint256 updatedAt)
    {
        ChainlinkResponse memory chainlinkResponse = _getCurrentChainlinkResponse(_oracle.aggregator);
        updatedAt = chainlinkResponse.timestamp;

        // Check oracle is serving an up-to-date and sensible price. If not, shut down this collateral branch.
        if (!_isValidChainlinkPrice(chainlinkResponse, _oracle.stalenessThreshold)) {
            oracleIsDown = true;
        } else {
            scaledPrice = _scaleChainlinkPriceTo18decimals(chainlinkResponse.answer, _oracle.decimals);
        }

        return (scaledPrice, oracleIsDown, updatedAt);
    }

    function _shutDownAndReturnLastGoodPrice(address _failedOracleAddr) internal returns (uint256) {
        // Enter the recoverable oracle-failure shutdown. Keep retrying the primary source so
        // PriceFeedProxy can prove recovery before resuming the branch.
        borrowerOperations.shutdownFromOracleFailure();

        emit ShutDownFromOracleFailure(_failedOracleAddr);
        return lastGoodPrice;
    }

    /// @dev Legacy name retained for archived feed sources that are compiled by historical tests.
    function _shutDownAndSwitchToLastGoodPrice(address _failedOracleAddr) internal returns (uint256) {
        uint256 fallbackPrice = _shutDownAndReturnLastGoodPrice(_failedOracleAddr);
        priceSource = PriceSource.lastGoodPrice;
        return fallbackPrice;
    }

    function _getCurrentChainlinkResponse(AggregatorV3Interface _aggregator)
        internal
        view
        returns (ChainlinkResponse memory chainlinkResponse)
    {
        uint256 gasBefore = gasleft();

        // Try to get latest price data:
        try _aggregator.latestRoundData() returns (
            uint80 roundId, int256 answer, uint256, /* startedAt */ uint256 updatedAt, uint80 answeredInRound
        ) {
            // If call to Chainlink succeeds, return the response and success = true
            chainlinkResponse.roundId = roundId;
            chainlinkResponse.answeredInRound = answeredInRound;
            chainlinkResponse.answer = answer;
            chainlinkResponse.timestamp = updatedAt;
            chainlinkResponse.success = true;

            return chainlinkResponse;
        } catch {
            // Require that enough gas was provided to prevent an OOG revert in the call to Chainlink
            // causing a shutdown. Instead, just revert. Slightly conservative, as it includes gas used
            // in the check itself.
            if (gasleft() <= gasBefore / 64) revert InsufficientGasForExternalCall();

            // If call to Chainlink aggregator reverts, return a zero response with success = false
            return chainlinkResponse;
        }
    }

    // False if:
    // - Call to Chainlink aggregator reverts
    // - roundId is zero
    // - answeredInRound is older than roundId
    // - updatedAt is zero or in the future
    // - price is too stale, i.e. older than the oracle's staleness threshold
    // - Price answer is 0 or negative
    function _isValidChainlinkPrice(ChainlinkResponse memory chainlinkResponse, uint256 _stalenessThreshold)
        internal
        view
        returns (bool)
    {
        return chainlinkResponse.success && chainlinkResponse.roundId != 0
            && chainlinkResponse.answeredInRound >= chainlinkResponse.roundId && chainlinkResponse.timestamp != 0
            && chainlinkResponse.timestamp <= block.timestamp
            && block.timestamp - chainlinkResponse.timestamp < _stalenessThreshold && chainlinkResponse.answer > 0;
    }

    // Trust assumption: Chainlink won't change the decimal precision on any feed used in v2 after deployment
    function _scaleChainlinkPriceTo18decimals(int256 _price, uint256 _decimals) internal pure returns (uint256) {
        // Scale an int price to a uint with 18 decimals
        return uint256(_price) * 10 ** (18 - _decimals);
    }
}
"
    },
    "src/PriceFeeds/PriceFeedPlaceholder.sol": {
      "content": "// SPDX-License-Identifier: MIT

pragma solidity 0.8.24;

import "../Interfaces/IPriceFeed.sol";

/**
 * @title PriceFeedPlaceholder
 * @notice Inert price feed used as the Day-1 `source` of a `PriceFeedProxy` for a placeholder
 *         (deferred-underlying) branch (placeholder branches), before the real collateral is chosen.
 *
 * @dev Why a dedicated stub instead of `address(0)` / an EOA:
 *      `CollateralRegistry.redeemCollateral` scans EVERY registered branch and reads its price
 *      via `priceFeed.fetchPrice()` / `fetchRedemptionPrice()` with NO try/catch at the registry
 *      level. So a placeholder branch's feed is read on every redemption, even before activation.
 *      It must therefore:
 *        1. be a deployed contract with code (a non-contract source makes `PriceFeedProxy`'s
 *           try/catch fail to catch and revert the whole redemption — guarded by PR #58); and
 *        2. return a price the proxy considers VALID and never revert, so that
 *           `PriceFeedProxy._handleFailedFetch()` (which calls `shutdownFromOracleFailure()`) is
 *           never reached and the branch is not oracle-paused before Day-2.
 *
 *      `PriceFeedProxy._isInvalidPrice(p)` returns true iff `p == 0 || p == type(uint256).max`.
 *      `SENTINEL_PRICE` (1e18) is neither, so the proxy passes it through cleanly.
 *
 *      At Day-2 activation the real feed replaces this stub via
 *      `PriceFeedProxy.proposeSource(realFeed)` -> (12h timelock) -> `confirmSource()` or
 *      `confirmSourceEmergency()`. A placeholder sentinel to real-price switch usually exceeds
 *      the normal price-jump guard, so the emergency path may be required; it still enforces the
 *      timelock and real-feed smoke tests.
 *      A placeholder branch holds no debt (cap = 0, no Troves), so this sentinel price is never
 *      used for any borrow/liquidation/redemption math; it only keeps the branch non-shutdown.
 */
contract PriceFeedPlaceholder is IPriceFeed {
    /// @notice Fixed sentinel price (1e18). Non-zero and != type(uint256).max, so
    ///         `PriceFeedProxy._isInvalidPrice` does not flag it and no shutdown is triggered.
    uint256 public constant SENTINEL_PRICE = 1e18;

    /// @notice Explicit synthetic JPY provenance for the inert placeholder source.
    /// @dev Placeholder branches cannot be activated by this sentinel quote. Returning self with
    ///      the current timestamp keeps system-wide redemption scans available without making a
    ///      missing provenance getter a fail-open path for real sources.
    function jpyUsdRateProvider() external view returns (address) {
        return address(this);
    }

    function lastGoodJpyUpdatedAt() external view returns (uint256) {
        return block.timestamp;
    }

    /// @inheritdoc IPriceFeed
    function fetchPrice() external pure override returns (uint256, bool) {
        return (SENTINEL_PRICE, false);
    }

    /// @inheritdoc IPriceFeed
    function fetchRedemptionPrice() external pure override returns (uint256, bool) {
        return (SENTINEL_PRICE, false);
    }

    /// @inheritdoc IPriceFeed
    function fetchUrgentRedemptionPrice() external pure override returns (uint256, bool) {
        return (SENTINEL_PRICE, false);
    }

    /// @inheritdoc IPriceFeed
    function lastGoodPrice() external pure override returns (uint256) {
        return SENTINEL_PRICE;
    }
}
"
    },
    "src/PriceFeeds/PriceFeedProxy.sol": {
      "content": "// SPDX-License-Identifier: MIT

pragma solidity 0.8.24;

import {Ownable2Step} from "openzeppelin-contracts/contracts/access/Ownable2Step.sol";

import "../Interfaces/IPriceFeedProxy.sol";
import "../Interfaces/IBorrowerOperations.sol";
import "../Interfaces/IJpyUsdRateProvider.sol";
// Imported only to bind the gas-griefing guard selector to upstream at COMPILE time
// (see _bubbleIfGasError). No core file is modified by importing it.
import {MainnetPriceFeedBase} from "./MainnetPriceFeedBase.sol";

interface IJpyUsdRateProviderSource {
    function jpyUsdRateProvider() external view returns (IJpyUsdRateProvider);
}

/**
 * @title PriceFeedProxy
 * @notice Swappable-source price feed: a fixed reference address whose underlying price
 *         source is switchable behind a 12h timelock. NOT a UUPS / delegatecall / storage
 *         proxy and not upgradeable in the storage sense — "proxy" here means indirection.
 * @dev Allows switching between different price feed sources without redeploying
 *      the protocol. The DF protocol should reference this proxy address, never
 *      the underlying source directly.
 *
 *      Use Cases:
 *      - WBTC: Switch from WBTC oracle to CBTC oracle if WBTC has issues
 *      - USD stablecoins: Switch underlying (USDT → USDC) when business terms change
 *      - JPYC/dJPY: Switch from fixed feed to Chainlink when oracle becomes available
 *      - WETH: Switch oracle provider if Chainlink feed is deprecated
 *
 *      Oracle failure handling:
 *      - Underlying feeds call borrowerOperations.shutdownFromOracleFailure() directly.
 *        Since BorrowerOperations checks msg.sender == address(priceFeed) (this proxy),
 *        and the caller is the underlying feed, the call reverts.
 *      - This proxy catches that revert, calls shutdownFromOracleFailure() itself
 *        (as the registered priceFeed), and returns lastGoodPrice.
 *      - If the source is completely bricked, the proxy falls back to its own
 *        cached last-good price for the active consumer path to prevent permanent DoS.
 *      - Composite / multi-stage feeds must be reviewed per feed before being wrapped.
 *        The production `CompositePriceFeed` used by sUSDS intentionally exposes only the
 *        primary -> lastGoodPrice path. Do not reintroduce an upstream LST-style secondary
 *        mode behind this proxy without a dedicated route/source design review.
 *
 *      Source switching (timelocked, governance-transparent):
 *      - Source changes follow a two-step timelock: proposeSource() → wait
 *        TIMELOCK_DELAY → confirmSource(). The timelock guarantees the swap cannot
 *        happen without TIMELOCK_DELAY of public notice (SourceProposed emits the
 *        executable time); it does NOT by itself eliminate price-jump MEV at the
 *        confirmSource block. The normal confirm path rejects material jumps against
 *        the old source's live price, or the proxy's cached last-good prices when the
 *        old source is unhealthy. Incident recovery / placeholder activation can use
 *        confirmSourceEmergency() to bypass only that price-jump guard after the same
 *        timelock and new-source smoke tests.
 *      - confirmSource smoke-tests the new source, always re-initialises the normal cache,
 *        and re-initialises the redemption cache only from fresh JPY provenance. An aged
 *        source cannot replace that cache and any later fallback is returned with failure=true.
 *      - Owner can cancel a pending proposal at any time.
 *
 *      Ownership:
 *      - Inherits OpenZeppelin Ownable2Step (v4.9.5). 2-step transfer
 *        (transferOwnership + acceptOwnership) prevents accidental loss of
 *        ownership via typos. The new owner must actively call acceptOwnership()
 *        to finalise the transfer.
 *      - Renounce is disabled. The source-swap authority is the only recovery path
 *        from future feed deprecation, placeholder activation, and shared JPY/USD
 *        oracle incidents, so ownership must be transferred to a governance /
 *        multisig address rather than burned.
 */
contract PriceFeedProxy is IPriceFeedProxy, Ownable2Step {
    // --- Constants ---

    /// @notice Minimum delay before a proposed source can be confirmed.
    uint256 public constant TIMELOCK_DELAY = 12 hours;
    uint256 public constant MAX_NORMAL_REDEMPTION_JPY_AGE = 30 hours;
    uint256 public constant MAX_SOURCE_SWITCH_DEVIATION_BPS = 100; // 1%
    uint256 private constant BPS_DENOMINATOR = 10_000;
    uint8 private constant JPY_PROVENANCE_INVALID = 0;
    uint8 private constant JPY_PROVENANCE_FRESH = 1;
    uint8 private constant JPY_PROVENANCE_AGED = 2;
    uint256 private constant JPY_PROVENANCE_GAS_STIPEND = 30_000;

    // --- State ---

    address public source;
    IBorrowerOperations public immutable borrowerOperations;

    /// @dev Proxy-level fallback price for the normal borrow/liquidation path.
    ///      Used if the source is completely bricked and lastGoodPrice() reverts.
    uint256 private _lastGoodPrice;
    /// @dev Proxy-level fallback price for the redemption path. Some sources intentionally
    ///      serve a distinct redemption price, so a bricked source must not collapse back to
    ///      the normal-path cache.
    uint256 private _lastGoodRedemptionPrice;

    // --- Timelock state ---
    address public proposedSource;
    uint256 public sourceProposedAt;

    struct SourceRead {
        bool healthy;
        bool redemptionPriceCacheable;
        uint256 price;
        uint256 redemptionPrice;
        uint256 urgentRedemptionPrice;
    }

    /**
     * @param _initialSource Initial price feed source address
     * @param _ownerAddress Owner address (typically deployer, then transferred to governance)
     * @param _borrowerOperations BorrowerOperations address for this collateral branch
     */
    constructor(address _initialSource, address _ownerAddress, address _borrowerOperations) {
        // Source must be a deployed contract. address(0) or an EOA would make
        // fetchPrice()/fetchRedemptionPrice() revert via Solidity's code-existence check
        // (which the try/catch in those functions does NOT catch), bricking redemption
        // system-wide since CollateralRegistry.redeemCollateral reads every branch unguarded.
        //
        // Scope of THIS guard (code.length): it blocks ONLY non-contract sources
        // (address(0) / EOA). It is not the full validity check — further screens run below:
        //   - a direct source exposing the PriceFeedProxy `source()` getter marker is rejected.
        //     This is a shallow type screen only; semantic forwarding and dependency cycles
        //     remain part of deployment and timelocked source-change review;
        //   - a deployed source that reverts on a cache-backed normal/redemption fetch is
        //     intentionally allowed: the F-01 warm just below uses the lastGoodPrice() view,
        //     and those runtime paths catch the revert and fall back to lastGoodPrice. The
        //     cache-free urgent fetch must succeed in the C-2 smoke-test below;
        //   - a deployed source that returns *mis-encoded* (wrong-ABI) data, an invalid (0/max)
        //     price, or a failure-flagged (oracleFailure==true) result is rejected — not here,
        //     but by the C-2 smoke-test at the end of this constructor (a wrong-ABI decode
        //     failure pierces try/catch; an invalid/failure-flagged success return is rejected
        //     explicitly), so it can never be set as an initial source that would brick or shut
        //     down the branch on its first fetch. A merely-reverting normal/redemption path is
        //     still tolerated there, while an urgent-path revert is rejected.
        // What stays the owner's responsibility (operationally, via Ownable2Step + the 12h
        // source-swap timelock — no on-chain check can verify it) is the source's *semantic*
        // honesty: returning a truthful, correctly-scaled price.
        if (_initialSource.code.length == 0) revert InvalidSource();
        if (_ownerAddress == address(0)) revert ZeroOwnerAddress();
        if (_borrowerOperations == address(0)) revert InvalidAddress();
        if (_isPriceFeedProxy(_initialSource)) revert InvalidSource();

        // Ownable's constructor already set owner to deployer; re-target to the
        // desired initial owner. Emits a second OwnershipTransferred event.
        _transferOwnership(_ownerAddress);

        source = _initialSource;
        borrowerOperations = IBorrowerOperations(_borrowerOperations);

        // F-01: warm the proxy-level cache from the initial source and reject a source that
        // cannot serve a valid (non-zero) price. lastGoodPrice() (a view) is used rather than
        // fetchPrice() so a source whose *live* fetch may revert — intentionally tolerated at
        // runtime by the try/catch in fetchPrice() — is still constructible (see
        // PriceFeedProxySourceValidation.t.sol), while a zero / bricked source is rejected at
        // deploy (fail-closed) instead of silently returning 0 to a downstream divisor
        // (TroveManager redemption divides jpydfLot by the redemption price).
        uint256 initialRedemptionPrice;
        try IPriceFeed(_initialSource).lastGoodPrice() returns (uint256 initPrice) {
            if (_isInvalidPrice(initPrice)) revert InvalidSource();
            _lastGoodPrice = initPrice;
            initialRedemptionPrice = initPrice;
        } catch {
            revert InvalidSource();
        }

        // C-2: smoke-test all fetch entrypoints the protocol reads with no try/catch (fetchPrice
        // via getUnbackedPortion...; fetchRedemptionPrice via RedemptionHelper / TroveManager
        // redemption math), and validate the SUCCESS-path result fail-closed — exactly as
        // confirmSource does at switch time. On a decodable, non-reverting return, reject a 0/max
        // sentinel OR an oracleFailure==true flag with InvalidSource. That revert fires inside the
        // success body which — like a return-data decode failure — is not caught by these external
        // call catches and so reverts the constructor. This rejects, at DEPLOY, an initial source
        // that is already failing or would serve an invalid price, instead of letting the branch
        // shut itself down (or, under a deploy miswire, stay live on a frozen price) on its first
        // fetch.
        //
        // Still tolerated (empty catch) for the cache-backed normal and redemption paths: a source
        // whose live fetch reverts can be served from the F-01 cache at runtime. Urgent redemption
        // has no cache by design, so its probe must succeed at construction. A wrong-ABI source's
        // decode failure still pierces try/catch and reverts here.
        try IPriceFeed(_initialSource).fetchPrice() returns (uint256 fp, bool fpFailure) {
            if (_isInvalidPrice(fp) || fpFailure) revert InvalidSource();
            _lastGoodPrice = fp;
        } catch {}
        try IPriceFeed(_initialSource).fetchRedemptionPrice() returns (uint256 rp, bool rpFailure) {
            if (_isInvalidPrice(rp) || rpFailure) revert InvalidSource();
            initialRedemptionPrice = rp;
        } catch {}
        try IPriceFeed(_initialSource).fetchUrgentRedemptionPrice() returns (uint256 up, bool upFailure) {
            if (_isInvalidPrice(up) || upFailure) revert InvalidSource();
        } catch (bytes memory err) {
            _bubbleIfGasError(err);
            revert InvalidSource();
        }

        if (_normalRedemptionJpyStatus(_initialSource) != JPY_PROVENANCE_FRESH) revert InvalidSource();
        _lastGoodRedemptionPrice = initialRedemptionPrice;

        emit SourceUpdated(address(0), _initialSource);
    }

    // =========================================================
    //  Price feed delegation
    // =========================================================

    /// @inheritdoc IPriceFeed
    function fetchPrice() external returns (uint256, bool) {
        try IPriceFeed(source).fetchPrice() returns (uint256 price, bool oracleFailure) {
            // A source-signalled failure follows the same temporary shutdown path as a revert.
            if (_isInvalidPrice(price) || oracleFailure) return _handleFailedFetch(false);
            _lastGoodPrice = price;
            // BorrowerOperations also requests the quote for irreversible SCR
            // shutdown decisions. Both it and risk-increasing operations must
            // use JPY provenance younger than 30h. Liquidations keep the source's
            // bounded cached-rate grace; pure repayment/addition needs no quote.
            if (msg.sender == address(borrowerOperations) && _normalRedemptionJpyStatus(source) != JPY_PROVENANCE_FRESH) {
                return (price, true);
            }
            // A recovered live normal price may be used before owner resume for liquidation,
            // the TCR<SCR check and CCR-checked close. Risk increases and
            // normal redemption remain gated by the latched shutdown flag.
            return (price, false);
        } catch (bytes memory err) {
            _bubbleIfGasError(err);
            return _handleFailedFetch(false);
        }
    }

    /// @inheritdoc IPriceFeed
    function fetchRedemptionPrice() external returns (uint256, bool) {
        try IPriceFeed(source).fetchRedemptionPrice() returns (uint256 price, bool oracleFailure) {
            // F-02: see fetchPrice(). Route a failure-flagged-but-valid price through shutdown too.
            if (_isInvalidPrice(price) || oracleFailure) return _handleFailedFetch(true);

            // Stop normal redemption once the shared JPY/USD round reaches 30h old.
            // The source call comes first so the first fresh round refreshes provenance and
            // reopens redemption automatically. This local gate deliberately does not invoke
            // _handleFailedFetch: the borrowing gate above is independent of the
            // liquidation and urgent-redemption source policies.
            if (_normalRedemptionJpyStatus(source) != JPY_PROVENANCE_FRESH) return (price, true);

            _lastGoodRedemptionPrice = price;
            // A latched BO pause keeps normal redemption closed until the owner validates all
            // three price paths; the JPY-age gate above independently requires fresh provenance.
            return (price, borrowerOperations.isOracleFailureShutdown());
        } catch (bytes memory err) {
            _bubbleIfGasError(err);
            return _handleFailedFetch(true);
        }
    }

    /// @inheritdoc IPriceFeed
    function fetchUrgentRedemptionPrice() external returns (uint256, bool) {
        try IPriceFeed(source).fetchUrgentRedemptionPrice() returns (uint256 price, bool oracleFailure) {
            // Wind-down must never settle against a normal-path cache. There is deliberately
            // no third cache: only a source-policy-valid urgent quote is accepted.
            if (_isInvalidPrice(price) || oracleFailure) revert UrgentRedemptionPriceUnavailable(source);
            return (price, false);
        } catch (bytes memory err) {
            _bubbleIfGasError(err);
            revert UrgentRedemptionPriceUnavailable(source);
        }
    }

    /**
     * @dev Handles the case where the underlying feed reverted or returned an invalid price.
     *      Triggers temporary oracle-failure shutdown, then tries to read lastGoodPrice from the source.
     *      For the normal path, a valid source.lastGoodPrice() can refresh the proxy cache.
     *      For the redemption path, lastGoodPrice() is not path-specific, so the proxy only
     *      serves its own last known redemption price. This prevents a failing source with
     *      intentionally distinct normal/redemption prices from collapsing redemption math to
     *      the normal-path cache.
     */
    function _handleFailedFetch(bool _isRedemption) internal returns (uint256, bool) {
        // L-2: surface proxy-level fail-safe activation for monitoring (the source failed and
        // the proxy is taking over shutdown + fallback). Emitted on the failure path only.
        emit SourceFailureHandled(source);

        // shutdownFromOracleFailure reverts ONLY on caller-mismatch (this proxy is not the
        // branch's registered priceFeed = a deploy miswire); it is a no-op when already shut
        // down, so in correct wiring it never reverts. We do NOT propagate (that would let one
        // failing branch DoS the system-wide redemption loop) -- instead we serve lastGoodPrice
        // and raise ShutdownCallReverted so a miswired branch on a frozen price is observable.
        try borrowerOperations.shutdownFromOracleFailure() {}
        catch {
            emit ShutdownCallReverted(address(borrowerOperations), source);
        }

        if (_isRedemption) {
            return (_lastGoodRedemptionPrice, true);
        }

        // Try to read lastGoodPrice from source; fall back to proxy cache if bricked.
        // Reject 0 AND type(uint256).max (via _isInvalidPrice, not a bare > 0): an invalid
        // sentinel from a misbehaving source must never be cached or served, because
        // redemption/liquidation ignore the failure bool and would consume it directly.
        try IPriceFeed(source).lastGoodPrice() returns (uint256 sourceLastGood) {
            if (!_isInvalidPrice(sourceLastGood)) {
                _lastGoodPrice = sourceLastGood;
                return (sourceLastGood, true);
            }
        } catch {}

        return (_lastGoodPrice, true);
    }

    /// @inheritdoc IPriceFeedProxy
    function resumeFromOracleFailure() external onlyOwner {
        if (!borrowerOperations.isOracleFailureShutdown()) revert OracleFailureShutdownNotActive();

        SourceRead memory read = _readSourceIfHealthy(source);
        if (!read.healthy) revert SourceNotHealthy();

        _lastGoodPrice = read.price;
        if (read.redemptionPriceCacheable) _lastGoodRedemptionPrice = read.redemptionPrice;
        borrowerOperations.resumeFromOracleFailure();

        emit OracleFailureShutdownResumed(source, read.price, read.redemptionPrice);
    }

    /**
     * @dev Returns true if price is zero or max uint256 (sentinel/invalid values).
     */
    function _isInvalidPrice(uint256 _price) internal pure returns (bool) {
        return _price == 0 || _price == type(uint256).max;
    }

    /// @dev Re-revert the underlying gas-griefing guard unchanged; otherwise a
    ///      gas-starved call would be misclassified as an oracle failure.
    function _bubbleIfGasError(bytes memory _err) private pure {
        if (_err.length == 4) {
            bytes4 sel;
            assembly {
                sel := mload(add(_err, 0x20))
            }
            // F-04: bind to upstream's selector at COMPILE time. If upstream renames or removes
            // this error, this file fails to compile (instead of silently misclassifying a
            // gas-starved call as an oracle failure and forcing an unnecessary shutdown).
            if (sel == MainnetPriceFeedBase.InsufficientGasForExternalCall.selector) {
                assembly {
                    revert(add(_err, 0x20), mload(_err))
                }
            }
        }
    }

    /// @inheritdoc IPriceFeed
    function lastGoodPrice() external view returns (uint256) {
        try IPriceFeed(source).lastGoodPrice() returns (uint256 sourceLastGood) {
            // Reject 0 AND type(uint256).max, mirroring _handleFailedFetch / fetchPrice.
            if (!_isInvalidPrice(sourceLastGood)) return sourceLastGood;
        } catch {}
        return _lastGoodPrice;
    }

    // =========================================================
    //  Timelocked source switching
    //  (timelock guarantees 12h public notice; it does NOT by itself eliminate price-jump
    //   MEV at the confirmSource block — submit confirmSource privately when prices may differ)
    // =========================================================

    /// @inheritdoc IPriceFeedProxy
    function proposeSource(address _newSource) external onlyOwner {
        // Reject non-contract sources (address(0) / EOA): a no-code source makes the
        // proxy's fetch revert un-catchably and DoS all redemptions. A source exposing the
        // PriceFeedProxy `source()` marker is also rejected as a shallow direct-proxy screen.
        // It does not traverse semantic forwarding or prove dependency-graph acyclicity; those
        // checks remain the owner's responsibility under the timelock (see constructor note).
        if (_newSource.code.length == 0) revert InvalidSource();
        if (_newSource == source) revert SameSource();
        if (_isPriceFeedProxy(_newSource)) revert InvalidSource();

        // If overwriting a pending proposal, emit cancellation for the old one
        if (proposedSource != address(0)) {
            emit SourceProposalCancelled(proposedSource);
        }

        proposedSource = _newSource;
        sourceProposedAt = block.timestamp;

        emit SourceProposed(_newSource, block.timestamp + TIMELOCK_DELAY);
    }

    /// @inheritdoc IPriceFeedProxy
    function confirmSource() external onlyOwner {
        _confirmSource(false);
    }

    /// @inheritdoc IPriceFeedProxy
    function confirmSourceEmergency() external onlyOwner {
        _confirmSource(true);
    }

    function _confirmSource(bool _bypassPriceGuard) internal {
        if (proposedSource == address(0)) revert NoProposalPending();
        if (block.timestamp < sourceProposedAt + TIMELOCK_DELAY) revert TimelockNotElapsed();
        // Defense-in-depth: re-check at execution time that the proposed source still has
        // code (it could have been removed between proposal and confirmation).
        if (proposedSource.code.length == 0) revert InvalidSource();
        // Redundant with proposeSource's check, but keeps confirm self-contained.
        if (proposedSource == source) revert SameSource();
        // Re-check the shallow direct-proxy marker after the timelock so proposal-time
        // classification cannot be bypassed by changed code or corrupted pending state.
        // This marker does not traverse forwarding dependencies or prove acyclicity.
        if (_isPriceFeedProxy(proposedSource)) revert InvalidSource();

        address oldSource = source;
        SourceRead memory oldRead;
        // The emergency path is the recovery route for a broken source. Do not call that
        // source here: it may consume all forwarded gas and otherwise make itself impossible
        // to replace. The validated proxy caches remain the continuity reference for the event.
        if (!_bypassPriceGuard) oldRead = _readSourceIfHealthy(oldSource);

        // F-03 / F-06: smoke-test the new source so the switch fails CLOSED if the new source
        // cannot serve a valid, ABI-decodable price *right now*. A reverting source reverts here;
        // a mis-encoded (wrong-ABI) source's return-data decode failure pierces try/catch and
        // also reverts here — both reject the switch instead of bricking redemption later
        // (CollateralRegistry.redeemCollateral reads every branch's feed with no try/catch).
        // Re-initialise the normal cache to the NEW source. Re-initialise the redemption cache
        // only from fresh JPY provenance; an aged source cannot replace the last fresh quote,
        // and any later fallback is returned with failure=true so consumers cannot settle on it.
        (uint256 newPrice, bool newOracleFailure) = IPriceFeed(proposedSource).fetchPrice();
        // Reject an invalid price AND a live-but-failing source (valid price + oracleFailure==true
        // without reverting) — consistent with fetchPrice's F-02 handling, so confirm only accepts
        // a source actually serving good data right now.
        if (_isInvalidPrice(newPrice) || newOracleFailure) revert InvalidSource();
        // C-1: validate fetchRedemptionPrice() too. Redemption divides by it (RedemptionHelper.sol
        // / TroveManager.sol) and reads it with no try/catch, so a source valid on fetchPrice() but
        // wrong-ABI / reverting / failure-flagged on fetchRedemptionPrice() would still DoS all
        // redemptions. A wrong-ABI return-data decode failure pierces try/catch and reverts here.
        (uint256 newRedemptionPrice, bool newRedemptionFailure) = IPriceFeed(proposedSource).fetchRedemptionPrice();
        if (_isInvalidPrice(newRedemptionPrice) || newRedemptionFailure) revert InvalidSource();
        (uint256 newUrgentRedemptionPrice, bool newUrgentRedemptionFailure) =
            IPriceFeed(proposedSource).fetchUrgentRedemptionPrice();
        if (_isInvalidPrice(newUrgentRedemptionPrice) || newUrgentRedemptionFailure) revert InvalidSource();

        uint256 referencePrice = oldRead.healthy ? oldRead.price : _lastGoodPrice;
        uint256 referenceRedemptionPrice =
            oldRead.healthy && oldRead.redemptionPriceCacheable ? oldRead.redemptionPrice : _lastGoodRedemptionPrice;
        uint256 referenceUrgentRedemptionPrice =
            oldRead.healthy ? oldRead.urgentRedemptionPrice : _lastGoodRedemptionPrice;

        // Normal confirmation never becomes an implicit emergency path merely because the old
        // source failed between proposal and execution. The proxy caches are initialized and
        // updated only from validated prices, so they provide the continuity reference while the
        // old source is unavailable. A deliberate jump remains possible through the explicitly
        // named emergency entrypoint, which keeps the same timelock and new-source smoke tests.
        if (!_bypassPriceGuard) {
            _requireWithinSwitchDeviation(referencePrice, newPrice);
            _requireWithinSwitchDeviation(referenceRedemptionPrice, newRedemptionPrice);
            _requireWithinSwitchDeviation(referenceUrgentRedemptionPrice, newUrgentRedemptionPrice);
        }

        _cacheConfirmedSourcePrices(proposedSource, newPrice, newRedemptionPrice);

        source = proposedSource;

        proposedSource = address(0);
        sourceProposedAt = 0;

        emit SourceUpdated(oldSource, source);
        emit SourceSwitchValidated(
            oldSource,
            source,
            oldRead.healthy,
            _bypassPriceGuard,
            referencePrice,
            newPrice,
            referenceRedemptionPrice,
            newRedemptionPrice
        );
    }

    function _readSourceIfHealthy(address _source) internal returns (SourceRead memory read) {
        try IPriceFeed(_source).fetchPrice() returns (uint256 price, bool oracleFailure) {
            if (_isInvalidPrice(price) || oracleFailure) return read;
            read.price = price;
        } catch {
            return read;
        }

        try IPriceFeed(_source).fetchRedemptionPrice() returns (uint256 redemptionPrice, bool oracleFailure) {
            if (_isInvalidPrice(redemptionPrice) || oracleFailure) return read;
            read.redemptionPrice = redemptionPrice;
        } catch {
            return read;
        }

        try IPriceFeed(_source).fetchUrgentRedemptionPrice() returns (uint256 urgentPrice, bool oracleFailure) {
            if (_isInvalidPrice(urgentPrice) || oracleFailure) return read;
            read.urgentRedemptionPrice = urgentPrice;
        } catch {
            return read;
        }

        uint8 jpyProvenance = _normalRedemptionJpyStatus(_source);
        read.redemptionPriceCacheable = jpyProvenance == JPY_PROVENANCE_FRESH;
        read.healthy = true;
    }

    /// @dev Validate the source-bound provider and classify the normal-redemption age gate.
    ///      Fixed-size return buffers keep malformed runtime provenance and oversized returndata
    ///      local to normal redemption without copying attacker-controlled return lengths.
    function _normalRedemptionJpyStatus(address _source) private view returns (uint8) {
        (bool sourceOk, uint256 encodedProvider) =
            _staticcallWord(_source, IJpyUsdRateProviderSource.jpyUsdRateProvider.selector);
        if (!sourceOk) return JPY_PROVENANCE_INVALID;
        if (encodedProvider > type(uint160).max) return JPY_PROVENANCE_INVALID;
        address provider = address(uint160(encodedProvider));
        if (provider.code.length == 0) return JPY_PROVENANCE_INVALID;

        (bool providerOk, uint256 updatedAt) =
            _staticcallWord(provider, IJpyUsdRateProvider.lastGoodJpyUpdatedAt.selector);
        if (!providerOk) return JPY_PROVENANCE_INVALID;
        if (updatedAt == 0 || updatedAt > block.timestamp) return JPY_PROVENANCE_INVALID;
        return block.timestamp - updatedAt >= MAX_NORMAL_REDEMPTION_JPY_AGE ? JPY_PROVENANCE_AGED : JPY_PROVENANCE_FRESH;
    }

    function _staticcallWord(address _target, bytes4 _selector) private view returns (bool success, uint256 result) {
        bytes memory callData = abi.encodeWithSelector(_selector);
        uint256 stipend = JPY_PROVENANCE_GAS_STIPEND;
        assembly {
            let output := mload(0x40)
            mstore(output, 0)
            success := staticcall(stipend, _target, add(callData, 0x20), mload(callData), output, 0x20)
            success := and(success, eq(returndatasize(), 0x20))
            if success { result := mload(output) }
        }
    }

    function _cacheConfirmedSourcePrices(address _source, uint256 _price, uint256 _redemptionPrice) private {
        uint8 jpyProvenance = _normalRedemptionJpyStatus(_source);
        if (jpyProvenance == JPY_PROVENANCE_INVALID) revert InvalidSource();

        _lastGoodPrice = _price;
        if (jpyProvenance == JPY_PROVENANCE_FRESH) _lastGoodRedemptionPrice = _redemptionPrice;
    }

    function _requireWithinSwitchDeviation(uint256 _oldPrice, uint256 _newPrice) internal pure {
        uint256 delta = _newPrice > _oldPrice ? _newPrice - _oldPrice : _oldPrice - _newPrice;
        uint256 maxDelta = _oldPrice * MAX_SOURCE_SWITCH_DEVIATION_BPS / BPS_DENOMINATOR;

        if (delta > maxDelta) {
            revert SourcePriceDeviationTooLarge(_oldPrice, _newPrice, MAX_SOURCE_SWITCH_DEVIATION_BPS);
        }
    }

    function _isPriceFeedProxy(address _candidate) private view returns (bool) {
        (bool success, bytes memory result) =
            _candidate.staticcall(abi.encodeWithSelector(IPriceFeedProxy.source.selector));
        return success && result.length == 32;
    }

    /// @inheritdoc IPriceFeedProxy
    function cancelSourceProposal() external onlyOwner {
        if (proposedSource == address(0)) revert NoProposalPending();

        address cancelled = proposedSource;
        proposedSource = address(0);
        sourceProposedAt = 0;

        emit SourceProposalCancelled(cancelled);
    }

    // =========================================================
    //  Ownership — overrides
    // =========================================================

    /// @notice Disable ownership renounce to preserve the source-swap recovery path.
    /// @dev Pending source proposals and pending ownership transfers remain unchanged;
    ///      cancel them explicitly with cancelSourceProposal() / transferOwnership(0).
    function renounceOwnership() public view override onlyOwner {
        revert RenounceOwnershipDisabled();
    }
}
"
    },
    "src/RedemptionHelper.sol": {
      "content": "// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.24;

import {IERC20} from "openzeppelin-contracts/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "openzeppelin-contracts/contracts/token/ERC20/utils/SafeERC20.sol";
import {Math} from "openzeppelin-contracts/contracts/utils/math/Math.sol";

import {_100pct, DECIMAL_PRECISION} from "./Dependencies/Constants.sol";
import {IAddressesRegistry} from "./Interfaces/IAddressesRegistry.sol";
import {IJpydfToken} from "./Interfaces/IJpydfToken.sol";
import {ICollateralRegistry} from "./Interfaces/ICollateralRegistry.sol";
import {IRedemptionHelper} from "./Interfaces/IRedemptionHelper.sol";
import {ISortedTroves} from "./Interfaces/ISortedTroves.sol";
import {ITroveManager} from "./Interfaces/ITroveManager.sol";
import {LatestTroveData} from "./Types/LatestTroveData.sol";

contract RedemptionHelper is IRedemptionHelper {
    using SafeERC20 for IERC20;

    struct RedemptionContext {
        IERC20 collToken;
        uint256 collBalanceBefore;
    }

    uint256 public immutable numBranches;
    ICollateralRegistry public immutable collateralRegistry;
    IJpydfToken public immutable jpydfToken;
    IAddressesRegistry[] public addresses; // only used off-chain, so we don't care about storage cost

    constructor(ICollateralRegistry _collateralRegistry, IAddressesRegistry[] memory _addresses) {
        require(_addresses.length == _collateralRegistry.totalCollaterals(), "Wrong number of registries");
        numBranches = _addresses.length;
        collateralRegistry = _collateralRegistry;
        jpydfToken = _collateralRegistry.jpydfToken();

        for (uint256 i = 0; i < _addresses.length; ++i) {
            require(_collateralRegistry.getTroveManager(i) == _addresses[i].troveManager(), "TroveManager mismatch");
            addresses.push(_addresses[i]);
        }
    }

    // Meant to be called off-chain
    // Not a view because price fetching has side-effects
    function simulateRedemption(uint256 _jpydf, uint256 _maxIterationsPerCollateral)
        public
        returns (SimulationContext[] memory branch, uint256 totalProportions)
    {
        branch = new SimulationContext[](numBranches);
        bool[] memory redemptionPriceAvailable = new bool[](numBranches);
        uint256 availableProportions;

        // First priority: proportional to unbacked debt
        for (uint256 i = 0; i < numBranches; ++i) {
            branch[i].troveManager = address(addresses[i].troveManager());
            branch[i].sortedTroves = address(addresses[i].sortedTroves());
            (branch[i].proportion, branch[i].price, branch[i].redeemable) =
                ITroveManager(branch[i].troveManager).getUnbackedPortionPriceAndRedeemability();
            if (branch[i].redeemable) {
                (, bool redemptionFailure) = addresses[i].priceFeed().fetchRedemptionPrice();
                redemptionPriceAvailable[i] = !redemptionFailure;
                totalProportions += branch[i].proportion;
                if (!redemptionFailure) availableProportions += branch[i].proportion;
            }
        }

        // CS-JPYDF-013: truncate redemption if it would exceed total unbacked debt
        if (0 < totalProportions && totalProportions < _jpydf) _jpydf = totalProportions;

        // Fallback: proportional to total debt
        if (totalProportions == 0) {
            availableProportions = 0;
            for (uint256 i = 0; i < numBranches; ++i) {
                branch[i].proportion = ITroveManager(branch[i].troveManager).getEntireBranchDebt();
                if (branch[i].redeemable) {
                    totalProportions += branch[i].proportion;
                    if (redemptionPriceAvailable[i]) availableProportions += branch[i].proportion;
                }
            }
        }

        for (uint256 i = 0; i < numBranches; ++i) {
            if (branch[i].redeemable && !redemptionPriceAvailable[i]) branch[i].redeemable = false;
        }

        if (totalProportions == 0 || availableProportions == 0) return (branch, 0);

        for (uint256 i = 0; i < numBranches; ++i) {
            if (!branch[i].redeemable) continue;

            branch[i].attemptedJpydf = _jpydf * branch[i].proportion / totalProportions;
            if (branch[i].attemptedJpydf == 0) continue;

            uint256 lastZombieTroveId = ITroveManager(branch[i].troveManager).lastZombieTroveId();
            uint256 lastTroveId = ISortedTroves(branch[i].sortedTroves).getLast();

            (uint256 troveId, uint256 nextTroveId) = lastZombieTroveId != 0
                ? (lastZombieTroveId, lastTroveId)
                : (lastTroveId, ISortedTroves(branch[i].sortedTroves).getPrev(lastTroveId));

            for (
                branch[i].iterations = 0;
                branch[i].iterations < _maxIterationsPerCollateral || _maxIterationsPerCollateral == 0;
                ++branch[i].iterations
            ) {
                if (branch[i].redeemedJpydf == branch[i].attemptedJpydf || troveId == 0) break;

                LatestTroveData memory trove = ITroveManager(branch[i].troveManager).getLatestTroveData(troveId);
                if (trove.entireColl * branch[i].price / trove.entireDebt >= _100pct) {
                    branch[i].redeemedJpydf +=
                        Math.min(branch[i].attemptedJpydf - branch[i].redeemedJpydf, trove.entireDebt);
                }

                troveId = nextTroveId;
                nextTroveId = ISortedTroves(branch[i].sortedTroves).getPrev(nextTroveId);
            }
        }
    }

    // Meant to be called off-chain
    // Not a view because price fetching has side-effects
    function truncateRedemption(uint256 _jpydf, uint256 _maxIterationsPerCollateral)
        external
        returns (uint256 truncatedJpydf, uint256 feePct, Redeemed[] memory redeemed)
    {
        (SimulationContext[] memory branch, uint256 totalProportions) =
            simulateRedemption(_jpydf, _maxIterationsPerCollateral);

        if (totalProportions == 0) return (0, 0, redeemed);

        truncatedJpydf = _jpydf;
        for (uint256 i = 0; i < numBranches; ++i) {
            if (branch[i].redeemable && branch[i].proportion > 0) {
                // Extrapolate how much the entire redeemed JPYDF would
                // have been if this branch was redeemed proportionally.
                uint256 extrapolatedJpydf = branch[i].redeemedJpydf * totalProportions / branch[i].proportion;

                // Normally this is no different from `_jpydf`, but can be less if the redemption on this branch
                // terminated due to hitting the iteration limit. We're looking for the smallest extrapolated value,
                // since that bounds the proportional request amount within the given
                // iteration limit. Any attempt to redeem more than this would result in a partial redemption, thus
                // paying a higher redemption fee than necessary — since the fee is based on the attempted amount.
                if (extrapolatedJpydf < truncatedJpydf) truncatedJpydf = extrapolatedJpydf;
            }
        }

        feePct = collateralRegistry.getRedemptionRateForRedeemedAmount(truncatedJpydf);
        redeemed = new Redeemed[](numBranches);

        for (uint256 i = 0; i < numBranches; ++i) {
            if (branch[i].redeemable && branch[i].proportion > 0) {
                (uint256 redemptionPrice, bool redemptionFailure) = addresses[i].priceFeed().fetchRedemptionPrice();
                if (redemptionFailure) return (0, 0, new Redeemed[](numBranches));
                redeemed[i].jpydf = truncatedJpydf * branch[i].proportion / totalProportions;
                redeemed[i].coll = redeemed[i].jpydf * (DECIMAL_PRECISION - feePct) / redemptionPrice;
            }
        }
    }

    function redeemCollateral(
        uint256 _jpydf,
        uint256 _maxIterationsPerCollateral,
        uint256 _maxFeePct,
        uint256[] memory _minCollRedeemed
    ) external {
        require(_jpydf > 0, "Redeemed amount must be non-zero");
        require(_minCollRedeemed.length == numBranches, "Wrong _minCollRedeemed length");

        RedemptionContext[] memory branch = new RedemptionContext[](numBranches);

        for (uint256 i = 0; i < numBranches; ++i) {
            branch[i].collToken = collateralRegistry.getToken(i);
            branch[i].collBalanceBefore = branch[i].collToken.balanceOf(address(this));
        }

        uint256 jpydfBalanceBefore = jpydfToken.balanceOf(address(this));

        IERC20(address(jpydfToken)).safeTransferFrom(msg.sender, address(this), _jpydf);
        collateralRegistry.redeemCollateral(_jpydf, _maxIterationsPerCollateral, _maxFeePct);

        for (uint256 i = 0; i < numBranches; ++i) {
            uint256 collRedeemed = branch[i].collToken.balanceOf(address(this)) - branch[i].collBalanceBefore;
            require(collRedeemed >= _minCollRedeemed[i], "Insufficient collateral redeemed");
            if (collRedeemed > 0) branch[i].collToken.safeTransfer(msg.sender, collRedeemed);
        }

        uint256 jpydfRemaining = jpydfToken.balanceOf(address(this)) - jpydfBalanceBefore;
        if (jpydfRemaining > 0) IERC20(address(jpydfToken)).safeTransfer(msg.sender, jpydfRemaining);
    }
}
"
    },
    "src/SortedTroves.sol": {
      "content": "// SPDX-License-Identifier: MIT

pragma solidity 0.8.24;

import "./Interfaces/ISortedTroves.sol";
import "./Interfaces/IAddressesRegistry.sol";
import "./Interfaces/ITroveManager.sol";

// ID of head & tail of the list. Callers should stop iterating with `getNext()` / `getPrev()`
// when encountering this node ID.
uint256 constant ROOT_NODE_ID = 0;

/*
* A sorted doubly linked list with nodes sorted in descending order.
*
* Nodes map to active Troves in the system - the ID property is the address of a Trove owner.
* Nodes are ordered according to the borrower's chosen annual interest rate.
*
* The list optionally accepts insert position hints.
*
* The annual interest rate is stored on the Trove struct in TroveManager, not directly on the Node.
*
* A node need only be re-inserted when the borrower adjusts their interest rate. Interest rate order is preserved
* under all other system operations.
*
* The list is a modification of the following audited SortedDoublyLinkedList:
* https://github.com/livepeer/protocol/blob/master/contracts/libraries/SortedDoublyLL.sol
*
* Changes made in the JPYDF implementation:
*
* - Keys have been removed from nodes
*
* - Ordering checks for insertion are performed by comparing an interest rate argument to the Trove's current interest rate.
*
* - Public functions with parameters have been made internal to save gas, and given an external wrapper function for external access
*/
contract SortedTroves is ISortedTroves {
    string public constant NAME = "SortedTroves";

    // Constants used for documentation purposes
    uint256 constant UNINITIALIZED_ID = 0;
    uint256 constant BAD_HINT = 0;

    event TroveManagerAddressChanged(address _troveManagerAddress);
    event BorrowerOperationsAddressChanged(address _borrowerOperationsAddress);

    address public immutable borrowerOperationsAddress;
    ITroveManager public immutable troveManager;

    // Information for a node in the list
    struct Node {
        uint256 nextId; // Id of next node (smaller interest rate) in the list
        uint256 prevId; // Id of previous node (larger interest rate) in the list
        BatchId batchId; // Id of this node's batch manager, or zero in case of non-batched nodes
        bool exists;
    }

    struct Batch {
        uint256 head;
        uint256 tail;
    }

    struct Position {
        uint256 prevId;
        uint256 nextId;
    }

    // Current size of the list
    uint256 public size;

    // Stores the forward and reverse links of each node in the list.
    // nodes[ROOT_NODE_ID] holds the head and tail of the list. This avoids the need for special
    // handling when inserting into or removing from a terminal position (head or tail), inserting
    // into an empty list or removing the element of a singleton list.
    mapping(uint256 => Node) public nodes;

    // Lookup batches by the address of their manager
    mapping(BatchId => Batch) public batches;

    constructor(IAddressesRegistry _addressesRegistry) {
        // Technically, this is not needed as long as ROOT_NODE_ID is 0, but it doesn't hurt
        nodes[ROOT_NODE_ID].nextId = ROOT_NODE_ID;
        nodes[ROOT_NODE_ID].prevId = ROOT_NODE_ID;

        troveManager = ITroveManager(_addressesRegistry.troveManager());
        borrowerOperationsAddress = address(_addressesRegistry.borrowerOperations());

        emit TroveManagerAddressChanged(address(troveManager));
        emit BorrowerOperationsAddressChanged(borrowerOperationsAddress);
    }

    // Insert an entire list slice (such as a batch of Troves sharing the same interest rate)
    // between adjacent nodes `_prevId` and `_nextId`.
    // Can be used to insert a single node by passing its ID as both `_sliceHead` and `_sliceTail`.
    function _insertSliceIntoVerifiedPosition(uint256 _sliceHead, uint256 _sliceTail, uint256 _prevId, uint256 _nextId)
        internal
    {
        nodes[_prevId].nextId = _sliceHead;
        nodes[_sliceHead].prevId = _prevId;
        nodes[_sliceTail].nextId = _nextId;
        nodes[_nextId].prevId = _sliceTail;
    }

    function _insertSlice(
        ITroveManager _troveManager,
        uint256 _sliceHead,
        uint256 _sliceTail,
        uint256 _annualInterestRate,
        uint256 _prevId,
        uint256 _nextId
    ) internal {
        if (!_validInsertPosition(_troveManager, _annualInterestRate, _prevId, _nextId)) {
            // Sender's hint was not a valid insert position
            // Use sender's hint to find a valid insert position
            (_prevId, _nextId) = _findInsertPosition(_troveManager, _annualInterestRate, _prevId, _nextId);
        }

        _insertSliceIntoVerifiedPosition(_sliceHead, _sliceTail, _prevId, _nextId);
    }

    /*
     * @dev Add a Trove to the list
     * @param _id Trove's id
     * @param _annualInterestRate Trove's annual interest rate
     * @param _prevId Id of previous Trove for the insert position
     * @param _nextId Id of next Trove for the insert position
     */
    function insert(uint256 _id, uint256 _annualInterestRate, uint256 _prevId, uint256 _nextId) external override {
        _requireCallerIsBorrowerOperations();
        require(!contains(_id), "SortedTroves: List already contains the node");
        require(_id != ROOT_NODE_ID, "SortedTroves: _id cannot be the root node's ID");

        _insertSlice(troveManager, _id, _id, _annualInterestRate, _prevId, _nextId);
        nodes[_id].exists = true;
        ++size;
    }

    // Remove the entire slice between `_sliceHead` and `_sliceTail` from the list while keeping
    // the removed nodes connected to each other, such that they can be reinserted into a different
    // position with `_insertSlice()`.
    // Can be used to remove a single node by passing its ID as both `_sliceHead` and `_sliceTail`.
    function _removeSlice(uint256 _sliceHead, uint256 _sliceTail) internal {
        nodes[nodes[_sliceHead].prevId].nextId = nodes[_sliceTail].nextId;
        nodes[nodes[_sliceTail].nextId].prevId = nodes[_sliceHead].prevId;
    }

    /*
     * @dev Remove a non-batched Trove from the list
     * @param _id Trove's id
     */
    function remove(uint256 _id) external override {
        _requireCallerIsBOorTM();
        require(contains(_id), "SortedTroves: List does not contain the id");
        require(!isBatchedNode(_id), "SortedTroves: Must use removeFromBatch() to remove batched node");

        _removeSlice(_id, _id);
        delete nodes[_id];
        --size;
    }

    function _reInsertSlice(
        ITroveManager _troveManager,
        uint256 _sliceHead,
        uint256 _sliceTail,
        uint256 _annualInterestRate,
        uint256 _prevId,
        uint256 _nextId
    ) internal {
        if (!_validInsertPosition(_troveManager, _annualInterestRate, _prevId, _nextId)) {
            // Sender's hint was not a valid insert position
            // Use sender's hint to find a valid insert position
            (_prevId, _nextId) = _findInsertPosition(_troveManager, _annualInterestRate, _prevId, _nextId);
        }

        // Check that the new insert position isn't the same as the existing one
        if (_nextId != _sliceHead && _prevId != _sliceTail) {
            _removeSlice(_sliceHead, _sliceTail);
            _insertSliceIntoVerifiedPosition(_sliceHead, _sliceTail, _prevId, _nextId);
        }
    }

    /*
     * @dev Re-insert a non-batched Trove at a new position, based on its new annual interest rate
     * @param _id Trove's id
     * @param _newAnnualInterestRate Trove's new annual interest rate
     * @param _prevId Id of previous Trove for the new insert position
     * @param _nextId Id of next Trove for the new insert position
     */
    function reInsert(uint256 _id, uint256 _newAnnualInterestRate, uint256 _prevId, uint256 _nextId)
        external
        override
    {
        _requireCallerIsBorrowerOperations();
        require(contains(_id), "SortedTroves: List does not contain the id");
        require(!isBatchedNode(_id), "SortedTroves: Must not reInsert() batched node");

        _reInsertSlice(troveManager, _id, _id, _newAnnualInterestRate, _prevId, _nextId);
    }

    /*
     * @dev Add a Trove to a Batch within the list
     * @param _troveId Trove's id
     * @param _batchId Batch's id
     * @param _annualInterestRate Batch's annual interest rate
     * @param _prevId Id of previous Trove for the insert position, in case the Batch is empty
     * @param _nextId Id of next Trove for the insert position, in case the Batch is empty
     */
    function insertIntoBatch(
        uint256 _troveId,
        BatchId _batchId,
        uint256 _annualInterestRate,
        uint256 _prevId,
        uint256 _nextId
    ) external override {
        _requireCallerIsBorrowerOperations();
        require(!contains(_troveId), "SortedTroves: List already contains the node");
        require(_troveId != ROOT_NODE_ID, "SortedTroves: _troveId cannot be the root node's ID");
        require(_batchId.isNotZero(), "SortedTroves: _batchId cannot be zero");

        uint256 batchTail = batches[_batchId].tail;

        if (batchTail == UNINITIALIZED_ID) {
            _insertSlice(troveManager, _troveId, _troveId, _annualInterestRate, _prevId, _nextId);
            // Initialize the batch by setting both its head & tail to its singular node
            batches[_batchId].head = _troveId;
            // (Tail will be set outside the "if")
        } else {
            _insertSliceIntoVerifiedPosition(_troveId, _troveId, batchTail, nodes[batchTail].nextId);
        }

        batches[_batchId].tail = _troveId;
        nodes[_troveId].batchId = _batchId;
        nodes[_troveId].exists = true;
        ++size;
    }

    /*
     * @dev Remove a batched Trove from the list
     * @param _id Trove's id
     */
    function removeFromBatch(uint256 _id) external override {
        _requireCallerIsBOorTM();
        BatchId batchId = nodes[_id].batchId;
        // batchId.isNotZero() implies that the list contains the node
        require(batchId.isNotZero(), "SortedTroves: Must use remove() to remove non-batched node");

        Batch memory batch = batches[batchId];

        if (batch.head == _id && batch.tail == _id) {
            // Remove singleton batch
            delete batches[batchId];
        } else if (batch.head == _id) {
            batches[batchId].head = nodes[_id].nextId;
        } else if (batch.tail == _id) {
            batches[batchId].tail = nodes[_id].prevId;
        }

        _removeSlice(_id, _id);
        delete nodes[_id];
        --size;
    }

    /*
     * @dev Re-insert an entire Batch of Troves at a new position, based on their new annual interest rate
     * @param _id Batch's id
     * @param _newAnnualInterestRate Trove's new annual interest rate
     * @param _prevId Id of previous Trove for the new insert position
     * @param _nextId Id of next Trove for the new insert position
     */
    function reInsertBatch(BatchId _id, uint256 _newAnnualInterestRate, uint256 _prevId, uint256 _nextId)
        external
        override
    {
        Batch memory batch = batches[_id];

        _requireCallerIsBorrowerOperations();
        require(batch.head != UNINITIALIZED_ID, "SortedTroves: List does not contain the batch");

        _reInsertSlice(troveManager, batch.head, batch.tail, _newAnnualInterestRate, _prevId, _nextId);
    }

    /*
     * @dev Checks if the list contains a node
     */
    function contains(uint256 _id) public view override returns (bool) {
        return nodes[_id].exists;
    }

    /*
     * @dev Checks whether the node is part of a batch
     */
    function isBatchedNode(uint256 _id) public view override returns (bool) {
        return nodes[_id].batchId.isNotZero();
    }

    function isEmptyBatch(BatchId _id) external view override returns (bool) {
        return batches[_id].head == UNINITIALIZED_ID;
    }

    /*
     * @dev Checks if the list is empty
     */
    function isEmpty() external view override returns (bool) {
        return size == 0;
    }

    /*
     * @dev Returns the current size of the list
     */
    function getSize() external view override returns (uint256) {
        return size;
    }

    /*
     * @dev Returns the first node in the list (node with the largest annual interest rate)
     */
    function getFirst() external view override returns (uint256) {
        return nodes[ROOT_NODE_ID].nextId;
    }

    /*
     * @dev Returns the last node in the list (node with the smallest annual interest rate)
     */
    function getLast() external view override returns (uint256) {
        return nodes[ROOT_NODE_ID].prevId;
    }

    /*
     * @dev Returns the next node (with a smaller interest rate) in the list for a given node
     * @param _id Node's id
     */
    function getNext(uint256 _id) external view override returns (uint256) {
        return nodes[_id].nextId;
    }

    /*
     * @dev Returns the previous node (with a larger interest rate) in the list for a given node
     * @param _id Node's id
     */
    function getPrev(uint256 _id) external view override returns (uint256) {
        return nodes[_id].prevId;
    }

    /*
     * @dev Check if a pair of nodes is a valid insertion point for a new node with the given interest rate
     * @param _annualInterestRate Node's annual interest rate
     * @param _prevId Id of previous node for the insert position
     * @param _nextId Id of next node for the insert position
     */
    function validInsertPosition(uint256 _annualInterestRate, uint256 _prevId, uint256 _nextId)
        external
        view
        override
        returns (bool)
    {
        return _validInsertPosition(troveManager, _annualInterestRate, _prevId, _nextId);
    }

    function _validInsertPosition(
        ITroveManager _troveManager,
        uint256 _annualInterestRate,
        uint256 _prevId,
        uint256 _nextId
    ) internal view returns (bool) {
        BatchId prevBatchId = nodes[_prevId].batchId;

        // `(_prevId, _nextId)` is a valid insert position if:
        return
        // they are adjacent nodes
        (
            nodes[_prevId].nextId == _nextId && nodes[_nextId].prevId == _prevId
            // they aren't part of the same batch
            && (prevBatchId != nodes[_nextId].batchId || prevBatchId.isZero())
            // `_annualInterestRate` falls between the two nodes' interest rates
            && (_prevId == ROOT_NODE_ID || _troveManager.getTroveAnnualInterestRate(_prevId) >= _annualInterestRate)
                && (_nextId == ROOT_NODE_ID || _annualInterestRate > _troveManager.getTroveAnnualInterestRate(_nextId))
        );
    }

    function _skipToBatchTail(uint256 _id) internal view returns (uint256) {
        BatchId batchId = nodes[_id].batchId;
        return batchId.isNotZero() ? batches[batchId].tail : _id;
    }

    function _skipToBatchHead(uint256 _id) internal view returns (uint256) {
        BatchId batchId = nodes[_id].batchId;
        return batchId.isNotZero() ? batches[batchId].head : _id;
    }

    function _descendOne(ITroveManager _troveManager, uint256 _annualInterestRate, Position memory _pos)
        internal
        view
        returns (bool found)
    {
        if (_pos.nextId == ROOT_NODE_ID || _annualInterestRate > _troveManager.getTroveAnnualInterestRate(_pos.nextId))
        {
            found = true;
        } else {
            _pos.prevId = _skipToBatchTail(_pos.nextId);
            _pos.nextId = nodes[_pos.prevId].nextId;
        }
    }

    function _ascendOne(ITroveManager _troveManager, uint256 _annualInterestRate, Position memory _pos)
        internal
        view
        returns (bool found)
    {
        if (_pos.prevId == ROOT_NODE_ID || _troveManager.getTroveAnnualInterestRate(_pos.prevId) >= _annualInterestRate)
        {
            found = true;
        } else {
            _pos.nextId = _skipToBatchHead(_pos.prevId);
            _pos.prevId = nodes[_pos.nextId].prevId;
        }
    }

    /*
     * @dev Descend the list (larger interest rates to smaller interest rates) to find a valid insert position
     * @param _troveManager TroveManager contract, passed in as param to save SLOAD’s
     * @param _annualInterestRate Node's annual interest rate
     * @param _startId Id of node to start descending the list from
     */
    function _descendList(ITroveManager _troveManager, uint256 _annualInterestRate, uint256 _startId)
        internal
        view
        returns (uint256, uint256)
    {
        Position memory pos = Position(_startId, nodes[_startId].nextId);

        while (!_descendOne(_troveManager, _annualInterestRate, pos)) {}
        return (pos.prevId, pos.nextId);
    }

    /*
     * @dev Ascend the list (smaller interest rates to larger interest rates) to find a valid insert position
     * @param _troveManager TroveManager contract, passed in as param to save SLOAD’s
     * @param _annualInterestRate Node's annual interest rate
     * @param _startId Id of node to start ascending the list from
     */
    function _ascendList(ITroveManager _troveManager, uint256 _annualInterestRate, uint256 _startId)
        internal
        view
        returns (uint256, uint256)
    {
        Position memory pos = Position(nodes[_startId].prevId, _startId);

        while (!_ascendOne(_troveManager, _annualInterestRate, pos)) {}
        return (pos.prevId, pos.nextId);
    }

    function _descendAndAscendList(
        ITroveManager _troveManager,
        uint256 _annualInterestRate,
        uint256 _descentStartId,
        uint256 _ascentStartId
    ) internal view returns (uint256 prevId, uint256 nextId) {
        Position memory descentPos = Position(_descentStartId, nodes[_descentStartId].nextId);
        Position memory ascentPos = Position(nodes[_ascentStartId].prevId, _ascentStartId);

        for (;;) {
            if (_descendOne(_troveManager, _annualInterestRate, descentPos)) {
                return (descentPos.prevId, descentPos.nextId);
            }

            if (_ascendOne(_troveManager, _annualInterestRate, ascentPos)) {
                return (ascentPos.prevId, ascentPos.nextId);
            }
        }

        assert(false); // Should not reach
    }

    /*
     * @dev Find the insert position for a new node with the given interest rate
     * @param _annualInterestRate Node's annual interest rate
     * @param _prevId Id of previous node for the insert position
     * @param _nextId Id of next node for the insert position
     */
    function findInsertPosition(uint256 _annualInterestRate, uint256 _prevId, uint256 _nextId)
        external
        view
        override
        returns (uint256, uint256)
    {
        return _findInsertPosition(troveManager, _annualInterestRate, _prevId, _nextId);
    }

    // This function is optimized under the assumption that only one of the original neighbours has been (re)moved.
    // In other words, we assume that the correct position can be found close to one of the two.
    // Nevertheless, the function will always find the correct position, regardless of hints or interference.
    function _findInsertPosition(
        ITroveManager _troveManager,
        uint256 _annualInterestRate,
        uint256 _prevId,
        uint256 _nextId
    ) internal view returns (uint256, uint256) {
        if (_prevId == ROOT_NODE_ID) {
            // The original correct position was found before the head of the list.
            // Assuming minimal interference, the new correct position is still close to the head.
            return _descendList(_troveManager, _annualInterestRate, ROOT_NODE_ID);
        } else {
            if (!contains(_prevId) || _troveManager.getTroveAnnualInterestRate(_prevId) < _annualInterestRate) {
                // `prevId` does not exist anymore or now has a smaller interest rate than the given interest rate
                _prevId = BAD_HINT;
            }
        }

        if (_nextId == ROOT_NODE_ID) {
            // The original correct position was found after the tail of the list.
            // Assuming minimal interference, the new correct position is still close to the tail.
            return _ascendList(_troveManager, _annualInterestRate, ROOT_NODE_ID);
        } else {
            if (!contains(_nextId) || _annualInterestRate <= _troveManager.getTroveAnnualInterestRate(_nextId)) {
                // `nextId` does not exist anymore or now has a larger interest rate than the given interest rate
                _nextId = BAD_HINT;
            }
        }

        if (_prevId == BAD_HINT && _nextId == BAD_HINT) {
            // Both original neighbours have been moved or removed.
            // We default to descending the list, starting from the head.
            return _descendList(_troveManager, _annualInterestRate, ROOT_NODE_ID);
        } else if (_prevId == BAD_HINT) {
            // No `prevId` for hint - ascend list starting from `nextId`
            return _ascendList(_troveManager, _annualInterestRate, _skipToBatchHead(_nextId));
        } else if (_nextId == BAD_HINT) {
            // No `nextId` for hint - descend list starting from `prevId`
            return _descendList(_troveManager, _annualInterestRate, _skipToBatchTail(_prevId));
        } else {
            // The correct position is still somewhere between the 2 hints, so it's not obvious
            // which of the 2 has been moved (assuming only one of them has been).
            // We simultaneously descend & ascend in the hope that one of them is very close.
            return _descendAndAscendList(
                _troveManager, _annualInterestRate, _skipToBatchTail(_prevId), _skipToBatchHead(_nextId)
            );
        }
    }

    // --- 'require' functions ---

    function _requireCallerIsBOorTM() internal view {
        require(
            msg.sender == borrowerOperationsAddress || msg.sender == address(troveManager),
            "SortedTroves: Caller is not BorrowerOperations nor TroveManager"
        );
    }

    function _requireCallerIsBorrowerOperations() internal view {
        require(msg.sender == borrowerOperationsAddress, "SortedTroves: Caller is not BorrowerOperations");
    }
}
"
    },
    "src/Strategies/AaveV3Strategy.sol": {
      "content": "// SPDX-License-Identifier: BUSL-1.1

pragma solidity 0.8.24;

import "openzeppelin-contracts/contracts/utils/math/Math.sol";

import "./BaseStrategy.sol";

/**
 * @title IAaveV3Pool - Aave V3 Pool Interface (minimal)
 */
interface IAaveV3Pool {
    function supply(address asset, uint256 amount, address onBehalfOf, uint16 referralCode) external;

    function withdraw(address asset, uint256 amount, address to) external returns (uint256);

    /// @notice Returns the normalized income of the reserve, in RAY (1e27).
    ///         underlying = scaled * income / RAY.
    function getReserveNormalizedIncome(address asset) external view returns (uint256);
}

/**
 * @title IAaveRewardsController - Aave V3 rewards interface (minimal)
 */
interface IAaveRewardsController {
    function claimRewards(address[] calldata assets, uint256 amount, address to, address reward)
        external
        returns (uint256);
}

/**
 * @title IAToken - Aave aToken Interface (minimal)
 */
interface IAToken {
    function balanceOf(address account) external view returns (uint256);

    /// @notice Scaled balance (RAY-precision share of the reserve). Unaffected
    ///         by interest accrual; changes only on supply / withdraw / transfer.
    function scaledBalanceOf(address account) external view returns (uint256);

    function UNDERLYING_ASSET_ADDRESS() external view returns (address);
}

/**
 * @title AaveV3Strategy - Aave V3 Lending Strategy (push model, Upgradeable)
 * @notice Synchronous lending strategy backed by Aave V3.
 *         Withdrawals are immediate up to the reserve's currently liquid
 *         underlying; `_doWithdraw` pulls underlying into this contract. The
 *         BaseStrategy then routes principal returns through
 *         `receiveFromStrategy` and yield-only pushes through a direct transfer
 *         to the Vault buffer.
 * @dev    The Strategy tracks the scaled-balance share that **this contract**
 *         accumulated via its own `supply` / `withdraw` calls. The Aave V3
 *         `Pool.supply(asset, X, onBehalfOf = AaveV3Strategy, 0)` entry point
 *         is permissionless, so anyone can credit additional aToken to this
 *         contract. To prevent such "donations" from inflating
 *         `realizedYield()` (which would let an adversary route arbitrary
 *         amounts into `treasury` via
 *         `sendProfitToVault` + `transferYieldToTreasury`),
 *         `_estimatedTotalUnderlying()` is computed from the locally tracked
 *         scaled balance rather than `aToken.balanceOf`.
 */
contract AaveV3Strategy is BaseStrategy {
    using SafeERC20 for IERC20;

    // =============================================================
    //                         STATE
    // =============================================================

    IAaveV3Pool public aavePool;
    IAToken public aToken;

    /// @notice Scaled balance (RAY-precision) that this contract minted
    ///         through its own `supply` calls minus what was burned through
    ///         its own `withdraw` calls. Donations made by third parties via
    ///         `supply(_, _, onBehalfOf=this, _)` do NOT affect this value,
    ///         so `_estimatedTotalUnderlying()` reflects only the Strategy's
    ///         own share of the reserve.
    uint256 internal _ownScaledBalance;

    /// @dev Storage gap for future upgrades of this derived contract.
    uint256[48] private __gapAaveV3;

    /// @dev Aave V3 normalized-income / scaled-balance precision.
    uint256 internal constant _RAY = 1e27;

    // =============================================================
    //                          EVENTS
    // =============================================================

    event OwnScaledBalanceUpdated(uint256 newScaledBalance);
    event AaveRewardsClaimed(
        address indexed rewardsController, address indexed reward, uint256 requested, uint256 claimed, uint256 settled
    );
    event AaveUnderlyingRewardsClaimed(
        address indexed rewardsController,
        address indexed reward,
        uint256 requested,
        uint256 claimed,
        uint256 sentToVault
    );

    // =============================================================
    //                        INITIALIZER
    // =============================================================

    error InvalidATokenUnderlying();
    error InvalidAaveRewardsController();
    error AaveSupplyZeroScaledBalance(uint256 amount);
    error AaveWithdrawZeroScaledBurn(uint256 actual);
    error AaveWithdrawZeroReported(uint256 actual);

    function initialize(
        address _vault,
        IERC20 _underlying,
        address _owner,
        address _upgrader,
        IAaveV3Pool _aavePool,
        IAToken _aToken
    ) external initializer {
        __BaseStrategy_init(_vault, _underlying, _owner, _upgrader);

        if (address(_aavePool) == address(0)) revert ZeroAddress();
        if (address(_aToken) == address(0)) revert ZeroAddress();
        if (address(_aavePool).code.length == 0) revert NotContract(address(_aavePool));
        if (address(_aToken).code.length == 0) revert NotContract(address(_aToken));
        if (_aToken.UNDERLYING_ASSET_ADDRESS() != address(_underlying)) {
            revert InvalidATokenUnderlying();
        }

        aavePool = _aavePool;
        aToken = _aToken;

        // Approve underlying token to Aave Pool (for supply).
        _underlying.forceApprove(address(_aavePool), type(uint256).max);
    }

    // =============================================================
    //                  BaseStrategy HOOKS
    // =============================================================

    /// @inheritdoc BaseStrategy
    /// @dev Tracks the scaled balance Aave mints for THIS specific `supply`
    ///      call by snapshotting before/after `scaledBalanceOf`. Concurrent
    ///      donations (separate transactions) inflate both snapshots equally,
    ///      so the delta still reflects only the amount attributable to this
    ///      call.
    function _doDeposit(uint256 _amount) internal override {
        uint256 scaledBalanceBeforeSupply = aToken.scaledBalanceOf(address(this));
        aavePool.supply(address(underlyingToken), _amount, address(this), 0);
        uint256 scaledBalanceAfterSupply = aToken.scaledBalanceOf(address(this));
        uint256 scaledBalanceMinted = scaledBalanceAfterSupply - scaledBalanceBeforeSupply;
        if (scaledBalanceMinted == 0) revert AaveSupplyZeroScaledBalance(_amount);

        _ownScaledBalance += scaledBalanceMinted;
        emit OwnScaledBalanceUpdated(_ownScaledBalance);
    }

    /// @inheritdoc BaseStrategy
    /// @dev Withdraws no more than the Strategy's Aave-accounted value and no
    ///      more than the reserve's currently liquid underlying. Aave V3 does
    ///      not partially fill ordinary withdraw requests; over-asking or
    ///      hitting an illiquid reserve reverts. Capping here gives the same
    ///      partial-withdraw semantics as ERC-4626 `maxWithdraw` without
    ///      treating utilization as a solvency loss.
    function _doWithdraw(uint256 _amount) internal override returns (uint256 actual) {
        uint256 withdrawAmount = _amount;

        uint256 accountingValue = _ownedAaveAccountingValue();
        if (accountingValue < withdrawAmount) withdrawAmount = accountingValue;

        uint256 liquidUnderlying = _aaveLiquidUnderlying();
        if (liquidUnderlying < withdrawAmount) withdrawAmount = liquidUnderlying;
        if (withdrawAmount == 0) return 0;

        actual = _withdrawFromAave(withdrawAmount);
    }

    /// @inheritdoc BaseStrategy
    /// @dev Computes underlying value from the locally tracked scaled balance,
    ///      capped at Aave's current `scaledBalanceOf` of this contract so
    ///      that an Aave-side scaled-balance shrink is reflected immediately.
    ///      This is an Aave accounting value, not a reserve-liquidity or
    ///      protocol-deficit oracle: Aave deficits that do not reduce scaled
    ///      balances / normalized income must be handled by monitoring and
    ///      `Vault.writeoffStrategyPrincipal`.
    function _estimatedTotalUnderlying() internal view override returns (uint256) {
        return _ownedAaveAccountingValue();
    }

    function _ownedAaveAccountingValue() internal view returns (uint256) {
        uint256 currentAaveScaledBalance = aToken.scaledBalanceOf(address(this));
        uint256 effectiveScaledBalance =
            _ownScaledBalance < currentAaveScaledBalance ? _ownScaledBalance : currentAaveScaledBalance;
        if (effectiveScaledBalance == 0) return 0;
        return _aaveAccountingValue(effectiveScaledBalance);
    }

    function _aaveAccountingValue(uint256 _scaledBalance) internal view returns (uint256) {
        uint256 normalizedReserveIncome = aavePool.getReserveNormalizedIncome(address(underlyingToken));
        return Math.mulDiv(_scaledBalance, normalizedReserveIncome, _RAY);
    }

    function _aaveLiquidUnderlying() internal view returns (uint256) {
        return underlyingToken.balanceOf(address(aToken));
    }

    function _withdrawFromAave(uint256 _amount) internal returns (uint256 actual) {
        uint256 underlyingBalanceBeforeWithdraw = underlyingToken.balanceOf(address(this));
        uint256 scaledBalanceBeforeWithdraw = aToken.scaledBalanceOf(address(this));
        uint256 reported = aavePool.withdraw(address(underlyingToken), _amount, address(this));
        uint256 scaledBalanceAfterWithdraw = aToken.scaledBalanceOf(address(this));
        uint256 underlyingBalanceAfterWithdraw = underlyingToken.balanceOf(address(this));

        uint256 actualBurnedScaledBalance = scaledBalanceBeforeWithdraw - scaledBalanceAfterWithdraw;
        actual = underlyingBalanceAfterWithdraw - underlyingBalanceBeforeWithdraw;
        if (actual != 0 && actualBurnedScaledBalance == 0) revert AaveWithdrawZeroScaledBurn(actual);

        _ownScaledBalance =
            actualBurnedScaledBalance > _ownScaledBalance ? 0 : _ownScaledBalance - actualBurnedScaledBalance;
        emit OwnScaledBalanceUpdated(_ownScaledBalance);

        if (reported == 0 && actual != 0) revert AaveWithdrawZeroReported(actual);
    }

    /// @inheritdoc BaseStrategy
    /// @dev aToken is the Aave position/accounting token, not a reward token.
    ///      It must leave the Strategy only through Aave withdraw paths.
    function _isSweepProtectedToken(address _token) internal view override returns (bool) {
        return super._isSweepProtectedToken(_token) || _token == address(aToken);
    }

    // =============================================================
    //                   REWARD CLAIM FUNCTIONS
    // =============================================================

    /**
     * @notice Claim Aave rewards earned by this Strategy's aToken position.
     * @dev The rewards asset list is fixed to this Strategy's aToken so the
     *      owner cannot accidentally claim rewards for an unrelated Aave
     *      position through this adapter. Ordinary reward tokens are swept to
     *      the Vault treasury; underlying rewards are treated as yield and sent
     *      to the Vault buffer without reducing principal.
     * @param _rewardsController Aave V3 rewards controller.
     * @param _amount Amount requested from Aave, or `type(uint256).max` for all
     *        currently claimable rewards.
     * @param _reward Reward token to claim.
     * @return claimed Amount reported by the rewards controller.
     * @return settled Amount actually received by treasury or Vault.
     */
    function claimAaveRewards(IAaveRewardsController _rewardsController, uint256 _amount, address _reward)
        external
        onlyOwner
        nonReentrantStrategy
        returns (uint256 claimed, uint256 settled)
    {
        if (address(_rewardsController) == address(0)) revert ZeroAddress();
        if (address(_rewardsController).code.length == 0) revert InvalidAaveRewardsController();
        if (_reward == address(0)) revert ZeroAddress();

        address underlyingAddress = address(underlyingToken);
        if (_reward != underlyingAddress && _isSweepProtectedToken(_reward)) revert CannotSweepProtectedToken();

        address[] memory assets = new address[](1);
        assets[0] = address(aToken);

        uint256 balanceBeforeClaim = IERC20(_reward).balanceOf(address(this));
        claimed = _rewardsController.claimRewards(assets, _amount, address(this), _reward);

        if (_reward == underlyingAddress) {
            uint256 balanceAfterClaim = IERC20(_reward).balanceOf(address(this));
            uint256 claimedUnderlying =
                balanceAfterClaim > balanceBeforeClaim ? balanceAfterClaim - balanceBeforeClaim : 0;
            settled = _sendUnderlyingToVault(claimedUnderlying);
            emit AaveUnderlyingRewardsClaimed(address(_rewardsController), _reward, _amount, claimed, settled);
        } else {
            settled = _sweepRewardToken(IERC20(_reward), type(uint256).max);
            emit AaveRewardsClaimed(address(_rewardsController), _reward, _amount, claimed, settled);
        }
    }

    // =============================================================
    //                   EMERGENCY FUNCTIONS
    // =============================================================

    /**
     * @notice Withdraw the currently liquid Aave position (including any
     *         liquid third-party donations) and immediately push all idle
     *         underlying back to the Vault. The Vault receipt is accounted as
     *         returned principal; if the remaining Aave-accounted position is
     *         later deemed unrecoverable, a Vault WRITEOFF_ROLE holder must call
     *         `Vault.writeoffStrategyPrincipal(...)` for that residual.
     * @dev    Owner only. Pushing through `receiveFromStrategy` keeps the
     *         Vault-side valuation cache in sync and avoids an observable
     *         window where funds sit idle in the Strategy but are excluded from
     *         `CollateralVault.backingRatio()`.
     */
    function emergencyWithdrawFromAave() external onlyOwner nonReentrantStrategy returns (uint256 sent) {
        uint256 aTokenBalance = aToken.balanceOf(address(this));
        uint256 liquidUnderlying = _aaveLiquidUnderlying();
        uint256 withdrawAmount = aTokenBalance < liquidUnderlying ? aTokenBalance : liquidUnderlying;
        if (withdrawAmount != 0) {
            _withdrawFromAave(withdrawAmount);
        }

        uint256 idleUnderlying = underlyingToken.balanceOf(address(this));
        if (idleUnderlying == 0) return 0;

        sent = _returnUnderlyingPrincipalToVault(idleUnderlying);
    }
}
"
