    "src/Strategies/BaseStrategy.sol": {
      "content": "// SPDX-License-Identifier: MIT

pragma solidity 0.8.24;

import "openzeppelin-contracts/contracts/token/ERC20/IERC20.sol";
import "openzeppelin-contracts/contracts/token/ERC20/utils/SafeERC20.sol";
import "openzeppelin-contracts/contracts/access/IAccessControl.sol";
import "openzeppelin-contracts-upgradeable/access/OwnableUpgradeable.sol";
import "openzeppelin-contracts-upgradeable/proxy/utils/Initializable.sol";
import "openzeppelin-contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";

import "../Interfaces/IStrategy.sol";
import "../Interfaces/ICollateralVault.sol";

interface IMerklDistributor {
    function claim(
        address[] calldata users,
        address[] calldata tokens,
        uint256[] calldata amounts,
        bytes32[][] calldata proofs
    ) external;
}

/**
 * @title BaseStrategy - Push-model Strategy base contract (Upgradeable)
 * @notice Implements the push model for all derived strategies.
 *
 *   - `deposit(declared, received)`: onlyVault. Underlying is transferred BEFORE this call.
 *                                  Runs `_doDeposit(received)` in an isolated self-call; on
 *                                  rejection, returns the exact receipt to the Vault or reverts.
 *   - `sendToVault(amount)`     : WITHDRAWER_ROLE on Vault.
 *                                  Withdraws from the upstream protocol via `_doWithdraw`,
 *                                  reduces `principal` (principal-first), pushes the result
 *                                  to the Vault via `receiveFromStrategy`.
 *   - `sendProfitToVault()`     : HARVESTER_ROLE on Vault.
 *                                  Caps the amount at `realizedYield()`, withdraws via
 *                                  `_doWithdraw`, leaves `principal` unchanged, pushes
 *                                  the result directly to the Vault buffer.
 *   - `writeoffPrincipal(amt)`  : onlyVault. Acknowledges a permanent loss so the Strategy
 *                                  can later be removed. Returns the clamped amount written off.
 *
 *   Derived contracts only implement three hooks:
 *     `_doDeposit(amount)`
 *     `_doWithdraw(amount) -> actual`
 *     `_estimatedTotalUnderlying() view -> uint256`
 */
abstract contract BaseStrategy is Initializable, IStrategy, OwnableUpgradeable, UUPSUpgradeable {
    using SafeERC20 for IERC20;

    // =============================================================
    //                          STATE
    // =============================================================

    /// @notice Vault address managing this Strategy
    address public vault;

    /// @notice Underlying token under management
    IERC20 public underlyingToken;

    /// @notice Principal currently tracked by this Strategy
    /// @dev    Increased on `deposit`, decreased on `sendToVault` and `writeoffPrincipal`.
    ///         `sendProfitToVault` does not change this.
    uint256 internal _principal;

    /// @notice Pending owner for two-step ownership transfer
    address private _pendingOwner;

    /// @notice Address authorized to upgrade this Strategy implementation.
    address public upgrader;

    /// @dev Local reentrancy guard for Strategy entry points that call external protocols or tokens.
    uint256 private _reentrancyStatus;

    /// @dev Storage gap for future upgrades.
    uint256[46] private __gap;

    // =============================================================
    //                          CONSTANTS
    // =============================================================

    /// @dev Legacy role retained only for archived async strategy request functions.
    bytes32 internal constant _ALLOCATOR_ROLE = keccak256("ALLOCATOR_ROLE");
    /// @dev Must match the operation-specific roles on CollateralVault.
    bytes32 internal constant _WITHDRAWER_ROLE = keccak256("WITHDRAWER_ROLE");
    bytes32 internal constant _HARVESTER_ROLE = keccak256("HARVESTER_ROLE");
    uint256 public constant MAX_MERKL_TOKENS_PER_CLAIM = 16;

    // =============================================================
    //                          EVENTS
    // =============================================================

    event Deposited(uint256 amount, uint256 newPrincipal);
    event SentToVault(address indexed caller, uint256 requested, uint256 actual, uint256 newPrincipal);
    event ProfitSentToVault(address indexed caller, uint256 yield, uint256 actual);
    event PrincipalWrittenOff(uint256 amount, uint256 newPrincipal);
    event PrincipalReturned(uint256 amount, uint256 newPrincipal);
    event EmergencyWithdrawn(uint256 amount);
    event RewardTokenSwept(address indexed token, address indexed treasury, uint256 requested, uint256 received);
    event MerklRewardsClaimed(
        address indexed distributor, address indexed token, uint256 cumulativeAmount, uint256 swept
    );
    event MerklUnderlyingRewardsClaimed(
        address indexed distributor, address indexed token, uint256 cumulativeAmount, uint256 sentToVault
    );
    event OwnershipTransferStarted(address indexed previousOwner, address indexed newOwner);
    event UpgraderUpdated(address indexed oldUpgrader, address indexed newUpgrader);

    // =============================================================
    //                          ERRORS
    // =============================================================

    error OnlyVault();
    error Unauthorized();
    error ZeroAddress();
    error NotContract(address target);
    error ReentrantCall();
    error CannotSweepProtectedToken();
    error RenounceOwnershipDisabled();
    error InvalidMerklDistributor();
    error InvalidMerklClaim();
    error DuplicateMerklToken(address token);
    error TooManyMerklTokens(uint256 tokenCount, uint256 maxTokenCount);
    error DepositRecoveryFailed();

    // =============================================================
    //                        MODIFIERS
    // =============================================================

    modifier onlyVault() {
        if (msg.sender != vault) revert OnlyVault();
        _;
    }

    modifier onlyVaultRole(bytes32 role) {
        if (!IAccessControl(vault).hasRole(role, msg.sender)) revert Unauthorized();
        _;
    }

    modifier nonReentrantStrategy() {
        if (_reentrancyStatus == 1) revert ReentrantCall();
        _reentrancyStatus = 1;
        _;
        _reentrancyStatus = 0;
    }

    // =============================================================
    //                       CONSTRUCTOR
    // =============================================================

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    // =============================================================
    //                      INITIALIZER
    // =============================================================

    /**
     * @notice BaseStrategy initialization function
     * @param _vault Vault address managing this Strategy
     * @param _underlying Underlying token under management
     * @param _owner Strategy manager (for emergency operations)
     * @param _upgrader Strategy upgrade authority
     */
    function __BaseStrategy_init(address _vault, IERC20 _underlying, address _owner, address _upgrader)
        internal
        onlyInitializing
    {
        __Ownable_init();
        __UUPSUpgradeable_init();

        if (_vault == address(0)) revert ZeroAddress();
        if (address(_underlying) == address(0)) revert ZeroAddress();
        if (_owner == address(0)) revert ZeroAddress();
        if (_upgrader == address(0)) revert ZeroAddress();
        if (_vault.code.length == 0) revert NotContract(_vault);
        if (address(_underlying).code.length == 0) revert NotContract(address(_underlying));

        vault = _vault;
        underlyingToken = _underlying;
        upgrader = _upgrader;
        _transferOwnership(_owner);

        // Pre-approve Vault so `receiveFromStrategy` can pull underlying via
        // `safeTransferFrom`. The Vault is a trusted contract (UUPS, GOV-controlled).
        _underlying.forceApprove(_vault, type(uint256).max);
    }

    // =============================================================
    //                    UUPS UPGRADE
    // =============================================================

    function _authorizeUpgrade(address) internal view override {
        if (msg.sender != upgrader) revert Unauthorized();
    }

    function setUpgrader(address _newUpgrader) external {
        if (msg.sender != upgrader) revert Unauthorized();
        if (_newUpgrader == address(0)) revert ZeroAddress();

        address oldUpgrader = upgrader;
        upgrader = _newUpgrader;
        emit UpgraderUpdated(oldUpgrader, _newUpgrader);
    }

    // =============================================================
    //                    OWNERSHIP OVERRIDES
    // =============================================================

    /**
     * @notice Pending owner for two-step ownership transfer.
     */
    function pendingOwner() public view returns (address) {
        return _pendingOwner;
    }

    /**
     * @notice Start a two-step ownership transfer.
     * @dev Passing address(0) cancels an existing pending transfer, matching
     *      OpenZeppelin Ownable2Step behavior.
     */
    function transferOwnership(address newOwner) public override onlyOwner {
        _pendingOwner = newOwner;
        emit OwnershipTransferStarted(owner(), newOwner);
    }

    /**
     * @notice Accept a pending ownership transfer.
     */
    function acceptOwnership() public {
        require(_pendingOwner == _msgSender(), "Ownable2Step: caller is not the new owner");
        _transferOwnership(_msgSender());
    }

    /**
     * @notice Disable ownership renounce to preserve emergency, reward-sweep,
     *         and upgrade controls.
     */
    function renounceOwnership() public view override onlyOwner {
        revert RenounceOwnershipDisabled();
    }

    function _transferOwnership(address newOwner) internal override {
        delete _pendingOwner;
        super._transferOwnership(newOwner);
    }

    // =============================================================
    //                    IStrategy VIEW FUNCTIONS
    // =============================================================

    /// @inheritdoc IStrategy
    function underlying() external view override returns (address) {
        return address(underlyingToken);
    }

    /// @inheritdoc IStrategy
    function principal() external view override returns (uint256) {
        return _principal;
    }

    /// @inheritdoc IStrategy
    function realizedYield() public view override returns (uint256) {
        uint256 total = _estimatedTotalUnderlying();
        return total > _principal ? total - _principal : 0;
    }

    /// @inheritdoc IStrategy
    function estimatedTotalUnderlying() external view override returns (uint256) {
        return _estimatedTotalUnderlying();
    }

    // =============================================================
    //                    IStrategy MUTATING FUNCTIONS
    // =============================================================

    /// @inheritdoc IStrategy
    function deposit(uint256 _declaredAmount, uint256 _receivedAmount)
        external
        override
        onlyVault
        nonReentrantStrategy
        returns (uint256 deposited)
    {
        if (_receivedAmount == 0) {
            if (_declaredAmount != 0) revert DepositRecoveryFailed();
            return 0;
        }

        try this.deployUnderlying(_receivedAmount) {
            _principal += _receivedAmount;
            emit Deposited(_receivedAmount, _principal);
            return _receivedAmount;
        } catch {
            if (_declaredAmount != _receivedAmount) revert DepositRecoveryFailed();
            uint256 vaultBalanceBeforeRecovery = underlyingToken.balanceOf(vault);
            uint256 strategyBalanceBeforeRecovery = underlyingToken.balanceOf(address(this));
            (bool transferSucceeded, bytes memory transferReturnData) =
                address(underlyingToken).call(abi.encodeCall(IERC20.transfer, (vault, _receivedAmount)));
            if (
                !transferSucceeded
                    || (transferReturnData.length != 0
                        && (transferReturnData.length < 32 || !abi.decode(transferReturnData, (bool))))
            ) {
                revert DepositRecoveryFailed();
            }
            uint256 vaultBalanceAfterRecovery = underlyingToken.balanceOf(vault);
            uint256 strategyBalanceAfterRecovery = underlyingToken.balanceOf(address(this));
            if (
                vaultBalanceAfterRecovery < vaultBalanceBeforeRecovery
                    || strategyBalanceAfterRecovery > strategyBalanceBeforeRecovery
                    || vaultBalanceAfterRecovery - vaultBalanceBeforeRecovery != _receivedAmount
                    || strategyBalanceBeforeRecovery - strategyBalanceAfterRecovery != _receivedAmount
            ) {
                revert DepositRecoveryFailed();
            }
            return 0;
        }
    }

    /// @notice Execute the protocol-specific deposit in an isolated call frame.
    /// @dev Self-only so an upstream revert rolls back its effects while the
    ///      outer `deposit` frame can return the idle Underlying to the Vault.
    function deployUnderlying(uint256 _amount) external {
        if (msg.sender != address(this)) revert Unauthorized();
        _doDeposit(_amount);
    }

    /// @inheritdoc IStrategy
    function sendToVault(uint256 _amount)
        external
        override
        nonReentrantStrategy
        onlyVaultRole(_WITHDRAWER_ROLE)
        returns (uint256 sent)
    {
        if (_amount == 0) return 0;

        uint256 withdrawnUnderlying = _doWithdraw(_amount);
        if (withdrawnUnderlying == 0) {
            emit SentToVault(msg.sender, _amount, 0, _principal);
            return 0;
        }

        // Push first, then decrement `_principal` using the amount the Vault
        // actually received (`sent`). Decrementing based on `actual` alone
        // would drop principal even when fee-on-transfer / rebasing / hook
        // tokens deliver less than `actual` to the Vault, producing silent
        // accounting drift between Strategy.principal and Vault.bufferBalance.
        // Principal-first decrement: any excess of `sent` over the remaining
        // `_principal` represents yield that is being deallocated as part of
        // this amount-specified push and stays in the Vault buffer to be
        // handled by `transferYieldToTreasury`.
        sent = ICollateralVault(vault).receiveFromStrategy(withdrawnUnderlying);
        uint256 principalReduction = sent > _principal ? _principal : sent;
        _principal -= principalReduction;

        emit SentToVault(msg.sender, _amount, sent, _principal);
    }

    /// @inheritdoc IStrategy
    function sendProfitToVault()
        external
        override
        nonReentrantStrategy
        onlyVaultRole(_HARVESTER_ROLE)
        returns (uint256 sent)
    {
        uint256 realizedProfit = realizedYield();
        if (realizedProfit == 0) {
            emit ProfitSentToVault(msg.sender, 0, 0);
            return 0;
        }

        uint256 withdrawnUnderlying = _doWithdraw(realizedProfit);
        if (withdrawnUnderlying == 0) {
            emit ProfitSentToVault(msg.sender, realizedProfit, 0);
            return 0;
        }

        // A converter's loss allowance can withdraw more than the measured yield.
        // Return that excess as principal instead of leaving phantom principal behind.
        if (withdrawnUnderlying > realizedProfit) {
            uint256 returned = ICollateralVault(vault).receiveFromStrategy(withdrawnUnderlying - realizedProfit);
            _accountReturnedPrincipal(returned);
            withdrawnUnderlying = realizedProfit;
        }

        // The remaining yield-only push leaves `_principal` unchanged. Send
        // directly to the Vault buffer so Strategy valuation cache is not
        // reduced as if principal had been returned.
        sent = _sendUnderlyingToVault(withdrawnUnderlying);
        emit ProfitSentToVault(msg.sender, realizedProfit, sent);
    }

    /// @inheritdoc IStrategy
    function writeoffPrincipal(uint256 _amount)
        external
        override
        onlyVault
        nonReentrantStrategy
        returns (uint256 writtenOff)
    {
        writtenOff = _amount > _principal ? _principal : _amount;
        _principal -= writtenOff;
        emit PrincipalWrittenOff(writtenOff, _principal);
    }

    // =============================================================
    //                   EMERGENCY FUNCTIONS
    // =============================================================

    /**
     * @notice Emergency push of Underlying held directly by this Strategy
     *         (not deployed in the upstream protocol) back to the Vault.
     *         Used to recover funds that became idle in the Strategy contract
     *         — e.g. after `emergencyWithdrawFromAave`, a donation, or an
     *         upstream protocol incident.
     * @dev    Owner only. The destination is fixed to `vault`; the previous
     *         arbitrary `_to` parameter allowed a Strategy owner (who can be
     *         distinct from the Vault GOV in some deployments) to drain
     *         Underlying to any address without GOV approval.
     *
     *         `_principal` is intentionally NOT decremented. This operation
     *         only moves recoverable idle Underlying back into Vault custody;
     *         it does not assert that the Strategy's upstream principal has
     *         been repaid or permanently lost.
     *
     *         Route through `Vault.receiveFromStrategy` instead of transferring
     *         directly so the Vault reduces an exact-delivery cache or
     *         invalidates it when declared and received amounts differ. A stale
     *         pre-recovery cache must not be able to count the same underlying
     *         once in the Vault buffer and again as Strategy value if live
     *         Strategy valuation is unavailable.
     *
     *         If the upstream balance is also gone and the residual loss needs
     *         to be acknowledged, the incident writeoff role should follow up with
     *         `Vault.writeoffStrategyPrincipal(strategy, amount, minBackingRatioAfter)`.
     */
    function emergencyWithdraw(uint256 _amount) external onlyOwner nonReentrantStrategy {
        if (_amount == 0) return;
        uint256 sent = ICollateralVault(vault).receiveFromStrategy(_amount);
        _afterEmergencyUnderlyingSent(_amount, sent);
        emit EmergencyWithdrawn(sent);
    }

    /**
     * @notice Sweep non-underlying, non-position reward tokens to the Vault treasury.
     * @dev    Covers Aave incentives, Merkl rewards, or accidental reward-token
     *         transfers that have already landed in the Strategy. Underlying and
     *         protocol position/accounting tokens are deliberately excluded:
     *         principal and underlying yield must return through `sendToVault`,
     *         `sendProfitToVault`, or `emergencyWithdraw`.
     *         Pass `type(uint256).max` to sweep the Strategy's full token balance.
     */
    function sweepRewardToken(IERC20 _token, uint256 _amount)
        external
        override
        onlyOwner
        nonReentrantStrategy
        returns (uint256 swept)
    {
        swept = _sweepRewardToken(_token, _amount);
    }

    /**
     * @notice Claim Merkl rewards earned by this Strategy. Ordinary reward
     *         tokens are swept to the current Vault treasury; underlying rewards
     *         are pushed back to the Vault as yield.
     * @dev    Uses Merkl's basic `claim` entry point only: every `user` is forced
     *         to `address(this)`, so no custom recipient or callback data can be
     *         injected. Upstream position/accounting tokens are rejected before
     *         the distributor call; underlying-token rewards are allowed but must
     *         are sent directly to the Vault buffer instead of the treasury
     *         sweep path, preserving the principal/yield accounting boundary for
     *         Morpho/Euler/Merkl-style reward programs without reducing the
     *         Vault's Strategy valuation cache.
     * @param  _distributor Merkl distributor contract.
     * @param  _tokens Reward tokens being claimed.
     * @param  _amounts Cumulative Merkl claim amounts for this Strategy.
     * @param  _proofs Merkle proofs matching each `(strategy, token, amount)`.
     * @return settledAmounts Amounts actually received by treasury or Vault per token.
     */
    function claimMerklRewards(
        IMerklDistributor _distributor,
        address[] calldata _tokens,
        uint256[] calldata _amounts,
        bytes32[][] calldata _proofs
    ) external onlyOwner nonReentrantStrategy returns (uint256[] memory settledAmounts) {
        if (address(_distributor) == address(0)) revert ZeroAddress();
        if (address(_distributor).code.length == 0) revert InvalidMerklDistributor();

        uint256 length = _tokens.length;
        if (length == 0 || length != _amounts.length || length != _proofs.length) revert InvalidMerklClaim();
        if (length > MAX_MERKL_TOKENS_PER_CLAIM) {
            revert TooManyMerklTokens(length, MAX_MERKL_TOKENS_PER_CLAIM);
        }

        address[] memory users = new address[](length);
        uint256[] memory balancesBeforeClaim = new uint256[](length);
        address underlyingAddress = address(underlyingToken);
        for (uint256 i = 0; i < length;) {
            address token = _tokens[i];
            if (token == address(0)) revert ZeroAddress();
            if (token != underlyingAddress && _isSweepProtectedToken(token)) revert CannotSweepProtectedToken();
            for (uint256 j = 0; j < i;) {
                if (_tokens[j] == token) revert DuplicateMerklToken(token);
                unchecked {
                    ++j;
                }
            }
            balancesBeforeClaim[i] = IERC20(token).balanceOf(address(this));
            users[i] = address(this);
            unchecked {
                ++i;
            }
        }

        _distributor.claim(users, _tokens, _amounts, _proofs);

        settledAmounts = new uint256[](length);
        for (uint256 i = 0; i < length;) {
            settledAmounts[i] = _settleClaimedMerklToken(
                address(_distributor), _tokens[i], _amounts[i], balancesBeforeClaim[i], underlyingAddress
            );
            unchecked {
                ++i;
            }
        }
    }

    function _settleClaimedMerklToken(
        address _distributor,
        address _token,
        uint256 _cumulativeAmount,
        uint256 _balanceBeforeClaim,
        address _underlyingAddress
    ) internal returns (uint256 settled) {
        if (_token == _underlyingAddress) {
            uint256 balanceAfterClaim = IERC20(_token).balanceOf(address(this));
            uint256 claimedUnderlying =
                balanceAfterClaim > _balanceBeforeClaim ? balanceAfterClaim - _balanceBeforeClaim : 0;
            if (claimedUnderlying != 0) {
                settled = _sendUnderlyingToVault(claimedUnderlying);
            }
            emit MerklUnderlyingRewardsClaimed(_distributor, _token, _cumulativeAmount, settled);
        } else {
            settled = _sweepRewardToken(IERC20(_token), type(uint256).max);
            emit MerklRewardsClaimed(_distributor, _token, _cumulativeAmount, settled);
        }
    }

    function _sendUnderlyingToVault(uint256 _amount) internal returns (uint256 sent) {
        if (_amount == 0) return 0;

        uint256 vaultBalanceBefore = underlyingToken.balanceOf(vault);
        underlyingToken.safeTransfer(vault, _amount);
        uint256 vaultBalanceAfter = underlyingToken.balanceOf(vault);
        sent = vaultBalanceAfter > vaultBalanceBefore ? vaultBalanceAfter - vaultBalanceBefore : 0;
    }

    function _accountReturnedPrincipal(uint256 _received) internal returns (uint256 principalReturned) {
        if (_received == 0) return 0;

        principalReturned = _received > _principal ? _principal : _received;
        if (principalReturned == 0) return 0;

        _principal -= principalReturned;
        emit PrincipalReturned(principalReturned, _principal);
    }

    /// @dev Common settlement path for protocol-specific emergency recovery.
    ///      This differs from `emergencyWithdraw`: recovered upstream principal
    ///      reduces `_principal` by the Vault's actual received amount.
    function _returnUnderlyingPrincipalToVault(uint256 _amount) internal returns (uint256 sent) {
        if (_amount == 0) return 0;

        sent = ICollateralVault(vault).receiveFromStrategy(_amount);
        _afterEmergencyUnderlyingSent(_amount, sent);
        _accountReturnedPrincipal(sent);
        emit EmergencyWithdrawn(sent);
    }

    /**
     * @dev Shared reward-token sweep primitive for future claim adapters.
     *      Protocol-specific strategies may claim rewards into this contract and
     *      call this helper, preserving the same accounting boundary and fixed
     *      treasury destination as the external owner operation. Derived
     *      strategies must mark any receipt/accounting token that represents the
     *      upstream position as sweep-protected.
     */
    function _sweepRewardToken(IERC20 _token, uint256 _amount) internal returns (uint256 swept) {
        address tokenAddress = address(_token);
        if (tokenAddress == address(0)) revert ZeroAddress();
        if (_isSweepProtectedToken(tokenAddress)) revert CannotSweepProtectedToken();

        uint256 amount = _amount == type(uint256).max ? _token.balanceOf(address(this)) : _amount;
        if (amount == 0) return 0;

        address recipient = ICollateralVault(vault).treasury();
        if (recipient == address(0)) revert ZeroAddress();

        uint256 recipientBalanceBeforeSweep = _token.balanceOf(recipient);
        _token.safeTransfer(recipient, amount);
        uint256 recipientBalanceAfterSweep = _token.balanceOf(recipient);
        swept = recipientBalanceAfterSweep > recipientBalanceBeforeSweep
            ? recipientBalanceAfterSweep - recipientBalanceBeforeSweep
            : 0;

        emit RewardTokenSwept(tokenAddress, recipient, amount, swept);
    }

    /**
     * @dev Tokens that are not rewards and must not be routed to treasury.
     *      Derived strategies override this to protect protocol-specific
     *      receipt/accounting tokens such as Aave aTokens.
     */
    function _isSweepProtectedToken(address _token) internal view virtual returns (bool) {
        return _token == address(underlyingToken) || _token == address(ICollateralVault(vault).dToken());
    }

    /// @dev Optional hook for derived strategies that separately track idle
    ///      underlying held by the Strategy contract itself.
    function _afterEmergencyUnderlyingSent(uint256, uint256) internal virtual {}

    // =============================================================
    //                   VIRTUAL HOOKS
    // =============================================================

    /// @dev Deploy `_amount` of underlying (already in this contract) into the
    ///      upstream yield protocol. Implementer is responsible for the actual
    ///      external call (e.g., `aavePool.supply(...)`).
    function _doDeposit(uint256 _amount) internal virtual;

    /// @dev Withdraw `_amount` of underlying from the upstream protocol. The
    ///      withdrawn underlying must end up held by THIS contract so the base
    ///      logic can route principal/cache-reducing returns through
    ///      `receiveFromStrategy` and yield-only returns through direct transfer.
    /// @return actual Amount actually withdrawn; may be less than requested.
    function _doWithdraw(uint256 _amount) internal virtual returns (uint256 actual);

    /// @dev Underlying value (principal + accrued yield) held in the upstream
    ///      protocol on behalf of this Strategy.
    function _estimatedTotalUnderlying() internal view virtual returns (uint256);
}
"
    },
    "src/Strategies/ERC4626Strategy.sol": {
      "content": "// SPDX-License-Identifier: BUSL-1.1

pragma solidity 0.8.24;

import "openzeppelin-contracts/contracts/interfaces/IERC4626.sol";

import "./BaseStrategy.sol";

/**
 * @title ERC4626Strategy - ERC-4626 vault Strategy (push model, Upgradeable)
 * @notice Synchronous Strategy adapter for ERC-4626 yield vaults whose `asset()`
 *         is the same token as this Strategy's underlying.
 * @dev    The Strategy tracks the vault shares minted through its own deposits.
 *         Anyone can transfer ERC-4626 shares directly to this contract, but
 *         donated shares must not inflate `estimatedTotalUnderlying()` or
 *         `realizedYield()`. Emergency recovery may still redeem donated shares
 *         and push the recovered underlying to the Vault.
 */
contract ERC4626Strategy is BaseStrategy {
    using SafeERC20 for IERC20;

    // =============================================================
    //                         STATE
    // =============================================================

    IERC4626 public erc4626Vault;

    /// @notice ERC-4626 shares minted through this Strategy's own deposits,
    ///         minus shares burned through this Strategy's own withdrawals.
    /// @dev Third-party share transfers to this contract do not affect this
    ///      value, so regular valuation ignores share-token donations.
    uint256 internal _ownShares;

    /// @dev Storage gap for future upgrades of this derived contract.
    uint256[48] private __gapERC4626;

    // =============================================================
    //                          EVENTS
    // =============================================================

    event OwnSharesUpdated(uint256 newOwnShares);

    // =============================================================
    //                          ERRORS
    // =============================================================

    error InvalidERC4626Asset();
    error ERC4626ZeroShares();
    error ERC4626ShareBalanceMismatch();
    error ERC4626AssetAmountMismatch(uint256 reported, uint256 actual);

    // =============================================================
    //                        INITIALIZER
    // =============================================================

    function initialize(address _vault, IERC20 _underlying, address _owner, address _upgrader, IERC4626 _erc4626Vault)
        external
        initializer
    {
        __BaseStrategy_init(_vault, _underlying, _owner, _upgrader);

        if (address(_erc4626Vault) == address(0)) revert ZeroAddress();
        if (address(_erc4626Vault).code.length == 0) revert NotContract(address(_erc4626Vault));
        if (_erc4626Vault.asset() != address(_underlying)) revert InvalidERC4626Asset();

        erc4626Vault = _erc4626Vault;

        _underlying.forceApprove(address(_erc4626Vault), type(uint256).max);
    }

    // =============================================================
    //                  BaseStrategy HOOKS
    // =============================================================

    /// @inheritdoc BaseStrategy
    function _doDeposit(uint256 _amount) internal override {
        uint256 shareBalanceBefore = erc4626Vault.balanceOf(address(this));
        uint256 reportedMintedShares = erc4626Vault.deposit(_amount, address(this));
        uint256 shareBalanceAfter = erc4626Vault.balanceOf(address(this));
        if (shareBalanceAfter < shareBalanceBefore) revert ERC4626ShareBalanceMismatch();

        uint256 actualMintedShares = shareBalanceAfter - shareBalanceBefore;
        if (actualMintedShares == 0) revert ERC4626ZeroShares();
        if (actualMintedShares != reportedMintedShares) revert ERC4626ShareBalanceMismatch();

        _ownShares += actualMintedShares;
        emit OwnSharesUpdated(_ownShares);
    }

    /// @inheritdoc BaseStrategy
    /// @dev Withdraws no more than the value of locally tracked shares and no
    ///      more than the ERC-4626 vault reports as currently withdrawable.
    function _doWithdraw(uint256 _amount) internal override returns (uint256 actual) {
        uint256 ownShares = _ownShares;
        if (ownShares == 0) return 0;

        uint256 trackedAssets = erc4626Vault.convertToAssets(ownShares);
        uint256 maxAssets = erc4626Vault.maxWithdraw(address(this));
        uint256 assetsToWithdraw = trackedAssets < maxAssets ? trackedAssets : maxAssets;
        if (_amount < assetsToWithdraw) assetsToWithdraw = _amount;
        if (assetsToWithdraw == 0) return 0;

        uint256 underlyingBalanceBefore = underlyingToken.balanceOf(address(this));
        uint256 shareBalanceBefore = erc4626Vault.balanceOf(address(this));
        uint256 reportedBurnedShares = erc4626Vault.withdraw(assetsToWithdraw, address(this), address(this));
        uint256 shareBalanceAfter = erc4626Vault.balanceOf(address(this));
        if (shareBalanceAfter > shareBalanceBefore) revert ERC4626ShareBalanceMismatch();

        uint256 actualBurnedShares = shareBalanceBefore - shareBalanceAfter;
        if (actualBurnedShares != reportedBurnedShares) revert ERC4626ShareBalanceMismatch();
        uint256 underlyingBalanceAfter = underlyingToken.balanceOf(address(this));
        actual = underlyingBalanceAfter - underlyingBalanceBefore;
        if (actualBurnedShares == 0) revert ERC4626ZeroShares();
        if (actual != assetsToWithdraw) revert ERC4626AssetAmountMismatch(assetsToWithdraw, actual);

        _ownShares = actualBurnedShares > ownShares ? 0 : ownShares - actualBurnedShares;
        emit OwnSharesUpdated(_ownShares);
    }

    /// @inheritdoc BaseStrategy
    /// @dev Values only the shares minted through this Strategy's own deposit
    ///      path, capped by the current share balance in case of an upstream or
    ///      accidental share loss. Direct share-token donations are ignored.
    function _estimatedTotalUnderlying() internal view override returns (uint256) {
        uint256 currentShareBalance = erc4626Vault.balanceOf(address(this));
        uint256 effectiveShares = _ownShares < currentShareBalance ? _ownShares : currentShareBalance;
        if (effectiveShares == 0) return 0;
        return erc4626Vault.convertToAssets(effectiveShares);
    }

    /// @inheritdoc BaseStrategy
    /// @dev The ERC-4626 share token is the position token, not a reward token.
    function _isSweepProtectedToken(address _token) internal view override returns (bool) {
        return super._isSweepProtectedToken(_token) || _token == address(erc4626Vault);
    }

    // =============================================================
    //                   EMERGENCY FUNCTIONS
    // =============================================================

    /**
     * @notice Redeem as many ERC-4626 shares as currently possible and
     *         immediately push all idle underlying back to the Vault.
     * @dev Owner only. The Vault receipt is accounted as returned principal. If
     *      recovered plus still-valued assets are short of principal, a Vault WRITEOFF_ROLE holder must call `Vault.writeoffStrategyPrincipal(...)`.
     */
    function emergencyWithdrawFromERC4626() external onlyOwner nonReentrantStrategy returns (uint256 sent) {
        uint256 currentShareBalance = erc4626Vault.balanceOf(address(this));
        if (currentShareBalance != 0) {
            uint256 redeemableShares = erc4626Vault.maxRedeem(address(this));
            if (currentShareBalance < redeemableShares) redeemableShares = currentShareBalance;

            if (redeemableShares != 0) {
                uint256 shareBalanceBefore = currentShareBalance;
                uint256 underlyingBalanceBefore = underlyingToken.balanceOf(address(this));
                uint256 reportedAssets = erc4626Vault.redeem(redeemableShares, address(this), address(this));
                uint256 shareBalanceAfter = erc4626Vault.balanceOf(address(this));
                if (shareBalanceAfter > shareBalanceBefore) revert ERC4626ShareBalanceMismatch();
                uint256 actualBurnedShares = shareBalanceBefore - shareBalanceAfter;
                if (actualBurnedShares != redeemableShares) revert ERC4626ShareBalanceMismatch();
                uint256 actualAssets = underlyingToken.balanceOf(address(this)) - underlyingBalanceBefore;
                if (reportedAssets != actualAssets) revert ERC4626AssetAmountMismatch(reportedAssets, actualAssets);

                // Emergency redemption is sized from the raw share balance, so
                // donated shares must absorb the burn before locally owned shares.
                uint256 ownShares = _ownShares;
                _ownShares = ownShares < shareBalanceAfter ? ownShares : shareBalanceAfter;
                emit OwnSharesUpdated(_ownShares);
            }
        }

        uint256 idleUnderlying = underlyingToken.balanceOf(address(this));
        if (idleUnderlying == 0) return 0;

        sent = _returnUnderlyingPrincipalToVault(idleUnderlying);
    }
}
"
    },
    "src/Strategies/MorphoV2Strategy.sol": {
      "content": "// SPDX-License-Identifier: BUSL-1.1

pragma solidity 0.8.24;

import "openzeppelin-contracts/contracts/interfaces/IERC4626.sol";

import "./BaseStrategy.sol";

/// @notice Minimal Morpho Vaults V2 surface used by this Strategy: the ERC-4626
///         core plus the permissionless `forceDeallocate` escape hatch that
///         pulls liquidity out of a market adapter for a share-paid penalty.
interface IMorphoVaultV2 is IERC4626 {
    function forceDeallocate(address adapter, bytes calldata data, uint256 assets, address onBehalf)
        external
        returns (uint256 penaltyShares);
}

/**
 * @title MorphoV2Strategy - Morpho Vaults V2 Strategy (push model, Upgradeable)
 * @notice Synchronous Strategy adapter for Morpho Vaults V2 whose `asset()` is
 *         the same token as this Strategy's underlying.
 * @dev    Morpho Vaults V2 keeps the ERC-4626 call surface but returns 0 from
 *         `maxDeposit`/`maxMint`/`maxWithdraw`/`maxRedeem` unconditionally, so
 *         unlike `ERC4626Strategy` this adapter never clamps against the max*
 *         views: it clamps only to the value of its own tracked shares and
 *         attempts the venue call inside an isolated self-call frame.
 *
 *         Venue behavior designed against:
 *           - Deposits are synchronous but CAN revert when the liquidity
 *             adapter's caps are hit or a receive gate is set. A rejected
 *             deposit reverts the isolated frame; `BaseStrategy.deposit`
 *             catches it and returns the exact receipt to the Vault, so no
 *             funds are stranded here (Low-01 recovery path).
 *           - Withdrawals pay from idle then deallocate from the single
 *             liquidity adapter; liquidity-short reverts bubble up as UNTYPED
 *             lower-level errors. The Strategy retries a bounded sequence of
 *             half-size requests before converting all-failed recovery into a
 *             fail-soft `0` result (ADR-006), with failed venue state rolled
 *             back per isolated attempt.
 *           - Losses reflect immediately in `convertToAssets` (maxRate caps
 *             gains only). No in-kind redemption: only underlying ever arrives
 *             from withdraw/redeem.
 *           - Rewards are Merkl-only (URD deprecated); the inherited
 *             `BaseStrategy.claimMerklRewards` / `sweepRewardToken` suffice.
 *
 *         Liquidity recovery map:
 *           - normal liquidity  -> `sendToVault` / `sendProfitToVault`
 *                                  (`_doWithdraw`);
 *           - vault idle only   -> owner `emergencyWithdrawFromMorphoV2` with a
 *                                  share cap sized to the redeemable portion;
 *           - no liquidity      -> WRITEOFF_ROLE through
 *                                  `CollateralVault.forceDeallocateMorphoV2`
 *                                  (atomic pauses/backing floor; penalty paid
 *                                  in this Strategy's shares and bounded by the
 *                                  init-frozen `maxForceDeallocatePenaltyBps`),
 *                                  with withdrawal to the Vault in the same
 *                                  transaction and a minimum actual receipt.
 *
 *         Venue freeze policy: deploy only against Morpho V2 vaults whose
 *         receive-/send-share gates are unset. A gate installed later surfaces
 *         as a recovered deposit rejection or a fail-soft withdraw, never as
 *         stranded funds.
 *
 *         Anyone can transfer vault shares directly to this contract, but
 *         donated shares must not inflate `estimatedTotalUnderlying()` or
 *         `realizedYield()`; only shares minted through this Strategy's own
 *         deposits are valued.
 */
contract MorphoV2Strategy is BaseStrategy {
    using SafeERC20 for IERC20;

    // =============================================================
    //                         CONSTANTS
    // =============================================================

    /// @notice Protocol-level ceiling for `forceDeallocatePenalty` (2%).
    uint256 public constant MAX_FORCE_DEALLOCATE_PENALTY_BPS = 200;

    /// @dev One full-size attempt plus seven bounded half-size probes. This
    ///      recovers useful liquidity without relying on Morpho V2's hard-zero
    ///      max* views or permitting an unbounded retry loop.
    uint256 internal constant _MAX_WITHDRAW_ATTEMPTS = 8;

    uint256 internal constant _BPS_DENOMINATOR = 10_000;

    // =============================================================
    //                         STATE
    // =============================================================

    /// @notice Morpho Vaults V2 vault this Strategy deposits into.
    IMorphoVaultV2 public morphoVault;

    /// @notice Maximum forceDeallocate penalty (in bps of deallocated assets)
    ///         this Strategy accepts before reverting. Frozen at initialization
    ///         (no setter); must not exceed the 2% protocol maximum.
    uint256 public maxForceDeallocatePenaltyBps;

    /// @notice Vault shares minted through this Strategy's own deposits, minus
    ///         shares burned through its own withdrawals and penalties.
    /// @dev Third-party share transfers to this contract do not affect this
    ///      value, so regular valuation ignores share-token donations.
    uint256 internal _ownShares;

    /// @dev Storage gap for future upgrades of this derived contract.
    uint256[47] private __gapMorphoV2;

    // =============================================================
    //                          EVENTS
    // =============================================================

    event OwnSharesUpdated(uint256 newOwnShares);
    event ForceDeallocated(address indexed adapter, uint256 assets, uint256 penaltyShares, uint256 penaltyAssets);

    // =============================================================
    //                          ERRORS
    // =============================================================

    error InvalidMorphoVaultAsset();
    error MorphoV2ZeroShares();
    error MorphoV2ShareBalanceMismatch();
    error MorphoV2AssetAmountMismatch(uint256 reported, uint256 actual);
    error MorphoV2DepositRejected();
    error ForceDeallocatePenaltyAboveMax(uint256 requestedBps, uint256 maxBps);
    error ForceDeallocatePenaltyExceeded(uint256 penaltyAssets, uint256 maxPenaltyAssets);

    // =============================================================
    //                        INITIALIZER
    // =============================================================

    function initialize(
        address _vault,
        IERC20 _underlying,
        address _owner,
        address _upgrader,
        IMorphoVaultV2 _morphoVault,
        uint256 _maxForceDeallocatePenaltyBps
    ) external initializer {
        __BaseStrategy_init(_vault, _underlying, _owner, _upgrader);

        if (address(_morphoVault) == address(0)) revert ZeroAddress();
        if (address(_morphoVault).code.length == 0) revert NotContract(address(_morphoVault));
        if (_morphoVault.asset() != address(_underlying)) revert InvalidMorphoVaultAsset();
        if (_maxForceDeallocatePenaltyBps > MAX_FORCE_DEALLOCATE_PENALTY_BPS) {
            revert ForceDeallocatePenaltyAboveMax(_maxForceDeallocatePenaltyBps, MAX_FORCE_DEALLOCATE_PENALTY_BPS);
        }

        morphoVault = _morphoVault;
        maxForceDeallocatePenaltyBps = _maxForceDeallocatePenaltyBps;

        _underlying.forceApprove(address(_morphoVault), type(uint256).max);
    }

    // =============================================================
    //                        VIEW FUNCTIONS
    // =============================================================

    /// @notice Vault shares currently attributed to this Strategy's own deposits.
    function ownShares() external view returns (uint256) {
        return _ownShares;
    }

    // =============================================================
    //                  BaseStrategy HOOKS
    // =============================================================

    /// @inheritdoc BaseStrategy
    /// @dev Morpho Vaults V2 deposits are synchronous but can be rejected by
    ///      the venue (liquidity-adapter caps, receive gate). The venue call
    ///      runs in an isolated self-call so a rejection rolls back cleanly and
    ///      is re-raised as a typed error: `BaseStrategy.deposit` catches it
    ///      and routes the exact receipt back to the Vault (Low-01 recovery)
    ///      instead of stranding idle underlying in this Strategy.
    function _doDeposit(uint256 _amount) internal override {
        try this.depositIntoMorphoVault(_amount) {}
        catch {
            revert MorphoV2DepositRejected();
        }
    }

    /// @notice Execute the Morpho vault deposit in an isolated call frame.
    /// @dev Self-only. Exact share-delta checks stay inside this frame so a
    ///      lying or zero-share venue response rolls back its own effects.
    function depositIntoMorphoVault(uint256 _amount) external {
        if (msg.sender != address(this)) revert Unauthorized();

        uint256 shareBalanceBefore = morphoVault.balanceOf(address(this));
        uint256 reportedMintedShares = morphoVault.deposit(_amount, address(this));
        uint256 shareBalanceAfter = morphoVault.balanceOf(address(this));
        if (shareBalanceAfter < shareBalanceBefore) revert MorphoV2ShareBalanceMismatch();

        uint256 actualMintedShares = shareBalanceAfter - shareBalanceBefore;
        if (actualMintedShares == 0) revert MorphoV2ZeroShares();
        if (actualMintedShares != reportedMintedShares) revert MorphoV2ShareBalanceMismatch();

        _ownShares += actualMintedShares;
        emit OwnSharesUpdated(_ownShares);
    }

    /// @inheritdoc BaseStrategy
    /// @dev Morpho Vaults V2 reports 0 from `maxWithdraw` unconditionally, so
    ///      the request is clamped only to the value of locally tracked shares.
    ///      The venue call runs in an isolated self-call: liquidity-short
    ///      deallocations bubble up as untyped lower-level reverts and are
    ///      converted into a fail-soft `0` result (ADR-006) with all venue
    ///      state rolled back.
    function _doWithdraw(uint256 _amount) internal override returns (uint256 actual) {
        // Same share basis as `_estimatedTotalUnderlying`: own shares capped by
        // the live balance, so a lost-shares scenario partially recovers
        // instead of failing soft on an over-sized venue request.
        uint256 ownShares_ = _ownShares;
        uint256 currentShareBalance = morphoVault.balanceOf(address(this));
        uint256 effectiveShares = ownShares_ < currentShareBalance ? ownShares_ : currentShareBalance;
        if (effectiveShares == 0) return 0;

        uint256 trackedAssets = morphoVault.convertToAssets(effectiveShares);
        uint256 assetsToWithdraw = _amount < trackedAssets ? _amount : trackedAssets;
        if (assetsToWithdraw == 0) return 0;

        for (uint256 attempt; attempt < _MAX_WITHDRAW_ATTEMPTS; ++attempt) {
            try this.withdrawFromMorphoVault(assetsToWithdraw) returns (uint256 withdrawn) {
                return withdrawn;
            } catch {
                if (assetsToWithdraw == 1) return 0;
                assetsToWithdraw /= 2;
            }
        }

        return 0;
    }

    /// @notice Execute the Morpho vault withdrawal in an isolated call frame.
    /// @dev Self-only. Exact share-delta / asset-delta mismatch reverts stay
    ///      inside this frame so a hostile venue response (lying return value,
    ///      zero-share burn, short asset delivery) rolls back its own effects
    ///      before the outer fail-soft catch reports `0`.
    function withdrawFromMorphoVault(uint256 _assets) external returns (uint256 actualAssets) {
        if (msg.sender != address(this)) revert Unauthorized();

        uint256 ownShares_ = _ownShares;
        uint256 underlyingBalanceBefore = underlyingToken.balanceOf(address(this));
        uint256 shareBalanceBefore = morphoVault.balanceOf(address(this));
        uint256 reportedBurnedShares = morphoVault.withdraw(_assets, address(this), address(this));
        uint256 shareBalanceAfter = morphoVault.balanceOf(address(this));
        if (shareBalanceAfter > shareBalanceBefore) revert MorphoV2ShareBalanceMismatch();

        uint256 actualBurnedShares = shareBalanceBefore - shareBalanceAfter;
        if (actualBurnedShares == 0) revert MorphoV2ZeroShares();
        if (actualBurnedShares != reportedBurnedShares) revert MorphoV2ShareBalanceMismatch();
        actualAssets = underlyingToken.balanceOf(address(this)) - underlyingBalanceBefore;
        if (actualAssets != _assets) revert MorphoV2AssetAmountMismatch(_assets, actualAssets);

        _ownShares = actualBurnedShares > ownShares_ ? 0 : ownShares_ - actualBurnedShares;
        emit OwnSharesUpdated(_ownShares);
    }

    /// @inheritdoc BaseStrategy
    /// @dev Values only the shares minted through this Strategy's own deposit
    ///      path, capped by the current share balance in case of an upstream or
    ///      accidental share loss. Direct share-token donations are ignored.
    ///      Venue losses reflect here immediately via `convertToAssets`.
    function _estimatedTotalUnderlying() internal view override returns (uint256) {
        uint256 currentShareBalance = morphoVault.balanceOf(address(this));
        uint256 effectiveShares = _ownShares < currentShareBalance ? _ownShares : currentShareBalance;
        if (effectiveShares == 0) return 0;
        return morphoVault.convertToAssets(effectiveShares);
    }

    /// @inheritdoc BaseStrategy
    /// @dev The Morpho vault share token is the position token, not a reward token.
    function _isSweepProtectedToken(address _token) internal view override returns (bool) {
        return super._isSweepProtectedToken(_token) || _token == address(morphoVault);
    }

    // =============================================================
    //                   EMERGENCY FUNCTIONS
    // =============================================================

    /**
     * @notice Redeem up to `_maxShares` of this Strategy's own Morpho vault
     *         shares and immediately push all idle underlying back to the
     *         Vault in the same transaction.
     * @dev Owner only. `maxRedeem` is always 0 on Morpho Vaults V2, so the cap
     *      is `min(full share balance, _maxShares)` — donated shares included,
     *      matching `emergencyWithdrawFromERC4626`, since this is their only
     *      recovery path (`sweepRewardToken` rejects the position token). The
     *      venue redeem simply reverts if liquidity is short — size `_maxShares`
     *      to the vault's idle/deallocatable portion. When deallocation is
     *      required, use the Vault's atomic force-deallocation recovery. Receipt is
     *      accounted as returned principal. If recovered plus still-valued
     *      assets are short of principal, a Vault WRITEOFF_ROLE holder must call
     *      `Vault.writeoffStrategyPrincipal(...)`.
     * @param _maxShares Upper bound on shares to redeem (pass
     *        `type(uint256).max` for a full drain attempt).
     */
    function emergencyWithdrawFromMorphoV2(uint256 _maxShares)
        external
        onlyOwner
        nonReentrantStrategy
        returns (uint256 sent)
    {
        uint256 currentShareBalance = morphoVault.balanceOf(address(this));
        uint256 sharesToRedeem = _maxShares < currentShareBalance ? _maxShares : currentShareBalance;

        if (sharesToRedeem != 0) {
            uint256 underlyingBalanceBefore = underlyingToken.balanceOf(address(this));
            uint256 reportedAssets = morphoVault.redeem(sharesToRedeem, address(this), address(this));
            uint256 shareBalanceAfter = morphoVault.balanceOf(address(this));
            if (shareBalanceAfter > currentShareBalance) revert MorphoV2ShareBalanceMismatch();
            uint256 actualBurnedShares = currentShareBalance - shareBalanceAfter;
            if (actualBurnedShares != sharesToRedeem) revert MorphoV2ShareBalanceMismatch();
            uint256 actualAssets = underlyingToken.balanceOf(address(this)) - underlyingBalanceBefore;
            if (reportedAssets != actualAssets) revert MorphoV2AssetAmountMismatch(reportedAssets, actualAssets);

            // Burn donated shares first. This function is the only one that sizes against the
            // raw balance -- `_estimatedTotalUnderlying` and `_doWithdraw` both clamp to
            // `min(_ownShares, balance)` so donations are invisible to them. Decrementing
            // `_ownShares` by the full redeemed count would therefore charge a donation
            // recovery against the Strategy's own position: the shares stay in the vault but
            // stop being counted, which understates `estimatedTotalUnderlying()`, feeds
            // `CollateralVault.backingRatio()`, and reprices every Trove on the branch.
            uint256 ownShares_ = _ownShares;
            uint256 donatedShares = currentShareBalance > ownShares_ ? currentShareBalance - ownShares_ : 0;
            uint256 ownSharesBurned = sharesToRedeem > donatedShares ? sharesToRedeem - donatedShares : 0;
            _ownShares = ownSharesBurned > ownShares_ ? 0 : ownShares_ - ownSharesBurned;
            emit OwnSharesUpdated(_ownShares);
        }

        uint256 idleUnderlying = underlyingToken.balanceOf(address(this));
        if (idleUnderlying == 0) return 0;

        sent = _returnUnderlyingPrincipalToVault(idleUnderlying);
    }

    /**
     * @notice Force the Morpho vault to deallocate `_assets` from a market
     *         adapter into idle liquidity, paying the venue penalty from this
     *         Strategy's own shares.
     * @dev Vault only. `forceDeallocate` is PERMISSIONLESS on the Morpho vault,
     *      but it must be called through this wrapper because the penalty
     *      (`assets * forceDeallocatePenalty[adapter]`, protocol max 2%) is
     *      burned from the caller-designated `onBehalf` shares — calling from
     *      the Strategy means the Strategy's shares pay. The wrapper measures
     *      the actual share burn and reverts if it exceeds the init-frozen
     *      `maxForceDeallocatePenaltyBps` bound (plus 1 wei of round-trip
     *      rounding). Donated (untracked) shares absorb the burn first; only
     *      the burn that reduces `_ownShares` is a confirmed valuation loss.
     *      Immediately withdraws up to `_assets` of tracked value and transfers
     *      it to the Vault without a callback into its locked incident entry.
     *      The Vault enforces a nonzero minimum actual receipt atomically.
     */
    function forceDeallocate(address _adapter, bytes calldata _data, uint256 _assets)
        external
        onlyVault
        nonReentrantStrategy
        returns (uint256 penaltyShares, uint256 penaltyAssets, uint256 valuationLossAssets, uint256 withdrawnAssets)
    {
        uint256 shareBalanceBefore = morphoVault.balanceOf(address(this));
        morphoVault.forceDeallocate(_adapter, _data, _assets, address(this));
        uint256 shareBalanceAfter = morphoVault.balanceOf(address(this));
        if (shareBalanceAfter > shareBalanceBefore) revert MorphoV2ShareBalanceMismatch();

        penaltyShares = shareBalanceBefore - shareBalanceAfter;
        penaltyAssets = penaltyShares == 0 ? 0 : morphoVault.convertToAssets(penaltyShares);
        // Boundary note: the venue rounds penalty assets and the resulting
        // share burn UP, while `convertToAssets` here rounds DOWN, so at a
        // venue whose penalty sits exactly on `maxForceDeallocatePenaltyBps`
        // the measured burn can exceed this bound by up to one share's asset
        // value and revert. That is deliberately fail-closed (never accept
        // more than the frozen bound); the operator remedy is to retry with a
        // smaller `_assets` so the rounding contribution shrinks relative to
        // the bound.
        uint256 maxPenaltyAssets = (_assets * maxForceDeallocatePenaltyBps) / _BPS_DENOMINATOR + 1;
        if (penaltyAssets > maxPenaltyAssets) revert ForceDeallocatePenaltyExceeded(penaltyAssets, maxPenaltyAssets);

        uint256 ownShares_ = _ownShares;
        _ownShares = shareBalanceAfter < ownShares_ ? shareBalanceAfter : ownShares_;
        uint256 ownSharesCharged = ownShares_ - _ownShares;
        valuationLossAssets = ownSharesCharged == 0 ? 0 : morphoVault.convertToAssets(ownSharesCharged);
        emit OwnSharesUpdated(_ownShares);
        emit ForceDeallocated(_adapter, _assets, penaltyShares, penaltyAssets);
        withdrawnAssets = _doWithdraw(_assets);
        _accountReturnedPrincipal(_sendUnderlyingToVault(withdrawnAssets));
    }
}
"
    },
    "src/Strategies/SkyUsdcSUsdsConverter.sol": {
      "content": "// SPDX-License-Identifier: BUSL-1.1

pragma solidity 0.8.24;

import {IERC20} from "openzeppelin-contracts/contracts/token/ERC20/IERC20.sol";
import {IERC20Metadata} from "openzeppelin-contracts/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import {SafeERC20} from "openzeppelin-contracts/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "openzeppelin-contracts/contracts/security/ReentrancyGuard.sol";
import {Math} from "openzeppelin-contracts/contracts/utils/math/Math.sol";

import {ISkyLitePsmWrapper, ISkyUsdcSUsdsConverter} from "../Interfaces/ISkyUsdcSUsdsConverter.sol";

/**
 * @title SkyUsdcSUsdsConverter
 * @notice Non-upgradeable USDC <-> USDS adapter for Sky's LitePSMWrapper-USDS-USDC.
 * @dev The reverse route treats `maxUsdsIn` as a budget because Sky's `buyGem`
 *      is output-denominated in six-decimal USDC. Any unspent USDS is returned
 *      to the caller in the same transaction.
 * @custom:security-contact security@deltaforesight.xyz
 */
contract SkyUsdcSUsdsConverter is ISkyUsdcSUsdsConverter, ReentrancyGuard {
    using SafeERC20 for IERC20;

    uint256 internal constant _WAD = 1e18;
    uint256 internal constant _USDC_TO_USDS_SCALE = 1e12;
    uint256 internal constant _HALTED = type(uint256).max;

    ISkyLitePsmWrapper public immutable psmWrapper;
    IERC20 public immutable usdcToken;
    IERC20 public immutable usdsToken;

    struct SwapBalances {
        uint256 converterUsdc;
        uint256 converterUsds;
        uint256 receiverToken;
    }

    event UsdcConvertedToUsds(address indexed caller, address indexed receiver, uint256 usdcAmount, uint256 usdsOut);
    event UsdsConvertedToUsdc(address indexed caller, address indexed receiver, uint256 usdsSpent, uint256 usdcOut);

    error SkyUsdcSUsdsConverter__ZeroAddress();
    error SkyUsdcSUsdsConverter__NotContract(address account);
    error SkyUsdcSUsdsConverter__ZeroAmount();
    error SkyUsdcSUsdsConverter__InvalidUsdcDecimals(uint8 decimals);
    error SkyUsdcSUsdsConverter__InvalidUsdsDecimals(uint8 decimals);
    error SkyUsdcSUsdsConverter__InvalidFee(uint256 fee);
    error SkyUsdcSUsdsConverter__RouteHalted();
    error SkyUsdcSUsdsConverter__InsufficientUsdsOut(uint256 actual, uint256 minimum);
    error SkyUsdcSUsdsConverter__InsufficientUsdcOut(uint256 actual, uint256 minimum);
    error SkyUsdcSUsdsConverter__TokenAmountMismatch(address token, uint256 reported, uint256 actual);
    error SkyUsdcSUsdsConverter__UnexpectedTokenBalance(address token, uint256 expected, uint256 actual);

    constructor(ISkyLitePsmWrapper _psmWrapper) {
        _requireContract(address(_psmWrapper));

        address usdc = _psmWrapper.gem();
        address usds = _psmWrapper.dai();
        _requireContract(usdc);
        _requireContract(usds);

        uint8 usdcDecimals = IERC20Metadata(usdc).decimals();
        if (usdcDecimals != 6) revert SkyUsdcSUsdsConverter__InvalidUsdcDecimals(usdcDecimals);
        uint8 usdsDecimals = IERC20Metadata(usds).decimals();
        if (usdsDecimals != 18) revert SkyUsdcSUsdsConverter__InvalidUsdsDecimals(usdsDecimals);

        psmWrapper = _psmWrapper;
        usdcToken = IERC20(usdc);
        usdsToken = IERC20(usds);
    }

    function convertUsdcToUsds(uint256 _usdcAmount, uint256 _minUsdsOut, address _receiver)
        external
        nonReentrant
        returns (uint256 usdsOut)
    {
        if (_usdcAmount == 0) revert SkyUsdcSUsdsConverter__ZeroAmount();
        _requireReceiver(_receiver);

        ISkyLitePsmWrapper wrapper = psmWrapper;
        uint256 tin = wrapper.tin();
        if (tin == _HALTED) revert SkyUsdcSUsdsConverter__RouteHalted();
        if (tin > _WAD) revert SkyUsdcSUsdsConverter__InvalidFee(tin);

        IERC20 usdc = usdcToken;
        IERC20 usds = usdsToken;
        SwapBalances memory beforeBalances = SwapBalances({
            converterUsdc: usdc.balanceOf(address(this)),
            converterUsds: usds.balanceOf(address(this)),
            receiverToken: usds.balanceOf(_receiver)
        });

        usdc.safeTransferFrom(msg.sender, address(this), _usdcAmount);
        _requireBalance(usdc, beforeBalances.converterUsdc + _usdcAmount);
        usdc.forceApprove(address(wrapper), _usdcAmount);
        uint256 reportedUsdsOut = wrapper.sellGem(_receiver, _usdcAmount);
        usdc.forceApprove(address(wrapper), 0);

        _requireBalance(usdc, beforeBalances.converterUsdc);
        _requireBalance(usds, beforeBalances.converterUsds);
        usdsOut = usds.balanceOf(_receiver) - beforeBalances.receiverToken;
        if (reportedUsdsOut != usdsOut) {
            revert SkyUsdcSUsdsConverter__TokenAmountMismatch(address(usds), reportedUsdsOut, usdsOut);
        }
        if (usdsOut < _minUsdsOut) {
            revert SkyUsdcSUsdsConverter__InsufficientUsdsOut(usdsOut, _minUsdsOut);
        }

        emit UsdcConvertedToUsds(msg.sender, _receiver, _usdcAmount, usdsOut);
    }

    function convertUsdsToUsdc(uint256 _maxUsdsIn, uint256 _minUsdcOut, address _receiver)
        external
        nonReentrant
        returns (uint256 usdcOut)
    {
        if (_maxUsdsIn == 0) revert SkyUsdcSUsdsConverter__ZeroAmount();
        _requireReceiver(_receiver);

        ISkyLitePsmWrapper wrapper = psmWrapper;
        uint256 tout = wrapper.tout();
        if (tout == _HALTED) revert SkyUsdcSUsdsConverter__RouteHalted();
        if (tout > _WAD) revert SkyUsdcSUsdsConverter__InvalidFee(tout);

        usdcOut = _previewUsdsToUsdc(_maxUsdsIn, tout);
        if (usdcOut == 0 || usdcOut < _minUsdcOut) {
            revert SkyUsdcSUsdsConverter__InsufficientUsdcOut(usdcOut, _minUsdcOut);
        }

        IERC20 usdc = usdcToken;
        IERC20 usds = usdsToken;
        SwapBalances memory beforeBalances = SwapBalances({
            converterUsdc: usdc.balanceOf(address(this)),
            converterUsds: usds.balanceOf(address(this)),
            receiverToken: usdc.balanceOf(_receiver)
        });

        usds.safeTransferFrom(msg.sender, address(this), _maxUsdsIn);
        _requireBalance(usds, beforeBalances.converterUsds + _maxUsdsIn);
        usds.forceApprove(address(wrapper), _maxUsdsIn);
        uint256 reportedUsdsIn = wrapper.buyGem(_receiver, usdcOut);
        usds.forceApprove(address(wrapper), 0);

        uint256 usdsAfterSwap = usds.balanceOf(address(this));
        uint256 actualUsdsIn = beforeBalances.converterUsds + _maxUsdsIn - usdsAfterSwap;
        if (reportedUsdsIn != actualUsdsIn) {
            revert SkyUsdcSUsdsConverter__TokenAmountMismatch(address(usds), reportedUsdsIn, actualUsdsIn);
        }

        uint256 refund = _maxUsdsIn - actualUsdsIn;
        if (refund != 0) usds.safeTransfer(msg.sender, refund);

        _requireBalance(usdc, beforeBalances.converterUsdc);
        _requireBalance(usds, beforeBalances.converterUsds);
        uint256 actualUsdcOut = usdc.balanceOf(_receiver) - beforeBalances.receiverToken;
        if (actualUsdcOut != usdcOut) {
            revert SkyUsdcSUsdsConverter__TokenAmountMismatch(address(usdc), usdcOut, actualUsdcOut);
        }

        emit UsdsConvertedToUsdc(msg.sender, _receiver, actualUsdsIn, usdcOut);
    }

    function previewUsdsToUsdc(uint256 _maxUsdsIn) external view returns (uint256 usdcOut) {
        uint256 tout = psmWrapper.tout();
        if (tout == _HALTED) revert SkyUsdcSUsdsConverter__RouteHalted();
        if (tout > _WAD) revert SkyUsdcSUsdsConverter__InvalidFee(tout);
        return _previewUsdsToUsdc(_maxUsdsIn, tout);
    }

    function isUsdsToUsdcRouteHalted() external view returns (bool) {
        return psmWrapper.tout() == _HALTED;
    }

    function _previewUsdsToUsdc(uint256 _maxUsdsIn, uint256 _tout) internal pure returns (uint256 usdcOut) {
        uint256 denominator = _USDC_TO_USDS_SCALE * (_WAD + _tout);
        usdcOut = Math.mulDiv(_maxUsdsIn, _WAD, denominator);

        if (usdcOut < type(uint256).max / _USDC_TO_USDS_SCALE) {
            uint256 next = usdcOut + 1;
            if (_requiredUsds(next, _tout) <= _maxUsdsIn) usdcOut = next;
        }
    }

    function _requiredUsds(uint256 _usdcAmount, uint256 _tout) internal pure returns (uint256) {
        uint256 base = _usdcAmount * _USDC_TO_USDS_SCALE;
        return base + Math.mulDiv(base, _tout, _WAD);
    }

    function _requireReceiver(address _receiver) internal view {
        if (_receiver == address(0) || _receiver == address(this)) {
            revert SkyUsdcSUsdsConverter__ZeroAddress();
        }
    }

    function _requireContract(address _account) internal view {
        if (_account == address(0)) revert SkyUsdcSUsdsConverter__ZeroAddress();
        if (_account.code.length == 0) revert SkyUsdcSUsdsConverter__NotContract(_account);
    }

    function _requireBalance(IERC20 _token, uint256 _expected) internal view {
        uint256 actual = _token.balanceOf(address(this));
        if (actual != _expected) {
            revert SkyUsdcSUsdsConverter__UnexpectedTokenBalance(address(_token), _expected, actual);
        }
    }
}
"
    },
    "src/Strategies/SkyUsdcSUsdsStrategy.sol": {
      "content": "// SPDX-License-Identifier: BUSL-1.1

pragma solidity 0.8.24;

import "openzeppelin-contracts/contracts/interfaces/IERC4626.sol";
import "openzeppelin-contracts/contracts/token/ERC20/IERC20.sol";
import "openzeppelin-contracts/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import "openzeppelin-contracts/contracts/token/ERC20/utils/SafeERC20.sol";
import "openzeppelin-contracts/contracts/utils/math/Math.sol";

import {ISkyUsdcSUsdsConverter} from "../Interfaces/ISkyUsdcSUsdsConverter.sol";
import "./BaseStrategy.sol";

/**
 * @title SkyUsdcSUsdsStrategy - USDC -> USDS -> sUSDS asset-transforming Strategy.
 * @notice Keeps the Vault underlying as USDC while deploying idle USDC into
 *         Sky sUSDS through an explicit converter boundary.
 * @dev The Strategy values only sUSDS shares minted by its own deposit path and
 *      USDS produced by its own emergency redeem path. Direct sUSDS / USDS /
 *      USDC donations do not inflate `estimatedTotalUnderlying()` or
 *      `realizedYield()`.
 * @custom:security-contact security@deltaforesight.xyz
 */
contract SkyUsdcSUsdsStrategy is BaseStrategy {
    using SafeERC20 for IERC20;

    // =============================================================
    //                         STATE
    // =============================================================

    IERC20 public usdsToken;
    IERC4626 public susdsVault;
    ISkyUsdcSUsdsConverter public converter;
    uint256 public maxConversionLossBps;

    uint256 internal _ownSUsdsShares;
    uint256 internal _ownIdleUsds;

    /// @dev Storage gap for future upgrades of this derived contract.
    uint256[44] private __gapSkyUsdcSUsds;

    // =============================================================
    //                         CONSTANTS
    // =============================================================

    uint256 internal constant _BPS_DENOMINATOR = 10_000;
    uint256 internal constant _USDC_TO_USDS_SCALE = 1e12;
    uint256 public constant MAX_CONVERSION_LOSS_BPS = 1_000;

    // =============================================================
    //                          EVENTS
    // =============================================================

    event MaxConversionLossBpsUpdated(uint256 oldMaxConversionLossBps, uint256 newMaxConversionLossBps);
    event OwnSUsdsSharesUpdated(uint256 ownSUsdsShares);
    event OwnIdleUsdsUpdated(uint256 ownIdleUsds);
    event SkyDeposited(uint256 usdcAmount, uint256 usdsAmount, uint256 susdsShares);
    event SkySUsdsRedeemed(uint256 usdsAmount, uint256 susdsShares);
    event SkyUsdsConverted(uint256 usdsAmount, uint256 usdcAmount);

    // =============================================================
    //                          ERRORS
    // =============================================================

    error SkyUsdcSUsdsStrategy__InvalidSUsdsAsset();
    error SkyUsdcSUsdsStrategy__InvalidConverterUsdc();
    error SkyUsdcSUsdsStrategy__InvalidConverterUsds();
    error SkyUsdcSUsdsStrategy__InvalidUsdcDecimals(uint8 decimals);
    error SkyUsdcSUsdsStrategy__InvalidUsdsDecimals(uint8 decimals);
    error SkyUsdcSUsdsStrategy__InvalidSUsdsDecimals(uint8 decimals);
    error SkyUsdcSUsdsStrategy__InvalidMaxConversionLossBps(uint256 maxConversionLossBps);
    error SkyUsdcSUsdsStrategy__InsufficientUsdsOut(uint256 actual, uint256 minimum);
    error SkyUsdcSUsdsStrategy__InsufficientUsdcOut(uint256 actual, uint256 minimum);
    error SkyUsdcSUsdsStrategy__UsdsAmountMismatch(uint256 reported, uint256 actual);
    error SkyUsdcSUsdsStrategy__UsdcAmountMismatch(uint256 reported, uint256 actual);
    error SkyUsdcSUsdsStrategy__InvalidUsdsSpent(uint256 actual, uint256 maximum);
    error SkyUsdcSUsdsStrategy__SUsdsShareBalanceMismatch();
    error SkyUsdcSUsdsStrategy__SUsdsZeroShares();
    error SkyUsdcSUsdsStrategy__ZeroUsdcOut(uint256 usdsAmount);
    error SkyUsdcSUsdsStrategy__UnexpectedTokenBalance(address token, uint256 expected, uint256 actual);

    // =============================================================
    //                        INITIALIZER
    // =============================================================

    function initialize(
        address _vault,
        IERC20 _usdcUnderlying,
        address _owner,
        address _upgrader,
        IERC20 _usdsToken,
        IERC4626 _susdsVault,
        ISkyUsdcSUsdsConverter _converter,
        uint256 _maxConversionLossBps
    ) external initializer {
        __BaseStrategy_init(_vault, _usdcUnderlying, _owner, _upgrader);

        if (address(_usdsToken) == address(0)) revert ZeroAddress();
        if (address(_susdsVault) == address(0)) revert ZeroAddress();
        if (address(_converter) == address(0)) revert ZeroAddress();
        if (address(_usdsToken).code.length == 0) revert NotContract(address(_usdsToken));
        if (address(_susdsVault).code.length == 0) revert NotContract(address(_susdsVault));
        if (address(_converter).code.length == 0) revert NotContract(address(_converter));
        if (_susdsVault.asset() != address(_usdsToken)) revert SkyUsdcSUsdsStrategy__InvalidSUsdsAsset();
        if (address(_converter.usdcToken()) != address(_usdcUnderlying)) {
            revert SkyUsdcSUsdsStrategy__InvalidConverterUsdc();
        }
        if (address(_converter.usdsToken()) != address(_usdsToken)) {
            revert SkyUsdcSUsdsStrategy__InvalidConverterUsds();
        }

        uint8 usdcDecimals = IERC20Metadata(address(_usdcUnderlying)).decimals();
        if (usdcDecimals != 6) revert SkyUsdcSUsdsStrategy__InvalidUsdcDecimals(usdcDecimals);
        uint8 usdsDecimals = IERC20Metadata(address(_usdsToken)).decimals();
        if (usdsDecimals != 18) revert SkyUsdcSUsdsStrategy__InvalidUsdsDecimals(usdsDecimals);
        uint8 susdsDecimals = IERC20Metadata(address(_susdsVault)).decimals();
        if (susdsDecimals != 18) revert SkyUsdcSUsdsStrategy__InvalidSUsdsDecimals(susdsDecimals);

        _requireValidMaxConversionLossBps(_maxConversionLossBps);

        usdsToken = _usdsToken;
        susdsVault = _susdsVault;
        converter = _converter;
        maxConversionLossBps = _maxConversionLossBps;
    }

    // =============================================================
    //                    SKY-SPECIFIC VIEWS
    // =============================================================

    function ownSUsdsShares() external view returns (uint256) {
        return _ownSUsdsShares;
    }

    function ownIdleUsds() external view returns (uint256) {
        return _ownIdleUsds;
    }

    // =============================================================
    //                    SKY-SPECIFIC MUTATORS
    // =============================================================

    function setMaxConversionLossBps(uint256 _maxConversionLossBps) external onlyOwner {
        _requireValidMaxConversionLossBps(_maxConversionLossBps);
        uint256 oldMaxConversionLossBps = maxConversionLossBps;
        maxConversionLossBps = _maxConversionLossBps;
        emit MaxConversionLossBpsUpdated(oldMaxConversionLossBps, _maxConversionLossBps);
    }

    function emergencyRedeemSUsdsToUsds(uint256 _usdsAmount)
        external
        onlyOwner
        nonReentrantStrategy
        returns (uint256 usdsReceived)
    {
        usdsReceived = _redeemSUsdsForUsds(_usdsAmount);
    }

    function emergencyConvertIdleUsdsToVault(uint256 _usdsAmount, uint256 _minUsdcOut)
        external
        onlyOwner
        nonReentrantStrategy
        returns (uint256 sent)
    {
        uint256 usdsToConvert = _usdsAmount < _ownIdleUsds ? _usdsAmount : _ownIdleUsds;
        uint256 usdcReceived = _convertUsdsToUsdc(usdsToConvert, _minUsdcOut);
        if (usdcReceived == 0) return 0;

        sent = _returnUnderlyingPrincipalToVault(usdcReceived);
    }

    function emergencyWithdrawFromSky(uint256 _maxUsdsToRedeem, uint256 _minUsdcOut)
        external
        onlyOwner
        nonReentrantStrategy
        returns (uint256 sent)
    {
        if (_maxUsdsToRedeem != 0) {
            _redeemSUsdsForUsds(_maxUsdsToRedeem);
        }

        uint256 usdcReceived = _convertUsdsToUsdc(_ownIdleUsds, _minUsdcOut);
        if (usdcReceived == 0) return 0;

        sent = _returnUnderlyingPrincipalToVault(usdcReceived);
    }

    // =============================================================
    //                  BaseStrategy HOOKS
    // =============================================================

    /// @inheritdoc BaseStrategy
    function _doDeposit(uint256 _amount) internal override {
        uint256 minUsdsOut = _minimumUsdsOut(_amount);
        uint256 usdsAmount = _convertUsdcToUsds(_amount, minUsdsOut);
        uint256 susdsShares = _depositUsdsIntoSUsds(usdsAmount);

        emit SkyDeposited(_amount, usdsAmount, susdsShares);
    }

    /// @inheritdoc BaseStrategy
    function _doWithdraw(uint256 _amount) internal override returns (uint256 actual) {
        uint256 usdsTarget = _usdsTargetForUsdc(_amount);
        uint256 idleUsds = _ownIdleUsds;
        if (idleUsds < usdsTarget) {
            _redeemSUsdsForUsds(usdsTarget - idleUsds);
        }

        uint256 usdsToConvert = _ownIdleUsds < usdsTarget ? _ownIdleUsds : usdsTarget;
        actual = _convertUsdsToUsdc(usdsToConvert, _minimumUsdcOut(usdsToConvert));
    }

    /// @inheritdoc BaseStrategy
    function _estimatedTotalUnderlying() internal view override returns (uint256) {
        uint256 usdsValue = _ownedSUsdsUsdsValue() + _ownIdleUsds;
        if (usdsValue == 0) return 0;

        uint256 oneToOneUsdc = _usdsToUsdc(usdsValue);
        if (converter.isUsdsToUsdcRouteHalted()) {
            uint256 principalCached = _principal;
            return oneToOneUsdc < principalCached ? oneToOneUsdc : principalCached;
        }

        uint256 quotedUsdc = converter.previewUsdsToUsdc(usdsValue);
        return quotedUsdc < oneToOneUsdc ? quotedUsdc : oneToOneUsdc;
    }

    /// @inheritdoc BaseStrategy
    function _isSweepProtectedToken(address _token) internal view override returns (bool) {
        return super._isSweepProtectedToken(_token) || _token == address(usdsToken) || _token == address(susdsVault);
    }

    // =============================================================
    //                   INTERNAL FUNCTIONS
    // =============================================================

    function _convertUsdcToUsds(uint256 _usdcAmount, uint256 _minUsdsOut) internal returns (uint256 usdsAmount) {
        IERC20 underlyingCached = underlyingToken;
        IERC20 usds = usdsToken;
        ISkyUsdcSUsdsConverter converterCached = converter;

        uint256 usdcBalanceBefore = underlyingCached.balanceOf(address(this));
        uint256 usdsBalanceBefore = usds.balanceOf(address(this));
        underlyingCached.forceApprove(address(converterCached), _usdcAmount);
        uint256 reportedUsdsAmount = converterCached.convertUsdcToUsds(_usdcAmount, _minUsdsOut, address(this));
        underlyingCached.forceApprove(address(converterCached), 0);

        _requireTokenBalance(underlyingCached, usdcBalanceBefore - _usdcAmount);
        usdsAmount = usds.balanceOf(address(this)) - usdsBalanceBefore;
        if (reportedUsdsAmount != usdsAmount) {
            revert SkyUsdcSUsdsStrategy__UsdsAmountMismatch(reportedUsdsAmount, usdsAmount);
        }
        if (usdsAmount < _minUsdsOut) revert SkyUsdcSUsdsStrategy__InsufficientUsdsOut(usdsAmount, _minUsdsOut);
    }

    function _depositUsdsIntoSUsds(uint256 _usdsAmount) internal returns (uint256 susdsShares) {
        IERC20 usds = usdsToken;
        IERC4626 susds = susdsVault;

        uint256 usdsBalanceBefore = usds.balanceOf(address(this));
        uint256 shareBalanceBefore = susds.balanceOf(address(this));
        usds.forceApprove(address(susds), _usdsAmount);
        uint256 reportedShares = susds.deposit(_usdsAmount, address(this));
        usds.forceApprove(address(susds), 0);

        _requireTokenBalance(usds, usdsBalanceBefore - _usdsAmount);

        uint256 shareBalanceAfter = susds.balanceOf(address(this));
        if (shareBalanceAfter < shareBalanceBefore) revert SkyUsdcSUsdsStrategy__SUsdsShareBalanceMismatch();
        susdsShares = shareBalanceAfter - shareBalanceBefore;
        if (susdsShares == 0) revert SkyUsdcSUsdsStrategy__SUsdsZeroShares();
        if (susdsShares != reportedShares) revert SkyUsdcSUsdsStrategy__SUsdsShareBalanceMismatch();

        _ownSUsdsShares += susdsShares;
        emit OwnSUsdsSharesUpdated(_ownSUsdsShares);
    }

    function _redeemSUsdsForUsds(uint256 _usdsAmount) internal returns (uint256 usdsReceived) {
        if (_usdsAmount == 0) return 0;

        IERC4626 susds = susdsVault;
        uint256 ownShares = _ownSUsdsShares;
        if (ownShares == 0) return 0;

        uint256 currentShareBalance = susds.balanceOf(address(this));
        uint256 effectiveShares = ownShares < currentShareBalance ? ownShares : currentShareBalance;
        if (effectiveShares == 0) return 0;

        uint256 ownedAssets = susds.convertToAssets(effectiveShares);
        uint256 maxAssets = susds.maxWithdraw(address(this));
        uint256 assetsToWithdraw = ownedAssets < maxAssets ? ownedAssets : maxAssets;
        if (_usdsAmount < assetsToWithdraw) assetsToWithdraw = _usdsAmount;
        if (assetsToWithdraw == 0) return 0;

        uint256 usdsBalanceBefore = usdsToken.balanceOf(address(this));
        uint256 shareBalanceBefore = currentShareBalance;
        uint256 reportedBurnedShares = susds.withdraw(assetsToWithdraw, address(this), address(this));
        uint256 shareBalanceAfter = susds.balanceOf(address(this));
        if (shareBalanceAfter > shareBalanceBefore) revert SkyUsdcSUsdsStrategy__SUsdsShareBalanceMismatch();

        uint256 actualBurnedShares = shareBalanceBefore - shareBalanceAfter;
        if (actualBurnedShares != reportedBurnedShares) revert SkyUsdcSUsdsStrategy__SUsdsShareBalanceMismatch();

        usdsReceived = usdsToken.balanceOf(address(this)) - usdsBalanceBefore;
        if (usdsReceived != assetsToWithdraw) {
            revert SkyUsdcSUsdsStrategy__UsdsAmountMismatch(assetsToWithdraw, usdsReceived);
        }

        _ownSUsdsShares = actualBurnedShares > ownShares ? 0 : ownShares - actualBurnedShares;
        _increaseOwnIdleUsds(usdsReceived);

        emit OwnSUsdsSharesUpdated(_ownSUsdsShares);
        emit SkySUsdsRedeemed(usdsReceived, actualBurnedShares);
    }

    function _convertUsdsToUsdc(uint256 _usdsAmount, uint256 _minUsdcOut) internal returns (uint256 usdcAmount) {
        if (_usdsAmount == 0) return 0;

        IERC20 usds = usdsToken;
        IERC20 underlyingCached = underlyingToken;
        ISkyUsdcSUsdsConverter converterCached = converter;
        uint256 enforcedMinUsdcOut = _minimumUsdcOut(_usdsAmount);
        if (_minUsdcOut > enforcedMinUsdcOut) enforcedMinUsdcOut = _minUsdcOut;

        uint256 usdsBalanceBefore = usds.balanceOf(address(this));
        uint256 usdcBalanceBefore = underlyingCached.balanceOf(address(this));
        usds.forceApprove(address(converterCached), _usdsAmount);
        uint256 reportedUsdcAmount = converterCached.convertUsdsToUsdc(_usdsAmount, enforcedMinUsdcOut, address(this));
        usds.forceApprove(address(converterCached), 0);

        uint256 usdsBalanceAfter = usds.balanceOf(address(this));
        if (usdsBalanceAfter > usdsBalanceBefore) {
            revert SkyUsdcSUsdsStrategy__UnexpectedTokenBalance(address(usds), usdsBalanceBefore, usdsBalanceAfter);
        }
        uint256 usdsSpent = usdsBalanceBefore - usdsBalanceAfter;
        if (usdsSpent == 0 || usdsSpent > _usdsAmount) {
            revert SkyUsdcSUsdsStrategy__InvalidUsdsSpent(usdsSpent, _usdsAmount);
        }
        usdcAmount = underlyingCached.balanceOf(address(this)) - usdcBalanceBefore;
        if (reportedUsdcAmount != usdcAmount) {
            revert SkyUsdcSUsdsStrategy__UsdcAmountMismatch(reportedUsdcAmount, usdcAmount);
        }
        if (usdcAmount < enforcedMinUsdcOut) {
            revert SkyUsdcSUsdsStrategy__InsufficientUsdcOut(usdcAmount, enforcedMinUsdcOut);
        }
        if (usdcAmount == 0) revert SkyUsdcSUsdsStrategy__ZeroUsdcOut(_usdsAmount);

        _decreaseOwnIdleUsds(usdsSpent);
        emit SkyUsdsConverted(usdsSpent, usdcAmount);
    }

    function _increaseOwnIdleUsds(uint256 _amount) internal {
        if (_amount == 0) return;
        _ownIdleUsds += _amount;
        emit OwnIdleUsdsUpdated(_ownIdleUsds);
    }

    function _decreaseOwnIdleUsds(uint256 _amount) internal {
        if (_amount == 0) return;
        uint256 idleUsds = _ownIdleUsds;
        _ownIdleUsds = _amount > idleUsds ? 0 : idleUsds - _amount;
        emit OwnIdleUsdsUpdated(_ownIdleUsds);
    }

    function _ownedSUsdsUsdsValue() internal view returns (uint256) {
        uint256 currentShareBalance = susdsVault.balanceOf(address(this));
        uint256 effectiveShares = _ownSUsdsShares < currentShareBalance ? _ownSUsdsShares : currentShareBalance;
        if (effectiveShares == 0) return 0;
        return susdsVault.convertToAssets(effectiveShares);
    }

    function _minimumUsdsOut(uint256 _usdcAmount) internal view returns (uint256) {
        return Math.mulDiv(_usdcToUsds(_usdcAmount), _BPS_DENOMINATOR - maxConversionLossBps, _BPS_DENOMINATOR);
    }

    function _minimumUsdcOut(uint256 _usdsAmount) internal view returns (uint256) {
        return Math.mulDiv(_usdsToUsdc(_usdsAmount), _BPS_DENOMINATOR - maxConversionLossBps, _BPS_DENOMINATOR);
    }

    function _usdcToUsdsWithLossBuffer(uint256 _usdcAmount) internal view returns (uint256) {
        uint256 denominator = _BPS_DENOMINATOR - maxConversionLossBps;
        return Math.mulDiv(_usdcAmount, _USDC_TO_USDS_SCALE * _BPS_DENOMINATOR, denominator, Math.Rounding.Up);
    }

    function _usdsTargetForUsdc(uint256 _usdcAmount) internal view returns (uint256) {
        uint256 oneToOneUsds = _usdcToUsds(_usdcAmount);
        if (converter.previewUsdsToUsdc(oneToOneUsds) >= _usdcAmount) return oneToOneUsds;
        return _usdcToUsdsWithLossBuffer(_usdcAmount);
    }

    function _usdcToUsds(uint256 _usdcAmount) internal pure returns (uint256) {
        return _usdcAmount * _USDC_TO_USDS_SCALE;
    }

    function _usdsToUsdc(uint256 _usdsAmount) internal pure returns (uint256) {
        return _usdsAmount / _USDC_TO_USDS_SCALE;
    }

    function _requireValidMaxConversionLossBps(uint256 _maxConversionLossBps) internal pure {
        if (_maxConversionLossBps > MAX_CONVERSION_LOSS_BPS) {
            revert SkyUsdcSUsdsStrategy__InvalidMaxConversionLossBps(_maxConversionLossBps);
        }
    }

    function _requireTokenBalance(IERC20 _token, uint256 _expectedBalance) internal view {
        uint256 actualBalance = _token.balanceOf(address(this));
        if (actualBalance != _expectedBalance) {
            revert SkyUsdcSUsdsStrategy__UnexpectedTokenBalance(address(_token), _expectedBalance, actualBalance);
        }
    }
}
"
    },
    "src/TroveManager.sol": {
      "content": "// SPDX-License-Identifier: BUSL-1.1

pragma solidity 0.8.24;

import "openzeppelin-contracts/contracts/token/ERC20/IERC20.sol";
import "openzeppelin-contracts/contracts/token/ERC20/utils/SafeERC20.sol";

import "./Interfaces/ITroveManager.sol";
import "./Interfaces/IAddressesRegistry.sol";
import "./Interfaces/IStabilityPool.sol";
import "./Interfaces/ICollSurplusPool.sol";
import "./Interfaces/IJpydfToken.sol";
import "./Interfaces/ISortedTroves.sol";
import "./Interfaces/ITroveEvents.sol";
import "./Interfaces/ITroveNFT.sol";
import "./Interfaces/ICollateralRegistry.sol";
import "./Interfaces/IWETH.sol";
import "./Dependencies/LiquityBase.sol";

contract TroveManager is LiquityBase, ITroveManager, ITroveEvents {
    using SafeERC20 for IERC20;

    // --- Connected contract declarations ---

    IAddressesRegistry internal immutable addressesRegistry;
    ITroveNFT public troveNFT;
    IBorrowerOperations public borrowerOperations;
    IStabilityPool public stabilityPool;
    address internal gasPoolAddress;
    ICollSurplusPool internal collSurplusPool;
    IJpydfToken internal jpydfToken;
    // A doubly linked list of Troves, sorted by their interest rate
    ISortedTroves public sortedTroves;
    ICollateralRegistry internal collateralRegistry;
    // Wrapped ETH for liquidation reserve (gas compensation)
    IWETH internal immutable WETH;

    // Critical system collateral ratio. If the system's total collateral ratio (TCR) falls below the CCR, some borrowing operation restrictions are applied
    uint256 public CCR;

    // Minimum collateral ratio for individual troves
    uint256 internal MCR;
    // Shutdown system collateral ratio. If the system's total collateral ratio (TCR) for a given collateral falls below the SCR,
    // the protocol triggers the shutdown of the borrow market and permanently disables all borrowing operations except for closing Troves.
    uint256 internal SCR;

    // Liquidation penalty for troves offset to the SP
    uint256 internal LIQUIDATION_PENALTY_SP;
    // Liquidation penalty for troves redistributed
    uint256 internal LIQUIDATION_PENALTY_REDISTRIBUTION;

    // --- Data structures ---

    // Store the necessary data for a trove
    struct Trove {
        uint256 debt;
        uint256 coll;
        uint256 stake;
        Status status;
        uint64 arrayIndex;
        uint64 lastDebtUpdateTime;
        uint64 lastInterestRateAdjTime;
        uint256 annualInterestRate;
        address interestBatchManager;
        uint256 batchDebtShares;
    }

    mapping(uint256 => Trove) public Troves;

    // Store the necessary data for an interest batch manager. We treat each batch as a “big trove”.
    // Each trove has a share of the debt of the global batch. Collateral is stored per trove (as CRs are different)
    // Still the total amount of batch collateral is stored for informational purposes
    struct Batch {
        uint256 debt;
        uint256 coll;
        uint64 arrayIndex;
        uint64 lastDebtUpdateTime;
        uint64 lastInterestRateAdjTime;
        uint256 annualInterestRate;
        uint256 annualManagementFee;
        uint256 totalDebtShares;
    }

    mapping(address => Batch) internal batches;

    uint256 internal totalStakes;

    // Snapshot of the value of totalStakes, taken immediately after the latest liquidation
    uint256 internal totalStakesSnapshot;

    // Snapshot of the total collateral across the ActivePool and DefaultPool, immediately after the latest liquidation.
    uint256 internal totalCollateralSnapshot;

    /*
    * L_coll and L_jpydfDebt track the sums of accumulated liquidation rewards per unit staked. During its lifetime, each stake earns:
    *
    * An Coll gain of ( stake * [L_coll - L_coll(0)] )
    * A jpydfDebt increase  of ( stake * [L_jpydfDebt - L_jpydfDebt(0)] )
    *
    * Where L_coll(0) and L_jpydfDebt(0) are snapshots of L_coll and L_jpydfDebt for the active Trove taken at the instant the stake was made
    */
    uint256 internal L_coll;
    uint256 internal L_jpydfDebt;

    // Map active troves to their RewardSnapshot
    mapping(uint256 => RewardSnapshot) public rewardSnapshots;

    // Object containing the Coll and JPYDF snapshots for a given active trove
    struct RewardSnapshot {
        uint256 coll;
        uint256 jpydfDebt;
    }

    // Array of all active trove addresses - used to compute an approximate hint off-chain, for the sorted list insertion
    uint256[] internal TroveIds;
    // Array of all batch managers - used to fetch them off-chain
    address[] public batchIds;

    uint256 public lastZombieTroveId;

    // Error trackers for the trove redistribution calculation
    uint256 internal lastCollError_Redistribution;
    uint256 internal lastJpydfDebtError_Redistribution;

    // Timestamp at which branch was shut down. 0 if not shut down.
    uint256 public shutdownTime;

    // Set at deployment, then finalized once with risk parameters on reserved branches.
    uint256 internal collGasCompensationCap;

    /*
    * --- Variable container structs for liquidations ---
    *
    * These structs are used to hold, return and assign variables inside the liquidation functions,
    * in order to avoid the error: "CompilerError: Stack too deep".
    **/

    struct LiquidationValues {
        uint256 collGasCompensation;
        uint256 debtToOffset;
        uint256 collToSendToSP;
        uint256 debtToRedistribute;
        uint256 collToRedistribute;
        uint256 collSurplus;
        uint256 ETHGasCompensation;
        uint256 oldWeightedRecordedDebt;
        uint256 newWeightedRecordedDebt;
    }

    // --- Variable container structs for redemptions ---

    struct RedeemCollateralValues {
        uint256 totalCollFee;
        uint256 remainingJpydf;
        address lastBatchUpdatedInterest;
        uint256 nextUserToCheck;
    }

    struct SingleRedemptionValues {
        uint256 troveId;
        address batchAddress;
        uint256 jpydfLot;
        uint256 collLot;
        uint256 collFee;
        uint256 appliedRedistJpydfDebtGain;
        uint256 oldWeightedRecordedDebt;
        uint256 newWeightedRecordedDebt;
        uint256 newStake;
        bool isZombieTrove;
        LatestTroveData trove;
        LatestBatchData batch;
    }

    // --- Errors ---

    error EmptyData();
    error NothingToLiquidate();
    error CallerNotAddressesRegistry();
    error CallerNotBorrowerOperations();
    error CallerNotCollateralRegistry();
    error OnlyOneTroveLeft();
    error NotShutDown();
    error ZeroAmount();
    error NotEnoughJpydfBalance();
    error MinCollNotReached(uint256 _coll);
    error BatchSharesRatioTooHigh();

    // --- Events ---

    event TroveNFTAddressChanged(address _newTroveNFTAddress);
    event BorrowerOperationsAddressChanged(address _newBorrowerOperationsAddress);
    event JpydfTokenAddressChanged(address _newJpydfTokenAddress);
    event StabilityPoolAddressChanged(address _stabilityPoolAddress);
    event GasPoolAddressChanged(address _gasPoolAddress);
    event CollSurplusPoolAddressChanged(address _collSurplusPoolAddress);
    event SortedTrovesAddressChanged(address _sortedTrovesAddress);
    event CollateralRegistryAddressChanged(address _collateralRegistryAddress);

    constructor(IAddressesRegistry _addressesRegistry, uint256 _collGasCompensationCap)
        LiquityBase(_addressesRegistry)
    {
        require(_collGasCompensationCap > 0 && _collGasCompensationCap <= COLL_GAS_COMPENSATION_CAP);
        collGasCompensationCap = _collGasCompensationCap;
        addressesRegistry = _addressesRegistry;
        CCR = _addressesRegistry.CCR();
        MCR = _addressesRegistry.MCR();
        SCR = _addressesRegistry.SCR();
        LIQUIDATION_PENALTY_SP = _addressesRegistry.LIQUIDATION_PENALTY_SP();
        LIQUIDATION_PENALTY_REDISTRIBUTION = _addressesRegistry.LIQUIDATION_PENALTY_REDISTRIBUTION();

        troveNFT = _addressesRegistry.troveNFT();
        borrowerOperations = _addressesRegistry.borrowerOperations();
        stabilityPool = _addressesRegistry.stabilityPool();
        gasPoolAddress = _addressesRegistry.gasPoolAddress();
        collSurplusPool = _addressesRegistry.collSurplusPool();
        jpydfToken = _addressesRegistry.jpydfToken();
        sortedTroves = _addressesRegistry.sortedTroves();
        WETH = _addressesRegistry.WETH();
        collateralRegistry = _addressesRegistry.collateralRegistry();

        emit TroveNFTAddressChanged(address(troveNFT));
        emit BorrowerOperationsAddressChanged(address(borrowerOperations));
        emit StabilityPoolAddressChanged(address(stabilityPool));
        emit GasPoolAddressChanged(gasPoolAddress);
        emit CollSurplusPoolAddressChanged(address(collSurplusPool));
        emit JpydfTokenAddressChanged(address(jpydfToken));
        emit SortedTrovesAddressChanged(address(sortedTroves));
        emit CollateralRegistryAddressChanged(address(collateralRegistry));
    }

    function syncRiskParams(RiskParams calldata _riskParams) external override {
        if (msg.sender != address(addressesRegistry)) revert CallerNotAddressesRegistry();

        CCR = _riskParams.CCR;
        MCR = _riskParams.MCR;
        SCR = _riskParams.SCR;
        LIQUIDATION_PENALTY_SP = _riskParams.LIQUIDATION_PENALTY_SP;
        LIQUIDATION_PENALTY_REDISTRIBUTION = _riskParams.LIQUIDATION_PENALTY_REDISTRIBUTION;
        collGasCompensationCap = _riskParams.COLL_GAS_COMPENSATION_CAP;
    }

    // --- Getters ---

    function getTroveIdsCount() external view override returns (uint256) {
        return TroveIds.length;
    }

    function getTroveFromTroveIdsArray(uint256 _index) external view override returns (uint256) {
        return TroveIds[_index];
    }

    // --- Trove Liquidation functions ---

    // --- Inner single liquidation functions ---

    // Liquidate one trove
    function _liquidate(
        IDefaultPool _defaultPool,
        uint256 _troveId,
        uint256 _jpydfInSPForOffsets,
        uint256 _price,
        LatestTroveData memory trove,
        LiquidationValues memory singleLiquidation
    ) internal {
        address owner = troveNFT.ownerOf(_troveId);

        _getLatestTroveData(_troveId, trove);
        address batchAddress = _getBatchManager(_troveId);
        bool isTroveInBatch = batchAddress != address(0);
        LatestBatchData memory batch;
        if (isTroveInBatch) _getLatestBatchData(batchAddress, batch);

        _movePendingTroveRewardsToActivePool(_defaultPool, trove.redistJpydfDebtGain, trove.redistCollGain);

        (
            singleLiquidation.debtToOffset,
            singleLiquidation.collToSendToSP,
            singleLiquidation.collGasCompensation,
            singleLiquidation.debtToRedistribute,
            singleLiquidation.collToRedistribute,
            singleLiquidation.collSurplus
        ) = _getOffsetAndRedistributionVals(trove.entireDebt, trove.entireColl, _jpydfInSPForOffsets, _price);

        TroveChange memory troveChange;
        troveChange.collDecrease = trove.entireColl;
        troveChange.debtDecrease = trove.entireDebt;
        troveChange.appliedRedistCollGain = trove.redistCollGain;
        troveChange.appliedRedistJpydfDebtGain = trove.redistJpydfDebtGain;
        _closeTrove(
            _troveId,
            troveChange,
            batchAddress,
            batch.entireCollWithoutRedistribution,
            batch.entireDebtWithoutRedistribution,
            Status.closedByLiquidation
        );

        if (isTroveInBatch) {
            // the parenthesis in the old weighted term equals `recordedDebt + accruedInterest + accruedBatchManagementFee`
            // We want to capture last 2 ones, as the batch part only has recorded debt. The recorded debt of the trove is duplicated there,
            // but it needs to be, because it’s also included in `entireDebtWithoutRedistribution` in the next line.
            // So in the end we add it once and subtract it twice, which is the same as subtracting it once.
            singleLiquidation.oldWeightedRecordedDebt =
                batch.weightedRecordedDebt + (trove.entireDebt - trove.redistJpydfDebtGain) * batch.annualInterestRate;
            singleLiquidation.newWeightedRecordedDebt = batch.entireDebtWithoutRedistribution * batch.annualInterestRate;
            // Mint batch management fee
            troveChange.batchAccruedManagementFee = batch.accruedManagementFee;
            troveChange.oldWeightedRecordedBatchManagementFee = batch.weightedRecordedBatchManagementFee
                + (trove.entireDebt - trove.redistJpydfDebtGain) * batch.annualManagementFee;
            troveChange.newWeightedRecordedBatchManagementFee =
                batch.entireDebtWithoutRedistribution * batch.annualManagementFee;
            activePool.mintBatchManagementFeeAndAccountForChange(troveChange, batchAddress);
        } else {
            singleLiquidation.oldWeightedRecordedDebt = trove.weightedRecordedDebt;
        }

        // Difference between liquidation penalty and liquidation threshold
        if (singleLiquidation.collSurplus > 0) {
            collSurplusPool.accountSurplus(owner, singleLiquidation.collSurplus);
        }

        // Wipe out state in BO
        borrowerOperations.onLiquidateTrove(_troveId);

        emit TroveUpdated({
            _troveId: _troveId,
            _debt: 0,
            _coll: 0,
            _stake: 0,
            _annualInterestRate: 0,
            _snapshotOfTotalCollRedist: 0,
            _snapshotOfTotalDebtRedist: 0
        });

        emit TroveOperation({
            _troveId: _troveId,
            _operation: Operation.liquidate,
            _annualInterestRate: 0,
            _debtIncreaseFromRedist: trove.redistJpydfDebtGain,
            _debtIncreaseFromUpfrontFee: 0,
            _debtChangeFromOperation: -int256(trove.entireDebt),
            _collIncreaseFromRedist: trove.redistCollGain,
            _collChangeFromOperation: -int256(trove.entireColl)
        });

        if (isTroveInBatch) {
            emit BatchUpdated({
                _interestBatchManager: batchAddress,
                _operation: BatchOperation.exitBatch,
                _debt: batches[batchAddress].debt,
                _coll: batches[batchAddress].coll,
                _annualInterestRate: batch.annualInterestRate,
                _annualManagementFee: batch.annualManagementFee,
                _totalDebtShares: batches[batchAddress].totalDebtShares,
                _debtIncreaseFromUpfrontFee: 0
            });
        }
    }

    // Return the amount of Coll to be drawn from a trove's collateral and sent as gas compensation.
    function _getCollGasCompensation(uint256 _coll) internal view returns (uint256) {
        return LiquityMath._min(_coll / COLL_GAS_COMPENSATION_DIVISOR, collGasCompensationCap);
    }

    /* In a full liquidation, returns the values for a trove's coll and debt to be offset, and coll and debt to be
    * redistributed to active troves.
    */
    function _getOffsetAndRedistributionVals(
        uint256 _entireTroveDebt,
        uint256 _entireTroveColl,
        uint256 _jpydfInSPForOffsets,
        uint256 _price
    )
        internal
        view
        returns (
            uint256 debtToOffset,
            uint256 collToSendToSP,
            uint256 collGasCompensation,
            uint256 debtToRedistribute,
            uint256 collToRedistribute,
            uint256 collSurplus
        )
    {
        uint256 collSPPortion;
        /*
         * Offset as much debt & collateral as possible against the Stability Pool, and redistribute the remainder
         * between all active troves.
         *
         *  If the trove's debt is larger than the deposited JPYDF in the Stability Pool:
         *
         *  - Offset an amount of the trove's debt equal to the JPYDF in the Stability Pool
         *  - Send a fraction of the trove's collateral to the Stability Pool, equal to the fraction of its offset debt
         *
         */
        if (_jpydfInSPForOffsets > 0) {
            debtToOffset = LiquityMath._min(_entireTroveDebt, _jpydfInSPForOffsets);
            collSPPortion = _entireTroveColl * debtToOffset / _entireTroveDebt;

            collGasCompensation = _getCollGasCompensation(collSPPortion);
            uint256 collToOffset = collSPPortion - collGasCompensation;

            (collToSendToSP, collSurplus) =
                _getCollPenaltyAndSurplus(collToOffset, debtToOffset, LIQUIDATION_PENALTY_SP, _price);
        }

        // Redistribution
        debtToRedistribute = _entireTroveDebt - debtToOffset;
        if (debtToRedistribute > 0) {
            uint256 collRedistributionPortion = _entireTroveColl - collSPPortion;
            if (collRedistributionPortion > 0) {
                (collToRedistribute, collSurplus) = _getCollPenaltyAndSurplus(
                    collRedistributionPortion + collSurplus, // Coll surplus from offset can be eaten up by red. penalty
                    debtToRedistribute,
                    LIQUIDATION_PENALTY_REDISTRIBUTION, // _penaltyRatio
                    _price
                );
            }
        }
        // assert(_collToLiquidate == collToSendToSP + collToRedistribute + collSurplus);
    }

    function _getCollPenaltyAndSurplus(
        uint256 _collToLiquidate,
        uint256 _debtToLiquidate,
        uint256 _penaltyRatio,
        uint256 _price
    ) internal pure returns (uint256 seizedColl, uint256 collSurplus) {
        uint256 maxSeizedColl = _debtToLiquidate * (DECIMAL_PRECISION + _penaltyRatio) / _price;
        if (_collToLiquidate > maxSeizedColl) {
            seizedColl = maxSeizedColl;
            collSurplus = _collToLiquidate - maxSeizedColl;
        } else {
            seizedColl = _collToLiquidate;
            collSurplus = 0;
        }
    }

    /*
     * Attempt to liquidate a custom list of troves provided by the caller.
     */
    function batchLiquidateTroves(uint256[] memory _troveArray) public override {
        if (_troveArray.length == 0) {
            revert EmptyData();
        }

        IActivePool activePoolCached = activePool;
        IDefaultPool defaultPoolCached = defaultPool;
        IStabilityPool stabilityPoolCached = stabilityPool;

        TroveChange memory troveChange;
        LiquidationValues memory totals;

        (uint256 price, bool oracleFailure) = priceFeed.fetchPrice();
        if (oracleFailure) return;

        // - If the SP has total deposits >= 1e18, we leave 1e18 in it untouched.
        // - If it has 0 < x < 1e18 total deposits, we leave x in it.
        uint256 totalJpydfDeposits = stabilityPoolCached.getTotalJpydfDeposits();
        uint256 jpydfToLeaveInSP = LiquityMath._min(MIN_JPYDF_IN_SP, totalJpydfDeposits);
        uint256 jpydfInSPForOffsets = totalJpydfDeposits - jpydfToLeaveInSP;

        // Perform the appropriate liquidation sequence - tally values and obtain their totals.
        _batchLiquidateTroves(defaultPoolCached, price, jpydfInSPForOffsets, _troveArray, totals, troveChange);

        if (troveChange.debtDecrease == 0) {
            revert NothingToLiquidate();
        }

        activePoolCached.mintAggInterestAndAccountForTroveChange(troveChange, address(0));

        // Move liquidated Coll and JPYDF to the appropriate pools
        if (totals.debtToOffset > 0 || totals.collToSendToSP > 0) {
            stabilityPoolCached.offset(totals.debtToOffset, totals.collToSendToSP);
        }
        // we check amount is not zero inside
        _redistributeDebtAndColl(
            activePoolCached, defaultPoolCached, totals.debtToRedistribute, totals.collToRedistribute
        );
        if (totals.collSurplus > 0) {
            activePoolCached.sendColl(address(collSurplusPool), totals.collSurplus);
        }

        // Update system snapshots
        _updateSystemSnapshots_excludeCollRemainder(activePoolCached, totals.collGasCompensation);

        emit Liquidation(
            totals.debtToOffset,
            totals.debtToRedistribute,
            totals.ETHGasCompensation,
            totals.collGasCompensation,
            totals.collToSendToSP,
            totals.collToRedistribute,
            totals.collSurplus,
            L_coll,
            L_jpydfDebt,
            price
        );

        // Send gas compensation to caller
        _sendGasCompensation(activePoolCached, msg.sender, totals.ETHGasCompensation, totals.collGasCompensation);
    }

    function _isActiveOrZombie(Status _status) internal pure returns (bool) {
        return _status == Status.active || _status == Status.zombie;
    }

    function _batchLiquidateTroves(
        IDefaultPool _defaultPool,
        uint256 _price,
        uint256 _jpydfInSPForOffsets,
        uint256[] memory _troveArray,
        LiquidationValues memory totals,
        TroveChange memory troveChange
    ) internal {
        uint256 remainingJpydfInSPForOffsets = _jpydfInSPForOffsets;

        for (uint256 i = 0; i < _troveArray.length; i++) {
            uint256 troveId = _troveArray[i];

            // Skip non-liquidatable troves
            if (!_isActiveOrZombie(Troves[troveId].status)) continue;

            uint256 ICR = getCurrentICR(troveId, _price);

            if (ICR < MCR) {
                LiquidationValues memory singleLiquidation;
                LatestTroveData memory trove;

                _liquidate(_defaultPool, troveId, remainingJpydfInSPForOffsets, _price, trove, singleLiquidation);
                remainingJpydfInSPForOffsets -= singleLiquidation.debtToOffset;

                // Add liquidation values to their respective running totals
                _addLiquidationValuesToTotals(trove, singleLiquidation, totals, troveChange);
            }
        }
    }

    // --- Liquidation helper functions ---

    // Adds all values from `singleLiquidation` to their respective totals in `totals` in-place
    function _addLiquidationValuesToTotals(
        LatestTroveData memory _trove,
        LiquidationValues memory _singleLiquidation,
        LiquidationValues memory totals,
        TroveChange memory troveChange
    ) internal pure {
        // Tally all the values with their respective running totals
        totals.collGasCompensation += _singleLiquidation.collGasCompensation;
        totals.ETHGasCompensation += ETH_GAS_COMPENSATION;
        troveChange.debtDecrease += _trove.entireDebt;
        troveChange.collDecrease += _trove.entireColl;
        troveChange.appliedRedistJpydfDebtGain += _trove.redistJpydfDebtGain;
        troveChange.oldWeightedRecordedDebt += _singleLiquidation.oldWeightedRecordedDebt;
        troveChange.newWeightedRecordedDebt += _singleLiquidation.newWeightedRecordedDebt;
        totals.debtToOffset += _singleLiquidation.debtToOffset;
        totals.collToSendToSP += _singleLiquidation.collToSendToSP;
        totals.debtToRedistribute += _singleLiquidation.debtToRedistribute;
        totals.collToRedistribute += _singleLiquidation.collToRedistribute;
        totals.collSurplus += _singleLiquidation.collSurplus;
    }

    function _sendGasCompensation(IActivePool _activePool, address _liquidator, uint256 _eth, uint256 _coll) internal {
        if (_eth > 0) {
            IERC20(address(WETH)).safeTransferFrom(gasPoolAddress, _liquidator, _eth);
        }

        if (_coll > 0) {
            _activePool.sendColl(_liquidator, _coll);
        }
    }

    // Move a Trove's pending debt and collateral rewards from distributions, from the Default Pool to the Active Pool
    function _movePendingTroveRewardsToActivePool(IDefaultPool _defaultPool, uint256 _jpydfDebt, uint256 _coll)
        internal
    {
        if (_jpydfDebt > 0) {
            _defaultPool.decreaseJpydfDebt(_jpydfDebt);
        }

        if (_coll > 0) {
            _defaultPool.sendCollToActivePool(_coll);
        }
    }

    // --- Redemption functions ---

    function _applySingleRedemption(
        IDefaultPool _defaultPool,
        SingleRedemptionValues memory _singleRedemption,
        bool _isTroveInBatch
    ) internal returns (uint256) {
        // Decrease the debt and collateral of the current Trove according to the JPYDF lot and corresponding ETH to send
        uint256 newDebt = _singleRedemption.trove.entireDebt - _singleRedemption.jpydfLot;
        uint256 newColl = _singleRedemption.trove.entireColl - _singleRedemption.collLot;

        _singleRedemption.appliedRedistJpydfDebtGain = _singleRedemption.trove.redistJpydfDebtGain;

        if (_isTroveInBatch) {
            _getLatestBatchData(_singleRedemption.batchAddress, _singleRedemption.batch);
            // We know jpydfLot <= trove entire debt, so this subtraction is safe
            uint256 newAmountForWeightedDebt = _singleRedemption.batch.entireDebtWithoutRedistribution
                + _singleRedemption.trove.redistJpydfDebtGain - _singleRedemption.jpydfLot;
            _singleRedemption.oldWeightedRecordedDebt = _singleRedemption.batch.weightedRecordedDebt;
            _singleRedemption.newWeightedRecordedDebt =
                newAmountForWeightedDebt * _singleRedemption.batch.annualInterestRate;

            TroveChange memory troveChange;
            troveChange.debtDecrease = _singleRedemption.jpydfLot;
            troveChange.collDecrease = _singleRedemption.collLot;
            troveChange.appliedRedistJpydfDebtGain = _singleRedemption.trove.redistJpydfDebtGain;
            troveChange.appliedRedistCollGain = _singleRedemption.trove.redistCollGain;
            // batchAccruedManagementFee is handled in the outer function
            troveChange.oldWeightedRecordedBatchManagementFee =
                _singleRedemption.batch.weightedRecordedBatchManagementFee;
            troveChange.newWeightedRecordedBatchManagementFee =
                newAmountForWeightedDebt * _singleRedemption.batch.annualManagementFee;

            activePool.mintBatchManagementFeeAndAccountForChange(troveChange, _singleRedemption.batchAddress);

            Troves[_singleRedemption.troveId].coll = newColl;
            // interest and fee were updated in the outer function
            // This call could revert due to BatchSharesRatioTooHigh if trove.redistCollGain > jpydfLot
            // so we skip that check to avoid blocking redemptions
            _updateBatchShares(
                _singleRedemption.troveId,
                _singleRedemption.batchAddress,
                troveChange,
                newDebt,
                _singleRedemption.batch.entireCollWithoutRedistribution,
                _singleRedemption.batch.entireDebtWithoutRedistribution,
                false // _checkBatchSharesRatio
            );
        } else {
            _singleRedemption.oldWeightedRecordedDebt = _singleRedemption.trove.weightedRecordedDebt;
            _singleRedemption.newWeightedRecordedDebt = newDebt * _singleRedemption.trove.annualInterestRate;
            Troves[_singleRedemption.troveId].debt = newDebt;
            Troves[_singleRedemption.troveId].coll = newColl;
            Troves[_singleRedemption.troveId].lastDebtUpdateTime = uint64(block.timestamp);
        }

        _singleRedemption.newStake = _updateStakeAndTotalStakes(_singleRedemption.troveId, newColl);
        _movePendingTroveRewardsToActivePool(
            _defaultPool, _singleRedemption.trove.redistJpydfDebtGain, _singleRedemption.trove.redistCollGain
        );
        _updateTroveRewardSnapshots(_singleRedemption.troveId);

        if (_isTroveInBatch) {
            emit BatchedTroveUpdated({
                _troveId: _singleRedemption.troveId,
                _interestBatchManager: _singleRedemption.batchAddress,
                _batchDebtShares: Troves[_singleRedemption.troveId].batchDebtShares,
                _coll: newColl,
                _stake: _singleRedemption.newStake,
                _snapshotOfTotalCollRedist: L_coll,
                _snapshotOfTotalDebtRedist: L_jpydfDebt
            });
        } else {
            emit TroveUpdated({
                _troveId: _singleRedemption.troveId,
                _debt: newDebt,
                _coll: newColl,
                _stake: _singleRedemption.newStake,
                _annualInterestRate: _singleRedemption.trove.annualInterestRate,
                _snapshotOfTotalCollRedist: L_coll,
                _snapshotOfTotalDebtRedist: L_jpydfDebt
            });
        }

        emit TroveOperation({
            _troveId: _singleRedemption.troveId,
            _operation: Operation.redeemCollateral,
            _annualInterestRate: _singleRedemption.trove.annualInterestRate,
            _debtIncreaseFromRedist: _singleRedemption.trove.redistJpydfDebtGain,
            _debtIncreaseFromUpfrontFee: 0,
            _debtChangeFromOperation: -int256(_singleRedemption.jpydfLot),
            _collIncreaseFromRedist: _singleRedemption.trove.redistCollGain,
            _collChangeFromOperation: -int256(_singleRedemption.collLot)
        });

        if (_isTroveInBatch) {
            emit BatchUpdated({
                _interestBatchManager: _singleRedemption.batchAddress,
                _operation: BatchOperation.troveChange,
                _debt: batches[_singleRedemption.batchAddress].debt,
                _coll: batches[_singleRedemption.batchAddress].coll,
                _annualInterestRate: _singleRedemption.batch.annualInterestRate,
                _annualManagementFee: _singleRedemption.batch.annualManagementFee,
                _totalDebtShares: batches[_singleRedemption.batchAddress].totalDebtShares,
                _debtIncreaseFromUpfrontFee: 0
            });
        }

        emit RedemptionFeePaidToTrove(_singleRedemption.troveId, _singleRedemption.collFee);

        return newDebt;
    }

    // Redeem as much collateral as possible from _borrower's Trove in exchange for JPYDF up to _maxJpydfAmount
    function _redeemCollateralFromTrove(
        IDefaultPool _defaultPool,
        SingleRedemptionValues memory _singleRedemption,
        uint256 _maxJpydfAmount,
        uint256 _redemptionPrice,
        uint256 _redemptionRate
    ) internal {
        _getLatestTroveData(_singleRedemption.troveId, _singleRedemption.trove);

        // Determine the remaining amount (lot) to be redeemed, capped by the entire debt of the Trove
        _singleRedemption.jpydfLot = LiquityMath._min(_maxJpydfAmount, _singleRedemption.trove.entireDebt);

        // Get the amount of Coll equal in USD value to the jpydfLot redeemed
        uint256 correspondingColl = _singleRedemption.jpydfLot * DECIMAL_PRECISION / _redemptionPrice;
        // Calculate the collFee separately (for events)
        _singleRedemption.collFee = correspondingColl * _redemptionRate / DECIMAL_PRECISION;
        // Get the final collLot to send to redeemer, leaving the fee in the Trove
        _singleRedemption.collLot = correspondingColl - _singleRedemption.collFee;

        bool isTroveInBatch = _singleRedemption.batchAddress != address(0);
        uint256 newDebt = _applySingleRedemption(_defaultPool, _singleRedemption, isTroveInBatch);

        // Make Trove zombie if it's tiny (and it wasn’t already), in order to prevent griefing future (normal, sequential) redemptions
        if (newDebt < MIN_DEBT) {
            if (!_singleRedemption.isZombieTrove) {
                Troves[_singleRedemption.troveId].status = Status.zombie;
                if (isTroveInBatch) {
                    sortedTroves.removeFromBatch(_singleRedemption.troveId);
                } else {
                    sortedTroves.remove(_singleRedemption.troveId);
                }
                // If it’s a partial redemption, let’s store a pointer to it so it’s used first in the next one
                if (newDebt > 0) {
                    lastZombieTroveId = _singleRedemption.troveId;
                }
            } else if (newDebt == 0) {
                // Reset last zombie trove pointer if the previous one was fully redeemed now
                lastZombieTroveId = 0;
            }
        }
        // Note: technically, it could happen that the Trove pointed to by `lastZombieTroveId` ends up with
        // newDebt >= MIN_DEBT thanks to JPYDF debt redistribution, which means it _could_ be made active again,
        // however we don't do that here, as it would require hints for re-insertion into `SortedTroves`.
    }

    function _updateBatchInterestPriorToRedemption(IActivePool _activePool, address _batchAddress) internal {
        LatestBatchData memory batch;
        _getLatestBatchData(_batchAddress, batch);
        batches[_batchAddress].debt = batch.entireDebtWithoutRedistribution;
        batches[_batchAddress].lastDebtUpdateTime = uint64(block.timestamp);
        // As we are updating the batch, we update the ActivePool weighted sum too
        TroveChange memory batchTroveChange;
        batchTroveChange.oldWeightedRecordedDebt = batch.weightedRecordedDebt;
        batchTroveChange.newWeightedRecordedDebt = batch.entireDebtWithoutRedistribution * batch.annualInterestRate;
        batchTroveChange.batchAccruedManagementFee = batch.accruedManagementFee;
        batchTroveChange.oldWeightedRecordedBatchManagementFee = batch.weightedRecordedBatchManagementFee;
        batchTroveChange.newWeightedRecordedBatchManagementFee =
            batch.entireDebtWithoutRedistribution * batch.annualManagementFee;

        _activePool.mintAggInterestAndAccountForTroveChange(batchTroveChange, _batchAddress);
    }

    /* Send _jpydfAmount JPYDF to the system and redeem the corresponding amount of collateral from as many Troves as are needed to fill the redemption
    * request.  Applies redistribution gains to a Trove before reducing its debt and coll.
    *
    * Note that if _amount is very large, this function can run out of gas, specially if traversed troves are small. This can be easily avoided by
    * splitting the total _amount in appropriate chunks and calling the function multiple times.
    *
    * Param `_maxIterations` can also be provided, so the loop through Troves is capped (if it’s zero, it will be ignored).This makes it easier to
    * avoid OOG for the frontend, as only knowing approximately the average cost of an iteration is enough, without needing to know the “topology”
    * of the trove list. It also avoids the need to set the cap in stone in the contract, nor doing gas calculations, as both gas price and opcode
    * costs can vary.
    *
    * All Troves that are redeemed from -- with the likely exception of the last one -- will end up with no debt left, and therefore in “zombie” state
    */
    function redeemCollateral(
        address _redeemer,
        uint256 _jpydfAmount,
        uint256 _price,
        uint256 _redemptionRate,
        uint256 _maxIterations
    ) external override returns (uint256 _redeemedAmount) {
        _requireCallerIsCollateralRegistry();

        IActivePool activePoolCached = activePool;
        ISortedTroves sortedTrovesCached = sortedTroves;

        TroveChange memory totalsTroveChange;
        RedeemCollateralValues memory vars;

        vars.remainingJpydf = _jpydfAmount;

        SingleRedemptionValues memory singleRedemption;
        // Let’s check if there’s a pending zombie trove from previous redemption
        if (lastZombieTroveId != 0) {
            singleRedemption.troveId = lastZombieTroveId;
            singleRedemption.isZombieTrove = true;
        } else {
            singleRedemption.troveId = sortedTrovesCached.getLast();
        }
        vars.lastBatchUpdatedInterest = address(0);

        // Get the price to use for the redemption collateral calculations
        (uint256 redemptionPrice, bool oracleFailure) = priceFeed.fetchRedemptionPrice();
        if (oracleFailure) return 0;

        // Loop through the Troves starting from the one with lowest interest rate until _amount of JPYDF is exchanged for collateral
        if (_maxIterations == 0) _maxIterations = type(uint256).max;
        while (singleRedemption.troveId != 0 && vars.remainingJpydf > 0 && _maxIterations > 0) {
            _maxIterations--;
            // Save the uint256 of the Trove preceding the current one
            if (singleRedemption.isZombieTrove) {
                vars.nextUserToCheck = sortedTrovesCached.getLast();
            } else {
                vars.nextUserToCheck = sortedTrovesCached.getPrev(singleRedemption.troveId);
            }

            // Skip if ICR < 100%, to make sure that redemptions don’t decrease the CR of hit Troves.
            // Use the normal price for the ICR check.
            if (getCurrentICR(singleRedemption.troveId, _price) < _100pct) {
                singleRedemption.troveId = vars.nextUserToCheck;
                singleRedemption.isZombieTrove = false;
                continue;
            }

            // If it’s in a batch, we need to update interest first
            // We do it here outside, to avoid repeating for each trove in the same batch
            singleRedemption.batchAddress = _getBatchManager(singleRedemption.troveId);
            if (
                singleRedemption.batchAddress != address(0)
                    && singleRedemption.batchAddress != vars.lastBatchUpdatedInterest
            ) {
                _updateBatchInterestPriorToRedemption(activePoolCached, singleRedemption.batchAddress);
                vars.lastBatchUpdatedInterest = singleRedemption.batchAddress;
            }

            _redeemCollateralFromTrove(
                defaultPool, singleRedemption, vars.remainingJpydf, redemptionPrice, _redemptionRate
            );

            totalsTroveChange.collDecrease += singleRedemption.collLot;
            totalsTroveChange.debtDecrease += singleRedemption.jpydfLot;
            totalsTroveChange.appliedRedistJpydfDebtGain += singleRedemption.appliedRedistJpydfDebtGain;
            // For recorded and weighted recorded debt totals, we need to capture the increases and decreases,
            // since the net debt change for a given Trove could be positive or negative: redemptions decrease a Trove's recorded
            // (and weighted recorded) debt, but the accrued interest increases it.
            totalsTroveChange.newWeightedRecordedDebt += singleRedemption.newWeightedRecordedDebt;
            totalsTroveChange.oldWeightedRecordedDebt += singleRedemption.oldWeightedRecordedDebt;
            vars.totalCollFee += singleRedemption.collFee;

            vars.remainingJpydf -= singleRedemption.jpydfLot;
            singleRedemption.troveId = vars.nextUserToCheck;
            singleRedemption.isZombieTrove = false;
        }

        // We are removing this condition to prevent blocking redemptions
        //require(totals.totalCollDrawn > 0, "TroveManager: Unable to redeem any amount");

        emit Redemption(
            _jpydfAmount,
            totalsTroveChange.debtDecrease,
            totalsTroveChange.collDecrease,
            vars.totalCollFee,
            _price,
            redemptionPrice
        );

        activePoolCached.mintAggInterestAndAccountForTroveChange(totalsTroveChange, address(0));

        // Send the redeemed Coll to sender
        activePoolCached.sendColl(_redeemer, totalsTroveChange.collDecrease);
        // We’ll burn all the JPYDF together out in the CollateralRegistry, to save gas

        return totalsTroveChange.debtDecrease;
    }

    // Redeem as much collateral as possible from _borrower's Trove in exchange for JPYDF up to _maxJpydfAmount
    function _urgentRedeemCollateralFromTrove(
        IDefaultPool _defaultPool,
        uint256 _maxJpydfAmount,
        uint256 _price,
        SingleRedemptionValues memory _singleRedemption
    ) internal {
        // Determine the remaining amount (lot) to be redeemed, capped by the entire debt of the Trove minus the liquidation reserve
        _singleRedemption.jpydfLot = LiquityMath._min(_maxJpydfAmount, _singleRedemption.trove.entireDebt);

        // Get the amount of ETH equal in USD value to the JPYDF lot redeemed
        _singleRedemption.collLot = _singleRedemption.jpydfLot * (DECIMAL_PRECISION + URGENT_REDEMPTION_BONUS) / _price;
        // As here we can redeem when CR < 101% (accounting for 1% bonus), we need to cap by collateral too
        if (_singleRedemption.collLot > _singleRedemption.trove.entireColl) {
            _singleRedemption.collLot = _singleRedemption.trove.entireColl;
            _singleRedemption.jpydfLot =
                _singleRedemption.trove.entireColl * _price / (DECIMAL_PRECISION + URGENT_REDEMPTION_BONUS);
        }

        bool isTroveInBatch = _singleRedemption.batchAddress != address(0);
        _applySingleRedemption(_defaultPool, _singleRedemption, isTroveInBatch);

        // No need to make this Trove zombie if it has tiny debt, since:
        // - This collateral branch has shut down and urgent redemptions are enabled
        // - Urgent redemptions aren't sequential, so they can't be griefed by tiny Troves.
    }

    function urgentRedemption(uint256 _jpydfAmount, uint256[] calldata _troveIds, uint256 _minCollateral) external {
        _requireIsShutDown();
        _requireAmountGreaterThanZero(_jpydfAmount);
        _requireJpydfBalanceCoversRedemption(jpydfToken, msg.sender, _jpydfAmount);

        IActivePool activePoolCached = activePool;
        TroveChange memory totalsTroveChange;

        // Use the wind-down quote so an irreversible shutdown does not reopen the
        // normal-redemption oracle-lag arbitrage.
        (uint256 price,) = priceFeed.fetchUrgentRedemptionPrice();

        uint256 remainingJpydf = _jpydfAmount;
        for (uint256 i = 0; i < _troveIds.length; i++) {
            if (remainingJpydf == 0) break;

            SingleRedemptionValues memory singleRedemption;
            singleRedemption.troveId = _troveIds[i];
            _getLatestTroveData(singleRedemption.troveId, singleRedemption.trove);

            if (!_isActiveOrZombie(Troves[singleRedemption.troveId].status) || singleRedemption.trove.entireDebt == 0) {
                continue;
            }

            // If it’s in a batch, we need to update interest first
            // As we don’t have them ordered now, we cannot avoid repeating for each trove in the same batch
            singleRedemption.batchAddress = _getBatchManager(singleRedemption.troveId);
            if (singleRedemption.batchAddress != address(0)) {
                _updateBatchInterestPriorToRedemption(activePoolCached, singleRedemption.batchAddress);
            }

            _urgentRedeemCollateralFromTrove(defaultPool, remainingJpydf, price, singleRedemption);

            totalsTroveChange.collDecrease += singleRedemption.collLot;
            totalsTroveChange.debtDecrease += singleRedemption.jpydfLot;
            totalsTroveChange.appliedRedistJpydfDebtGain += singleRedemption.appliedRedistJpydfDebtGain;
            // For recorded and weighted recorded debt totals, we need to capture the increases and decreases,
            // since the net debt change for a given Trove could be positive or negative: redemptions decrease a Trove's recorded
            // (and weighted recorded) debt, but the accrued interest increases it.
            totalsTroveChange.newWeightedRecordedDebt += singleRedemption.newWeightedRecordedDebt;
            totalsTroveChange.oldWeightedRecordedDebt += singleRedemption.oldWeightedRecordedDebt;

            remainingJpydf -= singleRedemption.jpydfLot;
        }

        if (totalsTroveChange.collDecrease < _minCollateral) {
            revert MinCollNotReached(totalsTroveChange.collDecrease);
        }

        emit Redemption(_jpydfAmount, totalsTroveChange.debtDecrease, totalsTroveChange.collDecrease, 0, price, price);

        // Since this branch is shut down, this will mint 0 interest.
        // We call this only to update the aggregate debt and weighted debt trackers.
        activePoolCached.mintAggInterestAndAccountForTroveChange(totalsTroveChange, address(0));

        // Send the redeemed coll to caller
        activePoolCached.sendColl(msg.sender, totalsTroveChange.collDecrease);
        // Burn JPYDF
        jpydfToken.burn(msg.sender, totalsTroveChange.debtDecrease);
    }

    function shutdown() external {
        _requireCallerIsBorrowerOperations();
        shutdownTime = block.timestamp;
        activePool.setShutdownFlag();
    }

    // --- Helper functions ---

    // Return the current collateral ratio (ICR) of a given Trove. Takes a trove's pending coll and debt rewards from redistributions into account.
    function getCurrentICR(uint256 _troveId, uint256 _price) public view override returns (uint256) {
        LatestTroveData memory trove;
        _getLatestTroveData(_troveId, trove);
        return LiquityMath._computeCR(trove.entireColl, trove.entireDebt, _price);
    }

    function _updateTroveRewardSnapshots(uint256 _troveId) internal {
        rewardSnapshots[_troveId].coll = L_coll;
        rewardSnapshots[_troveId].jpydfDebt = L_jpydfDebt;
    }

    // Return the Troves entire debt and coll, including redistribution gains from redistributions.
    function _getLatestTroveData(uint256 _troveId, LatestTroveData memory trove) internal view {
        // If trove belongs to a batch, we fetch the batch and apply its share to obtained values
        address batchAddress = _getBatchManager(_troveId);
        if (batchAddress != address(0)) {
            LatestBatchData memory batch;
            _getLatestBatchData(batchAddress, batch);
            _getLatestTroveDataFromBatch(_troveId, trove, batch);
            return;
        }

        uint256 stake = Troves[_troveId].stake;
        trove.redistJpydfDebtGain = stake * (L_jpydfDebt - rewardSnapshots[_troveId].jpydfDebt) / DECIMAL_PRECISION;
        trove.redistCollGain = stake * (L_coll - rewardSnapshots[_troveId].coll) / DECIMAL_PRECISION;

        trove.recordedDebt = Troves[_troveId].debt;
        trove.annualInterestRate = Troves[_troveId].annualInterestRate;
        trove.weightedRecordedDebt = trove.recordedDebt * trove.annualInterestRate;

        uint256 period = _getInterestPeriod(Troves[_troveId].lastDebtUpdateTime);
        trove.accruedInterest = _calcInterest(trove.weightedRecordedDebt, period);

        trove.entireDebt = trove.recordedDebt + trove.redistJpydfDebtGain + trove.accruedInterest;
        trove.entireColl = Troves[_troveId].coll + trove.redistCollGain;
        trove.lastInterestRateAdjTime = Troves[_troveId].lastInterestRateAdjTime;
    }

    function _getLatestTroveDataFromBatch(
        uint256 _troveId,
        LatestTroveData memory _latestTroveData,
        LatestBatchData memory _latestBatchData
    ) internal view {
        Trove memory trove = Troves[_troveId];
        uint256 batchDebtShares = trove.batchDebtShares;
        uint256 totalDebtShares = _latestBatchData.totalDebtShares;

        uint256 stake = trove.stake;
        _latestTroveData.redistJpydfDebtGain =
            stake * (L_jpydfDebt - rewardSnapshots[_troveId].jpydfDebt) / DECIMAL_PRECISION;
        _latestTroveData.redistCollGain = stake * (L_coll - rewardSnapshots[_troveId].coll) / DECIMAL_PRECISION;

        if (totalDebtShares > 0) {
            _latestTroveData.recordedDebt = _latestBatchData.recordedDebt * batchDebtShares / totalDebtShares;
            _latestTroveData.weightedRecordedDebt = _latestTroveData.recordedDebt * _latestBatchData.annualInterestRate;
            _latestTroveData.accruedInterest = _latestBatchData.accruedInterest * batchDebtShares / totalDebtShares;
            _latestTroveData.accruedBatchManagementFee =
                _latestBatchData.accruedManagementFee * batchDebtShares / totalDebtShares;
        }
        _latestTroveData.annualInterestRate = _latestBatchData.annualInterestRate;

        // We can’t do pro-rata batch entireDebt, because redist gains are proportional to coll, not to debt
        _latestTroveData.entireDebt = _latestTroveData.recordedDebt + _latestTroveData.redistJpydfDebtGain
            + _latestTroveData.accruedInterest + _latestTroveData.accruedBatchManagementFee;
        _latestTroveData.entireColl = trove.coll + _latestTroveData.redistCollGain;
        _latestTroveData.lastInterestRateAdjTime =
            LiquityMath._max(_latestBatchData.lastInterestRateAdjTime, trove.lastInterestRateAdjTime);
    }

    function getLatestTroveData(uint256 _troveId) external view returns (LatestTroveData memory trove) {
        _getLatestTroveData(_troveId, trove);
    }

    function getTroveAnnualInterestRate(uint256 _troveId) external view returns (uint256) {
        Trove memory trove = Troves[_troveId];
        address batchAddress = _getBatchManager(trove);
        if (batchAddress != address(0)) {
            return batches[batchAddress].annualInterestRate;
        }
        return trove.annualInterestRate;
    }

    function _getBatchManager(uint256 _troveId) internal view returns (address) {
        return Troves[_troveId].interestBatchManager;
    }

    function _getBatchManager(Trove memory trove) internal pure returns (address) {
        return trove.interestBatchManager;
    }

    // Return the Batch entire debt and coll, including redistribution gains from redistributions.
    function _getLatestBatchData(address _batchAddress, LatestBatchData memory latestBatchData) internal view {
        Batch memory batch = batches[_batchAddress];

        latestBatchData.totalDebtShares = batch.totalDebtShares;
        latestBatchData.recordedDebt = batch.debt;
        latestBatchData.annualInterestRate = batch.annualInterestRate;
        latestBatchData.weightedRecordedDebt = latestBatchData.recordedDebt * latestBatchData.annualInterestRate;
        uint256 period = _getInterestPeriod(batch.lastDebtUpdateTime);
        latestBatchData.accruedInterest = _calcInterest(latestBatchData.weightedRecordedDebt, period);
        latestBatchData.annualManagementFee = batch.annualManagementFee;
        latestBatchData.weightedRecordedBatchManagementFee =
            latestBatchData.recordedDebt * latestBatchData.annualManagementFee;
        latestBatchData.accruedManagementFee = _calcInterest(latestBatchData.weightedRecordedBatchManagementFee, period);

        latestBatchData.entireDebtWithoutRedistribution =
            latestBatchData.recordedDebt + latestBatchData.accruedInterest + latestBatchData.accruedManagementFee;
        latestBatchData.entireCollWithoutRedistribution = batch.coll;
        latestBatchData.lastDebtUpdateTime = batch.lastDebtUpdateTime;
        latestBatchData.lastInterestRateAdjTime = batch.lastInterestRateAdjTime;
    }

    function getLatestBatchData(address _batchAddress) external view returns (LatestBatchData memory batch) {
        _getLatestBatchData(_batchAddress, batch);
    }

    // Update borrower's stake based on their latest collateral value
    function _updateStakeAndTotalStakes(uint256 _troveId, uint256 _coll) internal returns (uint256 newStake) {
        newStake = _computeNewStake(_coll);
        uint256 oldStake = Troves[_troveId].stake;
        Troves[_troveId].stake = newStake;

        totalStakes = totalStakes - oldStake + newStake;
    }

    // Calculate a new stake based on the snapshots of the totalStakes and totalCollateral taken at the last liquidation
    function _computeNewStake(uint256 _coll) internal view returns (uint256) {
        uint256 stake;
        if (totalCollateralSnapshot == 0) {
            stake = _coll;
        } else {
            /*
            * The following assert() holds true because:
            * - The system always contains >= 1 trove
            * - When we close or liquidate a trove, we redistribute the redistribution gains, so if all troves were closed/liquidated,
            * rewards would’ve been emptied and totalCollateralSnapshot would be zero too.
            */
            // assert(totalStakesSnapshot > 0);
            stake = _coll * totalStakesSnapshot / totalCollateralSnapshot;
        }
        return stake;
    }

    function _redistributeDebtAndColl(
        IActivePool _activePool,
        IDefaultPool _defaultPool,
        uint256 _debtToRedistribute,
        uint256 _collToRedistribute
    ) internal {
        if (_debtToRedistribute == 0) return; // Otherwise _collToRedistribute > 0 too

        /*
        * Add distributed coll and debt rewards-per-unit-staked to the running totals. Division uses a "feedback"
        * error correction, to keep the cumulative error low in the running totals L_coll and L_jpydfDebt:
        *
        * 1) Form numerators which compensate for the floor division errors that occurred the last time this
        * function was called.
        * 2) Calculate "per-unit-staked" ratios.
        * 3) Multiply each ratio back by its denominator, to reveal the current floor division error.
        * 4) Store these errors for use in the next correction when this function is called.
        * 5) Note: static analysis tools complain about this "division before multiplication", however, it is intended.
        */
        uint256 collNumerator = _collToRedistribute * DECIMAL_PRECISION + lastCollError_Redistribution;
        uint256 jpydfDebtNumerator = _debtToRedistribute * DECIMAL_PRECISION + lastJpydfDebtError_Redistribution;

        // Get the per-unit-staked terms
        uint256 collRewardPerUnitStaked = collNumerator / totalStakes;
        uint256 jpydfDebtRewardPerUnitStaked = jpydfDebtNumerator / totalStakes;

        lastCollError_Redistribution = collNumerator - collRewardPerUnitStaked * totalStakes;
        lastJpydfDebtError_Redistribution = jpydfDebtNumerator - jpydfDebtRewardPerUnitStaked * totalStakes;

        // Add per-unit-staked terms to the running totals
        L_coll = L_coll + collRewardPerUnitStaked;
        L_jpydfDebt = L_jpydfDebt + jpydfDebtRewardPerUnitStaked;

        _defaultPool.increaseJpydfDebt(_debtToRedistribute);
        _activePool.sendCollToDefaultPool(_collToRedistribute);
    }

    /*
    * Updates snapshots of system total stakes and total collateral, excluding a given collateral remainder from the calculation.
    * Used in a liquidation sequence.
    */
    function _updateSystemSnapshots_excludeCollRemainder(IActivePool _activePool, uint256 _collRemainder) internal {
        totalStakesSnapshot = totalStakes;

        uint256 activeColl = _activePool.getCollBalance();
        uint256 liquidatedColl = defaultPool.getCollBalance();
        totalCollateralSnapshot = activeColl - _collRemainder + liquidatedColl;
    }

    /*
    * Remove a Trove owner from the TroveIds array, not preserving array order. Removing owner 'B' does the following:
    * [A B C D E] => [A E C D], and updates E's Trove struct to point to its new array index.
    */
    function _removeTroveId(uint256 _troveId, uint256 TroveIdsArrayLength) internal {
        uint64 index = Troves[_troveId].arrayIndex;
        uint256 idxLast = TroveIdsArrayLength - 1;

        // assert(index <= idxLast);

        uint256 idToMove = TroveIds[idxLast];

        TroveIds[index] = idToMove;
        Troves[idToMove].arrayIndex = index;

        TroveIds.pop();
    }

    function getTroveStatus(uint256 _troveId) external view override returns (Status) {
        return Troves[_troveId].status;
    }

    // --- Interest rate calculations ---

    function _getInterestPeriod(uint256 _lastDebtUpdateTime) internal view returns (uint256) {
        if (shutdownTime == 0) {
            // If branch is not shut down, interest is earned up to now.
            return block.timestamp - _lastDebtUpdateTime;
        } else if (shutdownTime > 0 && _lastDebtUpdateTime < shutdownTime) {
            // If branch is shut down and the Trove was not updated since shut down, interest is earned up to the shutdown time.
            return shutdownTime - _lastDebtUpdateTime;
        } else {
            // if (shutdownTime > 0 && _lastDebtUpdateTime >= shutdownTime)
            // If branch is shut down and the Trove was updated after shutdown, no interest is earned since.
            return 0;
        }
    }

    // --- 'require' wrapper functions ---

    function _requireCallerIsBorrowerOperations() internal view {
        if (msg.sender != address(borrowerOperations)) {
            revert CallerNotBorrowerOperations();
        }
    }

    function _requireCallerIsCollateralRegistry() internal view {
        if (msg.sender != address(collateralRegistry)) {
            revert CallerNotCollateralRegistry();
        }
    }

    function _requireMoreThanOneTroveInSystem(uint256 TroveIdsArrayLength) internal pure {
        if (TroveIdsArrayLength == 1) {
            revert OnlyOneTroveLeft();
        }
    }

    function _requireIsShutDown() internal view {
        if (shutdownTime == 0) {
            revert NotShutDown();
        }
    }

    function _requireAmountGreaterThanZero(uint256 _amount) internal pure {
        if (_amount == 0) {
            revert ZeroAmount();
        }
    }

    function _requireJpydfBalanceCoversRedemption(IJpydfToken _jpydfToken, address _redeemer, uint256 _amount)
        internal
        view
    {
        uint256 jpydfBalance = _jpydfToken.balanceOf(_redeemer);
        if (jpydfBalance < _amount) {
            revert NotEnoughJpydfBalance();
        }
    }

    // --- Trove property getters ---

    function getUnbackedPortionPriceAndRedeemability() external returns (uint256, uint256, bool) {
        uint256 totalDebt = getEntireBranchDebt();
        uint256 spSize = stabilityPool.getTotalJpydfDeposits();
        uint256 unbackedPortion = totalDebt > spSize ? totalDebt - spSize : 0;

        (uint256 price, bool oracleFailure) = priceFeed.fetchPrice();
        // It's redeemable if the TCR is above the shutdown threshold, and branch has not been shut down.
        // Use the normal price for the TCR check.
        bool redeemable = !oracleFailure && !borrowerOperations.isOracleFailureShutdown() && _getTCR(price) >= SCR
            && shutdownTime == 0;

        return (unbackedPortion, price, redeemable);
    }

    // --- Trove property setters, called by BorrowerOperations ---

    function onOpenTrove(address _owner, uint256 _troveId, TroveChange memory _troveChange, uint256 _annualInterestRate)
        external
    {
        _requireCallerIsBorrowerOperations();

        uint256 newStake = _computeNewStake(_troveChange.collIncrease);

        // Trove memory newTrove;
        Troves[_troveId].debt = _troveChange.debtIncrease + _troveChange.upfrontFee;
        Troves[_troveId].coll = _troveChange.collIncrease;
        Troves[_troveId].stake = newStake;
        Troves[_troveId].status = Status.active;
        Troves[_troveId].arrayIndex = uint64(TroveIds.length);
        Troves[_troveId].lastDebtUpdateTime = uint64(block.timestamp);
        Troves[_troveId].lastInterestRateAdjTime = uint64(block.timestamp);
        Troves[_troveId].annualInterestRate = _annualInterestRate;

        // Push the trove's id to the Trove list
        TroveIds.push(_troveId);

        uint256 newTotalStakes = totalStakes + newStake;
        totalStakes = newTotalStakes;

        // mint ERC721
        troveNFT.mint(_owner, _troveId);

        _updateTroveRewardSnapshots(_troveId);

        emit TroveUpdated({
            _troveId: _troveId,
            _debt: _troveChange.debtIncrease + _troveChange.upfrontFee,
            _coll: _troveChange.collIncrease,
            _stake: newStake,
            _annualInterestRate: _annualInterestRate,
            _snapshotOfTotalCollRedist: L_coll,
            _snapshotOfTotalDebtRedist: L_jpydfDebt
        });

        emit TroveOperation({
            _troveId: _troveId,
            _operation: Operation.openTrove,
            _annualInterestRate: _annualInterestRate,
            _debtIncreaseFromRedist: 0,
            _debtIncreaseFromUpfrontFee: _troveChange.upfrontFee,
            _debtChangeFromOperation: int256(_troveChange.debtIncrease),
            _collIncreaseFromRedist: 0,
            _collChangeFromOperation: int256(_troveChange.collIncrease)
        });
    }

    function onOpenTroveAndJoinBatch(
        address _owner,
        uint256 _troveId,
        TroveChange memory _troveChange,
        address _batchAddress,
        uint256 _batchColl,
        uint256 _batchDebt
    ) external {
        _requireCallerIsBorrowerOperations();
        // assert(batchIds[batches[_batchAddress].arrayIndex] == _batchAddress);

        uint256 newStake = _computeNewStake(_troveChange.collIncrease);

        // Trove memory newTrove;
        Troves[_troveId].coll = _troveChange.collIncrease;
        Troves[_troveId].stake = newStake;
        Troves[_troveId].status = Status.active;
        Troves[_troveId].arrayIndex = uint64(TroveIds.length);
        Troves[_troveId].interestBatchManager = _batchAddress;
        Troves[_troveId].lastInterestRateAdjTime = uint64(block.timestamp);

        _updateTroveRewardSnapshots(_troveId);

        // Push the trove's id to the Trove list
        TroveIds.push(_troveId);

        assert(_troveChange.debtIncrease > 0);
        _updateBatchShares(
            _troveId, _batchAddress, _troveChange, _troveChange.debtIncrease, _batchColl, _batchDebt, true
        );

        uint256 newTotalStakes = totalStakes + newStake;
        totalStakes = newTotalStakes;

        // mint ERC721
        troveNFT.mint(_owner, _troveId);

        emit BatchedTroveUpdated({
            _troveId: _troveId,
            _interestBatchManager: _batchAddress,
            _batchDebtShares: Troves[_troveId].batchDebtShares,
            _coll: _troveChange.collIncrease,
            _stake: newStake,
            _snapshotOfTotalCollRedist: L_coll,
            _snapshotOfTotalDebtRedist: L_jpydfDebt
        });

        emit TroveOperation({
            _troveId: _troveId,
            _operation: Operation.openTroveAndJoinBatch,
            _annualInterestRate: batches[_batchAddress].annualInterestRate,
            _debtIncreaseFromRedist: 0,
            _debtIncreaseFromUpfrontFee: _troveChange.upfrontFee,
            _debtChangeFromOperation: int256(_troveChange.debtIncrease),
            _collIncreaseFromRedist: 0,
            _collChangeFromOperation: int256(_troveChange.collIncrease)
        });

        emit BatchUpdated({
            _interestBatchManager: _batchAddress,
            _operation: BatchOperation.joinBatch,
            _debt: batches[_batchAddress].debt,
            _coll: batches[_batchAddress].coll,
            _annualInterestRate: batches[_batchAddress].annualInterestRate,
            _annualManagementFee: batches[_batchAddress].annualManagementFee,
            _totalDebtShares: batches[_batchAddress].totalDebtShares,
            // Although the Trove joining the batch pays an upfront fee,
            // it is an individual fee, so we don't include it here
            _debtIncreaseFromUpfrontFee: 0
        });
    }

    function setTroveStatusToActive(uint256 _troveId) external {
        _requireCallerIsBorrowerOperations();
        Troves[_troveId].status = Status.active;
        if (lastZombieTroveId == _troveId) {
            lastZombieTroveId = 0;
        }
    }

    function onAdjustTroveInterestRate(
        uint256 _troveId,
        uint256 _newColl,
        uint256 _newDebt,
        uint256 _newAnnualInterestRate,
        TroveChange calldata _troveChange
    ) external {
        _requireCallerIsBorrowerOperations();

        Troves[_troveId].coll = _newColl;
        Troves[_troveId].debt = _newDebt;
        Troves[_troveId].annualInterestRate = _newAnnualInterestRate;
        Troves[_troveId].lastDebtUpdateTime = uint64(block.timestamp);
        Troves[_troveId].lastInterestRateAdjTime = uint64(block.timestamp);

        _movePendingTroveRewardsToActivePool(
            defaultPool, _troveChange.appliedRedistJpydfDebtGain, _troveChange.appliedRedistCollGain
        );

        _updateTroveRewardSnapshots(_troveId);

        emit TroveUpdated({
            _troveId: _troveId,
            _debt: _newDebt,
            _coll: _newColl,
            _stake: Troves[_troveId].stake,
            _annualInterestRate: _newAnnualInterestRate,
            _snapshotOfTotalCollRedist: L_coll,
            _snapshotOfTotalDebtRedist: L_jpydfDebt
        });

        emit TroveOperation({
            _troveId: _troveId,
            _operation: Operation.adjustTroveInterestRate,
            _annualInterestRate: _newAnnualInterestRate,
            _debtIncreaseFromRedist: _troveChange.appliedRedistJpydfDebtGain,
            _debtIncreaseFromUpfrontFee: _troveChange.upfrontFee,
            _debtChangeFromOperation: 0,
            _collIncreaseFromRedist: _troveChange.appliedRedistCollGain,
            _collChangeFromOperation: 0
        });
    }

    function onAdjustTrove(uint256 _troveId, uint256 _newColl, uint256 _newDebt, TroveChange calldata _troveChange)
        external
    {
        _requireCallerIsBorrowerOperations();

        Troves[_troveId].coll = _newColl;
        Troves[_troveId].debt = _newDebt;
        Troves[_troveId].lastDebtUpdateTime = uint64(block.timestamp);

        _movePendingTroveRewardsToActivePool(
            defaultPool, _troveChange.appliedRedistJpydfDebtGain, _troveChange.appliedRedistCollGain
        );

        uint256 newStake = _updateStakeAndTotalStakes(_troveId, _newColl);
        _updateTroveRewardSnapshots(_troveId);

        emit TroveUpdated({
            _troveId: _troveId,
            _debt: _newDebt,
            _coll: _newColl,
            _stake: newStake,
            _annualInterestRate: Troves[_troveId].annualInterestRate,
            _snapshotOfTotalCollRedist: L_coll,
            _snapshotOfTotalDebtRedist: L_jpydfDebt
        });

        emit TroveOperation({
            _troveId: _troveId,
            _operation: Operation.adjustTrove,
            _annualInterestRate: Troves[_troveId].annualInterestRate,
            _debtIncreaseFromRedist: _troveChange.appliedRedistJpydfDebtGain,
            _debtIncreaseFromUpfrontFee: _troveChange.upfrontFee,
            _debtChangeFromOperation: int256(_troveChange.debtIncrease) - int256(_troveChange.debtDecrease),
            _collIncreaseFromRedist: _troveChange.appliedRedistCollGain,
            _collChangeFromOperation: int256(_troveChange.collIncrease) - int256(_troveChange.collDecrease)
        });
    }

    function onCloseTrove(
        uint256 _troveId,
        TroveChange memory _troveChange, // decrease vars: entire, with interest, batch fee and redistribution
        address _batchAddress,
        uint256 _newBatchColl,
        uint256 _newBatchDebt // entire, with interest and batch fee
    ) external override {
        _requireCallerIsBorrowerOperations();
        _closeTrove(_troveId, _troveChange, _batchAddress, _newBatchColl, _newBatchDebt, Status.closedByOwner);
        _movePendingTroveRewardsToActivePool(
            defaultPool, _troveChange.appliedRedistJpydfDebtGain, _troveChange.appliedRedistCollGain
        );

        emit TroveUpdated({
            _troveId: _troveId,
            _debt: 0,
            _coll: 0,
            _stake: 0,
            _annualInterestRate: 0,
            _snapshotOfTotalCollRedist: 0,
            _snapshotOfTotalDebtRedist: 0
        });

        emit TroveOperation({
            _troveId: _troveId,
            _operation: Operation.closeTrove,
            _annualInterestRate: 0,
            _debtIncreaseFromRedist: _troveChange.appliedRedistJpydfDebtGain,
            _debtIncreaseFromUpfrontFee: _troveChange.upfrontFee,
            _debtChangeFromOperation: int256(_troveChange.debtIncrease) - int256(_troveChange.debtDecrease),
            _collIncreaseFromRedist: _troveChange.appliedRedistCollGain,
            _collChangeFromOperation: int256(_troveChange.collIncrease) - int256(_troveChange.collDecrease)
        });

        if (_batchAddress != address(0)) {
            emit BatchUpdated({
                _interestBatchManager: _batchAddress,
                _operation: BatchOperation.exitBatch,
                _debt: batches[_batchAddress].debt,
                _coll: batches[_batchAddress].coll,
                _annualInterestRate: batches[_batchAddress].annualInterestRate,
                _annualManagementFee: batches[_batchAddress].annualManagementFee,
                _totalDebtShares: batches[_batchAddress].totalDebtShares,
                _debtIncreaseFromUpfrontFee: 0
            });
        }
    }

    function _closeTrove(
        uint256 _troveId,
        TroveChange memory _troveChange, // decrease vars: entire, with interest, batch fee and redistribution
        address _batchAddress,
        uint256 _newBatchColl,
        uint256 _newBatchDebt, // entire, with interest and batch fee
        Status closedStatus
    ) internal {
        // assert(closedStatus == Status.closedByLiquidation || closedStatus == Status.closedByOwner);

        uint256 TroveIdsArrayLength = TroveIds.length;
        // If branch has not been shut down, or it's a liquidation, require at least 1 trove in the system.
        if (shutdownTime == 0 || closedStatus == Status.closedByLiquidation) {
            _requireMoreThanOneTroveInSystem(TroveIdsArrayLength);
        }

        _removeTroveId(_troveId, TroveIdsArrayLength);

        Trove memory trove = Troves[_troveId];

        // If trove belongs to a batch, remove from it
        if (_batchAddress != address(0)) {
            if (trove.status == Status.active) {
                sortedTroves.removeFromBatch(_troveId);
            } else if (trove.status == Status.zombie && lastZombieTroveId == _troveId) {
                lastZombieTroveId = 0;
            }

            _removeTroveSharesFromBatch(
                _troveId,
                _troveChange.collDecrease,
                _troveChange.debtDecrease,
                _troveChange,
                _batchAddress,
                _newBatchColl,
                _newBatchDebt
            );
        } else {
            if (trove.status == Status.active) {
                sortedTroves.remove(_troveId);
            } else if (trove.status == Status.zombie && lastZombieTroveId == _troveId) {
                lastZombieTroveId = 0;
            }
        }

        uint256 newTotalStakes = totalStakes - trove.stake;
        totalStakes = newTotalStakes;

        // Zero Trove properties
        delete Troves[_troveId];
        Troves[_troveId].status = closedStatus;

        // Zero Trove snapshots
        delete rewardSnapshots[_troveId];

        // burn ERC721
        troveNFT.burn(_troveId);
    }

    function onAdjustTroveInsideBatch(
        uint256 _troveId,
        uint256 _newTroveColl, // entire, with redistribution and trove change
        uint256 _newTroveDebt, // entire, with redistribution and trove change
        TroveChange memory _troveChange,
        address _batchAddress,
        uint256 _newBatchColl, // without trove change
        uint256 _newBatchDebt // entire (with interest, batch fee), but without trove change nor upfront fee nor redistribution
    ) external {
        _requireCallerIsBorrowerOperations();

        // Trove
        Troves[_troveId].coll = _newTroveColl;
        _updateTroveRewardSnapshots(_troveId);
        uint256 newStake = _updateStakeAndTotalStakes(_troveId, _newTroveColl);

        // Batch
        assert(_newTroveDebt > 0);
        _updateBatchShares(_troveId, _batchAddress, _troveChange, _newTroveDebt, _newBatchColl, _newBatchDebt, true);

        _movePendingTroveRewardsToActivePool(
            defaultPool, _troveChange.appliedRedistJpydfDebtGain, _troveChange.appliedRedistCollGain
        );

        emit BatchedTroveUpdated({
            _troveId: _troveId,
            _interestBatchManager: _batchAddress,
            _batchDebtShares: Troves[_troveId].batchDebtShares,
            _coll: _newTroveColl,
            _stake: newStake,
            _snapshotOfTotalCollRedist: L_coll,
            _snapshotOfTotalDebtRedist: L_jpydfDebt
        });

        emit TroveOperation({
            _troveId: _troveId,
            _operation: Operation.adjustTrove,
            _annualInterestRate: batches[_batchAddress].annualInterestRate,
            _debtIncreaseFromRedist: _troveChange.appliedRedistJpydfDebtGain,
            _debtIncreaseFromUpfrontFee: _troveChange.upfrontFee,
            _debtChangeFromOperation: int256(_troveChange.debtIncrease) - int256(_troveChange.debtDecrease),
            _collIncreaseFromRedist: _troveChange.appliedRedistCollGain,
            _collChangeFromOperation: int256(_troveChange.collIncrease) - int256(_troveChange.collDecrease)
        });

        emit BatchUpdated({
            _interestBatchManager: _batchAddress,
            _operation: BatchOperation.troveChange,
            _debt: batches[_batchAddress].debt,
            _coll: batches[_batchAddress].coll,
            _annualInterestRate: batches[_batchAddress].annualInterestRate,
            _annualManagementFee: batches[_batchAddress].annualManagementFee,
            _totalDebtShares: batches[_batchAddress].totalDebtShares,
            // Although the Trove being adjusted may pay an upfront fee,
            // it is an individual fee, so we don't include it here
            _debtIncreaseFromUpfrontFee: 0
        });
    }

    function onApplyTroveInterest(
        uint256 _troveId,
        uint256 _newTroveColl,
        uint256 _newTroveDebt,
        address _batchAddress,
        uint256 _newBatchColl,
        uint256 _newBatchDebt,
        TroveChange calldata _troveChange
    ) external {
        _requireCallerIsBorrowerOperations();

        Troves[_troveId].coll = _newTroveColl;

        if (_batchAddress != address(0)) {
            assert(_newTroveDebt > 0);
            _updateBatchShares(_troveId, _batchAddress, _troveChange, _newTroveDebt, _newBatchColl, _newBatchDebt, true);

            emit BatchUpdated({
                _interestBatchManager: _batchAddress,
                _operation: BatchOperation.applyBatchInterestAndFee,
                _debt: _newBatchDebt,
                _coll: _newBatchColl,
                _annualInterestRate: batches[_batchAddress].annualInterestRate,
                _annualManagementFee: batches[_batchAddress].annualManagementFee,
                _totalDebtShares: batches[_batchAddress].totalDebtShares,
                _debtIncreaseFromUpfrontFee: 0
            });
        } else {
            Troves[_troveId].debt = _newTroveDebt;
            Troves[_troveId].lastDebtUpdateTime = uint64(block.timestamp);
        }

        _movePendingTroveRewardsToActivePool(
            defaultPool, _troveChange.appliedRedistJpydfDebtGain, _troveChange.appliedRedistCollGain
        );

        _updateTroveRewardSnapshots(_troveId);

        emit TroveUpdated({
            _troveId: _troveId,
            _debt: _newTroveDebt,
            _coll: _newTroveColl,
            _stake: Troves[_troveId].stake,
            _annualInterestRate: Troves[_troveId].annualInterestRate,
            _snapshotOfTotalCollRedist: L_coll,
            _snapshotOfTotalDebtRedist: L_jpydfDebt
        });

        emit TroveOperation({
            _troveId: _troveId,
            _operation: Operation.applyPendingDebt,
            _annualInterestRate: Troves[_troveId].annualInterestRate,
            _debtIncreaseFromRedist: _troveChange.appliedRedistJpydfDebtGain,
            _debtIncreaseFromUpfrontFee: _troveChange.upfrontFee,
            _debtChangeFromOperation: int256(_troveChange.debtIncrease) - int256(_troveChange.debtDecrease),
            _collIncreaseFromRedist: _troveChange.appliedRedistCollGain,
            _collChangeFromOperation: int256(_troveChange.collIncrease) - int256(_troveChange.collDecrease)
        });
    }

    function onRegisterBatchManager(address _account, uint256 _annualInterestRate, uint256 _annualManagementFee)
        external
    {
        _requireCallerIsBorrowerOperations();

        batches[_account].arrayIndex = uint64(batchIds.length);
        batches[_account].annualInterestRate = _annualInterestRate;
        batches[_account].annualManagementFee = _annualManagementFee;
        batches[_account].lastInterestRateAdjTime = uint64(block.timestamp);

        batchIds.push(_account);

        emit BatchUpdated({
            _interestBatchManager: _account,
            _operation: BatchOperation.registerBatchManager,
            _debt: 0,
            _coll: 0,
            _annualInterestRate: _annualInterestRate,
            _annualManagementFee: _annualManagementFee,
            _totalDebtShares: 0,
            _debtIncreaseFromUpfrontFee: 0
        });
    }

    function onLowerBatchManagerAnnualFee(
        address _batchAddress,
        uint256 _newColl,
        uint256 _newDebt,
        uint256 _newAnnualManagementFee
    ) external {
        _requireCallerIsBorrowerOperations();

        batches[_batchAddress].coll = _newColl;
        batches[_batchAddress].debt = _newDebt;
        batches[_batchAddress].annualManagementFee = _newAnnualManagementFee;
        batches[_batchAddress].lastDebtUpdateTime = uint64(block.timestamp);

        emit BatchUpdated({
            _interestBatchManager: _batchAddress,
            _operation: BatchOperation.lowerBatchManagerAnnualFee,
            _debt: _newDebt,
            _coll: _newColl,
            _annualInterestRate: batches[_batchAddress].annualInterestRate,
            _annualManagementFee: _newAnnualManagementFee,
            _totalDebtShares: batches[_batchAddress].totalDebtShares,
            _debtIncreaseFromUpfrontFee: 0
        });
    }

    function onSetBatchManagerAnnualInterestRate(
        address _batchAddress,
        uint256 _newColl,
        uint256 _newDebt,
        uint256 _newAnnualInterestRate,
        uint256 _upfrontFee
    ) external {
        _requireCallerIsBorrowerOperations();

        batches[_batchAddress].coll = _newColl;
        batches[_batchAddress].debt = _newDebt;
        batches[_batchAddress].annualInterestRate = _newAnnualInterestRate;
        batches[_batchAddress].lastDebtUpdateTime = uint64(block.timestamp);
        batches[_batchAddress].lastInterestRateAdjTime = uint64(block.timestamp);

        emit BatchUpdated({
            _interestBatchManager: _batchAddress,
            _operation: BatchOperation.setBatchManagerAnnualInterestRate,
            _debt: _newDebt,
            _coll: _newColl,
            _annualInterestRate: _newAnnualInterestRate,
            _annualManagementFee: batches[_batchAddress].annualManagementFee,
            _totalDebtShares: batches[_batchAddress].totalDebtShares,
            _debtIncreaseFromUpfrontFee: _upfrontFee
        });
    }

    function onSetInterestBatchManager(OnSetInterestBatchManagerParams calldata _params) external {
        _requireCallerIsBorrowerOperations();
        TroveChange memory _troveChange = _params.troveChange;

        // assert(batchIds[batches[_params.newBatchAddress].arrayIndex] == _params.newBatchAddress);

        _updateTroveRewardSnapshots(_params.troveId);

        // Clean Trove state
        Troves[_params.troveId].debt = 0;
        Troves[_params.troveId].annualInterestRate = 0;
        Troves[_params.troveId].lastDebtUpdateTime = 0;
        Troves[_params.troveId].coll = _params.troveColl;

        Troves[_params.troveId].interestBatchManager = _params.newBatchAddress;
        Troves[_params.troveId].lastInterestRateAdjTime = uint64(block.timestamp);

        _troveChange.collIncrease = _params.troveColl - _troveChange.appliedRedistCollGain;
        _troveChange.debtIncrease =
            _params.troveDebt - _troveChange.appliedRedistJpydfDebtGain - _troveChange.upfrontFee;
        assert(_params.troveDebt > 0);
        _updateBatchShares(
            _params.troveId,
            _params.newBatchAddress,
            _troveChange,
            _params.troveDebt,
            _params.newBatchColl,
            _params.newBatchDebt,
            true
        );

        _movePendingTroveRewardsToActivePool(
            defaultPool, _troveChange.appliedRedistJpydfDebtGain, _troveChange.appliedRedistCollGain
        );

        emit BatchedTroveUpdated({
            _troveId: _params.troveId,
            _interestBatchManager: _params.newBatchAddress,
            _batchDebtShares: Troves[_params.troveId].batchDebtShares,
            _coll: _params.troveColl,
            _stake: Troves[_params.troveId].stake,
            _snapshotOfTotalCollRedist: L_coll,
            _snapshotOfTotalDebtRedist: L_jpydfDebt
        });

        emit TroveOperation({
            _troveId: _params.troveId,
            _operation: Operation.setInterestBatchManager,
            _annualInterestRate: batches[_params.newBatchAddress].annualInterestRate,
            _debtIncreaseFromRedist: _troveChange.appliedRedistJpydfDebtGain,
            _debtIncreaseFromUpfrontFee: _troveChange.upfrontFee,
            _debtChangeFromOperation: 0,
            _collIncreaseFromRedist: _troveChange.appliedRedistCollGain,
            _collChangeFromOperation: 0
        });

        emit BatchUpdated({
            _interestBatchManager: _params.newBatchAddress,
            _operation: BatchOperation.joinBatch,
            _debt: batches[_params.newBatchAddress].debt,
            _coll: batches[_params.newBatchAddress].coll,
            _annualInterestRate: batches[_params.newBatchAddress].annualInterestRate,
            _annualManagementFee: batches[_params.newBatchAddress].annualManagementFee,
            _totalDebtShares: batches[_params.newBatchAddress].totalDebtShares,
            // Although the Trove joining the batch may pay an upfront fee,
            // it is an individual fee, so we don't include it here
            _debtIncreaseFromUpfrontFee: 0
        });
    }

    // This function will revert if there’s a total debt increase and the ratio debt / shares has exceeded the max
    function _updateBatchShares(
        uint256 _troveId,
        address _batchAddress,
        TroveChange memory _troveChange,
        uint256 _newTroveDebt, // entire, with interest, batch fee and redistribution
        uint256 _batchColl, // without trove change
        uint256 _batchDebt, // entire (with interest, batch fee), but without trove change, nor upfront fee nor redist
        bool _checkBatchSharesRatio // whether we do the check on the resulting ratio inside the func call
    ) internal {
        // Debt
        uint256 currentBatchDebtShares = batches[_batchAddress].totalDebtShares;
        uint256 batchDebtSharesDelta;
        uint256 debtIncrease =
            _troveChange.debtIncrease + _troveChange.upfrontFee + _troveChange.appliedRedistJpydfDebtGain;
        uint256 debtDecrease;
        if (debtIncrease > _troveChange.debtDecrease) {
            debtIncrease -= _troveChange.debtDecrease;
        } else {
            debtDecrease = _troveChange.debtDecrease - debtIncrease;
            debtIncrease = 0;
        }

        if (debtIncrease == 0 && debtDecrease == 0) {
            batches[_batchAddress].debt = _batchDebt;
        } else {
            if (debtIncrease > 0) {
                // Add debt
                if (_batchDebt == 0) {
                    batchDebtSharesDelta = debtIncrease;
                } else {
                    // To avoid rebasing issues, let’s make sure the ratio debt / shares is not too high
                    _requireBelowMaxSharesRatio(currentBatchDebtShares, _batchDebt, _checkBatchSharesRatio);

                    batchDebtSharesDelta = currentBatchDebtShares * debtIncrease / _batchDebt;
                }

                Troves[_troveId].batchDebtShares += batchDebtSharesDelta;
                batches[_batchAddress].debt = _batchDebt + debtIncrease;
                batches[_batchAddress].totalDebtShares = currentBatchDebtShares + batchDebtSharesDelta;
            } else if (debtDecrease > 0) {
                // Subtract debt
                // We make sure that if final trove debt is zero, shares are too (avoiding rounding issues)
                // This can only happen from redemptions, as otherwise we would be using _removeTroveSharesFromBatch
                // In redemptions we don’t do that because we don’t want to kick the trove out of the batch (it’d be bad UX)
                if (_newTroveDebt == 0) {
                    batches[_batchAddress].debt = _batchDebt - debtDecrease;
                    batches[_batchAddress].totalDebtShares = currentBatchDebtShares - Troves[_troveId].batchDebtShares;
                    Troves[_troveId].batchDebtShares = 0;
                } else {
                    batchDebtSharesDelta = currentBatchDebtShares * debtDecrease / _batchDebt;

                    Troves[_troveId].batchDebtShares -= batchDebtSharesDelta;
                    batches[_batchAddress].debt = _batchDebt - debtDecrease;
                    batches[_batchAddress].totalDebtShares = currentBatchDebtShares - batchDebtSharesDelta;
                }
            }
        }
        // Update debt checkpoint
        batches[_batchAddress].lastDebtUpdateTime = uint64(block.timestamp);

        // Collateral
        uint256 collIncrease = _troveChange.collIncrease + _troveChange.appliedRedistCollGain;
        uint256 collDecrease;
        if (collIncrease > _troveChange.collDecrease) {
            collIncrease -= _troveChange.collDecrease;
        } else {
            collDecrease = _troveChange.collDecrease - collIncrease;
            collIncrease = 0;
        }

        if (collIncrease == 0 && collDecrease == 0) {
            batches[_batchAddress].coll = _batchColl;
        } else {
            if (collIncrease > 0) {
                // Add coll
                batches[_batchAddress].coll = _batchColl + collIncrease;
            } else if (collDecrease > 0) {
                // Subtract coll
                batches[_batchAddress].coll = _batchColl - collDecrease;
            }
        }
    }

    // For the debt / shares ratio to increase by a factor 1e9
    // at a average annual debt increase (compounded interest + fees) of 10%, it would take more than 217 years (log(1e9)/log(1.1))
    // at a average annual debt increase (compounded interest + fees) of 50%, it would take more than 51 years (log(1e9)/log(1.5))
    // When that happens, no more debt can be manually added to the batch, so batch should be migrated to a new one
    function _requireBelowMaxSharesRatio(
        uint256 _currentBatchDebtShares,
        uint256 _batchDebt,
        bool _checkBatchSharesRatio
    ) internal pure {
        // debt / shares should be below MAX_BATCH_SHARES_RATIO
        if (_currentBatchDebtShares * MAX_BATCH_SHARES_RATIO < _batchDebt && _checkBatchSharesRatio) {
            revert BatchSharesRatioTooHigh();
        }
    }

    function onRemoveFromBatch(
        uint256 _troveId,
        uint256 _newTroveColl, // entire, with redistribution
        uint256 _newTroveDebt, // entire, with interest, batch fee and redistribution
        TroveChange memory _troveChange,
        address _batchAddress,
        uint256 _newBatchColl,
        uint256 _newBatchDebt, // entire, with interest and batch fee
        uint256 _newAnnualInterestRate
    ) external {
        _requireCallerIsBorrowerOperations();
        // assert(batchIds[batches[_batchAddress].arrayIndex] == _batchAddress);

        // Subtract from batch
        _removeTroveSharesFromBatch(
            _troveId, _newTroveColl, _newTroveDebt, _troveChange, _batchAddress, _newBatchColl, _newBatchDebt
        );

        // Restore Trove state
        Troves[_troveId].debt = _newTroveDebt;
        Troves[_troveId].coll = _newTroveColl;
        Troves[_troveId].lastDebtUpdateTime = uint64(block.timestamp);
        Troves[_troveId].annualInterestRate = _newAnnualInterestRate;
        Troves[_troveId].lastInterestRateAdjTime = uint64(block.timestamp);

        _updateTroveRewardSnapshots(_troveId);
        _movePendingTroveRewardsToActivePool(
            defaultPool, _troveChange.appliedRedistJpydfDebtGain, _troveChange.appliedRedistCollGain
        );

        emit TroveUpdated({
            _troveId: _troveId,
            _debt: _newTroveDebt,
            _coll: _newTroveColl,
            _stake: Troves[_troveId].stake,
            _annualInterestRate: _newAnnualInterestRate,
            _snapshotOfTotalCollRedist: L_coll,
            _snapshotOfTotalDebtRedist: L_jpydfDebt
        });

        emit TroveOperation({
            _troveId: _troveId,
            _operation: Operation.removeFromBatch,
            _annualInterestRate: _newAnnualInterestRate,
            _debtIncreaseFromRedist: _troveChange.appliedRedistJpydfDebtGain,
            _debtIncreaseFromUpfrontFee: _troveChange.upfrontFee,
            _debtChangeFromOperation: 0,
            _collIncreaseFromRedist: _troveChange.appliedRedistCollGain,
            _collChangeFromOperation: 0
        });

        emit BatchUpdated({
            _interestBatchManager: _batchAddress,
            _operation: BatchOperation.exitBatch,
            _debt: batches[_batchAddress].debt,
            _coll: batches[_batchAddress].coll,
            _annualInterestRate: batches[_batchAddress].annualInterestRate,
            _annualManagementFee: batches[_batchAddress].annualManagementFee,
            _totalDebtShares: batches[_batchAddress].totalDebtShares,
            // Although the Trove leaving the batch may pay an upfront fee,
            // it is an individual fee, so we don't include it here
            _debtIncreaseFromUpfrontFee: 0
        });
    }

    function _removeTroveSharesFromBatch(
        uint256 _troveId,
        uint256 _newTroveColl, // entire, with redistribution
        uint256 _newTroveDebt, // entire, with interest, batch fee and redistribution
        TroveChange memory _troveChange,
        address _batchAddress,
        uint256 _newBatchColl, // without trove change
        uint256 _newBatchDebt // entire (with interest and batch fee), but without trove change
    ) internal {
        // As we are removing:
        // assert(_newBatchDebt > 0 || _newBatchColl > 0);

        Trove memory trove = Troves[_troveId];

        // We don’t need to increase the shares corresponding to redistribution first, because they would be subtracted immediately after
        // We don’t need to account for interest nor batch fee because it’s proportional to debt shares
        uint256 batchDebtDecrease = _newTroveDebt - _troveChange.upfrontFee - _troveChange.appliedRedistJpydfDebtGain;
        uint256 batchCollDecrease = _newTroveColl - _troveChange.appliedRedistCollGain;

        batches[_batchAddress].totalDebtShares -= trove.batchDebtShares;
        batches[_batchAddress].debt = _newBatchDebt - batchDebtDecrease;
        batches[_batchAddress].coll = _newBatchColl - batchCollDecrease;
        batches[_batchAddress].lastDebtUpdateTime = uint64(block.timestamp);

        Troves[_troveId].interestBatchManager = address(0);
        Troves[_troveId].batchDebtShares = 0;
    }
}
